class SoftBlueGridItemDelegate(QStyledItemDelegate):
    """Σχεδιάζει απαλές γαλάζιες γραμμές grid για δενδρικά tables του chat."""

    def __init__(self, parent: QWidget | None = None, color: str = "#d7ecff") -> None:
        super().__init__(parent)
        self._grid_color = QColor(color)

    def paint(self, painter: QPainter, option, index) -> None:  # type: ignore[override]
        super().paint(painter, option, index)
        painter.save()
        pen = QPen(self._grid_color)
        pen.setWidth(1)
        pen.setCosmetic(True)
        painter.setPen(pen)
        rect = option.rect.adjusted(0, 0, -1, -1)
        painter.drawLine(rect.topRight(), rect.bottomRight())
        painter.drawLine(rect.bottomLeft(), rect.bottomRight())
        painter.restore()

