def slugify(value: str) -> str:
    value = value.strip().lower().replace("/", "__")
    value = re.sub(r"[^a-z0-9_.-]+", "_", value)
    return value.strip("_.") or "model"


@dataclass
class ModelEntry:
    label: str
    repo_id: str
    source: str = "preset"
    local_dir: str | None = None
    notes: str = ""
    downloads: int | None = None
    likes: int | None = None
    gated: bool | None = None


def append_text_line(path: Path, line: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(line.rstrip() + "\n")


def write_exception_report(title: str, exc: BaseException | str, stack: str | None = None) -> None:
    LOGS_DIR.mkdir(parents=True, exist_ok=True)
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    if isinstance(exc, BaseException):
        body = "".join(traceback.format_exception(type(exc), exc, exc.__traceback__))
    else:
        body = str(exc)
    if stack:
        body += "\n" + stack
    append_text_line(LOGS_DIR / "errors.log", f"\n[{timestamp}] {title}\n{body}")


_STUDIO_GPU_CLEANUP_ONLY_ON_APP_EXIT = True


def _studio_release_gpu_memory(context: str = "", include_inference_cache: bool = True) -> bool:
    """Best-effort cleanup for GPU VRAM after training / inference work."""
    released = False

    if include_inference_cache:
        clear_cache = globals().get("clear_inference_runtime_cache")
        if callable(clear_cache):
            try:
                clear_cache()
                released = True
            except Exception:
                pass

    try:
        import gc
        gc.collect()
    except Exception:
        pass

    try:
        import torch
        if torch.cuda.is_available():
            try:
                torch.cuda.synchronize()
            except Exception:
                pass
            try:
                torch.cuda.empty_cache()
                released = True
            except Exception:
                pass
            try:
                ipc_collect = getattr(torch.cuda, "ipc_collect", None)
                if callable(ipc_collect):
                    ipc_collect()
                    released = True
            except Exception:
                pass
    except Exception:
        pass

    if context:
        try:
            message = f"[cleanup] VRAM cleanup: {context}"
            if "append_log" in globals() and callable(globals().get("append_log")):
                append_log(message)
            else:
                print(message, flush=True)
        except Exception:
            pass

    return released


def _studio_terminate_process_tree(process: subprocess.Popen[str] | subprocess.Popen[bytes] | None) -> None:
    if process is None:
        return
    try:
        if process.poll() is not None:
            return
    except Exception:
        return

    try:
        if os.name == "nt":
            creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            subprocess.run(
                ["taskkill", "/PID", str(process.pid), "/T", "/F"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
                creationflags=creationflags,
            )
        else:
            import signal
            try:
                os.killpg(os.getpgid(process.pid), signal.SIGTERM)
            except Exception:
                process.terminate()
    except Exception:
        try:
            process.terminate()
        except Exception:
            pass


def install_global_exception_hooks() -> None:
    def _hook(exc_type, exc, tb):
        write_exception_report("Unhandled exception", exc, "".join(traceback.format_exception(exc_type, exc, tb)))
    sys.excepthook = _hook
    if hasattr(threading, "excepthook"):
        def _thread_hook(args):
            write_exception_report(f"Unhandled thread exception in {getattr(args.thread, 'name', 'thread')}", args.exc_value,
                                   "".join(traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback)))
        threading.excepthook = _thread_hook  # type: ignore[attr-defined]


def profile_defaults_for_vram(vram_gb: int) -> dict[str, Any]:
    """Return optimised training defaults for the available VRAM.

    Design goals:
    • Maximum accuracy: cosine LR schedule, NEFTune noise, higher effective batch
      (micro_batch × grad_accum ≈ 32), rsLoRA scaling, bf16 where available.
    • Good speed: gradient checkpointing, pinned memory, torch.compile
      hint for Ampere+ GPUs.
    • LoRA alpha = 2 × r (rule of thumb for best convergence).
    """
    # effective_batch = micro_batch × grad_accum
    # We target effective_batch = 32 across all tiers
    if vram_gb <= 8:
        return {
            "max_length": 1024, "micro_batch_size": 1,
            "gradient_accumulation_steps": 32,
            "lora_r": 16, "lora_alpha": 32,
            "learning_rate": 2e-4, "lr_scheduler_type": "cosine",
            "warmup_ratio": 0.05,
            "weight_decay": 0.01,
            "neftune_noise_alpha": 5.0,
            "optim": "adamw_torch_fused",
            "use_rslora": True,
            "packing": False,          # packing needs enough RAM
            "bf16_auto": True,         # enable bf16 if GPU supports it
            "fp16_fallback": True,
        }
    if vram_gb <= 12:
        return {
            "max_length": 2048, "micro_batch_size": 1,
            "gradient_accumulation_steps": 32,
            "lora_r": 32, "lora_alpha": 64,
            "learning_rate": 2e-4, "lr_scheduler_type": "cosine",
            "warmup_ratio": 0.05,
            "weight_decay": 0.01,
            "neftune_noise_alpha": 5.0,
            "optim": "adamw_torch_fused",
            "use_rslora": True,
            "packing": False,
            "bf16_auto": True,
            "fp16_fallback": True,
        }
    if vram_gb <= 16:
        return {
            "max_length": 2048, "micro_batch_size": 2,
            "gradient_accumulation_steps": 16,
            "lora_r": 64, "lora_alpha": 128,
            "learning_rate": 2e-4, "lr_scheduler_type": "cosine_with_restarts",
            "warmup_ratio": 0.05,
            "weight_decay": 0.01,
            "neftune_noise_alpha": 5.0,
            "optim": "adamw_torch_fused",
            "use_rslora": True,
            "packing": False,
            "bf16_auto": True,
            "fp16_fallback": True,
        }
    if vram_gb <= 24:
        return {
            "max_length": 4096, "micro_batch_size": 2,
            "gradient_accumulation_steps": 16,
            "lora_r": 128, "lora_alpha": 256,
            "learning_rate": 1e-4, "lr_scheduler_type": "cosine_with_restarts",
            "warmup_ratio": 0.05,
            "weight_decay": 0.01,
            "neftune_noise_alpha": 5.0,
            "optim": "adamw_torch_fused",
            "use_rslora": True,
            "packing": False,
            "bf16_auto": True,
            "fp16_fallback": True,
        }
    # 40 GB+
    return {
        "max_length": 8192, "micro_batch_size": 4,
        "gradient_accumulation_steps": 8,
        "lora_r": 256, "lora_alpha": 512,
        "learning_rate": 5e-5, "lr_scheduler_type": "cosine_with_restarts",
        "warmup_ratio": 0.03,
        "weight_decay": 0.01,
        "neftune_noise_alpha": 5.0,
        "optim": "adamw_torch_fused",
        "use_rslora": True,
        "packing": False,
        "bf16_auto": True,
        "fp16_fallback": False,       # large cards always bf16
    }


# ---------------------------------------------------------------------------
# Model-size aware hyperparameter tuning
# Each entry: (repo_id_substring, billion_params, best_lr, lora_r_scale)
# IMPORTANT: sorted largest → smallest so "13b" matches before "3b" does.
# ---------------------------------------------------------------------------
MODEL_SIZE_HINTS: list[tuple[str, float, float, float]] = [
    ("72b",  72.0,  3e-5, 2.00),
    ("70b",  70.0,  3e-5, 2.00),
    ("34b",  34.0,  5e-5, 2.00),
    ("32b",  32.0,  5e-5, 2.00),
    ("20b",  20.0,  5e-5, 2.00),
    ("14b",  14.0,  8e-5, 2.00),
    ("13b",  13.0,  8e-5, 2.00),
    ("9b",    9.0,  1e-4, 1.50),
    ("8b",    8.0,  1e-4, 1.50),
    ("7b",    7.0,  1e-4, 1.50),
    ("3b",    3.0,  2e-4, 1.00),
    ("1.5b",  1.5,  2e-4, 1.00),   # before "1b" — "1.5b" does not contain "1b"
    ("1b",    1.0,  2e-4, 0.75),
    ("0.5b",  0.5,  3e-4, 0.50),
]


def _nearest_power_of_two(n: int) -> int:
    """Return the largest power-of-2 ≤ n (minimum 8)."""
    n = max(8, n)
    p = 1
    while p * 2 <= n:
        p *= 2
    return p


def model_defaults_for_repo_id(repo_id: str, vram_gb: int) -> dict[str, Any]:
    """Return optimised hyperparameters combining GPU VRAM tier and model size.

    Logic:
    • Start from the VRAM-based profile (safe baseline for memory).
    • Scan MODEL_SIZE_HINTS for a substring match in repo_id.
    • Adjust learning_rate, lora_r, lora_alpha and max_length accordingly.
    • Round lora_r to nearest power-of-2 for CUDA kernel efficiency.
    """
    base = profile_defaults_for_vram(vram_gb)
    if not repo_id:
        return base
    repo_low = repo_id.lower()
    for hint_key, size_b, lr, lora_scale in MODEL_SIZE_HINTS:
        if hint_key in repo_low:
            base["learning_rate"] = lr
            base["lora_r"] = _nearest_power_of_two(int(base["lora_r"] * lora_scale))
            base["lora_alpha"] = base["lora_r"] * 2
            # Large models on limited VRAM: cap max_length to avoid OOM
            if size_b >= 13 and vram_gb <= 16:
                base["max_length"] = min(base["max_length"], 1024)
            elif size_b >= 7 and vram_gb <= 8:
                base["max_length"] = min(base["max_length"], 512)
            base["_autotune_matched_size"] = size_b   # informational — used by UI badge
            break
    return base


def describe_model_autotune(repo_id: str, vram_gb: int) -> str:
    """Return a short human-readable summary of what was auto-tuned."""
    d = model_defaults_for_repo_id(repo_id, vram_gb)
    size_b = d.get("_autotune_matched_size")
    if size_b is None:
        return ""
    return (
        f"🤖 Αυτόματη ρύθμιση βάσει μοντέλου  ·  "
        f"Μέγεθος ≈{size_b}B  ·  "
        f"LR={d['learning_rate']:.0e}  ·  "
        f"LoRA r={d['lora_r']}  LoRA alpha={d['lora_alpha']}  ·  "
        f"max_len={d['max_length']}  warmup={float(d.get('warmup_ratio', 0.05)):.3f}"
    )


def make_profile_template(profile_name: str, vram_gb: int) -> dict[str, Any]:
    tuned = profile_defaults_for_vram(vram_gb)
    return {
        "profile_name": profile_name,
        "base_model": "",
        "selected_model_repo_id": "",
        "selected_model_local_dir": "",
        "project_root": str(PROJECT_ROOT),
        "output_dir": str(ARTIFACTS_DIR),
        "artifacts_dir": str(ARTIFACTS_DIR),
        "cache_dir": str(PROJECT_ROOT / "hf_cache"),
        "hardware": {"target_gpu": profile_name, "vram_gb": vram_gb},
        "dataset": {
            "collect_dir": str(ARTIFACTS_DIR / "01_collect"),
            "preprocess_dir": str(ARTIFACTS_DIR / "02_preprocess"),
            "build_sft_dir": str(ARTIFACTS_DIR / "04_build_sft"),
        },
        "training": {
            "max_length":                tuned["max_length"],
            "micro_batch_size":          tuned["micro_batch_size"],
            "gradient_accumulation_steps": tuned["gradient_accumulation_steps"],
            "learning_rate":             tuned.get("learning_rate", 2e-4),
            "lr_scheduler_type":         tuned.get("lr_scheduler_type", "cosine"),
            "epochs":                    3,      # 3 epochs better than 1 for most tasks
            "warmup_ratio":              tuned.get("warmup_ratio", 0.05),
            "weight_decay":              tuned.get("weight_decay", 0.01),
            "neftune_noise_alpha":       tuned.get("neftune_noise_alpha", 5.0),
            "optim":                     tuned.get("optim", "adamw_torch_fused"),
            "packing":                   tuned.get("packing", False),
            "bf16_auto":                 tuned.get("bf16_auto", True),
            "fp16_fallback":             tuned.get("fp16_fallback", True),
            "gradient_checkpointing":    True,
            "logging_steps":             1,
            "save_steps":                100,
            "save_total_limit":          2,
            "seed":                      42,
            "max_train_samples":         0,
            "cpt_max_steps":             0,
            "sft_max_steps":             0,
            "dataloader_num_workers":    2,
            "group_by_length":           True,   # reduces padding waste → speed
            "max_grad_norm":             1.0,
        },
        "lora": {
            "r":              tuned["lora_r"],
            "alpha":          tuned["lora_alpha"],
            "dropout":        0.05,
            "use_rslora":     tuned.get("use_rslora", True),
            "target_modules": "all-linear",
            "bias":           "none",
        },
        "export": {
            "final_model_dir": str(ARTIFACTS_DIR / "final_model"),
        },
        "gui_runtime": {},
    }


PROFILE_TEMPLATES: dict[str, dict[str, Any]] = {name: make_profile_template(name, vram) for name, vram in EMBEDDED_PROFILE_SPECS}
PROFILE_TEMPLATES[PROFILE_DEFAULT] = make_profile_template(PROFILE_DEFAULT, 16)
PROFILE_TEMPLATES[PROFILE_SAFE] = make_profile_template(PROFILE_SAFE, 12)
PROFILE_OPTION_LABELS = [PROFILE_DEFAULT, PROFILE_SAFE] + [name for name, _ in EMBEDDED_PROFILE_SPECS if name != "RTX 3060 12GB"] + [PROFILE_SELECTED]


def normalize_repo_id_alias(repo_id: str) -> str:
    raw = str(repo_id or "").strip()
    if not raw:
        return ""
    return COMMON_MODEL_ID_ALIASES.get(raw.lower(), raw)


def is_probable_network_error(exc: BaseException) -> bool:
    parts: list[str] = []
    current: BaseException | None = exc
    depth = 0
    while current is not None and depth < 6:
        parts.append(f"{type(current).__name__}: {current}")
        current = getattr(current, "__cause__", None) or getattr(current, "__context__", None)
        depth += 1
    text = " | ".join(parts).lower()
    network_markers = [
        "connecterror", "getaddrinfo failed", "name or service not known", "temporary failure in name resolution",
        "nodename nor servname provided", "connection error", "failed to establish a new connection",
        "max retries exceeded", "dns", "network is unreachable", "connection refused",
        "timed out", "read timeout", "proxyerror", "remote end closed connection"
    ]
    return any(marker in text for marker in network_markers)


def format_network_error_message(action: str, exc: BaseException) -> str:
    detail = str(exc).strip() or type(exc).__name__
    return (
        f"Αποτυχία δικτυακής σύνδεσης κατά το {action}. "
        f"Ελέγξτε σύνδεση Internet / DNS / proxy / firewall και δοκιμάστε ξανά. "
        f"Λεπτομέρειες: {detail}"
    )


HF_TOKEN_OVERRIDE = ""
_APP_SET_HF_TOKEN = ""


def apply_runtime_hf_token_override(token: str | None) -> None:
    global HF_TOKEN_OVERRIDE, _APP_SET_HF_TOKEN

    token_value = str(token or "").strip()
    previous_app_token = _APP_SET_HF_TOKEN
    HF_TOKEN_OVERRIDE = token_value

    if token_value:
        os.environ["HF_TOKEN"] = token_value
        _APP_SET_HF_TOKEN = token_value
        return

    if previous_app_token and os.environ.get("HF_TOKEN", "") == previous_app_token:
        try:
            os.environ.pop("HF_TOKEN", None)
        except Exception:
            pass
    _APP_SET_HF_TOKEN = ""


def get_hf_token() -> str | None:
    candidates: list[str] = []

    override = str(globals().get("HF_TOKEN_OVERRIDE", "") or "").strip()
    if override:
        candidates.append(override)

    for env_name in ("HF_TOKEN", "HUGGINGFACE_HUB_TOKEN", "HUGGING_FACE_HUB_TOKEN"):
        env_value = str(os.environ.get(env_name, "") or "").strip()
        if env_value:
            candidates.append(env_value)

    try:
        from huggingface_hub import get_token as hf_get_token  # type: ignore
        hub_token = str(hf_get_token() or "").strip()
        if hub_token:
            candidates.append(hub_token)
    except Exception:
        pass

    for token in candidates:
        if token:
            return token
    return None


def get_hf_auth_status_message() -> str:
    token = get_hf_token()
    if token:
        masked = token[:6] + "..." + token[-4:] if len(token) >= 14 else "διαθέσιμο"
        return f"✓ Εντοπίστηκε HF_TOKEN για Hugging Face Hub ({masked})."
    return (
        "ℹ Δεν έχει οριστεί HF_TOKEN για το Hugging Face Hub. "
        "Η εφαρμογή θα λειτουργεί κανονικά και χωρίς token, αλλά μπορεί να έχει χαμηλότερα όρια λήψεων ή πιο αργή απόκριση. "
        "Αν θέλεις υψηλότερα όρια, όρισε μεταβλητή περιβάλλοντος HF_TOKEN."
    )


def resolve_huggingface_repo_id(
    repo_id: str,
    token: str | None = None,
    progress_callback: Callable[[str], None] | None = None,
) -> tuple[str, list[str]]:
    raw_repo_id = str(repo_id or "").strip()
    if not raw_repo_id:
        raise RuntimeError("Δεν δόθηκε Hugging Face model id.")

    normalized = normalize_repo_id_alias(raw_repo_id)

    try:
        from huggingface_hub import HfApi
    except Exception as exc:
        write_exception_report("huggingface_hub import failed during repo validation", exc)
        raise RuntimeError("Δεν είναι διαθέσιμο το πακέτο huggingface_hub για έλεγχο model id.") from exc

    api = HfApi(token=token)

    direct_candidates: list[str] = []
    for candidate in [normalized, raw_repo_id]:
        candidate = str(candidate).strip()
        if candidate and candidate not in direct_candidates:
            direct_candidates.append(candidate)

    network_error: Exception | None = None

    for candidate in direct_candidates:
        if "/" not in candidate:
            continue
        try:
            api.model_info(candidate, token=token)
            return candidate, [candidate]
        except Exception as exc:
            if is_probable_network_error(exc):
                network_error = exc
                break

    search_terms: list[str] = []
    for term in [normalized, raw_repo_id, raw_repo_id.split("/")[-1], normalized.split("/")[-1]]:
        term = str(term).strip()
        if term and term not in search_terms:
            search_terms.append(term)

    scored: dict[str, tuple[int, int, int, list[str]]] = {}
    attempts_template = [
        {"sort": "downloads", "limit": 12, "full": True, "gated": False},
        {"sort": "downloads", "limit": 12, "full": True},
        {"limit": 12, "full": True},
    ]

    for term in search_terms:
        models_iter = None
        for base_kwargs in attempts_template:
            kwargs = dict(base_kwargs)
            kwargs["search"] = term
            try:
                models_iter = api.list_models(**kwargs)
                break
            except TypeError:
                continue
            except Exception as exc:
                if is_probable_network_error(exc):
                    network_error = exc
                    break
                write_exception_report(f"HF search failed during repo validation for term {term}", exc)
                continue
        if network_error is not None:
            break
        if models_iter is None:
            continue

        for model in models_iter:
            candidate = str(getattr(model, "modelId", None) or getattr(model, "id", None) or "").strip()
            if not candidate:
                continue
            tags = list(getattr(model, "tags", None) or [])
            candidate_low = candidate.lower()
            raw_low = raw_repo_id.lower()
            normalized_low = normalized.lower()
            score = 0
            if candidate_low == raw_low or candidate_low == normalized_low:
                score += 500
            if candidate_low.endswith("/" + raw_low) or candidate_low.endswith("/" + normalized_low):
                score += 300
            if raw_low in candidate_low:
                score += 80
            if normalized_low in candidate_low:
                score += 90
            score += _looks_like_code_model(candidate, tags, raw_repo_id) * 10
            score += 25 if "qwen" in raw_low and candidate_low.startswith("qwen/") else 0
            score += 15 if "coder" in candidate_low else 0
            score += 10 if "instruct" in candidate_low else 0
            downloads = int(getattr(model, "downloads", None) or 0)
            likes = int(getattr(model, "likes", None) or 0)
            previous = scored.get(candidate)
            current = (score, downloads, likes, tags)
            if previous is None or current[:3] > previous[:3]:
                scored[candidate] = current

    if network_error is not None:
        fallback_candidates: list[str] = []
        for candidate in direct_candidates + search_terms:
            candidate = normalize_repo_id_alias(candidate)
            if candidate and candidate not in fallback_candidates:
                fallback_candidates.append(candidate)
        full_candidates = [c for c in fallback_candidates if "/" in c]
        if full_candidates:
            chosen = full_candidates[0]
            if progress_callback:
                progress_callback("Δεν ήταν δυνατός ο online έλεγχος model id. Θα χρησιμοποιηθεί το δηλωμένο πλήρες repo id χωρίς online επιβεβαίωση.")
            write_exception_report("HF network issue during repo validation", network_error)
            return chosen, full_candidates[:5]
        raise RuntimeError(format_network_error_message("έλεγχο του Hugging Face model id", network_error)) from network_error

    if not scored:
        raise RuntimeError(
            f"Δεν βρέθηκε δημόσιο Hugging Face repo για το '{raw_repo_id}'. "
            f"Χρησιμοποίησε πλήρες model id, π.χ. Qwen/Qwen2.5-Coder-1.5B."
        )

    ranked = sorted(scored.items(), key=lambda kv: (kv[1][0], kv[1][1], kv[1][2]), reverse=True)
    suggestions = [repo for repo, _meta in ranked[:5]]
    best = suggestions[0]
    if progress_callback and best != raw_repo_id:
        progress_callback(f"Το model id '{raw_repo_id}' αντιστοιχίστηκε στο δημόσιο repo '{best}'.")
    return best, suggestions


def model_local_dir(base_dir: Path, repo_id: str) -> Path:
    return base_dir / slugify(repo_id)


def read_local_model_repo_id(local_dir: Path) -> str:
    meta = local_dir / ".studio_model.json"
    if meta.exists():
        try:
            payload = json.loads(meta.read_text(encoding="utf-8"))
            return str(payload.get("repo_id") or "").strip()
        except Exception:
            pass
    cfg = local_dir / "config.json"
    if cfg.exists():
        try:
            payload = json.loads(cfg.read_text(encoding="utf-8"))
            return str(payload.get("_name_or_path") or payload.get("model_type") or local_dir.name)
        except Exception:
            pass
    return local_dir.name


def read_integrity_payload(local_dir: Path) -> dict[str, Any]:
    marker = local_dir / MODEL_INTEGRITY_FILE
    if not marker.exists():
        return {}
    try:
        payload = json.loads(marker.read_text(encoding="utf-8"))
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}


def inspect_local_model_dir(local_dir: Path, expected_repo_id: str | None = None, ignore_in_progress: bool = False) -> dict[str, Any]:
    result: dict[str, Any] = {
        "path": str(local_dir),
        "exists": local_dir.exists(),
        "is_dir": local_dir.is_dir(),
        "complete": False,
        "reason": "Ο φάκελος δεν υπάρχει.",
        "repo_id": "",
        "meta_repo_id": "",
        "config_files": [],
        "tokenizer_files": [],
        "weight_files": [],
        "file_count": 0,
        "in_progress": False,
    }
    if not local_dir.exists() or not local_dir.is_dir():
        return result

    all_files = [p for p in local_dir.rglob("*") if p.is_file()]
    config_files = [name for name in MODEL_CONFIG_CANDIDATES if (local_dir / name).exists()]
    tokenizer_files = [name for name in MODEL_TOKENIZER_CANDIDATES if (local_dir / name).exists()]
    weight_files: list[str] = []
    for pattern in MODEL_WEIGHT_PATTERNS:
        for candidate in local_dir.glob(pattern):
            if candidate.is_file():
                try:
                    rel = str(candidate.relative_to(local_dir))
                except Exception:
                    rel = candidate.name
                weight_files.append(rel)
    weight_files = sorted(set(weight_files))

    meta_repo_id = ""
    meta = local_dir / ".studio_model.json"
    if meta.exists():
        try:
            payload = json.loads(meta.read_text(encoding="utf-8"))
            meta_repo_id = str(payload.get("repo_id") or "").strip()
        except Exception:
            meta_repo_id = ""

    repo_id = meta_repo_id or read_local_model_repo_id(local_dir)
    in_progress = (local_dir / MODEL_DOWNLOAD_IN_PROGRESS_FILE).exists()
    effective_in_progress = in_progress and not ignore_in_progress
    integrity_payload = read_integrity_payload(local_dir)
    integrity_repo_id = str(integrity_payload.get("repo_id") or "").strip()

    complete = bool(config_files and tokenizer_files and weight_files and not effective_in_progress)
    reason_parts: list[str] = []
    if effective_in_progress:
        reason_parts.append("Υπάρχει προηγούμενη ή ατελής λήψη σε εξέλιξη.")
    if not config_files:
        reason_parts.append("Λείπουν αρχεία config.")
    if not tokenizer_files:
        reason_parts.append("Λείπουν αρχεία tokenizer.")
    if not weight_files:
        reason_parts.append("Λείπουν αρχεία βαρών μοντέλου.")
    if expected_repo_id and meta_repo_id and meta_repo_id != expected_repo_id:
        complete = False
        reason_parts.append("Ο τοπικός φάκελος αντιστοιχεί σε διαφορετικό repo id.")
    if expected_repo_id and integrity_repo_id and integrity_repo_id != expected_repo_id:
        complete = False
        reason_parts.append("Το αρχείο ακεραιότητας αντιστοιχεί σε διαφορετικό repo id.")
    if not reason_parts and complete:
        reason_parts.append("Το μοντέλο φαίνεται πλήρες.")

    result.update(
        {
            "repo_id": repo_id,
            "meta_repo_id": meta_repo_id,
            "config_files": config_files,
            "tokenizer_files": tokenizer_files,
            "weight_files": weight_files,
            "file_count": len(all_files),
            "in_progress": in_progress,
            "effective_in_progress": effective_in_progress,
            "complete": complete,
            "reason": " ".join(reason_parts),
        }
    )
    return result


def write_model_integrity_file(local_dir: Path, repo_id: str) -> dict[str, Any]:
    payload = inspect_local_model_dir(local_dir, expected_repo_id=repo_id)
    record = {
        "repo_id": repo_id,
        "validated_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "complete": payload.get("complete", False),
        "reason": payload.get("reason", ""),
        "file_count": payload.get("file_count", 0),
        "config_files": payload.get("config_files", []),
        "tokenizer_files": payload.get("tokenizer_files", []),
        "weight_files": payload.get("weight_files", []),
    }
    (local_dir / MODEL_INTEGRITY_FILE).write_text(json.dumps(record, ensure_ascii=False, indent=2), encoding="utf-8")
    return record


def delete_model_dir_if_incomplete(local_dir: Path, repo_id: str, progress_callback: Callable[[str], None] | None = None) -> dict[str, Any]:
    info = inspect_local_model_dir(local_dir, expected_repo_id=repo_id)
    if info.get("complete"):
        return info
    if local_dir.exists():
        if progress_callback:
            progress_callback(f"Βρέθηκε ελλιπές Μοντέλο Βάσης για το {repo_id}. Ο φάκελος θα διαγραφεί και θα γίνει νέα λήψη.")
        shutil.rmtree(local_dir, ignore_errors=True)
    return info


def list_local_models_embedded(base_dir: Path) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    base_dir.mkdir(parents=True, exist_ok=True)
    for item in sorted(base_dir.iterdir()):
        if not item.is_dir():
            continue
        info = inspect_local_model_dir(item)
        if not info.get("complete"):
            continue
        repo_id = str(info.get("repo_id") or item.name)
        entries.append({
            "label": repo_id,
            "repo_id": repo_id,
            "source": "local",
            "local_dir": str(item),
            "downloads": None,
            "likes": None,
            "gated": False,
            "notes": f"Τοπικός φάκελος: {item}",
        })
    return entries


def _looks_like_code_model(repo_id: str, tags: list[str], term: str) -> int:
    repo_low = repo_id.lower()
    score = 0
    keywords = ["code", "coder", "python", "program", "instruct", "chat"]
    if any(key in repo_low for key in keywords):
        score += 4
    if term and term.lower() in repo_low:
        score += 3
    tag_string = " ".join(tags).lower()
    if any(key in tag_string for key in ["code", "text-generation", "causal-lm", "transformers"]):
        score += 2
    return score


def discover_supported_models_embedded(
    search_terms: list[str],
    limit_per_term: int = 20,
    gated: bool | None = False,
    token: str | None = None,
    progress_callback: Callable[[str], None] | None = None,
) -> list[dict[str, Any]]:
    try:
        from huggingface_hub import HfApi
    except Exception as exc:
        write_exception_report("huggingface_hub import failed", exc)
        if progress_callback:
            progress_callback("⚠ Δεν βρέθηκε το πακέτο huggingface_hub — φορτώνονται cached αποτελέσματα.")
        if MODEL_DISCOVERY_CACHE.exists():
            try:
                return json.loads(MODEL_DISCOVERY_CACHE.read_text(encoding="utf-8"))
            except Exception:
                pass
        return []

    api = HfApi(token=token)
    results: list[dict[str, Any]] = []
    network_error: Exception | None = None
    seen: set[str] = set()
    terms = search_terms or ["coder", "python", "code"]

    for term in terms:
        if progress_callback:
            progress_callback(f"Αναζήτηση για όρο: {term}")
        models_iter = None
        attempts = [
            {"search": term, "sort": "downloads", "direction": -1, "limit": limit_per_term, "full": True, "gated": gated},
            {"search": term, "sort": "downloads", "limit": limit_per_term, "full": True, "gated": gated},
            {"search": term, "sort": "downloads", "limit": limit_per_term, "full": True},
        ]
        last_exc: Exception | None = None
        for kwargs in attempts:
            try:
                models_iter = api.list_models(**kwargs)
                break
            except TypeError:
                continue
            except Exception as exc:
                last_exc = exc
                if is_probable_network_error(exc):
                    network_error = exc
                    break
                continue

        if network_error is not None:
            break

        if models_iter is None:
            if last_exc:
                write_exception_report(f"HF search failed for term {term}", last_exc)
            continue

        for model in models_iter:
            repo_id = str(getattr(model, "modelId", None) or getattr(model, "id", None) or "").strip()
            if not repo_id or repo_id in seen:
                continue
            tags = list(getattr(model, "tags", None) or [])
            is_gated = bool(getattr(model, "gated", False) or ("gated" in tags))
            if gated is False and is_gated:
                continue
            seen.add(repo_id)
            results.append({
                "label": repo_id,
                "repo_id": repo_id,
                "source": "huggingface",
                "downloads": getattr(model, "downloads", None),
                "likes": getattr(model, "likes", None),
                "gated": is_gated,
                "score": _looks_like_code_model(repo_id, tags, term),
                "notes": ", ".join(tags[:8]),
            })

    results.sort(key=lambda x: (x.get("score", 0), x.get("downloads") or 0, x.get("likes") or 0), reverse=True)
    trimmed = []
    seen2: set[str] = set()
    for item in results:
        repo_id = str(item.get("repo_id") or "")
        if repo_id in seen2:
            continue
        seen2.add(repo_id)
        item.pop("score", None)
        trimmed.append(item)
    if network_error is not None:
        write_exception_report("HF network issue during model discovery", network_error)
        if MODEL_DISCOVERY_CACHE.exists():
            if progress_callback:
                progress_callback("Δεν κατέστη δυνατή η online αναζήτηση. Φορτώνονται cached αποτελέσματα.")
            return json.loads(MODEL_DISCOVERY_CACHE.read_text(encoding="utf-8"))
        if progress_callback:
            progress_callback("Δεν κατέστη δυνατή η online αναζήτηση. Θα εμφανιστούν μόνο τοπικά μοντέλα.")
        return []

    if not trimmed and MODEL_DISCOVERY_CACHE.exists():
        return json.loads(MODEL_DISCOVERY_CACHE.read_text(encoding="utf-8"))
    return trimmed


def download_model_snapshot_embedded(
    repo_id: str,
    local_dir: Path,
    token: str | None = None,
    force: bool = False,
    progress_callback: Callable[[str], None] | None = None,
) -> Path:
    try:
        from huggingface_hub import snapshot_download
    except Exception as exc:
        write_exception_report("huggingface_hub import failed during download", exc)
        raise RuntimeError("Δεν είναι διαθέσιμο το πακέτο huggingface_hub.") from exc

    existing_info = inspect_local_model_dir(local_dir, expected_repo_id=repo_id)
    if existing_info.get("complete") and not force:
        if progress_callback:
            progress_callback(f"Το Μοντέλο Βάσης {repo_id} είναι ήδη πλήρες. Δεν απαιτείται νέα λήψη.")
        write_model_integrity_file(local_dir, repo_id)
        return local_dir
    if force or existing_info.get("exists"):
        delete_model_dir_if_incomplete(local_dir, repo_id, progress_callback=progress_callback)

    local_dir.mkdir(parents=True, exist_ok=True)
    download_marker = local_dir / MODEL_DOWNLOAD_IN_PROGRESS_FILE
    download_marker.write_text(json.dumps({"repo_id": repo_id, "started_at": time.strftime("%Y-%m-%d %H:%M:%S")}, ensure_ascii=False, indent=2), encoding="utf-8")

    if progress_callback:
        progress_callback(f"Έναρξη λήψης του {repo_id} ...")
    try:
        snapshot_download(
            repo_id=repo_id,
            local_dir=str(local_dir),
            token=token,
            allow_patterns=[
                "*.json", "*.txt", "*.model", "*.tiktoken", "*.py",
                "*.safetensors", "*.bin", "*.index.json", "*.gguf",
                "*.md", "tokenizer*", "generation_config.json", "special_tokens_map.json"
            ],
            ignore_patterns=["*.msgpack", "*.h5", "*.ot", "*.onnx_data", "*.png", "*.jpg"],
            force_download=force,
        )

        integrity = inspect_local_model_dir(local_dir, expected_repo_id=repo_id, ignore_in_progress=True)
        if not integrity.get("complete"):
            raise RuntimeError(f"Η λήψη ολοκληρώθηκε αλλά το Μοντέλο Βάσης φαίνεται ελλιπές. {integrity.get('reason', '')}")

        (local_dir / ".studio_model.json").write_text(
            json.dumps(
                {
                    "repo_id": repo_id,
                    "downloaded_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "file_count": integrity.get("file_count", 0),
                },
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        write_model_integrity_file(local_dir, repo_id)
        return local_dir
    except Exception as exc:
        write_exception_report(f"Αποτυχία λήψης Μοντέλου Βάσης {repo_id}", exc)
        if is_probable_network_error(exc):
            raise RuntimeError(format_network_error_message(f"λήψη του Μοντέλου Βάσης {repo_id}", exc)) from exc
        raise
    finally:
        if download_marker.exists():
            try:
                download_marker.unlink()
            except Exception:
                pass


def load_local_causal_lm_with_fallbacks(model_dir: Path, torch_module):
    from transformers import AutoModelForCausalLM

    attempts: list[dict[str, Any]] = []
    if torch_module.cuda.is_available():
        attempts.extend([
            {"local_files_only": True, "dtype": "auto", "device_map": "auto", "trust_remote_code": True},
            {"local_files_only": True, "dtype": "auto", "trust_remote_code": True},
            {"local_files_only": True, "trust_remote_code": True},
        ])
    else:
        attempts.extend([
            {"local_files_only": True, "dtype": "auto", "trust_remote_code": True},
            {"local_files_only": True, "trust_remote_code": True},
        ])

    last_exc: Exception | None = None
    for kwargs in attempts:
        try:
            model = AutoModelForCausalLM.from_pretrained(str(model_dir), **kwargs)
            if torch_module.cuda.is_available() and kwargs.get("device_map") is None:
                try:
                    model = model.to("cuda")
                except Exception:
                    pass
            return model
        except Exception as exc:
            last_exc = exc
    if last_exc is not None:
        raise RuntimeError(f"Αποτυχία φόρτωσης μοντέλου: {last_exc}") from last_exc
    raise RuntimeError("Αποτυχία φόρτωσης μοντέλου για άγνωστο λόγο.")


def _hub_detect_base_model_from_dir(model_dir: str) -> str:
    """Scan a local model directory and return the clean HF base model ID.

    Checks (in priority order):
      1. adapter_config.json  →  base_model_name_or_path
      2. config.json          →  _name_or_path
      3. training_args.json   →  model_name_or_path
      4. runtime_config*.json (our own) →  selected_model_repo_id / base_model
      5. Directory name slug  →  reverse-slugify
    """
    d = Path(model_dir) if model_dir else None
    if d is None or not d.is_dir():
        return ""

    candidates: list[str] = []

    def _try_json(path: Path, *keys) -> str:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            for key in keys:
                val = str(data.get(key) or "").strip()
                if val and val != "null":
                    return val
        except Exception:
            pass
        return ""

    # 1. adapter_config.json
    for fname in ("adapter_config.json",):
        p = d / fname
        if p.exists():
            v = _try_json(p, "base_model_name_or_path")
            if v:
                candidates.append(v)

    # 2. config.json → _name_or_path
    p = d / "config.json"
    if p.exists():
        v = _try_json(p, "_name_or_path", "base_model_name_or_path")
        if v:
            candidates.append(v)

    # 3. training_args.json
    for fname in ("training_args.json", "train_args.json"):
        p = d / fname
        if p.exists():
            v = _try_json(p, "model_name_or_path", "base_model")
            if v:
                candidates.append(v)

    # 4. Our own runtime config files in the project root
    try:
        for cfg in sorted(RUNTIME_CONFIG_DIR.glob("runtime_*.json"), reverse=True):
            v = _try_json(cfg, "selected_model_repo_id", "base_model")
            if v:
                candidates.append(v)
                break
    except Exception:
        pass

    # 5. Fallback: reverse-slugify the directory name
    candidates.append(d.name)

    # Pick the first that looks like a valid HF model ID after sanitization
    for raw in candidates:
        clean = _hub_sanitize_base_model(raw)
        # Valid HF ID: "namespace/name" with no path separators
        if "/" in clean and not any(c in clean for c in ("\\", ":")):
            ns, nm = clean.split("/", 1)
            if re.match(r"^[\w\-.]+$", ns) and re.match(r"^[\w\-.]+$", nm):
                return clean

    return ""

def _hub_sanitize_base_model(raw: str) -> str:
    """Convert a local path or slugified dir name to a clean HF model ID.

    Examples:
      C:/Base_Models/qwen__qwen2.5-coder-1.5b  →  Qwen/qwen2.5-coder-1.5b
      /home/user/Base_Models/meta-llama__llama-2-7b  →  meta-llama/llama-2-7b-hf
      Qwen/Qwen2.5-Coder-1.5B             →  (unchanged)
      unknown                                        →  (unchanged)
    """
    v = str(raw or "").strip()
    if not v or v == "unknown":
        return v

    # Already looks like a valid HF model ID (contains / but not a path separator sequence)
    if "/" in v and not any(c in v for c in ("\\", ":", "\n")) and len(v.split("/")) == 2:
        ns, name = v.split("/", 1)
        # Quick sanity: namespace should not contain spaces or path chars
        if re.match(r"^[\w\-.]+$", ns) and re.match(r"^[\w\-.]+$", name):
            return v

    # Extract the basename (last path component)
    # Works for both Windows (\) and Unix (/) paths
    basename = re.split(r"[\\/]", v)[-1].strip()
    if not basename:
        return v

    # Reverse-slugify: "qwen__qwen2.5-coder-1.5b-instruct" → "Qwen/Qwen2.5-Coder-1.5B"
    # The slugify() function in this codebase replaces "/" with "__"
    if "__" in basename:
        parts = basename.split("__", 1)
        namespace = parts[0]
        model_name = parts[1] if len(parts) > 1 else basename

        # Known namespace capitalisation
        ns_map = {
            "qwen": "Qwen",
            "meta-llama": "meta-llama",
            "mistralai": "mistralai",
            "google": "google",
            "microsoft": "microsoft",
            "tiiuae": "tiiuae",
            "bigcode": "bigcode",
            "codellama": "codellama",
            "deepseek-ai": "deepseek-ai",
        }
        ns_clean = ns_map.get(namespace.lower(), namespace)
        return f"{ns_clean}/{model_name}"

    # No double-underscore: try to use as-is if it looks like a model name
    return basename


class _HubWorker(QObject):
    """Module-level worker for Hub operations.
    Must be at module scope — Qt Signal metaclass cannot process classes
    defined inside functions or methods.
    """
    finished = Signal(object)
    error    = Signal(str)
    progress = Signal(str)

    def __init__(self, fn, args: tuple) -> None:
        super().__init__()
        self._fn   = fn
        self._args = args

    def run(self) -> None:
        try:
            result = self._fn(*self._args, progress_callback=self.progress.emit)
            self.finished.emit(result)
        except BaseException as exc:  # catch SystemExit / KeyboardInterrupt too
            tb = "".join(traceback.format_exception(type(exc), exc, exc.__traceback__))
            try:
                self.error.emit(f"{type(exc).__name__}: {exc}\n\n{tb}")
            except Exception:
                pass


class _HubRefreshBridge(QObject):
    """Signal bridge for Python-threaded Hub repo refreshes.

    We intentionally avoid QThread for repo list refresh because a QThread object
    getting destroyed while still running can terminate the whole application.
    A plain daemon Python thread plus queued Qt signals is more forgiving here.
    """
    finished = Signal(object, object)
    error    = Signal(object, str)
    progress = Signal(object, str)

    def __init__(self) -> None:
        super().__init__(None)


class BackgroundWorker(QObject):
    finished = Signal(object)
    error = Signal(str)
    progress = Signal(str)

    def __init__(self, fn: Callable[..., Any], *args: Any, **kwargs: Any) -> None:
        super().__init__()
        self.fn = fn
        self.args = args
        self.kwargs = kwargs

    def run(self) -> None:
        try:
            result = self.fn(*self.args, progress_callback=self.progress.emit, **self.kwargs)
            self.finished.emit(result)
        except BaseException as exc:  # catch SystemExit / KeyboardInterrupt too
            tb_str = "".join(traceback.format_exception(type(exc), exc, exc.__traceback__))
            try:
                self.error.emit(f"{type(exc).__name__}: {exc}\n\n{tb_str}")
            except Exception:
                pass


class CommandStreamWorker(QObject):
    line = Signal(str)          # kept for compatibility
    batch_lines = Signal(str)   # multi-line batch (newline-separated), 100 ms cadence
    finished = Signal(int)
    started = Signal()

    def __init__(self, command: list[str], cwd: str | Path | None = None) -> None:
        super().__init__()
        self.command = command
        self.cwd = str(cwd or PROJECT_ROOT)
        self.process: subprocess.Popen[str] | None = None
        self._stop_requested = False

    def run(self) -> None:
        self.started.emit()
        creationflags = 0
        start_new_session = False
        if os.name == "nt":
            creationflags = subprocess.CREATE_NO_WINDOW  # type: ignore[attr-defined]
            creationflags |= getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
        else:
            start_new_session = True
        self.process = subprocess.Popen(
            self.command,
            cwd=self.cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
            universal_newlines=True,
            encoding="utf-8",
            errors="replace",
            creationflags=creationflags,
            start_new_session=start_new_session,
        )
        if self.process.stdout is None:
            self.finished.emit(-1)
            return
        for raw_line in self.process.stdout:
            self.line.emit(raw_line.rstrip())
            if self._stop_requested:
                break
        if self._stop_requested and self.process.poll() is None:
            self._terminate()
        return_code = self.process.wait()
        self.finished.emit(return_code)

    def stop(self) -> None:
        self._stop_requested = True
        self._terminate()

    def _terminate(self) -> None:
        if not self.process or self.process.poll() is not None:
            return
        _studio_terminate_process_tree(self.process)


class PipelineStudioGUI(QMainWindow):
    def __init__(self) -> None:
        super().__init__()
        self.setWindowTitle(APP_TITLE)
        self.resize(1456, 832)
        self.setMinimumSize(1080, 720)
        self._job_thread: QThread | None = None
        self._job_worker: CommandStreamWorker | BackgroundWorker | None = None
        self._runtime_config_path: Path | None = None
        self._current_process: CommandStreamWorker | None = None
        self._model_entries: list[dict[str, Any]] = []
        self._online_entries: list[dict[str, Any]] = []
        self._local_entries: list[dict[str, Any]] = []
        self._background_success_callback: Callable[[object], None] | None = None
        self._background_error_callback: Callable[[str], None] | None = None
        self._theme_name = DEFAULT_THEME
        self._hf_auth_notice_shown = False
        self._session_log_path = LOGS_DIR / f"session_{time.strftime('%Y%m%d_%H%M%S')}.log"

        # Hub log: initialize immediately so crashes are always captured
        _hub_ts = time.strftime('%Y%m%d_%H%M%S')
        self._HUB_LOG_FILE = LOGS_DIR / f"hub_{_hub_ts}.log"

        BASE_MODELS_DIR.mkdir(parents=True, exist_ok=True)
        RUNTIME_CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        LOGS_DIR.mkdir(parents=True, exist_ok=True)
        ARTIFACTS_DIR.mkdir(parents=True, exist_ok=True)

        self._build_state()
        self._build_ui()
        self._load_model_presets()
        self._refresh_local_models()
        self._update_selected_model_state()
        self.log("Η εφαρμογή ξεκίνησε επιτυχώς.")
        self._log_hf_auth_status_once()
        # Write startup entry to hub log immediately (before any Hub operation)
        try:
            _hub_log_path = self._hub_ensure_log_file()
            with open(_hub_log_path, "a", encoding="utf-8") as _f:
                _f.write(
                    f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] [INFO ] "
                    f"Εφαρμογή εκκίνησε — hub log ενεργό.\n"
                )
                _f.flush()
                try:
                    os.fsync(_f.fileno())
                except (OSError, AttributeError):
                    pass
            self.log(f"[Hub] 📋 Hub log: {_hub_log_path}")
        except Exception:
            pass
        self.log(f"Ριζικός φάκελος project: {PROJECT_ROOT}")
        self.log(f"Κατάλογος Base_Models: {BASE_MODELS_DIR}")
        QTimer.singleShot(900, self.search_models_on_start)

        # Live clock in status bar
        self._clock_timer = QTimer(self)
        self._clock_timer.setInterval(1000)
        self._clock_timer.timeout.connect(self._tick_clock)
        self._clock_timer.start()
        self._tick_clock()

    # ---------- state ----------
    def _build_state(self) -> None:
        self.python_exec = sys.executable
        self.config_path = str(DEFAULT_SAFE_CONFIG if DEFAULT_SAFE_CONFIG.exists() else DEFAULT_CONFIG)
        self.custom_model_id = ""
        self.profile_name = PROFILE_SAFE
        self.include_gated = False
        self.auto_search_on_start = True
        self.auto_prepare_model = True
        self._last_model_autotune_signature: tuple[Any, ...] | None = None

    # ---------- UI ----------
    def _build_ui(self) -> None:
        self.apply_theme(DEFAULT_THEME)
        self._build_menu()
        self._build_status_bar()

        shell = QWidget()
        shell_layout = QVBoxLayout(shell)
        shell_layout.setContentsMargins(0, 0, 0, 0)

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)

        central = QWidget()
        root = QHBoxLayout(central)
        root.setContentsMargins(16, 16, 16, 16)
        root.setSpacing(16)

        sidebar = self._wrap_in_scroll(self._build_sidebar(), min_width=250, max_width=320)
        root.addWidget(sidebar, 0)

        main_panel = QFrame()
        main_panel.setObjectName("MainPanel")
        main_layout = QVBoxLayout(main_panel)
        main_layout.setContentsMargins(18, 18, 18, 18)
        main_layout.setSpacing(14)

        main_layout.addWidget(self._build_hero_card())
        main_layout.addWidget(self._build_info_tiles())

        self.tabs = QTabWidget()
        self.tabs.setUsesScrollButtons(True)
        self.tabs.addTab(self._build_training_tab(), "📚  Εκπαίδευση")
        self.tabs.addTab(self._build_inference_tab(), "🔬  Δοκιμή Μοντέλου")
        self.tabs.addTab(self._build_hub_tab(), "🤗  Hub Manager")
        self.tabs.addTab(self._build_help_tab(), "❓  Βοήθεια")
        main_layout.addWidget(self.tabs, 1)

        root.addWidget(main_panel, 1)
        scroll.setWidget(central)
        shell_layout.addWidget(scroll)
        self.setCentralWidget(shell)
        self._window_scroll = scroll

    def _build_menu(self) -> None:
        menu_bar = self.menuBar()

        file_menu = menu_bar.addMenu("Αρχείο")
        self._add_action(file_menu, "Επιλογή Python interpreter", self.browse_python)
        self._add_action(file_menu, "Επιλογή config JSON", self.browse_config)
        self._add_action(file_menu, "Άνοιγμα φακέλου Μοντέλων Βάσης", self.open_model_folder)
        self._add_action(file_menu, "Άνοιγμα logs", self.open_logs_folder)
        self._add_action(file_menu, "Άνοιγμα φακέλου artifacts", lambda: self.open_path(ARTIFACTS_DIR))
        file_menu.addSeparator()
        self._add_action(file_menu, "Έξοδος\tCtrl+Q", self.close).setShortcut("Ctrl+Q")

        run_menu = menu_bar.addMenu("Εκτέλεση")
        a = self._add_action(run_menu, "Auto: αναζήτηση → λήψη → config → pipeline\tCtrl+Shift+R",
                             self.auto_prepare_and_run_pipeline)
        a.setShortcut("Ctrl+Shift+R")
        b = self._add_action(run_menu, "Τρέξε όλο το pipeline\tCtrl+R", self.run_full_pipeline)
        b.setShortcut("Ctrl+R")
        c = self._add_action(run_menu, "Τερματισμός τρέχουσας διεργασίας\tCtrl+K", self.stop_current_job)
        c.setShortcut("Ctrl+K")

        tools_menu = menu_bar.addMenu("Εργαλεία")
        d = self._add_action(tools_menu, "Αναζήτηση online μοντέλων\tCtrl+F",
                             lambda: self.refresh_online_models(manual=True))
        d.setShortcut("Ctrl+F")
        self._add_action(tools_menu, "Λήψη Μοντέλου Βάσης", self.download_selected_model)
        self._add_action(tools_menu, "Δημιουργία ενεργού config", self.generate_runtime_config)
        self._add_action(tools_menu, "Άνοιγμα logs", self.open_logs_folder)

        theme_menu = menu_bar.addMenu("Θέμα")
        self._add_action(theme_menu, "☀ Light", lambda: self.apply_theme("light"))
        self._add_action(theme_menu, "🌙 Dark", lambda: self.apply_theme("dark"))

        help_menu = menu_bar.addMenu("Βοήθεια")
        self._add_action(help_menu, "Γρήγορη εκκίνηση\tF1", self.show_quick_start).setShortcut("F1")
        self._add_action(help_menu, "Αναλυτικές οδηγίες", self.open_help_window)
        self._add_action(help_menu, "Σχετικά", self.show_about)

    def _build_status_bar(self) -> None:
        # Χρησιμοποιούμε custom widget αντί για QStatusBar showMessage,
        # ώστε το copyright να φαίνεται πάντα στο κέντρο.
        self.status = QStatusBar()
        self.setStatusBar(self.status)
        self.status.setSizeGripEnabled(True)

        # -- Αριστερά: μήνυμα κατάστασης --
        self._status_msg_lbl = QLabel("Έτοιμο")
        self._status_msg_lbl.setStyleSheet("font-size:14px; padding: 0 8px;")
        self._status_msg_lbl.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        self.status.addWidget(self._status_msg_lbl, 1)

        # -- Κέντρο: copyright (permanent, ανάμεσα σε spacers) --
        self._status_copyright_lbl = QLabel("© Ευάγγελος Πεφάνης")
        self._status_copyright_lbl.setStyleSheet(
            "font-size:14px; padding: 0 16px; color:#5b7698; font-style:italic; font-weight:600;"
        )
        self._status_copyright_lbl.setAlignment(Qt.AlignCenter)
        self.status.addPermanentWidget(self._status_copyright_lbl, 2)

        # -- Δεξιά: Μοντέλο / Profile / Ώρα --
        self._status_model_lbl = QLabel("Μοντέλο: —")
        self._status_model_lbl.setStyleSheet("font-size:14px; padding: 0 8px;")
        self._status_model_lbl.setToolTip("Τρέχον επιλεγμένο Μοντέλο Βάσης")
        self.status.addPermanentWidget(self._status_model_lbl)

        self._status_gpu_lbl = QLabel("Profile: —")
        self._status_gpu_lbl.setStyleSheet("font-size:14px; padding: 0 8px;")
        self._status_gpu_lbl.setToolTip("Ενεργό GPU profile")
        self.status.addPermanentWidget(self._status_gpu_lbl)

        self._status_clock_lbl = QLabel(time.strftime("%H:%M:%S"))
        self._status_clock_lbl.setStyleSheet("font-size:14px; padding: 0 8px; font-family: monospace;")
        self._status_clock_lbl.setToolTip("Τρέχουσα ώρα")
        self.status.addPermanentWidget(self._status_clock_lbl)

    def _set_status_message(self, msg: str, timeout: int = 0) -> None:
        """Ενημερώνει το αριστερό label της status bar (αντί για showMessage)."""
        try:
            self._status_msg_lbl.setText(msg)
            if timeout > 0:
                QTimer.singleShot(timeout, lambda: self._status_msg_lbl.setText("Έτοιμο"))
        except Exception:
            try:
                self.status.showMessage(msg, timeout)
            except Exception:
                pass

    def _get_status_message(self) -> str:
        """Επιστρέφει το τρέχον μήνυμα της status bar."""
        try:
            return self._status_msg_lbl.text()
        except Exception:
            return ""

    def _tick_clock(self) -> None:
        try:
            if hasattr(self, "_status_clock_lbl"):
                self._status_clock_lbl.setText(time.strftime("%H:%M:%S"))
        except Exception:
            pass

    def _update_status_bar_labels(self) -> None:
        """Update the permanent status bar labels with current model/GPU info."""
        try:
            current = self._current_selected_model()
            if current:
                repo = current.get("repo_id") or "—"
                short = repo.split("/")[-1] if "/" in repo else repo
                local = "✓ τοπικό" if current.get("local_dir") else "☁ hub"
                self._status_model_lbl.setText(f"Μοντέλο: {short} ({local})")
            else:
                self._status_model_lbl.setText("Μοντέλο: —")
        except Exception:
            pass
        try:
            profile = getattr(self, "profile_combo", None)
            if profile is not None:
                text = profile.currentText()
                short_profile = text[:20] + "…" if len(text) > 20 else text
                self._status_gpu_lbl.setText(f"Profile: {short_profile}")
        except Exception:
            pass

