        for _tb in (self.hf_token_toggle_btn, self.hf_token_apply_btn, self.hf_token_clear_btn):
            _tb.setSizePolicy(QSizePolicy.Minimum, QSizePolicy.Fixed)
        token_row = QHBoxLayout()
        token_row.setSpacing(6)
        token_row.addWidget(token_lbl)
        token_row.addWidget(self.hf_token_edit, 1)
        token_row.addWidget(self.hf_token_toggle_btn)
        token_row.addWidget(self.hf_token_apply_btn)
        token_row.addWidget(self.hf_token_clear_btn)
        lay.addLayout(token_row)
        self.hf_token_status_label.setStyleSheet("font-size:12px; color:#5b7698;")
        lay.addWidget(self.hf_token_status_label)

        buttons = QHBoxLayout()
        preview_btn = QPushButton("👁  Προεπισκόπηση config")
        preview_btn.setToolTip("Εμφανίζει το template config JSON.")
