    def fill_demo_prompt(self) -> None:
        self.infer_prompt.setPlainText(
            "Write a Python function called `parse_csv_to_records` that:\n"
            "1. Accepts a file path as a string parameter\n"
            "2. Reads a CSV file using the `csv` module (no pandas)\n"
            "3. Returns a list of dictionaries, one per row\n"
            "4. Handles missing values by replacing them with None\n"
            "5. Raises a FileNotFoundError with a clear message if the file doesn't exist\n\n"
            "Include type hints and a brief docstring."
        )

    def clear_logs(self) -> None:
        try:
            self.logs.clear()
        except Exception:
            pass
        # Clear all registered log views
        for v in getattr(self, "_log_views", []):
            try:
                v.clear()
            except Exception:
                pass
        # Clear internal buffer so filter also resets
        if hasattr(self, "_log_buffer"):
            self._log_buffer.clear()
        try:
            self._set_status_message("Τα logs καθαρίστηκαν.", 2000)
        except Exception:
            pass

    def copy_logs(self) -> None:
        text = "\n".join(getattr(self, "_log_buffer", []))
        if not text:
            try:
                text = self.logs.toPlainText()
            except Exception:
                text = ""
        QApplication.clipboard().setText(text)
        self._set_status_message(f"✓ Αντιγράφηκαν {len(text.splitlines())} γραμμές logs.", 3000)

    def log(self, message: str) -> None:
        timestamp = time.strftime("%H:%M:%S")
        line = f"[{timestamp}] {message}"
        try:
            self.logs.appendPlainText(line)
            # Respect the autoscroll toggle if present
            autoscroll = getattr(self, "_log_autoscroll", None)
            if autoscroll is None or autoscroll.isChecked():
                cursor = self.logs.textCursor()
                cursor.movePosition(QTextCursor.End)
                self.logs.setTextCursor(cursor)
                self.logs.ensureCursorVisible()
        except Exception:
            pass
        try:
            append_text_line(self._session_log_path, line)
        except Exception:
            pass

    def apply_theme(self, name: str) -> None:
        self._theme_name = "dark" if name == "dark" else "light"
        qss = DARK_QSS if self._theme_name == "dark" else LIGHT_QSS
        self.setStyleSheet(qss)
        # Propagate to help window — also refresh HTML for dark/light colours
        try:
            w = getattr(self, "_help_window", None)
            if w and w.isVisible():
                w.setStyleSheet(qss)
                try:
                    # Re-render help HTML with new theme palette
                    view = w.centralWidget().findChild(QTextBrowser)
                    if view:
                        view.setHtml(self._build_help_html())
                except Exception:
                    pass
        except Exception:
            pass
        # Propagate to all chat windows via their apply_theme()
        # (handles inline-styled widgets + HTML bubble re-render)
        for win in list(getattr(self, "_chat_windows", [])):
            try:
                if hasattr(win, "apply_theme"):
                    win.apply_theme(self._theme_name)
                elif win.isVisible():
                    win.setStyleSheet(qss)
            except Exception:
                pass
        try:
            self._set_status_message(
                f"Θέμα: {'🌙 Dark' if self._theme_name == 'dark' else '☀ Light'}", 2000
            )
        except Exception:
            pass

    def _quote_part(self, part: str) -> str:
        return shlex.quote(part) if os.name != "nt" else f'"{part}"' if " " in part else part

    def open_help_window(self) -> None:
        # Reuse existing window if already open
        try:
            w = getattr(self, "_help_window", None)
            if w and w.isVisible():
                w.raise_()
                w.activateWindow()
                return
        except Exception:
            pass

        win = QMainWindow(self)
        win.setWindowTitle("📖 Αναλυτικές οδηγίες χρήσης — LLM Training Studio")
        win.resize(1060, 820)
        win.setStyleSheet(self.styleSheet())
        win.setMinimumSize(720, 500)

        container = QWidget()
        lay = QVBoxLayout(container)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)

        # ── View ────────────────────────────────────────────────────────
        view = QTextBrowser()
        view.setOpenExternalLinks(True)
        view.setFrameShape(QFrame.NoFrame)
        view.setContentsMargins(0, 0, 0, 0)
        try:
            help_html = self._build_help_html()
            view.setHtml(help_html)
        except Exception:
            view.setPlainText(HELP_TEXT)
        lay.addWidget(view, 1)

        # ── Bottom bar ──────────────────────────────────────────────────
        _dark = getattr(self, "_theme_name", "light") == "dark"
