def append_log(message: str) -> None:
    line = f"[{time.strftime('%H:%M:%S')}] {message}"
    print(line, flush=True)  # flush=True ensures subprocess pipe sees lines immediately
    try:
        append_text_line(LOGS_DIR / "embedded_pipeline.log", line)
    except Exception:
        pass

def load_config(path: str | Path) -> dict[str, Any]:
    cfg_path = Path(path).resolve()
    if not cfg_path.exists():
        raise FileNotFoundError(f"Δεν βρέθηκε το config: {cfg_path}")
    return json.loads(cfg_path.read_text(encoding="utf-8"))

def stage_output_dir(config: dict[str, Any], stage_key: str) -> Path:
    artifacts = Path(config.get("artifacts_dir") or ARTIFACTS_DIR)
    artifacts.mkdir(parents=True, exist_ok=True)
    folder = artifacts / {
        "collect": "01_collect",
        "preprocess": "02_preprocess",
        "cpt": "03_cpt",
        "build_sft": "04_build_sft",
        "sft": "05_sft",
        "eval": "06_eval",
        "export": "final_model",
    }.get(stage_key, stage_key)
    folder.mkdir(parents=True, exist_ok=True)
    return folder

