def _studio_iter_collect_file_candidates(config: dict[str, Any]) -> list[Path]:
    config = _studio_ensure_runtime_defaults(config)
    dataset = config.get("dataset", {})
    project_root = Path(config.get("project_root") or PROJECT_ROOT).resolve()
    include_ext = {str(x).lower() for x in dataset.get("source_extensions") or []}
    exclude_dirs = {str(x).strip().lower() for x in dataset.get("exclude_dirs") or []}
    max_bytes = int(dataset.get("max_file_size_bytes") or 0)
    candidates: list[Path] = []

    def _include_file(path: Path) -> bool:
        try:
            if not path.is_file():
                return False
        except Exception:
            return False
        if include_ext and path.suffix.lower() not in include_ext:
            return False
        parts = {part.lower() for part in path.parts}
        if exclude_dirs and any(part in exclude_dirs for part in parts):
            return False
        try:
            if max_bytes > 0 and path.stat().st_size > max_bytes:
                return False
        except Exception:
            return False
        return True

    for raw_dir in dataset.get("source_dirs") or []:
        base_dir = Path(raw_dir)
        if not base_dir.is_absolute():
            base_dir = (project_root / base_dir).resolve()
        if not base_dir.exists() or not base_dir.is_dir():
            continue
        for root, dirs, files in os.walk(base_dir):
            dirs[:] = [d for d in dirs if d.lower() not in exclude_dirs]
            root_path = Path(root)
            for name in files:
                file_path = root_path / name
                if _include_file(file_path):
                    candidates.append(file_path)

    for raw_file in dataset.get("source_files") or []:
        path = Path(raw_file)
        if not path.is_absolute():
            path = (project_root / path).resolve()
        if _include_file(path):
            candidates.append(path)

    for pattern in dataset.get("source_globs") or []:
        try:
            for path in project_root.glob(str(pattern)):
                if _include_file(path):
                    candidates.append(path)
        except Exception:
            continue

    deduped: list[Path] = []
    seen: set[str] = set()
    for path in candidates:
        try:
            key = str(path.resolve())
        except Exception:
            key = str(path)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(path)
    return deduped

def collect_training_sources(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults(config)
    dataset = config.get("dataset", {})
    project_root = Path(config.get("project_root") or PROJECT_ROOT).resolve()
    collect_dir = Path(dataset.get("collect_dir") or (ARTIFACTS_DIR / "01_collect"))
    raw_dir = collect_dir / "raw_sources"
    collect_dir.mkdir(parents=True, exist_ok=True)
    raw_dir.mkdir(parents=True, exist_ok=True)

    records: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []

    for file_path in _studio_iter_collect_file_candidates(config):
        try:
            text = _studio_normalize_space(_studio_read_text_file(file_path))
            if len(text) < 20:
                skipped.append({"path": str(file_path), "reason": "too_short"})
                continue
            rel_path = str(file_path.resolve().relative_to(project_root)) if str(file_path.resolve()).startswith(str(project_root)) else str(file_path)
            record_id = _studio_hash_text(rel_path + "|" + text[:500])
            record = {
                "id": f"file_{record_id[:16]}",
                "source_kind": "file",
                "source_path": rel_path,
                "title": file_path.name,
                "text": text,
                "char_count": len(text),
                "sha1": _studio_hash_text(text),
            }
            records.append(record)
            (raw_dir / f"{record['id']}.txt").write_text(text, encoding="utf-8")
            append_log(f"[collect] + αρχείο: {rel_path}")
        except Exception as exc:
            skipped.append({"path": str(file_path), "reason": str(exc)})
            append_log(f"[collect] ! αποτυχία αρχείου: {file_path}")

    configured_web_entries = list(dataset.get("source_urls") or [])
    discovered_web_entries: list[dict[str, Any]] = []
    if bool(dataset.get("auto_discover_web_sources", True)):
        discovered_web_entries = _studio_discover_web_sources(config)
        if discovered_web_entries:
            append_log(f"[collect] i βρέθηκαν {len(discovered_web_entries)} web πηγές από online αναζήτηση")
    merged_web_entries = _studio_merge_source_url_entries(configured_web_entries + discovered_web_entries)
    require_language_match = bool(dataset.get("web_discovery_require_language_match", True))
    web_timeout_sec = max(5, int(dataset.get("web_discovery_timeout_sec") or 20))

    for index, entry in enumerate(merged_web_entries, start=1):
        url = entry["url"]
        expected_language = str(entry.get("language") or "").strip().lower()
        try:
            fetched = _studio_fetch_web_text(url, timeout_sec=web_timeout_sec)
            text = fetched.get("text") or ""
            if len(text) < 50:
                raise RuntimeError("κενό ή πολύ μικρό περιεχόμενο")
            detected_language = _studio_guess_language(text)
            if require_language_match and expected_language in {"el", "en"}:
                if expected_language == "el" and detected_language not in {"el", "mixed"}:
                    raise RuntimeError("η ανακαλυμμένη πηγή δεν φαίνεται να είναι ελληνική")
            title = str(entry.get("title") or fetched.get("title") or url).strip() or url
            record_id = _studio_hash_text(url + "|" + text[:500])
            record = {
                "id": f"web_{record_id[:16]}",
                "source_kind": "web",
                "source_url": url,
                "title": title,
                "text": text,
                "char_count": len(text),
                "sha1": _studio_hash_text(text),
                "language": detected_language,
                "discovered_query": entry.get("discovered_query") or "",
            }
            records.append(record)
            (raw_dir / f"{record['id']}.txt").write_text(text, encoding="utf-8")
            if entry.get("discovered_query"):
                append_log(f"[collect] + web(discovery/{expected_language or detected_language}): {title}")
            else:
                append_log(f"[collect] + web: {title}")
        except Exception as exc:
            skipped.append({
                "url": url,
                "reason": str(exc),
                "expected_language": expected_language,
                "query": entry.get("discovered_query") or "",
            })
            append_log(f"[collect] ! αποτυχία web πηγής: {url}")

    corpus_path = collect_dir / "collected_corpus.jsonl"
    _studio_jsonl_dump(corpus_path, records)
    manifest = {
        "stage": "collect",
        "status": "completed" if records else "empty",
        "records": len(records),
        "skipped": len(skipped),
        "configured_web_sources": len(configured_web_entries),
        "discovered_web_sources": len(discovered_web_entries),
        "collect_dir": str(collect_dir.resolve()),
        "corpus_path": str(corpus_path.resolve()),
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    (collect_dir / "collect_manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    (collect_dir / "skipped_files.json").write_text(json.dumps(skipped, ensure_ascii=False, indent=2), encoding="utf-8")
    report_path = collect_dir / "collect_report.json"
    report_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    return manifest


class _StudioTokenDataset:
    def __init__(self, items: list[dict[str, Any]]) -> None:
        self.items = items
    def __len__(self) -> int:
        return len(self.items)
    def __getitem__(self, idx: int) -> dict[str, Any]:
        return self.items[idx]


def _studio_expected_base_repo_id(config: dict[str, Any]) -> str:
    repo_id = str(config.get("selected_model_repo_id") or "").strip()
    if repo_id:
        return normalize_repo_id_alias(repo_id)
    base_model_value = str(config.get("base_model") or "").strip()
    if base_model_value and not Path(base_model_value).exists():
        return normalize_repo_id_alias(base_model_value)
    return ""


def _studio_raise_model_mismatch(path: Path, info: dict[str, Any], expected_repo_id: str) -> None:
    detected_repo = str(info.get("meta_repo_id") or info.get("repo_id") or path.name).strip() or path.name
    reason = str(info.get("reason") or "").strip()
    raise RuntimeError(
        "Το επιλεγμένο Μοντέλο Βάσης δεν ταιριάζει με το repo του runtime config. "
        f"Αναμενόταν: {expected_repo_id} | Βρέθηκε στον φάκελο {path}: {detected_repo}. "
        "Διέγραψε τον λάθος φάκελο από το Base_Models ή ξανακατέβασε το σωστό μοντέλο από το GUI. "
        + (f"Λεπτομέρειες: {reason}" if reason else "")
    )


def _studio_resolve_complete_base_model_dir(config: dict[str, Any]) -> Path:
    expected_repo_id = _studio_expected_base_repo_id(config)
    selected_local = str(config.get("selected_model_local_dir") or "").strip()
    if selected_local:
        candidate = Path(selected_local)
        selected_info = inspect_local_model_dir(candidate, expected_repo_id=expected_repo_id or None)
        if selected_info.get("complete"):
            return candidate.resolve()
        if candidate.exists() and expected_repo_id and str(selected_info.get("repo_id") or "").strip() and str(selected_info.get("repo_id") or "").strip() != expected_repo_id:
            _studio_raise_model_mismatch(candidate, selected_info, expected_repo_id)
    base_model_value = str(config.get("base_model") or config.get("selected_model_repo_id") or "").strip()
    if not base_model_value:
        raise RuntimeError("Δεν έχει οριστεί Μοντέλο Βάσης στο config.")
    base_candidate = Path(base_model_value)
    if base_candidate.exists():
        base_info = inspect_local_model_dir(base_candidate, expected_repo_id=expected_repo_id or None)
        if base_info.get("complete"):
            return base_candidate.resolve()
        if expected_repo_id and str(base_info.get("repo_id") or "").strip() and str(base_info.get("repo_id") or "").strip() != expected_repo_id:
            _studio_raise_model_mismatch(base_candidate, base_info, expected_repo_id)
    local_key = expected_repo_id or normalize_repo_id_alias(base_model_value)
    local_dir = model_local_dir(BASE_MODELS_DIR, local_key)
    local_info = inspect_local_model_dir(local_dir, expected_repo_id=expected_repo_id or None)
    if local_info.get("complete"):
        return local_dir.resolve()
    if local_dir.exists() and expected_repo_id and str(local_info.get("repo_id") or "").strip() and str(local_info.get("repo_id") or "").strip() != expected_repo_id:
        _studio_raise_model_mismatch(local_dir, local_info, expected_repo_id)
    raise RuntimeError(f"Δεν βρέθηκε πλήρες Μοντέλο Βάσης για training: {base_model_value}")

def _studio_try_read_json(path: Path) -> dict[str, Any]:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}

def _studio_has_adapter_files(path: Path) -> bool:
    return ((path / "adapter_config.json").exists() and any(path.glob("adapter_model*.safetensors"))) or any(path.glob("adapter_model*.bin"))

def _studio_stage_model_dir(config: dict[str, Any], stage_key: str) -> Path:
    return stage_output_dir(config, stage_key)

def _studio_resolve_training_start(config: dict[str, Any], stage_key: str) -> tuple[Path, Path | None, str]:
    config = _studio_ensure_runtime_defaults(config)
    base_dir = _studio_resolve_complete_base_model_dir(config)
    if stage_key == "cpt":
        return base_dir, None, "base_model"

    cpt_dir = _studio_stage_model_dir(config, "cpt")
    if _studio_has_adapter_files(cpt_dir):
        return base_dir, cpt_dir.resolve(), "cpt_adapter"
    if inspect_local_model_dir(cpt_dir).get("complete"):
        return cpt_dir.resolve(), None, "cpt_full_model"
    return base_dir, None, "base_model"


def _studio_load_tokenizer_for_runtime(requested_dir: Path, base_dir: Path | None = None):
    stack = _studio_import_training_stack()
    AutoTokenizer = stack["AutoTokenizer"]
    attempts = []
    for candidate in [requested_dir, base_dir]:
        if candidate is None:
            continue
        attempts.extend([
            (candidate, {"local_files_only": True, "trust_remote_code": True}),
            (candidate, {"local_files_only": True, "trust_remote_code": True, "use_fast": False}),
            (candidate, {"local_files_only": True}),
        ])
    last_exc = None
    for candidate, kwargs in attempts:
        try:
            tok = AutoTokenizer.from_pretrained(str(candidate), **kwargs)
            if getattr(tok, "pad_token_id", None) is None and getattr(tok, "eos_token", None):
                tok.pad_token = tok.eos_token
            _studio_align_padding_for_generation(tok)
            return tok
        except Exception as exc:
            last_exc = exc
    raise RuntimeError(f"Αποτυχία φόρτωσης tokenizer: {last_exc}") from last_exc


def _studio_align_padding_for_generation(tokenizer, model: Any | None = None) -> int | None:
    pad_token_id = getattr(tokenizer, "pad_token_id", None)
    eos_token = getattr(tokenizer, "eos_token", None)
    eos_token_id = getattr(tokenizer, "eos_token_id", None)

    if pad_token_id is None and eos_token_id is not None:
        try:
            if getattr(tokenizer, "pad_token", None) is None and eos_token:
                tokenizer.pad_token = eos_token
        except Exception:
            pass
        try:
            tokenizer.pad_token_id = int(eos_token_id)
        except Exception:
            pass
        pad_token_id = getattr(tokenizer, "pad_token_id", None)

    if model is not None:
        for obj_name in ("config", "generation_config"):
            obj = getattr(model, obj_name, None)
            if obj is None:
                continue
            try:
                if getattr(obj, "eos_token_id", None) is None and eos_token_id is not None:
                    obj.eos_token_id = int(eos_token_id)
            except Exception:
                pass
            try:
                if getattr(obj, "pad_token_id", None) is None and pad_token_id is not None:
                    obj.pad_token_id = int(pad_token_id)
            except Exception:
                pass
            try:
                bos_token_id = getattr(tokenizer, "bos_token_id", None)
                if getattr(obj, "bos_token_id", None) is None and bos_token_id is not None:
                    obj.bos_token_id = int(bos_token_id)
            except Exception:
                pass

    try:
        return int(pad_token_id) if pad_token_id is not None else None
    except Exception:
        return None


def _studio_load_model_for_runtime(base_dir: Path, adapter_dir: Path | None = None, trainable: bool = False, config: dict[str, Any] | None = None):
    config = _studio_ensure_runtime_defaults(config or {})
    need_peft = bool(trainable or adapter_dir or config.get("lora", {}).get("enabled", True))
    stack = _studio_import_training_stack(require_peft=need_peft)
    torch = stack["torch"]
    AutoModelForCausalLM = stack["AutoModelForCausalLM"]
    model_kwargs: dict[str, Any] = {"local_files_only": True, "trust_remote_code": True}
    _native_windows = (os.name == "nt")
    if torch.cuda.is_available():
        # Prefer bfloat16 (Ampere+) for better numerical stability; fallback to float16
        try:
            _bf16_sup = torch.cuda.is_bf16_supported()
        except Exception:
            _bf16_sup = False
        model_kwargs["torch_dtype"] = torch.bfloat16 if _bf16_sup else torch.float16
        model_kwargs["device_map"] = "auto"   # multi-GPU / offload support
        if _native_windows:
            # Native Windows: prefer PyTorch SDPA instead of FlashAttention 2 source builds.
            model_kwargs["attn_implementation"] = "sdpa"
    elif _native_windows:
        try:
            model_kwargs["attn_implementation"] = "sdpa"
        except Exception:
            pass
    model = AutoModelForCausalLM.from_pretrained(str(base_dir), **model_kwargs)

    if adapter_dir is not None:
        model = stack["PeftModel"].from_pretrained(model, str(adapter_dir), is_trainable=trainable)
    elif trainable and bool(config.get("lora", {}).get("enabled", True)):
        lora_cfg = config.get("lora", {})
        _lora_r = int(lora_cfg.get("r") or 32)
        _lora_alpha = int(lora_cfg.get("alpha") or _lora_r * 2)
        _use_rslora = bool(lora_cfg.get("use_rslora", True))
        try:
            model = stack["get_peft_model"](
                model,
                stack["LoraConfig"](
                    task_type=getattr(stack["TaskType"], "CAUSAL_LM", "CAUSAL_LM"),
                    r=_lora_r,
                    lora_alpha=_lora_alpha,
                    lora_dropout=float(lora_cfg.get("dropout") or 0.05),
                    target_modules=lora_cfg.get("target_modules") or "all-linear",
                    bias=lora_cfg.get("bias") or "none",
                    use_rslora=_use_rslora,   # rsLoRA: better stability at high rank
                ),
            )
        except TypeError:
            # Older peft without use_rslora
            model = stack["get_peft_model"](
                model,
                stack["LoraConfig"](
                    task_type=getattr(stack["TaskType"], "CAUSAL_LM", "CAUSAL_LM"),
                    r=_lora_r,
                    lora_alpha=_lora_alpha,
                    lora_dropout=float(lora_cfg.get("dropout") or 0.05),
                    target_modules=lora_cfg.get("target_modules") or "all-linear",
                    bias=lora_cfg.get("bias") or "none",
                ),
            )

    if trainable:
        if getattr(model, "config", None) is not None:
            try:
                model.config.use_cache = False
            except Exception:
                pass
        if bool(config.get("training", {}).get("gradient_checkpointing", True)) and hasattr(model, "gradient_checkpointing_enable"):
            try:
                model.gradient_checkpointing_enable()
            except Exception:
                pass
        if hasattr(model, "enable_input_require_grads"):
            try:
                model.enable_input_require_grads()
            except Exception:
                pass
    return model

def _studio_count_trainable_params(model: Any) -> tuple[int, int]:
    total = 0
    trainable = 0
    for param in model.parameters():
        num = int(param.numel())
        total += num
        if getattr(param, "requires_grad", False):
            trainable += num
    return trainable, total


def _studio_resolve_runtime_bundle(model_dir: Path, config_hint: dict[str, Any] | None = None) -> tuple[Path, Path | None, str]:
    requested = Path(model_dir)
    export_info = _studio_try_read_json(requested / "EXPORT_INFO.json")
    adapter_dir: Path | None = None
    base_candidates: list[Path] = []

    if inspect_local_model_dir(requested).get("complete"):
        return requested.resolve(), None, ""

    if _studio_has_adapter_files(requested):
        adapter_dir = requested.resolve()
        adapter_cfg = _studio_try_read_json(requested / "adapter_config.json")
        base_ref = str(adapter_cfg.get("base_model_name_or_path") or "").strip()
        if base_ref:
            base_path = Path(base_ref)
            if base_path.exists():
                base_candidates.append(base_path)
            else:
                base_candidates.append(model_local_dir(BASE_MODELS_DIR, base_ref))

    for key in ("selected_model_local_dir", "base_model", "selected_model_repo_id"):
        value = str(export_info.get(key) or (config_hint or {}).get(key) or "").strip()
        if not value:
            continue
        path_value = Path(value)
        if path_value.exists():
            base_candidates.append(path_value)
        else:
            base_candidates.append(model_local_dir(BASE_MODELS_DIR, value))

    if config_hint:
        try:
            base_candidates.append(_studio_resolve_complete_base_model_dir(config_hint))
        except Exception:
            pass

    seen: set[str] = set()
    for candidate in base_candidates:
        try:
            resolved = candidate.resolve()
        except Exception:
            resolved = candidate
        key = str(resolved)
        if key in seen:
            continue
        seen.add(key)
        if inspect_local_model_dir(resolved).get("complete"):
            note = f"Θα χρησιμοποιηθεί το πλήρες Μοντέλο Βάσης: {resolved}"
            if adapter_dir is not None:
                note += f" μαζί με adapter από: {adapter_dir}"
            return resolved, adapter_dir, note

    raise RuntimeError(f"Ο φάκελος {requested} δεν περιέχει πλήρες runnable μοντέλο ούτε επιλύσιμο Μοντέλο Βάσης.")

def _studio_load_inference_runtime(model_dir: Path):
    import torch
    base_dir, adapter_dir, note = _studio_resolve_runtime_bundle(model_dir, {})
    tokenizer = _studio_load_tokenizer_for_runtime(adapter_dir or model_dir, base_dir=base_dir)
    model = _studio_load_model_for_runtime(base_dir, adapter_dir=adapter_dir, trainable=False, config={})
    _studio_align_padding_for_generation(tokenizer, model)
    if torch.cuda.is_available():
        try:
            model = model.to("cuda")
        except Exception:
            pass
    return tokenizer, model, note, str(base_dir), str(adapter_dir) if adapter_dir else ""


def _studio_default_eval_prompts() -> list[str]:
    return [
        'Write a Python function that reverses a string.',
        'Explain in simple terms what a transformer model is.',
        'Write a Python function that returns the unique elements of a list while preserving order.',
        'Debug this Python error: TypeError: list indices must be integers or slices, not str.',
        'Refactor a Python function that is too long into smaller helper functions and explain why.',
        'What is the difference between a list, tuple, and set in Python?',
    ]



def _studio_normalize_eval_text(value: Any) -> str:
    text = str(value or '')
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    text = re.sub(r'[ \t]+', ' ', text)
    text = re.sub(r'\n{3,}', '\n\n', text)
    return text.strip()


def _studio_eval_word_tokens(value: Any) -> list[str]:
    normalized = _studio_normalize_eval_text(value).lower()
    return re.findall(r"[\wΑ-Ωα-ω]+", normalized, flags=re.UNICODE)


def _studio_eval_token_f1(reference: Any, generated: Any) -> float:
    ref_tokens = _studio_eval_word_tokens(reference)
    gen_tokens = _studio_eval_word_tokens(generated)
    if not ref_tokens and not gen_tokens:
        return 1.0
    if not ref_tokens or not gen_tokens:
        return 0.0
    ref_counts = Counter(ref_tokens)
    gen_counts = Counter(gen_tokens)
    overlap = sum(min(ref_counts[token], gen_counts[token]) for token in ref_counts)
    if overlap <= 0:
        return 0.0
    precision = overlap / max(1, len(gen_tokens))
    recall = overlap / max(1, len(ref_tokens))
    if precision + recall <= 0:
        return 0.0
    return float((2.0 * precision * recall) / (precision + recall))


def _studio_eval_sequence_similarity(reference: Any, generated: Any) -> float:
    ref_text = _studio_normalize_eval_text(reference)
    gen_text = _studio_normalize_eval_text(generated)
    if not ref_text and not gen_text:
        return 1.0
    if not ref_text or not gen_text:
        return 0.0
    return float(SequenceMatcher(None, ref_text, gen_text).ratio())


def _studio_eval_exact_match(reference: Any, generated: Any) -> bool:
    return _studio_normalize_eval_text(reference) == _studio_normalize_eval_text(generated)


def _studio_extract_python_code_candidates(text: Any) -> list[str]:
    raw_text = str(text or '')
    if not raw_text.strip():
        return []
    code_blocks = []
    for match in re.finditer(r"```(?:python|py)?\s*(.*?)```", raw_text, flags=re.IGNORECASE | re.DOTALL):
        code = str(match.group(1) or '').strip()
        if code:
            code_blocks.append(code)
    if code_blocks:
        return code_blocks

    stripped = raw_text.strip()
    lower = stripped.lower()
    likely_code_markers = (
        'import ',
        'from ',
        'def ',
        'class ',
        'torch.',
        'plt.',
        'if __name__',
        'for ',
        'while ',
        'return ',
    )
    if sum(1 for marker in likely_code_markers if marker in lower) >= 2:
        return [stripped]
    return []


def _studio_python_syntax_diagnostics(text: Any) -> dict[str, Any]:
    candidates = _studio_extract_python_code_candidates(text)
    if not candidates:
        return {
            'has_code': False,
            'code_blocks': 0,
            'syntax_ok': False,
            'valid_blocks': 0,
            'invalid_blocks': 0,
            'errors': [],
            'code_lines': 0,
        }

    errors: list[str] = []
    valid_blocks = 0
    invalid_blocks = 0
    code_lines = 0
    for block in candidates:
        non_empty_lines = [line for line in block.splitlines() if line.strip()]
        code_lines += len(non_empty_lines)
        try:
            ast.parse(block)
            valid_blocks += 1
        except SyntaxError as exc:
            invalid_blocks += 1
            line_info = f"line {exc.lineno}" if getattr(exc, 'lineno', None) else 'unknown line'
            errors.append(f"{exc.msg} ({line_info})")
        except Exception as exc:
            invalid_blocks += 1
            errors.append(str(exc))
    return {
        'has_code': True,
        'code_blocks': len(candidates),
        'syntax_ok': valid_blocks > 0 and invalid_blocks == 0,
        'valid_blocks': valid_blocks,
        'invalid_blocks': invalid_blocks,
        'errors': errors[:5],
        'code_lines': code_lines,
    }


def _studio_eval_requested_feature_keys(prompt: Any) -> list[str]:
    lower = f" {str(prompt or '').strip().lower()} "
    requested: list[str] = []

    def _want(key: str, patterns: list[str]) -> None:
        if key in requested:
            return
        if any(pattern in lower for pattern in patterns):
            requested.append(key)

    _want('complete_code', [' complete code ', ' full code ', ' entire code ', ' πλήρη κώδικα ', ' πληρη κωδικα '])
    _want('validation_split', [' validation ', ' validate ', ' validate and ', ' val ', ' validate data ', ' validate and test '])
    _want('test_split', [' test dataset ', ' test data ', ' test split ', ' training, validate and test ', ' train, validate and test ', ' validation and test '])
    if ' cuda ' in lower or (' gpu ' in lower and ' only ' in lower):
        requested.append('cuda_only')
    _want('loss_graphs', [' graph ', ' graphs ', ' plot ', ' losses ', ' γράφημα ', ' γραφημα '])
    if ' prediction ' in lower or ' predictions ' in lower or 'πρόβλε' in lower or 'προβλε' in lower:
        requested.append('predictions_display')
    if ' random image ' in lower or ' τυχαία εικόνα ' in lower or ' τυχαια εικονα ' in lower:
        requested.append('random_image')
    if ' window ' in lower or ' displayed in a window ' in lower or ' display in a window ' in lower or ' παράθυρο ' in lower or ' παραθυρο ' in lower:
        requested.append('window_display')
    if ' model.pth ' in lower or ' save the model ' in lower or ' saved with the name ' in lower:
        requested.append('save_model')
    if ' load the trained model ' in lower or ' loads the trained model ' in lower or ' loads model ' in lower or ' φορτώνει το μοντέλο ' in lower or ' φορτωνει το μοντελο ' in lower:
        requested.append('load_model')
    if ' new code of an application ' in lower or ' application that loads ' in lower or ' δεύτερο ' in lower or ' δευτερο ' in lower:
        requested.append('second_script')
    if ' weights ' in lower or ' βάρη ' in lower or ' βαρη ' in lower:
        requested.append('print_weights')

    return requested


def _studio_eval_feature_present(text: Any, feature_key: str) -> bool:
    lower = str(text or '').lower()
    if feature_key == 'complete_code':
        syntax = _studio_python_syntax_diagnostics(text)
        return bool(syntax.get('has_code')) and int(syntax.get('code_lines') or 0) >= 15
    if feature_key == 'validation_split':
        return any(marker in lower for marker in ('validation', 'val_loader', 'val_dataset', 'valid_loader', 'valid_dataset', 'random_split'))
    if feature_key == 'test_split':
        return any(marker in lower for marker in ('test_loader', 'test_dataset', 'test split', 'test_ds', 'test data'))
    if feature_key == 'cuda_only':
        if 'cuda' not in lower and '.to(device)' not in lower:
            return False
        cpu_fallback_patterns = (
            'else "cpu"',
            "else 'cpu'",
            'if torch.cuda.is_available() else "cpu"',
            "if torch.cuda.is_available() else 'cpu'",
        )
        return not any(pattern in lower for pattern in cpu_fallback_patterns)
    if feature_key == 'loss_graphs':
        return 'matplotlib' in lower or 'plt.plot' in lower or 'plt.figure' in lower
    if feature_key == 'predictions_display':
        return 'pred' in lower or 'prediction' in lower or 'argmax' in lower
    if feature_key == 'random_image':
        return 'randint' in lower or 'random' in lower
    if feature_key == 'window_display':
        return any(marker in lower for marker in ('plt.imshow', 'cv2.imshow', 'tkinter', 'pil.imagetk', 'window', 'figure('))
    if feature_key == 'save_model':
        return 'torch.save' in lower and 'model.pth' in lower
    if feature_key == 'load_model':
        return 'torch.load' in lower or 'load_state_dict' in lower
    if feature_key == 'second_script':
        return len(_studio_extract_python_code_candidates(text)) >= 2 or ('torch.save' in lower and ('torch.load' in lower or 'load_state_dict' in lower))
    if feature_key == 'print_weights':
        return 'state_dict' in lower or 'named_parameters' in lower or 'print(model)' in lower
    return False


def _studio_grade_from_score(score: float) -> str:
    value = float(score or 0.0)
    if value >= 90.0:
        return 'excellent'
    if value >= 75.0:
        return 'good'
    if value >= 50.0:
        return 'fair'
    if value >= 25.0:
        return 'poor'
    return 'failed'


def _studio_score_generated_answer(prompt: Any, reference: Any, generated: Any) -> dict[str, Any]:
    prompt_text = str(prompt or '').strip()
    reference_text = str(reference or '').strip()
    generated_text = str(generated or '').strip()

    exact_match = _studio_eval_exact_match(reference_text, generated_text)
    token_f1 = _studio_eval_token_f1(reference_text, generated_text)
    sequence_similarity = _studio_eval_sequence_similarity(reference_text, generated_text)
    requested_features = _studio_eval_requested_feature_keys(prompt_text)
    matched_features = [key for key in requested_features if _studio_eval_feature_present(generated_text, key)]
    missing_features = [key for key in requested_features if key not in matched_features]

    syntax = _studio_python_syntax_diagnostics(generated_text)
    prompt_lower = prompt_text.lower()
    expects_code = bool(
        requested_features
        or any(keyword in prompt_lower for keyword in ('python', 'code', 'script', 'function', 'class', 'model', 'cuda', 'mnist'))
    )

    if requested_features:
        requirements_coverage = round(40.0 * (len(matched_features) / max(1, len(requested_features))))
    else:
        requirements_coverage = round(40.0 * ((0.65 * token_f1) + (0.35 * sequence_similarity)))

    if expects_code:
        code_correctness = 0
        if syntax.get('has_code'):
            code_correctness += 6
        if syntax.get('syntax_ok'):
            code_correctness += 12
        elif syntax.get('valid_blocks'):
            code_correctness += 6
        if 'torch' in generated_text.lower():
            code_correctness += 3
        if any(marker in generated_text for marker in ('def ', 'class ', 'for ', 'return ')):
            code_correctness += 2
        if matched_features:
            code_correctness += min(2, len(matched_features))
        code_correctness = min(25, code_correctness)
    else:
        code_correctness = round(25.0 * ((0.6 * token_f1) + (0.4 * sequence_similarity)))

    if expects_code:
        code_lines = int(syntax.get('code_lines') or 0)
        completeness = 0
        if code_lines >= 40:
            completeness += 8
        elif code_lines >= 20:
            completeness += 6
        elif code_lines >= 10:
            completeness += 4
        elif code_lines > 0:
            completeness += 2
        if 'import ' in generated_text:
            completeness += 2
        if any(marker in generated_text for marker in ('if __name__', 'main(', 'main()')):
            completeness += 2
        if 'torch.save' in generated_text or 'torch.load' in generated_text:
            completeness += 2
        if len(_studio_extract_python_code_candidates(generated_text)) >= 2:
            completeness += 1
        completeness = min(15, completeness)
    else:
        completeness = round(15.0 * max(token_f1, sequence_similarity))

    presentation = 0
    code_candidates = _studio_extract_python_code_candidates(generated_text)
    if '```' in generated_text:
        presentation += 4
    elif code_candidates:
        presentation += 2
    if syntax.get('syntax_ok'):
        presentation += 3
    elif syntax.get('has_code'):
        presentation += 1
    if len(generated_text.splitlines()) >= 8:
        presentation += 2
    if generated_text and len(max(generated_text.splitlines(), key=len, default='')) <= 140:
        presentation += 1
    presentation = min(10, presentation)

    prompt_overlap = _studio_eval_token_f1(prompt_text, generated_text)
    relevance = round(10.0 * ((0.4 * prompt_overlap) + (0.35 * token_f1) + (0.25 * sequence_similarity)))
    relevance = min(10, relevance)

    total_score = int(round(requirements_coverage + code_correctness + completeness + presentation + relevance))
    total_score = max(0, min(100, total_score))
    grade = _studio_grade_from_score(total_score)

    issues: list[str] = []
    strengths: list[str] = []

    if requested_features:
        for missing_key in missing_features:
            issues.append(f"missing requested feature: {missing_key}")
        for matched_key in matched_features:
            strengths.append(f"covers requested feature: {matched_key}")

    if expects_code and not syntax.get('has_code'):
        issues.append('no executable-looking code detected')
    if syntax.get('errors'):
        issues.extend(f"syntax issue: {error}" for error in list(syntax.get('errors') or [])[:3])
    if syntax.get('syntax_ok'):
        strengths.append('python syntax appears valid')
    if exact_match:
        strengths.append('exact match with reference')
    if token_f1 >= 0.65:
        strengths.append('strong lexical overlap with reference')
    if sequence_similarity >= 0.65:
        strengths.append('strong sequence similarity with reference')
    if total_score < 50 and not issues:
        issues.append('multiple core requirements appear to be missing or weakly covered')

    short_judgement = (
        'The answer aligns well with the reference and covers the requested requirements.'
        if total_score >= 75
        else 'The answer is partially useful but misses important requirements or quality checks.'
        if total_score >= 50
        else 'The answer is weak relative to the prompt and reference, with notable omissions or quality issues.'
    )

    return {
        'total_score': total_score,
        'max_score': 100,
        'grade': grade,
        'breakdown': {
            'requirements_coverage': int(requirements_coverage),
            'code_correctness': int(code_correctness),
            'completeness': int(completeness),
            'presentation': int(presentation),
            'relevance': int(relevance),
        },
        'match_metrics': {
            'exact_match': bool(exact_match),
            'token_f1': round(float(token_f1), 4),
            'sequence_similarity': round(float(sequence_similarity), 4),
        },
        'requested_features': requested_features,
        'matched_features': matched_features,
        'missing_features': missing_features,
        'syntax_diagnostics': syntax,
        'strengths': strengths[:10],
        'issues': issues[:10],
        'short_judgement': short_judgement,
    }


def _studio_build_random_dataset_eval_samples(
    records: list[dict[str, Any]],
    *,
    limit: int = 6,
    seed: int = 42,
) -> list[dict[str, Any]]:
    prepared: list[dict[str, Any]] = []
    for idx, record in enumerate(records, start=1):
        pair = _studio_extract_prompt_completion_pair(record)
        if not pair:
            continue
        prompt_text, reference_text = pair
        prompt_text = str(prompt_text or '').strip()
        reference_text = str(reference_text or '').strip()
        if not prompt_text or not reference_text:
            continue
        prepared.append({
            'sample_index': idx,
            'record_id': str(record.get('id') or f'eval_{idx}'),
            'prompt': prompt_text,
            'reference': reference_text,
            'structured_example': bool(record.get('structured_example')),
        })

    rng = random.Random(int(seed))
    rng.shuffle(prepared)
    return prepared[: max(1, int(limit or 6))]


def _studio_summarize_generation_scores(sample_outputs: list[dict[str, Any]]) -> dict[str, Any] | None:
    scored_outputs = [item for item in sample_outputs if isinstance(item.get('rubric'), dict)]
    if not scored_outputs:
        return None

    total_scores = [int(item['rubric'].get('total_score') or 0) for item in scored_outputs]
    breakdown_keys = ('requirements_coverage', 'code_correctness', 'completeness', 'presentation', 'relevance')
    breakdown_averages = {}
    for key in breakdown_keys:
        values = [
            int(((item.get('rubric') or {}).get('breakdown') or {}).get(key) or 0)
            for item in scored_outputs
        ]
        breakdown_averages[key] = round(sum(values) / max(1, len(values)), 2)

    exact_match_rate = round(
        sum(1 for item in scored_outputs if ((item.get('rubric') or {}).get('match_metrics') or {}).get('exact_match')) / max(1, len(scored_outputs)),
        4,
    )
    avg_token_f1 = round(
        sum(float(((item.get('rubric') or {}).get('match_metrics') or {}).get('token_f1') or 0.0) for item in scored_outputs) / max(1, len(scored_outputs)),
        4,
    )
    avg_sequence_similarity = round(
        sum(float(((item.get('rubric') or {}).get('match_metrics') or {}).get('sequence_similarity') or 0.0) for item in scored_outputs) / max(1, len(scored_outputs)),
        4,
    )
    average_total_score = round(sum(total_scores) / max(1, len(total_scores)), 2)

    return {
        'scored_samples': len(scored_outputs),
        'average_total_score': average_total_score,
        'grade': _studio_grade_from_score(average_total_score),
        'exact_match_rate': exact_match_rate,
        'avg_token_f1': avg_token_f1,
        'avg_sequence_similarity': avg_sequence_similarity,
        'average_breakdown': breakdown_averages,
        'best_sample_score': max(total_scores) if total_scores else None,
        'worst_sample_score': min(total_scores) if total_scores else None,
    }



def _studio_evaluate_stage(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults(config)
    training_cfg = config.setdefault('training', {})
    training_cfg['eval_max_records'] = STUDIO_PATCH_EVAL_MAX_RECORDS
    training_cfg['eval_max_new_tokens'] = STUDIO_PATCH_EVAL_MAX_NEW_TOKENS
    print(f"[STUDIO PATCH] {STUDIO_PATCH_FINGERPRINT} ACTIVE | stage=evaluate | eval_max_records=ALL | eval_max_new_tokens={STUDIO_PATCH_EVAL_MAX_NEW_TOKENS}", flush=True)

    strategy = _studio_auto_dataset_strategy(config)
    dataset_cfg = config.get('dataset', {}) or {}
    preprocess_dir = Path(dataset_cfg.get('preprocess_dir') or (ARTIFACTS_DIR / '02_preprocess'))
    build_dir = Path(dataset_cfg.get('build_sft_dir') or (ARTIFACTS_DIR / '04_build_sft'))

    final_model_dir = _studio_stage_model_dir(config, 'sft')
    final_model_role = 'sft_final_model'
    if not (_studio_has_adapter_files(final_model_dir) or inspect_local_model_dir(final_model_dir).get('complete')):
        final_model_dir = _studio_stage_model_dir(config, 'cpt')
        final_model_role = 'cpt_final_model'
    if not (_studio_has_adapter_files(final_model_dir) or inspect_local_model_dir(final_model_dir).get('complete')):
        final_model_dir = _studio_resolve_complete_base_model_dir(config)
        final_model_role = 'base_model'

    cpt_model_dir = _studio_stage_model_dir(config, 'cpt')
    has_cpt_model = bool(_studio_has_adapter_files(cpt_model_dir) or inspect_local_model_dir(cpt_model_dir).get('complete'))

    structured_eval_path = Path(strategy.get('sft_eval_path') or (build_dir / 'sft_eval_dataset.jsonl'))
    raw_eval_path = Path(strategy.get('cpt_eval_path') or (preprocess_dir / 'auto_cpt_eval.jsonl'))
    fallback_eval_path, fallback_eval_records = _studio_resolve_eval_records_source(config)

    def _load_records(path_obj: Path) -> list[dict[str, Any]]:
        try:
            if path_obj.exists():
                return _studio_jsonl_load(path_obj)
        except Exception:
            return []
        return []

    structured_eval_records = _load_records(structured_eval_path)
    raw_eval_records = _load_records(raw_eval_path)

    eval_sections: dict[str, Any] = {}
    evaluation_plan: list[dict[str, Any]] = []

    if bool(strategy.get('mixed_raw_and_structured')):
        if structured_eval_records:
            evaluation_plan.append({
                'section_key': 'structured_final_model',
                'model_dir': final_model_dir,
                'model_role': final_model_role,
                'eval_path': structured_eval_path,
                'records': structured_eval_records,
                'enable_generation': True,
                'purpose': 'primary_structured_eval',
            })
        if raw_eval_records:
            evaluation_plan.append({
                'section_key': 'raw_final_model',
                'model_dir': final_model_dir,
                'model_role': final_model_role,
                'eval_path': raw_eval_path,
                'records': raw_eval_records,
                'enable_generation': False,
                'purpose': 'raw_regression_eval_on_final_model',
            })
        if raw_eval_records and has_cpt_model:
            evaluation_plan.append({
                'section_key': 'raw_cpt_reference',
                'model_dir': cpt_model_dir,
                'model_role': 'cpt_reference_model',
                'eval_path': raw_eval_path,
                'records': raw_eval_records,
                'enable_generation': False,
                'purpose': 'raw_reference_eval_on_cpt_model',
            })
    elif bool(strategy.get('pure_structured_sft_only')):
        if structured_eval_records:
            evaluation_plan.append({
                'section_key': 'structured_final_model',
                'model_dir': final_model_dir,
                'model_role': final_model_role,
                'eval_path': structured_eval_path,
                'records': structured_eval_records,
                'enable_generation': True,
                'purpose': 'structured_eval',
            })
    elif bool(strategy.get('pure_raw_cpt_only')):
        if raw_eval_records:
            evaluation_plan.append({
                'section_key': 'raw_final_model',
                'model_dir': final_model_dir,
                'model_role': final_model_role,
                'eval_path': raw_eval_path,
                'records': raw_eval_records,
                'enable_generation': False,
                'purpose': 'raw_eval',
            })

    if not evaluation_plan:
        if fallback_eval_records:
            fallback_kind = _studio_eval_source_kind(fallback_eval_records, fallback_eval_path)
            evaluation_plan.append({
                'section_key': 'fallback_eval',
                'model_dir': final_model_dir,
                'model_role': final_model_role,
                'eval_path': fallback_eval_path,
                'records': fallback_eval_records,
                'enable_generation': fallback_kind == 'structured',
                'purpose': 'fallback_eval',
            })
        else:
            raise RuntimeError(f'Δεν βρέθηκαν δεδομένα για αξιολόγηση στο: {fallback_eval_path}')

    print(
        f"[Evaluate] Πλάνο αξιολόγησης | policy={strategy.get('pipeline_policy')} | mixed={bool(strategy.get('mixed_raw_and_structured'))} | sections={','.join(item['section_key'] for item in evaluation_plan)}",
        flush=True,
    )

    loaded_runtime_cache: dict[tuple[str, str], tuple[Any, Any, str, str, str]] = {}
    runtime_order: list[tuple[str, str]] = []
    try:
        for plan_item in evaluation_plan:
            model_dir = Path(plan_item['model_dir'])
            cache_key = (str(model_dir.resolve()), str(plan_item['model_role']))
            runtime = loaded_runtime_cache.get(cache_key)
            if runtime is None:
                print(f"[Evaluate] Φόρτωση inference runtime από: {model_dir} | role={plan_item['model_role']}", flush=True)
                runtime = _studio_load_inference_runtime(model_dir)
                loaded_runtime_cache[cache_key] = runtime
                runtime_order.append(cache_key)
            tokenizer, model, note, base_dir_text, adapter_dir_text = runtime
            device = _studio_primary_model_device(model)
            section_report = _studio_run_eval_pass(
                config,
                tokenizer,
                model,
                device,
                Path(plan_item['eval_path']),
                list(plan_item['records'] or []),
                pass_name=str(plan_item['section_key']),
                model_role=str(plan_item['model_role']),
                enable_generation=bool(plan_item.get('enable_generation')),
            )
            section_report['purpose'] = str(plan_item.get('purpose') or '')
            section_report['model_dir'] = str(model_dir.resolve())
            section_report['base_model_dir'] = base_dir_text
            section_report['adapter_dir'] = adapter_dir_text
            section_report['note'] = note
            eval_sections[str(plan_item['section_key'])] = section_report
    finally:
        for cache_key in reversed(runtime_order):
            tokenizer, model, *_rest = loaded_runtime_cache.get(cache_key, (None, None, '', '', ''))
            tokenizer = None
            model = None
            _studio_release_loaded_runtime(tokenizer=tokenizer, model=model)
        loaded_runtime_cache.clear()

    primary_section_key = 'structured_final_model' if 'structured_final_model' in eval_sections else (
        'raw_final_model' if 'raw_final_model' in eval_sections else next(iter(eval_sections.keys()), '')
    )
    primary_section = eval_sections.get(primary_section_key) or {}

    raw_regression: dict[str, Any] | None = None
    final_raw = eval_sections.get('raw_final_model') or {}
    cpt_raw = eval_sections.get('raw_cpt_reference') or {}
    final_raw_loss = final_raw.get('weighted_avg_loss')
    cpt_raw_loss = cpt_raw.get('weighted_avg_loss')
    if final_raw_loss is not None and cpt_raw_loss is not None:
        loss_delta = float(final_raw_loss) - float(cpt_raw_loss)
        final_raw_ppl = final_raw.get('perplexity')
        cpt_raw_ppl = cpt_raw.get('perplexity')
        perplexity_delta = None
        if final_raw_ppl is not None and cpt_raw_ppl is not None:
            perplexity_delta = float(final_raw_ppl) - float(cpt_raw_ppl)
        raw_regression = {
            'reference_section': 'raw_cpt_reference',
            'target_section': 'raw_final_model',
            'weighted_avg_loss_delta': loss_delta,
            'perplexity_delta': perplexity_delta,
            'status': 'regressed' if loss_delta > 0.02 else ('improved' if loss_delta < -0.02 else 'stable'),
        }

    section_summaries: dict[str, Any] = {}
    for section_key, section in eval_sections.items():
        section_summaries[section_key] = {
            'purpose': section.get('purpose'),
            'model_role': section.get('model_role'),
            'dataset_kind': section.get('dataset_kind'),
            'eval_source': section.get('eval_source'),
            'weighted_avg_loss': section.get('weighted_avg_loss'),
            'perplexity': section.get('perplexity'),
            'eval_samples': section.get('eval_samples'),
            'generation_enabled': section.get('generation_enabled'),
            'generation_grade': ((section.get('generation_score_summary') or {}).get('grade') if isinstance(section.get('generation_score_summary'), dict) else None),
            'generation_average_total_score': ((section.get('generation_score_summary') or {}).get('average_total_score') if isinstance(section.get('generation_score_summary'), dict) else None),
        }

    report = {
        'stage': 'eval',
        'status': 'completed',
        'evaluation_policy': 'split_eval_by_record_type' if bool(strategy.get('mixed_raw_and_structured')) else 'single_stage_eval',
        'pipeline_policy': str(strategy.get('pipeline_policy') or ''),
        'primary_eval_section': primary_section_key,
        'primary_eval_source': primary_section.get('eval_source'),
        'primary_model_dir': primary_section.get('model_dir') or str(final_model_dir.resolve()),
        'model_dir': primary_section.get('model_dir') or str(final_model_dir.resolve()),
        'base_model_dir': primary_section.get('base_model_dir') or '',
        'adapter_dir': primary_section.get('adapter_dir') or '',
        'note': primary_section.get('note') or '',
        'eval_source': primary_section.get('eval_source') or '',
        'eval_samples': int(primary_section.get('eval_samples') or 0),
        'skipped_empty': int(primary_section.get('skipped_empty') or 0),
        'loss_aggregation': str(primary_section.get('loss_aggregation') or 'token_weighted'),
        'mean_sample_loss': primary_section.get('mean_sample_loss'),
        'avg_loss': primary_section.get('avg_loss'),
        'weighted_avg_loss': primary_section.get('weighted_avg_loss'),
        'total_supervised_tokens': int(primary_section.get('total_supervised_tokens') or 0),
        'eval_mode_counts': primary_section.get('eval_mode_counts') or {},
        'perplexity': primary_section.get('perplexity'),
        'per_sample_metrics': primary_section.get('per_sample_metrics') or [],
        'sample_outputs': primary_section.get('sample_outputs') or [],
        'generation_source': primary_section.get('generation_source') or 'disabled',
        'requested_generation_samples': int(primary_section.get('requested_generation_samples') or 0),
        'dataset_prompt_candidates': int(primary_section.get('dataset_prompt_candidates') or 0),
        'generation_score_summary': primary_section.get('generation_score_summary'),
        'effective_generation_kwargs': primary_section.get('effective_generation_kwargs'),
        'strategy': strategy,
        'section_summaries': section_summaries,
        'eval_sections': eval_sections,
        'raw_regression': raw_regression,
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }

    out_dir = _studio_stage_model_dir(config, 'eval')
    out_dir.mkdir(parents=True, exist_ok=True)
    for section_key, section in eval_sections.items():
        section_path = out_dir / f'eval_{section_key}.json'
        section_path.write_text(json.dumps(section, ensure_ascii=False, indent=2), encoding='utf-8')
    out_path = out_dir / 'eval_report.json'
    out_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
    print(
        f"[Evaluate] Ολοκλήρωση | primary={primary_section_key} | weighted_avg_loss={report['weighted_avg_loss'] if report['weighted_avg_loss'] is not None else 'n/a'} | perplexity={report['perplexity'] if report['perplexity'] is not None else 'n/a'} | sections={','.join(eval_sections.keys())} | report={out_path}",
        flush=True,
    )
    if raw_regression is not None:
        print(
            f"[Evaluate] Raw regression check | status={raw_regression['status']} | weighted_avg_loss_delta={raw_regression['weighted_avg_loss_delta']:.6f}",
            flush=True,
        )
    return report


def _studio_export_stage(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults(config)
    final_dir = Path(config.get("export", {}).get("final_model_dir") or (ARTIFACTS_DIR / "final_model"))
    source_dir = _studio_stage_model_dir(config, "sft")
    source_stage = "sft"
    if not (_studio_has_adapter_files(source_dir) or inspect_local_model_dir(source_dir).get("complete")):
        source_dir = _studio_stage_model_dir(config, "cpt")
        source_stage = "cpt"
    if not (_studio_has_adapter_files(source_dir) or inspect_local_model_dir(source_dir).get("complete")):
        source_dir = _studio_resolve_complete_base_model_dir(config)
        source_stage = "base_model"

    print(f"[Export] Επιλεγμένη πηγή | stage={source_stage} | source={source_dir}", flush=True)
    print(f"[Export] Τελικός φάκελος | target={final_dir}", flush=True)

    import shutil as _shutil
    if final_dir.exists() and final_dir.resolve() != source_dir.resolve():
        print(f"[Export] Καθαρισμός προηγούμενου export: {final_dir}", flush=True)
        _shutil.rmtree(final_dir, ignore_errors=True)
    final_dir.mkdir(parents=True, exist_ok=True)

    copied_items = 0
    skipped_checkpoints = 0
    if final_dir.resolve() != source_dir.resolve():
        children = list(source_dir.iterdir())
        print(f"[Export] Αντιγραφή αντικειμένων | total={len(children)}", flush=True)
        for idx, child in enumerate(children, start=1):
            if child.name.startswith("checkpoint-"):
                skipped_checkpoints += 1
                print(f"[Export] Copy | item={idx}/{len(children)} | skipped_checkpoint={child.name}", flush=True)
                continue
            target = final_dir / child.name
            if child.is_dir():
                _shutil.copytree(child, target, dirs_exist_ok=True)
                item_kind = "dir"
            else:
                _shutil.copy2(child, target)
                item_kind = "file"
            copied_items += 1
            print(f"[Export] Copy | item={idx}/{len(children)} | type={item_kind} | name={child.name}", flush=True)
    else:
        print("[Export] Παράλειψη αντιγραφής: η πηγή είναι ήδη ο τελικός φάκελος export.", flush=True)

    payload = {
        "stage": "export",
        "status": "completed",
        "selected_stage": source_stage,
        "exported_from": str(source_dir.resolve()),
        "contains_adapter": _studio_has_adapter_files(final_dir),
        "selected_model_local_dir": str(config.get("selected_model_local_dir") or ""),
        "selected_model_repo_id": str(config.get("selected_model_repo_id") or ""),
        "base_model": str(config.get("base_model") or ""),
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    info_path = final_dir / "EXPORT_INFO.json"
    info_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    print(
        f"[Export] Ολοκλήρωση | copied_items={copied_items} | skipped_checkpoints={skipped_checkpoints} | info={info_path}",
        flush=True,
    )
    return payload


def run_embedded_stage(stage_key: str, config_path: Path) -> int:
    config = _studio_ensure_runtime_defaults(load_config(config_path))
    print(f"[embedded] Εκκίνηση σταδίου: {stage_key}")
    print(f"[embedded] Config: {config_path}")
    try:
        if stage_key == "collect":
            collect_training_sources(config)
        elif stage_key == "preprocess":
            preprocess_training_sources(config)
        elif stage_key == "build_sft":
            build_sft_dataset(config)
        elif stage_key in {"cpt", "sft"}:
            _studio_train_stage(config, stage_key)
        elif stage_key == "eval":
            _studio_evaluate_stage(config)
        elif stage_key == "export":
            _studio_export_stage(config)
        else:
            raise RuntimeError(f"Άγνωστο στάδιο: {stage_key}")
        print(f"[embedded] Ολοκληρώθηκε το στάδιο: {stage_key}")
        return 0
    except Exception as exc:
        write_exception_report(f"Embedded stage {stage_key} failed", exc)
        print(f"[embedded] Αποτυχία σταδίου {stage_key}: {exc}")
        return 1
    finally:
        if not _STUDIO_GPU_CLEANUP_ONLY_ON_APP_EXIT:
            try:
                released = _studio_release_gpu_memory(f"τέλος σταδίου {stage_key}", include_inference_cache=False)
                if released:
                    print(f"[embedded] Η VRAM της GPU καθαρίστηκε μετά το στάδιο: {stage_key}")
            except Exception as cleanup_exc:
                print(f"[embedded] Προειδοποίηση cleanup VRAM στο στάδιο {stage_key}: {cleanup_exc}")


def _studio_normalize_chat_messages(messages: list[dict[str, str]] | None) -> list[dict[str, str]]:
    normalized: list[dict[str, str]] = []
    for item in list(messages or []):
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "user").strip().lower()
        if role not in {"system", "user", "assistant"}:
            role = "user"
        content = str(item.get("content") or "").strip()
        if not content:
            continue
        normalized.append({"role": role, "content": content})
    if not normalized:
        normalized = [{"role": "user", "content": "Write a short reply."}]
    return normalized


def _studio_render_chat_text(tokenizer, messages: list[dict[str, str]], *, add_generation_prompt: bool) -> str:
    normalized = _studio_normalize_chat_messages(messages)
    apply_template = getattr(tokenizer, "apply_chat_template", None)
    if callable(apply_template):
        try:
            rendered = apply_template(
                normalized,
                tokenize=False,
                add_generation_prompt=bool(add_generation_prompt),
            )
            if isinstance(rendered, str) and rendered.strip():
                return rendered
        except Exception:
            pass

    system_parts = [m["content"] for m in normalized if m["role"] == "system"]
    conversation_parts: list[str] = []
    if system_parts:
        conversation_parts.append("<|system|>\n" + "\n\n".join(system_parts).strip())
    for m in normalized:
        if m["role"] == "system":
            continue
        if m["role"] == "assistant":
            conversation_parts.append("<|assistant|>\n" + m["content"].strip())
        else:
            conversation_parts.append("<|user|>\n" + m["content"].strip())
    if add_generation_prompt:
        conversation_parts.append("<|assistant|>\n")
    return "\n\n".join(conversation_parts).strip()


def build_chat_prompt(tokenizer, messages: list[dict[str, str]]) -> str:
    return _studio_render_chat_text(tokenizer, messages, add_generation_prompt=True)


def get_cached_or_load_inference_runtime(model_dir: Path):
    return _studio_cached_get_cached_or_load_inference_runtime(model_dir)


def _studio_prompt_to_messages(prompt: str) -> list[dict[str, str]]:
    content = str(prompt or '').strip()
    if not content:
        content = 'Write a short reply.'
    system_text = str(globals().get('SYSTEM_PROMPT_DEFAULT_EN') or '').strip()
    messages: list[dict[str, str]] = []
    if system_text:
        messages.append({'role': 'system', 'content': system_text})
    messages.append({'role': 'user', 'content': content})
    return messages


def _studio_prepare_inputs_for_generation(tokenizer: Any, model: Any, prompt_text: str) -> dict[str, Any]:
    inputs = tokenizer(prompt_text, return_tensors='pt')
    device = getattr(model, 'device', 'cpu')
    try:
        inputs = {k: v.to(device) for k, v in inputs.items()}
    except Exception:
        pass
    return inputs


def _studio_resolve_generation_kwargs(
    generation_options: dict[str, Any] | None = None,
    *,
    default_max_new_tokens: int = 1024,
    default_temperature: float = 0.2,
    default_top_p: float = 0.95,
    default_top_k: int = 50,
    default_repetition_penalty: float = 1.05,
    default_do_sample: bool = True,
) -> dict[str, Any]:
    options = generation_options or {}
    max_new_tokens = max(16, min(int(options.get('max_new_tokens') or default_max_new_tokens), 4096))
    raw_temperature = float(options.get('temperature') or default_temperature)
    temperature = max(0.0, min(raw_temperature, 2.0))
    top_p = min(max(float(options.get('top_p') or default_top_p), 0.05), 1.0)
    top_k = max(0, int(options.get('top_k') or default_top_k))
    repetition_penalty = max(1.0, float(options.get('repetition_penalty') or default_repetition_penalty))
    no_repeat_ngram_size = max(0, int(options.get('no_repeat_ngram_size') or (4 if not bool(options.get('do_sample', default_do_sample)) else 3)))
    do_sample = bool(options.get('do_sample', default_do_sample)) and temperature > 0.0

    resolved: dict[str, Any] = {
        'max_new_tokens': max_new_tokens,
        'do_sample': do_sample,
        'repetition_penalty': repetition_penalty,
    }
    if no_repeat_ngram_size > 0:
        resolved['no_repeat_ngram_size'] = no_repeat_ngram_size
    if do_sample:
        resolved['temperature'] = max(0.01, temperature)
        resolved['top_p'] = top_p
        if top_k > 0:
            resolved['top_k'] = top_k
    else:
        resolved['num_beams'] = 1
    return resolved


def _studio_trim_generated_text(prompt_text: str, text: str) -> str:
    cleaned = str(text or '').strip()
    if not cleaned:
        return ''

    prompt_stripped = str(prompt_text or '').strip()
    if prompt_stripped and cleaned.startswith(prompt_stripped):
        cleaned = cleaned[len(prompt_stripped):].lstrip()

    stop_markers = [
        '<|assistant|>', '<|user|>', '<|system|>', '<|im_start|>', '<|im_end|>',
        'User:', 'Assistant:', 'System:'
    ]
    for marker in stop_markers:
        pos = cleaned.find(marker)
        if pos > 0:
            cleaned = cleaned[:pos].rstrip()

    words = cleaned.split()
    if len(words) >= 8:
        run_word = words[0]
        run_start = None
        run_len = 1
        for i in range(1, len(words)):
            if words[i] == words[i - 1]:
                if run_start is None:
                    run_start = i - 1
                    run_word = words[i]
                    run_len = 2
                else:
                    run_len += 1
                if run_len >= 5 and len(run_word) >= 4:
                    cleaned = ' '.join(words[:run_start]).strip()
                    break
            else:
                run_start = None
                run_len = 1

    lines = [ln.rstrip() for ln in cleaned.splitlines()]
    deduped: list[str] = []
    for ln in lines:
        if deduped and ln and ln == deduped[-1]:
            continue
        deduped.append(ln)
    cleaned = '\n'.join(deduped).strip()

    return cleaned


def _studio_generate_text_from_prompt(
    tokenizer: Any,
    model: Any,
    prompt_text: str,
    generation_options: dict[str, Any] | None = None,
    *,
    default_max_new_tokens: int = 1024,
    default_temperature: float = 0.2,
    default_top_p: float = 0.95,
    default_top_k: int = 50,
    default_repetition_penalty: float = 1.05,
    default_do_sample: bool = True,
) -> str:
    import torch

    inputs = _studio_prepare_inputs_for_generation(tokenizer, model, prompt_text)
    generation_kwargs = _studio_resolve_generation_kwargs(
        generation_options,
        default_max_new_tokens=default_max_new_tokens,
        default_temperature=default_temperature,
        default_top_p=default_top_p,
        default_top_k=default_top_k,
        default_repetition_penalty=default_repetition_penalty,
        default_do_sample=default_do_sample,
    )
    pad_token_id = _studio_align_padding_for_generation(tokenizer, model)
    if pad_token_id is not None:
        generation_kwargs['pad_token_id'] = pad_token_id
    eos_token_id = getattr(tokenizer, 'eos_token_id', None)
    if eos_token_id is not None:
        generation_kwargs['eos_token_id'] = int(eos_token_id)

    with torch.inference_mode():
        output = model.generate(**inputs, **generation_kwargs)

    input_length = int(inputs['input_ids'].shape[-1]) if 'input_ids' in inputs else 0
    generated_ids = output[0][input_length:]
    text = tokenizer.decode(generated_ids, skip_special_tokens=True).strip()
    if not text:
        full_text = tokenizer.decode(output[0], skip_special_tokens=True).strip()
        text = full_text[len(prompt_text):].strip() if full_text.startswith(prompt_text) else full_text
    text = _studio_trim_generated_text(prompt_text, text)
    return text.strip()


def _studio_generate_text_from_messages(
    tokenizer: Any,
    model: Any,
    messages: list[dict[str, str]],
    generation_options: dict[str, Any] | None = None,
    *,
    default_max_new_tokens: int = 1024,
    default_temperature: float = 0.2,
    default_top_p: float = 0.95,
    default_top_k: int = 50,
    default_repetition_penalty: float = 1.05,
    default_do_sample: bool = True,
) -> tuple[str, str]:
    prompt_text = build_chat_prompt(tokenizer, messages)
    text = _studio_generate_text_from_prompt(
        tokenizer,
        model,
        prompt_text,
        generation_options,
        default_max_new_tokens=default_max_new_tokens,
        default_temperature=default_temperature,
        default_top_p=default_top_p,
        default_top_k=default_top_k,
        default_repetition_penalty=default_repetition_penalty,
        default_do_sample=default_do_sample,
    )
    return prompt_text, text


def _studio_count_active_labels(labels: list[int] | tuple[int, ...]) -> int:
    return sum(1 for token in list(labels or []) if int(token) != -100)


def _studio_build_eval_item(record: dict[str, Any], tokenizer: Any, max_length: int) -> tuple[dict[str, Any] | None, str, str]:
    response_only_item = _studio_build_response_only_item(record, tokenizer, max_length=max_length)
    if response_only_item is not None:
        return response_only_item, 'response_only', ''

    text_row = _studio_extract_training_text(record)
    if not text_row:
        return None, 'empty', ''

    try:
        tokenized = tokenizer(text_row, truncation=True, max_length=max_length, add_special_tokens=True, verbose=False)
    except TypeError:
        tokenized = tokenizer(text_row, truncation=True, max_length=max_length, add_special_tokens=True)

    input_ids = tokenized.get('input_ids') or []
    attention_mask = tokenized.get('attention_mask') or []
    if input_ids and isinstance(input_ids[0], list):
        input_ids = input_ids[0]
    if attention_mask and isinstance(attention_mask[0], list):
        attention_mask = attention_mask[0]

    input_ids = [int(token) for token in list(input_ids or [])]
    attention_mask = [int(token) for token in list(attention_mask or ([1] * len(input_ids)))]
    if not input_ids:
        return None, 'empty', text_row

    labels = list(input_ids)
    pad_token_id = getattr(tokenizer, 'pad_token_id', None)
    if pad_token_id is not None:
        labels = [(-100 if int(token) == int(pad_token_id) else int(token)) for token in labels]

    return {
        'input_ids': input_ids,
        'attention_mask': attention_mask,
        'labels': labels,
        'response_only': False,
        'structured_example': False,
    }, 'full_sequence', text_row


def _studio_prepare_eval_batch(item: dict[str, Any], device: Any) -> tuple[dict[str, Any], int, int]:
    import torch

    input_ids = torch.tensor([list(item.get('input_ids') or [])], dtype=torch.long)
    attention_mask = torch.tensor([list(item.get('attention_mask') or [])], dtype=torch.long)
    labels_list = [int(token) for token in list(item.get('labels') or [])]
    labels = torch.tensor([labels_list], dtype=torch.long)

    if device is not None:
        try:
            input_ids = input_ids.to(device)
            attention_mask = attention_mask.to(device)
            labels = labels.to(device)
        except Exception:
            pass

    token_count = int(input_ids.shape[-1]) if hasattr(input_ids, 'shape') else 0
    supervised_tokens = _studio_count_active_labels(labels_list)
    batch = {
        'input_ids': input_ids,
        'attention_mask': attention_mask,
        'labels': labels,
    }
    return batch, token_count, supervised_tokens


def _studio_primary_model_device(model: Any) -> Any:
    try:
        return next(model.parameters()).device
    except Exception:
        return getattr(model, 'device', 'cpu')


def _studio_resolve_eval_records_source(config: dict[str, Any]) -> tuple[Path, list[dict[str, Any]]]:
    dataset_cfg = config.get('dataset', {}) or {}
    preprocess_dir = Path(dataset_cfg.get('preprocess_dir') or (ARTIFACTS_DIR / '02_preprocess'))
    build_dir = Path(dataset_cfg.get('build_sft_dir') or (ARTIFACTS_DIR / '04_build_sft'))
    candidates = [
        build_dir / 'sft_eval_dataset.jsonl',
        preprocess_dir / 'auto_cpt_eval.jsonl',
        preprocess_dir / 'preprocessed_corpus.jsonl',
    ]
    for candidate in candidates:
        try:
            if candidate.exists():
                records = _studio_jsonl_load(candidate)
                if records:
                    return candidate, records
        except Exception:
            continue
    return candidates[-1], []


def _studio_eval_source_kind(records: list[dict[str, Any]], source_path: Path | None = None) -> str:
    source_hint = str(source_path or '').lower()
    if 'sft' in source_hint or 'structured' in source_hint:
        return 'structured'
    if 'cpt' in source_hint or 'raw' in source_hint:
        return 'raw'
    structured_count = sum(1 for record in list(records or []) if _studio_auto_is_structured_record(record))
    if structured_count and structured_count >= max(1, len(list(records or [])) // 2):
        return 'structured'
    return 'raw'


def _studio_release_loaded_runtime(tokenizer: Any | None = None, model: Any | None = None) -> None:
    tokenizer = None
    model = None
    try:
        import gc
        gc.collect()
    except Exception:
        pass
    try:
        import torch
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass


def _studio_run_eval_pass(
    config: dict[str, Any],
    tokenizer: Any,
    model: Any,
    device: Any,
    eval_source_path: Path,
    eval_records: list[dict[str, Any]],
    *,
    pass_name: str,
    model_role: str,
    enable_generation: bool,
) -> dict[str, Any]:
    import torch

    max_length = int(config.get('training', {}).get('max_length') or 2048)
    dataset_kind = _studio_eval_source_kind(eval_records, eval_source_path)
    print(
        f"[Evaluate] {pass_name} | Loss pass έναρξη | model_role={model_role} | source={eval_source_path} | candidate_records={len(eval_records)} | max_length={max_length} | dataset_kind={dataset_kind}",
        flush=True,
    )

    losses: list[float] = []
    weighted_loss_numerator = 0.0
    weighted_loss_denominator = 0
    skipped_empty = 0
    mode_counts = {'response_only': 0, 'full_sequence': 0}
    per_sample_metrics: list[dict[str, Any]] = []
    structured_records = 0
    raw_records = 0

    for idx, record in enumerate(eval_records, start=1):
        if _studio_auto_is_structured_record(record):
            structured_records += 1
        else:
            raw_records += 1

        eval_item, eval_mode, text_row = _studio_build_eval_item(record, tokenizer, max_length=max_length)
        if eval_item is None:
            skipped_empty += 1
            print(f"[Evaluate] {pass_name} | Loss pass | sample={idx}/{len(eval_records)} | skipped=empty_text", flush=True)
            continue

        batch, token_count, supervised_tokens = _studio_prepare_eval_batch(eval_item, device)
        if supervised_tokens <= 0:
            skipped_empty += 1
            print(f"[Evaluate] {pass_name} | Loss pass | sample={idx}/{len(eval_records)} | skipped=no_supervised_tokens", flush=True)
            continue

        with torch.inference_mode():
            output = model(**batch)
        loss_value = float(getattr(output, 'loss').detach().float().cpu().item())
        losses.append(loss_value)
        weighted_loss_numerator += loss_value * supervised_tokens
        weighted_loss_denominator += supervised_tokens
        if eval_mode in mode_counts:
            mode_counts[eval_mode] += 1
        per_sample_metrics.append({
            'sample_index': idx,
            'mode': eval_mode,
            'tokens': token_count,
            'supervised_tokens': supervised_tokens,
            'loss': loss_value,
            'has_text_preview': bool(text_row),
        })
        print(
            f"[Evaluate] {pass_name} | Loss pass | sample={idx}/{len(eval_records)} | mode={eval_mode} | tokens={token_count} | supervised_tokens={supervised_tokens} | loss={loss_value:.4f}",
            flush=True,
        )

    requested_eval_samples = max(1, int(config.get('training', {}).get('eval_num_prompts') or 6))
    eval_seed = int(config.get('training', {}).get('seed') or 42)
    dataset_eval_samples: list[dict[str, Any]] = []
    prompt_entries: list[dict[str, Any]] = []
    generation_source = 'disabled'
    sample_outputs: list[dict[str, Any]] = []
    effective_eval_generation_kwargs: dict[str, Any] | None = None

    raw_eval_generation_options = {
        'max_new_tokens': STUDIO_PATCH_EVAL_MAX_NEW_TOKENS,
        'temperature': float(config.get('training', {}).get('eval_temperature') or 0.2),
        'top_p': float(config.get('training', {}).get('eval_top_p') or 0.95),
        'top_k': int(config.get('training', {}).get('eval_top_k') or 50),
        'repetition_penalty': float(config.get('training', {}).get('eval_repetition_penalty') or 1.1),
        'no_repeat_ngram_size': int(config.get('training', {}).get('eval_no_repeat_ngram_size') or 4),
        'do_sample': bool(config.get('training', {}).get('eval_do_sample', False)),
    }

    if enable_generation:
        dataset_eval_samples = _studio_build_random_dataset_eval_samples(
            eval_records,
            limit=requested_eval_samples,
            seed=eval_seed,
        )
        generation_source = 'dataset_random_pairs'
        prompt_entries = list(dataset_eval_samples)
        if not prompt_entries:
            generation_source = 'fallback_prompts'
            configured_prompts = list(config.get('training', {}).get('sample_prompts') or [])
            seen_prompts: set[str] = set()
            for candidate_prompt in configured_prompts + _studio_default_eval_prompts():
                candidate_text = str(candidate_prompt or '').strip()
                if not candidate_text or candidate_text in seen_prompts:
                    continue
                seen_prompts.add(candidate_text)
                prompt_entries.append({
                    'sample_index': len(prompt_entries) + 1,
                    'record_id': f'{pass_name}_fallback_{len(prompt_entries) + 1}',
                    'prompt': candidate_text,
                    'reference': '',
                    'structured_example': False,
                })
                if len(prompt_entries) >= requested_eval_samples:
                    break

        print(
            f"[Evaluate] {pass_name} | Generation έναρξη | prompts={len(prompt_entries)} | source={generation_source} | dataset_pairs_available={len(dataset_eval_samples)}",
            flush=True,
        )
        print(f"[Evaluate] {pass_name} | HARDENED_EVAL_V7 | eval_max_records=ALL | eval_max_new_tokens={STUDIO_PATCH_EVAL_MAX_NEW_TOKENS}", flush=True)
        effective_eval_generation_kwargs = _studio_resolve_generation_kwargs(
            raw_eval_generation_options,
            default_max_new_tokens=256,
            default_temperature=0.2,
            default_top_p=0.95,
            default_top_k=50,
            default_repetition_penalty=1.1,
            default_do_sample=False,
        )
        print(f"[Evaluate] {pass_name} | Generation ρυθμίσεις | effective={effective_eval_generation_kwargs}", flush=True)
        for idx, prompt_entry in enumerate(prompt_entries, start=1):
            prompt = str(prompt_entry.get('prompt') or '').strip()
            reference_text = str(prompt_entry.get('reference') or '').strip()
            prompt_preview = (prompt or '').replace('\r', ' ').replace('\n', ' ').strip()
            if len(prompt_preview) > 80:
                prompt_preview = prompt_preview[:77] + '...'
            print(
                f"[Evaluate] {pass_name} | Generation | prompt={idx}/{len(prompt_entries)} | source={generation_source} | text={prompt_preview}",
                flush=True,
            )
            prompt_text, generated_text = _studio_generate_text_from_messages(
                tokenizer,
                model,
                _studio_prompt_to_messages(prompt),
                raw_eval_generation_options,
                default_max_new_tokens=256,
                default_temperature=0.2,
                default_top_p=0.95,
                default_top_k=50,
                default_repetition_penalty=1.1,
                default_do_sample=False,
            )
            rubric = _studio_score_generated_answer(prompt, reference_text, generated_text) if reference_text else None
            sample_output = {
                'sample_index': int(prompt_entry.get('sample_index') or idx),
                'record_id': str(prompt_entry.get('record_id') or f'{pass_name}_{idx}'),
                'prompt': prompt,
                'rendered_prompt': prompt_text,
                'reference': reference_text,
                'reference_available': bool(reference_text),
                'completion': generated_text,
                'effective_generation_kwargs': dict(effective_eval_generation_kwargs or {}),
                'generation_source': generation_source,
            }
            if rubric is not None:
                sample_output['rubric'] = rubric
                sample_output['match_metrics'] = rubric.get('match_metrics')
            sample_outputs.append(sample_output)

            completion_preview = (generated_text or '').replace('\r', ' ').replace('\n', ' ').strip()
            if len(completion_preview) > 120:
                completion_preview = completion_preview[:117] + '...'
            score_preview = ((rubric or {}).get('total_score') if rubric else 'n/a')
            print(
                f"[Evaluate] {pass_name} | Generation | prompt={idx}/{len(prompt_entries)} | completion_chars={len(generated_text)} | score={score_preview} | preview={completion_preview}",
                flush=True,
            )

    generation_score_summary = _studio_summarize_generation_scores(sample_outputs)
    mean_sample_loss = sum(losses) / len(losses) if losses else None
    weighted_avg_loss = (weighted_loss_numerator / weighted_loss_denominator) if weighted_loss_denominator > 0 else None
    try:
        perplexity = float(torch.exp(torch.tensor(weighted_avg_loss)).item()) if weighted_avg_loss is not None else None
    except Exception:
        perplexity = None

    report = {
        'pass_name': pass_name,
        'model_role': model_role,
        'eval_source': str(eval_source_path),
        'dataset_kind': dataset_kind,
        'input_records': len(eval_records),
        'structured_records': structured_records,
        'raw_records': raw_records,
        'eval_samples': len(losses),
        'skipped_empty': skipped_empty,
        'loss_aggregation': 'token_weighted',
        'mean_sample_loss': mean_sample_loss,
        'avg_loss': weighted_avg_loss,
        'weighted_avg_loss': weighted_avg_loss,
        'total_supervised_tokens': weighted_loss_denominator,
        'eval_mode_counts': mode_counts,
        'perplexity': perplexity,
        'per_sample_metrics': per_sample_metrics,
        'sample_outputs': sample_outputs,
        'generation_enabled': bool(enable_generation),
        'generation_source': generation_source,
        'requested_generation_samples': requested_eval_samples if enable_generation else 0,
        'dataset_prompt_candidates': len(dataset_eval_samples),
        'generation_score_summary': generation_score_summary,
        'effective_generation_kwargs': effective_eval_generation_kwargs,
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    print(
        f"[Evaluate] {pass_name} | Ολοκλήρωση | eval_samples={len(losses)} | skipped_empty={skipped_empty} | weighted_avg_loss={weighted_avg_loss if weighted_avg_loss is not None else 'n/a'} | mean_sample_loss={mean_sample_loss if mean_sample_loss is not None else 'n/a'} | total_supervised_tokens={weighted_loss_denominator} | perplexity={perplexity if perplexity is not None else 'n/a'}",
        flush=True,
    )
    return report


def generate_chat_completion(model_dir: Path, messages: list[dict[str, str]], generation_options: dict[str, Any]) -> dict[str, Any]:
    tokenizer, model, info = get_cached_or_load_inference_runtime(model_dir)
    _prompt_text, text = _studio_generate_text_from_messages(
        tokenizer,
        model,
        messages,
        generation_options,
        default_max_new_tokens=1024,
        default_temperature=0.2,
        default_top_p=0.95,
        default_top_k=50,
        default_repetition_penalty=1.05,
        default_do_sample=True,
    )
    return {
        'text': text or '(Το μοντέλο δεν επέστρεψε κείμενο.)',
        'resolved_model_dir': info.get('base_model_dir') or '',
        'note': info.get('note') or '',
        'from_cache': bool(info.get('from_cache')),
        'adapter_dir': info.get('adapter_dir') or '',
    }


def run_embedded_inference(
    model_dir: Path,
    prompt: str,
    max_new_tokens: int = 512,
    temperature: float = 0.7,
    top_p: float = 0.9,
) -> int:
    """Run local inference and stream output to stdout for the GUI log view."""
    print(f"[embedded] Inference model dir: {model_dir}", flush=True)
    print(f"[embedded] Prompt ({len(prompt)} chars): {prompt[:120]}{'...' if len(prompt) > 120 else ''}", flush=True)
    print(f"[embedded] Params: max_new_tokens={max_new_tokens}  temperature={temperature}  top_p={top_p}", flush=True)
    try:
        tokenizer, model, info = get_cached_or_load_inference_runtime(model_dir)
        if info.get('note'):
            print(f"[embedded] {info.get('note')}", flush=True)
        if info.get('adapter_dir'):
            print(f"[embedded] Adapter: {info.get('adapter_dir')}", flush=True)

        generation_options = {
            'max_new_tokens': max_new_tokens,
            'temperature': temperature,
            'top_p': top_p,
            'do_sample': float(temperature) > 0.01,
        }
        effective_generation_kwargs = _studio_resolve_generation_kwargs(
            generation_options,
            default_max_new_tokens=512,
            default_temperature=0.7,
            default_top_p=0.9,
            default_top_k=50,
            default_repetition_penalty=1.05,
            default_do_sample=True,
        )
        print(f"[embedded] Generating... | effective={effective_generation_kwargs}", flush=True)
        _prompt_text, response = _studio_generate_text_from_messages(
            tokenizer,
            model,
            _studio_prompt_to_messages(prompt),
            generation_options,
            default_max_new_tokens=512,
            default_temperature=0.7,
            default_top_p=0.9,
            default_top_k=50,
            default_repetition_penalty=1.05,
            default_do_sample=True,
        )

        print('', flush=True)
        print('=' * 60, flush=True)
        print('ΑΠΟΤΕΛΕΣΜΑ INFERENCE', flush=True)
        print('=' * 60, flush=True)
        print(response, flush=True)
        print('=' * 60, flush=True)
        print(f"[embedded] ✓ Ολοκληρώθηκε ({len(response)} chars)", flush=True)
        return 0
    except Exception as exc:
        write_exception_report('Embedded inference failed', exc)
        print(f"[embedded] ❌ Η εκτέλεση inference απέτυχε: {exc}", flush=True)
        print('[embedded] Βεβαιώσου ότι υπάρχει πλήρες Μοντέλο Βάσης και τα πακέτα torch/transformers/accelerate/peft.', flush=True)
        traceback.print_exc()
        return 1

