append_log = _studio_patched_append_log  # noqa: F811


def _studio_patched_build_logs_card(self) -> QWidget:
    group = self._card_group("📋  Live logs")
    lay = QVBoxLayout(group)

    view = QPlainTextEdit()
    view.setReadOnly(True)
    view.setObjectName("LogView")
    try:
        view.document().setMaximumBlockCount(3000)
    except Exception:
        pass
    lay.addWidget(view, 1)

    if not hasattr(self, "_log_views"):
        self._log_views = []
    self._log_views.append(view)
    if not hasattr(self, "_log_buffer"):
        self._log_buffer = []

    existing_lines = list(getattr(self, "_log_buffer", []) or [])
    if existing_lines:
        view.setPlainText("\n".join(existing_lines))

    if not getattr(self, "logs", None):
        self.logs = view

    row = QHBoxLayout()
    clear_btn = QPushButton("Καθαρισμός logs")
    clear_btn.clicked.connect(self.clear_logs)
    copy_btn = QPushButton("Αντιγραφή logs")
    copy_btn.clicked.connect(self.copy_logs)
    open_artifacts_btn = QPushButton("Άνοιγμα artifacts")
    open_artifacts_btn.clicked.connect(lambda: self.open_path(ARTIFACTS_DIR))
    row.addWidget(clear_btn)
    row.addWidget(copy_btn)
    row.addWidget(open_artifacts_btn)
    row.addStretch(1)
    lay.addLayout(row)
    return group


def _studio_patched_clear_logs(self) -> None:
    self._log_buffer = []
    for view in list(getattr(self, "_log_views", None) or []):
        try:
            view.clear()
        except Exception:
            pass


def _studio_patched_copy_logs(self) -> None:
    buffer_lines = list(getattr(self, "_log_buffer", None) or [])
    if not buffer_lines and getattr(self, "logs", None) is not None:
        try:
            buffer_lines = self.logs.toPlainText().splitlines()
        except Exception:
            buffer_lines = []
    QApplication.clipboard().setText("\n".join(buffer_lines))
    self._set_status_message("Τα logs αντιγράφηκαν στο clipboard.", 3000)


def _studio_patched_log(self, message: str) -> None:
    timestamp = time.strftime("%H:%M:%S")
    line = f"[{timestamp}] {message}"

    if not hasattr(self, "_log_buffer"):
        self._log_buffer = []
    self._log_buffer.append(line)

    alive_views = []
    for view in list(getattr(self, "_log_views", None) or []):
        try:
            view.appendPlainText(line)
            cursor = view.textCursor()
            cursor.movePosition(QTextCursor.End)
            view.setTextCursor(cursor)
            view.ensureCursorVisible()
            alive_views.append(view)
        except RuntimeError:
            continue
        except Exception:
            continue
    self._log_views = alive_views
    if alive_views:
        self.logs = alive_views[0]
    append_text_line(self._session_log_path, line)


def _studio_internal_python_command(self, *args: str) -> list[str]:
    return [self._python_exec(), "-u", str(Path(__file__).resolve()), *[str(arg) for arg in args]]


def _studio_patched_run_full_pipeline(self) -> None:
    config = self._config_path()
    start_stage = self.stage_combo.currentData() or "collect"
    self._start_command(
        self._build_internal_python_command("--internal-pipeline", "--config", config, "--start-stage", start_stage),
        "Πλήρες pipeline",
    )


def _studio_patched_run_internal_stage(self, stage_key: str, title: str) -> None:
    config = self._config_path()
    self._start_command(self._build_internal_python_command("--internal-step", stage_key, "--config", config), title)


def _studio_patched_run_inference(self, title: str = "Inference") -> None:
    model_dir = self.infer_model_edit.text().strip()
    prompt = self.infer_prompt.toPlainText().strip()
    if not model_dir:
        QMessageBox.warning(self, APP_TITLE, "Επίλεξε φάκελο μοντέλου για inference.")
        return
    if not prompt:
        QMessageBox.warning(self, APP_TITLE, "Γράψε prompt για δοκιμή μοντέλου.")
        return
    command = self._build_internal_python_command(
        "--internal-infer",
        "--model",
        model_dir,
        "--prompt",
        prompt,
    )
    self._start_command(command, title)


def _studio_patched_start_command(self, command: list[str], title: str) -> None:
    if self._current_process is not None:
        QMessageBox.warning(self, APP_TITLE, "Υπάρχει ήδη ενεργή διεργασία. Σταμάτησέ την πρώτα.")
        return
    self.log(f"🚀 Εκκίνηση: {title}")
    self.log("$ " + " ".join(self._quote_part(part) for part in command))
    self._set_status_message(title)
    self.progress.setRange(0, 100)

    thread = QThread(self)
    worker = CommandStreamWorker(command, cwd=PROJECT_ROOT)
    worker.extra_env = {
        "PYTHONIOENCODING": "utf-8",
        "PYTHONUTF8": "1",
    }
    self._job_thread = thread
    self._job_worker = worker
    self._current_process = worker
    worker.moveToThread(thread)
    thread.started.connect(worker.run)
    worker.batch_lines.connect(self._log_batch, Qt.QueuedConnection)
    worker.started.connect(lambda: self.log("ℹ Η διεργασία ξεκίνησε."))
    worker.finished.connect(self._on_command_finished, Qt.QueuedConnection)
    worker.finished.connect(thread.quit, Qt.QueuedConnection)
    thread.finished.connect(self._clear_command_job, Qt.QueuedConnection)
    thread.start()


def _studio_patched_command_stream_run(self) -> None:
    """Read subprocess stdout and emit lines in batches every 100 ms.

    Emitting one Qt signal per line when training outputs hundreds of lines
    per second floods the main-thread event queue and freezes the UI.
    Batching at the worker level keeps the event loop free between flushes.
    """
    self.started.emit()
    creationflags = 0
    if os.name == "nt":
        creationflags = subprocess.CREATE_NO_WINDOW  # type: ignore[attr-defined]

    env = os.environ.copy()
    extra_env = getattr(self, "extra_env", None)
    if isinstance(extra_env, dict):
        for key, value in extra_env.items():
            if value is not None:
                env[str(key)] = str(value)

    self.process = subprocess.Popen(
        self.command,
        cwd=self.cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        bufsize=1,
        universal_newlines=True,
        encoding="utf-8",
        errors="replace",
        creationflags=creationflags,
        env=env,
    )
    assert self.process.stdout is not None

    _FLUSH_INTERVAL = 0.10   # seconds — flush batch every 100 ms
    _MAX_BATCH = 200          # safety cap: never hold more than 200 lines

    pending: list[str] = []
    last_flush = time.monotonic()

    for raw_line in self.process.stdout:
        pending.append(raw_line.rstrip())

        now = time.monotonic()
        if (now - last_flush) >= _FLUSH_INTERVAL or len(pending) >= _MAX_BATCH:
            self.batch_lines.emit("\n".join(pending))
            pending.clear()
            last_flush = now

        if self._stop_requested:
            break

    # flush any remaining lines
    if pending:
        self.batch_lines.emit("\n".join(pending))

    if self._stop_requested and self.process.poll() is None:
        self._terminate()
    return_code = self.process.wait()
    self.finished.emit(return_code)


# NOTE: _studio_patched_prepare_lm_items below is superseded by the canonical
# _studio_prepare_lm_items (defined later). Kept for reference only.
def _studio_patched_prepare_lm_items(records: list[dict[str, Any]], tokenizer: Any, max_length: int, max_train_samples: int = 0) -> tuple[list[dict[str, Any]], int]:
    all_token_ids: list[int] = []
    total_raw_tokens = 0
    eos_id = getattr(tokenizer, "eos_token_id", None)

    for record in records:
        text = _studio_extract_training_text(record)
        if not text:
            continue

        try:
            tokenized = tokenizer(text, add_special_tokens=True, truncation=False, verbose=False)
        except TypeError:
            tokenized = tokenizer(text, add_special_tokens=True, truncation=False)

        token_ids = tokenized["input_ids"]
        if token_ids and isinstance(token_ids[0], list):
            token_ids = token_ids[0]

        total_raw_tokens += len(token_ids)
        if eos_id is not None and (not token_ids or token_ids[-1] != eos_id):
            token_ids = token_ids + [eos_id]
        all_token_ids.extend(int(tok) for tok in token_ids)

    items: list[dict[str, Any]] = []
    chunk_size = max(128, int(max_length))
    min_chunk = max(32, min(128, chunk_size // 4))
    for start in range(0, len(all_token_ids), chunk_size):
        chunk = all_token_ids[start:start + chunk_size]
        if len(chunk) < min_chunk:
            continue
        items.append({"input_ids": chunk, "attention_mask": [1] * len(chunk)})
        if max_train_samples and len(items) >= max_train_samples:
            break
    return items, total_raw_tokens


def _studio_build_training_arguments(training_cls: Any, kwargs: dict[str, Any]) -> tuple[Any, list[str]]:
    import inspect as _inspect

    try:
        params = _inspect.signature(training_cls.__init__).parameters
        supported = set(params.keys())
    except Exception:
        supported = set()

    if not supported:
        return training_cls(**kwargs), []

    local_kwargs = dict(kwargs or {})

    # Compatibility bridge across Transformers versions:
    # some versions use `evaluation_strategy`, while newer ones may expose `eval_strategy`.
    if 'evaluation_strategy' in local_kwargs and 'evaluation_strategy' not in supported and 'eval_strategy' in supported:
        local_kwargs['eval_strategy'] = local_kwargs.pop('evaluation_strategy')
    if 'eval_strategy' in local_kwargs and 'eval_strategy' not in supported and 'evaluation_strategy' in supported:
        local_kwargs['evaluation_strategy'] = local_kwargs.pop('eval_strategy')

    filtered_kwargs = {key: value for key, value in local_kwargs.items() if key in supported}
    dropped = [key for key in local_kwargs.keys() if key not in supported]
    return training_cls(**filtered_kwargs), dropped


def _studio_patched_train_stage(config: dict[str, Any], stage_key: str) -> dict[str, Any]:
    # DEAD CODE: this function is overwritten at module end by
    # _studio_patched_train_stage = _studio_train_stage_with_live_metrics
    # It is kept only for historical reference.
    config = _studio_ensure_runtime_defaults(config)
    training_cfg = config.get("training", {})
    dataset_cfg = config.get("dataset", {})
    if stage_key == "cpt":
        dataset_path = Path(dataset_cfg.get("preprocess_dir") or (ARTIFACTS_DIR / "02_preprocess")) / "preprocessed_corpus.jsonl"
        max_steps = int(training_cfg.get("cpt_max_steps") or 0)
    else:
        build_dir = Path(dataset_cfg.get("build_sft_dir") or (ARTIFACTS_DIR / "04_build_sft"))
        dataset_path = build_dir / "sft_dataset.jsonl"
        if not dataset_path.exists():
            build_sft_dataset(config)
        max_steps = int(training_cfg.get("sft_max_steps") or 0)

    records = _studio_jsonl_load(dataset_path)
    if not records:
        raise RuntimeError(f"Δεν βρέθηκαν εγγραφές training στο {dataset_path}")

    base_dir, adapter_dir, training_base_kind = _studio_resolve_training_start(config, stage_key)
    tokenizer = _studio_load_tokenizer_for_runtime(adapter_dir or base_dir, base_dir=base_dir)

    max_length = int(training_cfg.get("max_length") or 2048)
    model_max_len = int(getattr(tokenizer, "model_max_length", max_length) or max_length)
    if model_max_len > 0 and model_max_len < 1000000:
        max_length = min(max_length, model_max_len)

    max_train_samples = int(training_cfg.get("max_train_samples") or 0)
    train_items, total_raw_tokens = _studio_prepare_lm_items(
        records,
        tokenizer,
        max_length=max_length,
        max_train_samples=max_train_samples,
    )
    if not train_items:
        raise RuntimeError("Το training dataset δεν παρήγαγε έγκυρα tokenized δείγματα.")

    stack = _studio_import_training_stack(require_peft=bool(config.get("lora", {}).get("enabled", True)))
    torch = stack["torch"]
    out_dir = _studio_stage_model_dir(config, stage_key)
    out_dir.mkdir(parents=True, exist_ok=True)

    model = _studio_load_model_for_runtime(base_dir, adapter_dir=adapter_dir, trainable=True, config=config)
    _studio_align_padding_for_generation(tokenizer, model)
    trainable_params, total_params = _studio_count_trainable_params(model)

    training_kwargs = {
        "output_dir": str(out_dir),
        "overwrite_output_dir": True,
        "num_train_epochs": float(training_cfg.get("epochs") or 1),
        "per_device_train_batch_size": int(training_cfg.get("micro_batch_size") or 1),
        "gradient_accumulation_steps": int(training_cfg.get("gradient_accumulation_steps") or 1),
        "learning_rate": float(training_cfg.get("learning_rate") or 2e-4),
        "warmup_ratio": float(training_cfg.get("warmup_ratio") or 0.03),
        "logging_steps": max(1, int(training_cfg.get("logging_steps") or 1)),
        "save_steps": max(10, int(training_cfg.get("save_steps") or 50)),
        "save_total_limit": max(1, int(training_cfg.get("save_total_limit") or 2)),
        "weight_decay": float(training_cfg.get("weight_decay") or 0.0),
        "report_to": [],
        "remove_unused_columns": False,
        "bf16": bool(training_cfg.get("bf16", False)),
        "fp16": bool(training_cfg.get("fp16", True)) and torch.cuda.is_available() and not bool(training_cfg.get("bf16", False)),
        "gradient_checkpointing": bool(training_cfg.get("gradient_checkpointing", True)),
        "dataloader_pin_memory": torch.cuda.is_available(),
        "seed": int(training_cfg.get("seed") or 42),
        "max_steps": max_steps if max_steps > 0 else -1,
    }
    args, dropped_training_args = _studio_build_training_arguments(stack["TrainingArguments"], training_kwargs)

    trainer = stack["Trainer"](
        model=model,
        args=args,
        train_dataset=_StudioTokenDataset(train_items),
        data_collator=stack["DataCollatorForLanguageModeling"](tokenizer=tokenizer, mlm=False),
    )

    append_log(f"[{stage_key}] Εκπαίδευση από: {base_dir}")
    if adapter_dir is not None:
        append_log(f"[{stage_key}] Συνέχιση adapter από: {adapter_dir}")
    append_log(f"[{stage_key}] Δείγματα training: {len(train_items)} | tokens: {total_raw_tokens}")
    append_log(f"[{stage_key}] Trainable params: {trainable_params:,} / {total_params:,}")
    if dropped_training_args:
        append_log(f"[{stage_key}] Παραλείφθηκαν μη υποστηριζόμενα TrainingArguments: {', '.join(dropped_training_args)}")

    result = trainer.train()
    metrics = dict(getattr(result, "metrics", {}) or {})
    _studio_align_padding_for_generation(tokenizer, model)
    trainer.save_model(str(out_dir))
    tokenizer.save_pretrained(str(out_dir))

    report = {
        "stage": stage_key,
        "status": "trained",
        "dataset_path": str(dataset_path.resolve()),
        "records": len(records),
        "train_samples": len(train_items),
        "total_raw_tokens": total_raw_tokens,
        "base_model_dir": str(base_dir),
        "adapter_start_dir": str(adapter_dir) if adapter_dir else "",
        "training_base_kind": training_base_kind,
        "output_dir": str(out_dir.resolve()),
        "contains_adapter": _studio_has_adapter_files(out_dir),
        "trainable_params": trainable_params,
        "total_params": total_params,
        "metrics": metrics,
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
    }

    report_path = out_dir / "TRAINING_REPORT.json"
    report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    return report


def _studio_patched_load_local_causal_lm_with_fallbacks(model_dir: Path, torch_module):
    from transformers import AutoModelForCausalLM

    attempts: list[dict[str, Any]] = []
    if torch_module.cuda.is_available():
        attempts.extend([
            {"local_files_only": True, "dtype": "auto", "device_map": "auto", "trust_remote_code": True},
            {"local_files_only": True, "dtype": "auto", "trust_remote_code": True},
            {"local_files_only": True, "trust_remote_code": True},
        ])
    else:
        attempts.extend([
            {"local_files_only": True, "dtype": "auto", "trust_remote_code": True},
            {"local_files_only": True, "trust_remote_code": True},
        ])

    last_exc: Exception | None = None
    for kwargs in attempts:
        try:
            model = AutoModelForCausalLM.from_pretrained(str(model_dir), **kwargs)
            if torch_module.cuda.is_available() and kwargs.get("device_map") is None:
                try:
                    model = model.to("cuda")
                except Exception:
                    pass
            return model
        except Exception as exc:
            last_exc = exc

    if last_exc is not None:
        raise RuntimeError(f"Αποτυχία φόρτωσης μοντέλου: {last_exc}") from last_exc
    raise RuntimeError("Αποτυχία φόρτωσης μοντέλου για άγνωστο λόγο.")


def _studio_patched_load_model_for_runtime(base_dir: Path, adapter_dir: Path | None = None, trainable: bool = False, config: dict[str, Any] | None = None):
    config = _studio_ensure_runtime_defaults(config or {})
    need_peft = bool(trainable or adapter_dir or config.get("lora", {}).get("enabled", True))
    stack = _studio_import_training_stack(require_peft=need_peft)
    torch = stack["torch"]
    AutoModelForCausalLM = stack["AutoModelForCausalLM"]

    model_kwargs: dict[str, Any] = {"local_files_only": True, "trust_remote_code": True}
    if torch.cuda.is_available():
        model_kwargs["dtype"] = torch.float16
    requested_attn_impl = str((config.get('training', {}) or {}).get('attn_implementation') or 'sdpa').strip() or 'sdpa'
    if requested_attn_impl:
        model_kwargs['attn_implementation'] = requested_attn_impl

    try:
        model = AutoModelForCausalLM.from_pretrained(str(base_dir), **model_kwargs)
    except TypeError:
        model_kwargs.pop('attn_implementation', None)
        model = AutoModelForCausalLM.from_pretrained(str(base_dir), **model_kwargs)
    except Exception as exc:
        message = str(exc).lower()
        if 'flash_attention' in message or 'flash-attention' in message or 'flash attn' in message:
            model_kwargs.pop('attn_implementation', None)
            model = AutoModelForCausalLM.from_pretrained(str(base_dir), **model_kwargs)
        elif "mamba-ssm" in message or "mamba_ssm" in message:
            expected_repo_id = _studio_expected_base_repo_id(config)
            detected_repo = read_local_model_repo_id(base_dir)
            raise RuntimeError(
                "Αποτυχία φόρτωσης Μοντέλου Βάσης επειδή το local model απαιτεί το πακέτο mamba-ssm. "
                f"Επιλεγμένο repo: {expected_repo_id or 'άγνωστο'} | Φάκελος μοντέλου: {base_dir} | Ανιχνεύθηκε repo/model: {detected_repo}. "
                "Πιθανότατα έχει φορτωθεί λάθος ή παλιός φάκελος μοντέλου. Διέγραψε τον συγκεκριμένο φάκελο από το Base_Models και ξανακατέβασε το σωστό μοντέλο από το GUI. "
                "Αν όντως θέλεις να χρησιμοποιήσεις αυτό το μοντέλο, εγκατέστησε πρώτα: pip install mamba-ssm"
            ) from exc
        else:
            raise

    if adapter_dir is not None:
        model = stack["PeftModel"].from_pretrained(model, str(adapter_dir), is_trainable=trainable)
    elif trainable and bool(config.get("lora", {}).get("enabled", True)):
        lora_cfg = config.get("lora", {})
        model = stack["get_peft_model"](
            model,
            stack["LoraConfig"](
                task_type=getattr(stack["TaskType"], "CAUSAL_LM", "CAUSAL_LM"),
                r=int(lora_cfg.get("r") or 16),
                lora_alpha=int(lora_cfg.get("alpha") or 32),
                lora_dropout=float(lora_cfg.get("dropout") or 0.05),
                target_modules=lora_cfg.get("target_modules") or "all-linear",
                bias="none",
            ),
        )

    if trainable:
        if getattr(model, "config", None) is not None:
            try:
                model.config.use_cache = False
            except Exception:
                pass
        try:
            model.train()
        except Exception:
            pass
    else:
        try:
            model.eval()
        except Exception:
            pass
    return model


