_STUDIO_INFERENCE_RUNTIME_CACHE: dict[str, tuple[Any, Any, dict[str, Any]]] = {}


def clear_inference_runtime_cache(model_dir: str | Path | None = None) -> None:
    import gc
    keys: list[str]
    if model_dir is None:
        keys = list(_STUDIO_INFERENCE_RUNTIME_CACHE.keys())
    else:
        try:
            keys = [str(Path(model_dir).resolve())]
        except Exception:
            keys = [str(model_dir)]
    for key in keys:
        entry = _STUDIO_INFERENCE_RUNTIME_CACHE.pop(key, None)
        if not entry:
            continue
        _tokenizer, model, _info = entry
        try:
            model.to("cpu")
        except Exception:
            pass
        try:
            del model
        except Exception:
            pass
    try:
        gc.collect()
    except Exception:
        pass
    try:
        import torch
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass


def _studio_cached_get_cached_or_load_inference_runtime(model_dir: Path):
    try:
        resolved = Path(model_dir).resolve()
    except Exception:
        resolved = Path(model_dir)
    cache_key = str(resolved)
    cached = _STUDIO_INFERENCE_RUNTIME_CACHE.get(cache_key)
    if cached:
        tokenizer, model, info = cached
        result_info = dict(info)
        result_info["from_cache"] = True
        return tokenizer, model, result_info
    tokenizer, model, note, base_dir_text, adapter_dir_text = _studio_load_inference_runtime(resolved)
    info = {
        "from_cache": False,
        "note": note,
        "base_model_dir": base_dir_text,
        "adapter_dir": adapter_dir_text,
    }
    _STUDIO_INFERENCE_RUNTIME_CACHE[cache_key] = (tokenizer, model, dict(info))
    return tokenizer, model, info


def _studio_chat_generate_worker(
    model_dir: str,
    messages: list[dict[str, str]],
    generation_options: dict[str, Any],
    progress_callback: Callable[[str], None] | None = None,
) -> dict[str, Any]:
    if progress_callback:
        progress_callback("Φόρτωση runtime και παραγωγή απάντησης...")
    result = generate_chat_completion(Path(model_dir), messages, generation_options)
    if progress_callback:
        progress_callback("Η απάντηση δημιουργήθηκε.")
    return result


