# ===== SINGLE LIVE TERMINAL SESSION HELPERS =====

_STUDIO_LIVE_TERMINAL_SENTINEL = "__STUDIO_LIVE_TERMINAL_DONE__"


def _studio_live_terminal_log_dir() -> Path:
    folder = LOGS_DIR / "live_terminals"
    folder.mkdir(parents=True, exist_ok=True)
    return folder


def _studio_live_terminal_log_path(title: str = "training") -> Path:
    safe_title = slugify(title or "training") or "training"
    stamp = time.strftime("%Y%m%d_%H%M%S")
    return _studio_live_terminal_log_dir() / f"{stamp}_{safe_title}_{os.getpid()}.log"


def _studio_append_live_terminal_line(path: Path | str | None, message: str) -> None:
    if not path:
        return
    try:
        append_text_line(Path(path), str(message))
    except Exception:
        pass


def _studio_open_live_terminal_window(log_path: Path, title: str) -> bool:
    if os.name != "nt":
        return False
    try:
        import base64

        path_text = str(Path(log_path).resolve())
        ps_path = path_text.replace("'", "''")
        ps_title = str(title or "LLM Studio - Training").replace("'", "''")
        sentinel = _STUDIO_LIVE_TERMINAL_SENTINEL.replace("'", "''")

        script = f"""
$ErrorActionPreference = 'SilentlyContinue'
$Host.UI.RawUI.WindowTitle = '{ps_title}'
Write-Host 'LLM Studio live terminal'
Write-Host 'Αρχείο παρακολούθησης:'
Write-Host '{ps_path}'
Write-Host ''
$p = '{ps_path}'
while (-not (Test-Path -LiteralPath $p)) {{
    Start-Sleep -Milliseconds 250
}}
Get-Content -LiteralPath $p -Wait -Encoding UTF8 | ForEach-Object {{
    if ($_ -like '{sentinel}*') {{
        break
    }}
    Write-Host $_
}}
Write-Host ''
Write-Host 'Η διεργασία ολοκληρώθηκε ή διακόπηκε.'
Write-Host 'Το παράθυρο θα μείνει ανοιχτό μέχρι να το κλείσεις εσύ.'
""".strip()

        encoded = base64.b64encode(script.encode('utf-16le')).decode('ascii')
        terminal_cmd = [
            'powershell.exe',
            '-NoExit',
            '-NoProfile',
            '-ExecutionPolicy',
            'Bypass',
            '-EncodedCommand',
            encoded,
        ]
        wt_path = shutil.which('wt.exe')
        if wt_path:
            subprocess.Popen(
                [
                    wt_path,
                    'new-tab',
                    '--title',
                    str(title or 'LLM Studio - Training'),
                    *terminal_cmd,
                ],
                cwd=str(PROJECT_ROOT),
            )
        else:
            subprocess.Popen(
                terminal_cmd,
                cwd=str(PROJECT_ROOT),
                creationflags=getattr(subprocess, 'CREATE_NEW_CONSOLE', 0),
            )
        return True
    except Exception:
        return False

# ===== END SINGLE LIVE TERMINAL SESSION HELPERS =====


def parse_cli_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--internal-pipeline", action="store_true")
    parser.add_argument("--internal-step", default="")
    parser.add_argument("--internal-infer", action="store_true")
    parser.add_argument("--config", default="")
    parser.add_argument("--start-stage", default="collect")
    parser.add_argument("--model", default="")
    parser.add_argument("--prompt", default="")
    # Inference generation params (from GUI spinboxes)
    parser.add_argument("--max-new-tokens", type=int, default=512)
    parser.add_argument("--temperature", type=float, default=0.7)
    parser.add_argument("--top-p", type=float, default=0.9)
    return parser.parse_known_args(argv)[0]


def main() -> None:
    args = parse_cli_args(sys.argv[1:])

    if args.internal_pipeline:
        config_path = Path(args.config).resolve()
        raise SystemExit(run_embedded_pipeline(config_path, args.start_stage))

    if args.internal_step:
        config_path = Path(args.config).resolve()
        raise SystemExit(run_embedded_stage(args.internal_step, config_path))

    if args.internal_infer:
        raise SystemExit(run_embedded_inference(
            Path(args.model).resolve(),
            args.prompt,
            max_new_tokens=getattr(args, "max_new_tokens", 512),
            temperature=getattr(args, "temperature", 0.7),
            top_p=getattr(args, "top_p", 0.9),
        ))

    install_global_exception_hooks()

    # Install Qt message handler BEFORE QApplication
    try:
        from PySide6.QtCore import qInstallMessageHandler as _qimh
        _prev = _qimh(_studio_qt_message_handler)
        globals().setdefault('_STUDIO_PREV_QT_MESSAGE_HANDLER', _prev)
    except Exception:
        pass

    app = QApplication(sys.argv)
    app.setApplicationName(APP_TITLE)
    base_font = app.font()
    safe_size = float(base_font.pointSizeF()) if float(base_font.pointSizeF()) > 0 else 11.0
    base_font.setFamily("Segoe UI")
    base_font.setPointSizeF(max(safe_size, 11.0))
    app.setFont(base_font)
    # Προ-δημιουργία GUI bridge στο GUI thread πριν ξεκινήσουν workers
    try:
        _studio_get_gui_bridge()
    except Exception:
        pass

    window = PipelineStudioGUI()

    def _enforce_positive_font_sizes() -> None:
        try:
            for widget in [window, *window.findChildren(QWidget)]:
                font = widget.font()
                if float(font.pointSizeF()) <= 0:
                    font.setPointSizeF(11.0)
                    widget.setFont(font)
        except Exception as exc:
            write_exception_report("QFont positive-size enforcement failed", exc)

    QTimer.singleShot(0, _enforce_positive_font_sizes)

    # Restore saved geometry or centre on screen
    geometry_restored = False
    try:
        from PySide6.QtCore import QSettings
        settings = QSettings(
            str(RUNTIME_CONFIG_DIR / "studio_gui_settings.ini"), QSettings.IniFormat
        )
        saved_geo = settings.value("main/geometry")
        if saved_geo:
            window.restoreGeometry(saved_geo)
            geometry_restored = True
    except Exception:
        pass

    if not geometry_restored:
        try:
            screen = app.primaryScreen()
            if screen is not None:
                available = screen.availableGeometry()
                win_size = window.frameGeometry()
                x = available.x() + (available.width() - win_size.width()) // 2
                y = available.y() + (available.height() - win_size.height()) // 2
                window.move(max(available.x(), x), max(available.y(), y))
        except Exception:
            pass

    window.showMaximized()
    sys.exit(app.exec())


