TRAINED_MODELS_DIR = ARTIFACTS_DIR / "trained_models"
CHAT_ATTACHMENT_MAX_FILES = 12
CHAT_ATTACHMENT_MAX_CHARS_PER_FILE = 14000
CHAT_ATTACHMENT_MAX_TOTAL_CHARS = 50000


def _studio_model_identity_from_config(config: dict[str, Any]) -> tuple[str, str]:
    repo_id = str(config.get("selected_model_repo_id") or "").strip()
    selected_local_dir = str(config.get("selected_model_local_dir") or "").strip()
    base_model = str(config.get("base_model") or "").strip()
    preferred = repo_id or (Path(selected_local_dir).name if selected_local_dir else "") or (Path(base_model).name if base_model and Path(base_model).exists() else "") or base_model or "trained_model"
    label = preferred.strip() or "trained_model"
    return label, slugify(label)


def _studio_model_artifact_root(config: dict[str, Any]) -> Path:
    _label, key = _studio_model_identity_from_config(config)
    root = TRAINED_MODELS_DIR / key
    root.mkdir(parents=True, exist_ok=True)
    return root


def _studio_pick_best_model_dir_from_root(root: Path) -> tuple[Path | None, str]:
    candidates = [
        (root / "final_model", "export"),
        (root / "05_sft", "sft"),
        (root / "03_cpt", "cpt"),
    ]
    for path, stage_name in candidates:
        if not path.exists():
            continue
        if stage_name == "export":
            return path.resolve(), stage_name
        if _studio_has_adapter_files(path) or inspect_local_model_dir(path).get("complete"):
            return path.resolve(), stage_name
    return None, ""


def _studio_write_trained_model_entry(root: Path, config: dict[str, Any], export_payload: dict[str, Any] | None = None) -> dict[str, Any]:
    label, model_key = _studio_model_identity_from_config(config)
    chosen_dir, stage_name = _studio_pick_best_model_dir_from_root(root)
    payload = {
        "model_key": model_key,
        "display_name": label,
        "selected_model_repo_id": str(config.get("selected_model_repo_id") or "").strip(),
        "selected_model_local_dir": str(config.get("selected_model_local_dir") or "").strip(),
        "base_model": str(config.get("base_model") or "").strip(),
        "artifact_root": str(root.resolve()),
        "best_model_dir": str(chosen_dir or ""),
        "best_stage": stage_name,
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
    }
    if isinstance(export_payload, dict) and export_payload:
        payload["last_export"] = export_payload
    try:
        (root / "MODEL_ENTRY.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass
    return payload


def list_trained_model_entries() -> list[dict[str, Any]]:
    TRAINED_MODELS_DIR.mkdir(parents=True, exist_ok=True)
    entries: list[dict[str, Any]] = []
    for root in sorted(TRAINED_MODELS_DIR.iterdir(), key=lambda p: p.stat().st_mtime if p.exists() else 0, reverse=True):
        if not root.is_dir():
            continue
        model_dir, stage_name = _studio_pick_best_model_dir_from_root(root)
        if model_dir is None:
            continue
        metadata = _studio_try_read_json(root / "MODEL_ENTRY.json")
        export_info = _studio_try_read_json(root / "final_model" / "EXPORT_INFO.json")
        display_name = str(export_info.get("selected_model_repo_id") or metadata.get("selected_model_repo_id") or metadata.get("display_name") or root.name).strip() or root.name
        updated_ts = str(export_info.get("timestamp") or metadata.get("timestamp") or "").strip()
        combo_label = f"{display_name}  •  {stage_name}  •  {root.name}"
        entries.append(
            {
                "model_key": str(metadata.get("model_key") or root.name),
                "display_name": display_name,
                "combo_label": combo_label,
                "root_dir": str(root.resolve()),
                "model_dir": str(model_dir.resolve()),
                "stage": stage_name,
                "timestamp": updated_ts,
                "repo_id": str(export_info.get("selected_model_repo_id") or metadata.get("selected_model_repo_id") or "").strip(),
                "base_model": str(export_info.get("base_model") or metadata.get("base_model") or "").strip(),
            }
        )

    legacy_dir = ARTIFACTS_DIR / "final_model"
    legacy_info = _studio_try_read_json(legacy_dir / "EXPORT_INFO.json")
    if legacy_dir.exists() and legacy_dir.is_dir():
        legacy_path = str(legacy_dir.resolve())
        if not any(item.get("model_dir") == legacy_path for item in entries):
            legacy_name = str(legacy_info.get("selected_model_repo_id") or "latest_export").strip() or "latest_export"
            entries.insert(
                0,
                {
                    "model_key": slugify(legacy_name),
                    "display_name": f"{legacy_name} (τελευταίο export)",
                    "combo_label": f"{legacy_name}  •  latest export",
                    "root_dir": str(legacy_dir.resolve()),
                    "model_dir": legacy_path,
                    "stage": "export",
                    "timestamp": str(legacy_info.get("timestamp") or "").strip(),
                    "repo_id": str(legacy_info.get("selected_model_repo_id") or "").strip(),
                    "base_model": str(legacy_info.get("base_model") or "").strip(),
                },
            )
    return entries


_studio_old_stage_output_dir = stage_output_dir

def _studio_patched_stage_output_dir_v2(config: dict[str, Any], stage_key: str) -> Path:
    root = _studio_model_artifact_root(config)
    folder = root / {
        "collect": "01_collect",
        "preprocess": "02_preprocess",
        "cpt": "03_cpt",
        "build_sft": "04_build_sft",
        "sft": "05_sft",
        "eval": "06_eval",
        "export": "final_model",
    }.get(stage_key, stage_key)
    folder.mkdir(parents=True, exist_ok=True)
    _studio_write_trained_model_entry(root, config)
    return folder

