def _studio_patched_ensure_runtime_defaults_v2(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_old_ensure_runtime_defaults_v2(config)
    TRAINED_MODELS_DIR.mkdir(parents=True, exist_ok=True)
    root = _studio_model_artifact_root(config)
    config["model_artifact_root"] = str(root)
    config["trained_model_key"] = root.name
    export_cfg = config.setdefault("export", {})
    export_cfg["final_model_dir"] = str(root / "final_model")
