_studio_ensure_runtime_defaults = _studio_patched_ensure_runtime_defaults_v2


_studio_old_export_stage_v2 = _studio_export_stage

def _studio_sync_latest_export(source_dir: Path, latest_dir: Path) -> None:
    import shutil as _shutil

    if latest_dir.exists() and latest_dir.resolve() != source_dir.resolve():
        _shutil.rmtree(latest_dir, ignore_errors=True)
    latest_dir.parent.mkdir(parents=True, exist_ok=True)
    if latest_dir.resolve() == source_dir.resolve():
        return
    _shutil.copytree(source_dir, latest_dir, dirs_exist_ok=True)


def _studio_patched_export_stage_v2(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults(config)
    payload = _studio_old_export_stage_v2(config)
    final_dir = Path(config.get("export", {}).get("final_model_dir") or (_studio_model_artifact_root(config) / "final_model"))
    latest_dir = Path(config.get("export", {}).get("latest_final_model_dir") or (ARTIFACTS_DIR / "final_model"))
    print(f"[Export] Συγχρονισμός latest export | source={final_dir} | latest={latest_dir}", flush=True)
    try:
        _studio_sync_latest_export(final_dir, latest_dir)
        print("[Export] Συγχρονισμός latest export | status=ok", flush=True)
    except Exception as exc:
        append_log(f"[export] ! αποτυχία συγχρονισμού latest export: {exc}")
        print(f"[Export] Συγχρονισμός latest export | status=failed | error={exc}", flush=True)
    _studio_write_trained_model_entry(_studio_model_artifact_root(config), config, payload)
    print("[Export] Ενημέρωση βιβλιοθήκης trained_models | status=ok", flush=True)
    return payload


_studio_export_stage = _studio_patched_export_stage_v2


def _studio_refresh_trained_model_entries(self, preserve_path: str = "") -> list[dict[str, Any]]:
    entries = list_trained_model_entries()
    self._trained_model_entries = entries
    preserve = preserve_path.strip()
    if not preserve:
        try:
            preserve = self.trained_models_combo.currentData().get("model_dir", "") if self.trained_models_combo.currentData() else ""
        except Exception:
            preserve = ""
    if hasattr(self, "trained_models_combo"):
        combo = self.trained_models_combo
        combo.blockSignals(True)
        combo.clear()
        combo.addItem("— Επίλεξε εκπαιδευμένο / exported μοντέλο —", None)
        selected_index = 0
        for idx, entry in enumerate(entries, start=1):
            combo.addItem(entry.get("combo_label") or entry.get("display_name") or entry.get("model_dir") or "Μοντέλο", entry)
            if preserve and str(entry.get("model_dir") or "") == preserve:
                selected_index = idx
        combo.setCurrentIndex(selected_index)
        combo.blockSignals(False)
    if hasattr(self, "trained_model_info_label"):
        if entries:
            self.trained_model_info_label.setText(f"Βρέθηκαν {len(entries)} εκπαιδευμένα/exported μοντέλα σε ξεχωριστούς φακέλους.")
        else:
            self.trained_model_info_label.setText("Δεν υπάρχουν ακόμη εκπαιδευμένα/exported μοντέλα στη βιβλιοθήκη artifacts/trained_models.")
    return entries


def _studio_get_selected_trained_model_entry(self) -> dict[str, Any] | None:
    combo = getattr(self, "trained_models_combo", None)
    if combo is None:
        return None
    data = combo.currentData()
    return data if isinstance(data, dict) else None


def _studio_use_selected_trained_model_for_training(self) -> None:
    entry = self.get_selected_trained_model_entry()
    if not entry:
        QMessageBox.information(self, APP_TITLE, "Επίλεξε πρώτα εκπαιδευμένο/exported μοντέλο από τη λίστα.")
        return
    model_dir = str(entry.get("model_dir") or "").strip()
    if not model_dir:
        QMessageBox.warning(self, APP_TITLE, "Το επιλεγμένο στοιχείο δεν έχει έγκυρο φάκελο μοντέλου.")
        return
    self.training_model_override_edit.setText(model_dir)
    self._training_override_entry = dict(entry)
    self.log(f"🎯 Η εκπαίδευση θα ξεκινήσει από εκπαιδευμένο/exported μοντέλο: {model_dir}")
    self._set_status_message("Ορίστηκε μοντέλο συνέχειας εκπαίδευσης")


def _studio_clear_training_model_override(self) -> None:
    self.training_model_override_edit.clear()
    self._training_override_entry = None
    self._set_status_message("Καθαρίστηκε το override μοντέλου εκπαίδευσης")


def _studio_use_selected_trained_model_for_inference_from_list(self) -> None:
    entry = self.get_selected_trained_model_entry()
    if not entry:
        QMessageBox.information(self, APP_TITLE, "Επίλεξε πρώτα εκπαιδευμένο/exported μοντέλο από τη λίστα.")
        return
    model_dir = str(entry.get("model_dir") or "").strip()
    if hasattr(self, "infer_model_edit") and model_dir:
        self.infer_model_edit.setText(model_dir)
        self.tabs.setCurrentIndex(1)
        self.log(f"💡 Η δοκιμή θα χρησιμοποιήσει το μοντέλο: {model_dir}")


def _studio_open_selected_trained_model_folder(self) -> None:
    entry = self.get_selected_trained_model_entry()
    if not entry:
        QMessageBox.information(self, APP_TITLE, "Επίλεξε πρώτα εκπαιδευμένο/exported μοντέλο από τη λίστα.")
        return
    path = str(entry.get("root_dir") or entry.get("model_dir") or "").strip()
    if not path:
        return
    self.open_path(path)


def _studio_open_selected_trained_model_chat(self) -> None:
    entry = self.get_selected_trained_model_entry()
    if not entry:
        QMessageBox.information(self, APP_TITLE, "Επίλεξε πρώτα εκπαιδευμένο/exported μοντέλο από τη λίστα.")
        return
    model_dir = str(entry.get("model_dir") or "").strip()
    if model_dir:
        try:
            self.infer_model_edit.setText(model_dir)
        except Exception:
            pass
