def _studio_refresh_inference_trained_models_combo(self, preserve_path: str = "") -> None:
    combo = getattr(self, "infer_trained_models_combo", None)
    if combo is None:
        return
    entries = getattr(self, "_trained_model_entries", None) or list_trained_model_entries()
    preserve = preserve_path.strip() or self.infer_model_edit.text().strip() if hasattr(self, "infer_model_edit") else ""
    combo.blockSignals(True)
    combo.clear()
    combo.addItem("— Γρήγορη επιλογή εκπαιδευμένου μοντέλου —", None)
    selected_index = 0
    for idx, entry in enumerate(entries, start=1):
        combo.addItem(entry.get("combo_label") or entry.get("display_name") or entry.get("model_dir") or "Μοντέλο", entry)
        if preserve and str(entry.get("model_dir") or "") == preserve:
            selected_index = idx
    combo.setCurrentIndex(selected_index)
    combo.blockSignals(False)


def _studio_use_selected_inference_trained_model(self) -> None:
    combo = getattr(self, "infer_trained_models_combo", None)
    if combo is None:
        return
    entry = combo.currentData()
    if not isinstance(entry, dict):
        QMessageBox.information(self, APP_TITLE, "Επίλεξε πρώτα εκπαιδευμένο/exported μοντέλο από τη λίστα.")
        return
    model_dir = str(entry.get("model_dir") or "").strip()
    if model_dir:
        self.infer_model_edit.setText(model_dir)
        self.log(f"💬 Επιλέχθηκε εκπαιδευμένο/exported μοντέλο για δοκιμή: {model_dir}")


_studio_old_build_runtime_config_payload_v3 = PipelineStudioGUI._build_runtime_config_payload

def _studio_patched_build_runtime_config_payload_v3(self):
    payload = _studio_old_build_runtime_config_payload_v3(self)
    override_path = self.training_model_override_edit.text().strip() if hasattr(self, "training_model_override_edit") else ""
    if override_path and Path(override_path).exists():
        payload["base_model"] = override_path
        payload["selected_model_local_dir"] = override_path
        entry = getattr(self, "_training_override_entry", None)
        payload["selected_model_repo_id"] = str((entry or {}).get("repo_id") or (entry or {}).get("display_name") or override_path)
        payload.setdefault("gui_runtime", {})
        payload["gui_runtime"]["training_override_model"] = override_path
        payload["gui_runtime"]["training_override_source"] = "trained_export_list"
    return _studio_ensure_runtime_defaults(payload)


_studio_old_on_command_finished_v2 = PipelineStudioGUI._on_command_finished

def _studio_patched_on_command_finished_v2(self, code: int) -> None:
    _studio_old_on_command_finished_v2(self, code)
    if code == 0:
        try:
            self.refresh_trained_model_entries()
            self._refresh_inference_trained_models_combo()
        except Exception:
            pass


