def _studio_chat_browse_attachments(self) -> None:
    start_dir = str(PROJECT_ROOT)
    if getattr(self, "_attachment_paths", None):
        try:
            start_dir = str(Path(self._attachment_paths[-1]).parent)
        except Exception:
            start_dir = str(PROJECT_ROOT)
    files, _ = QFileDialog.getOpenFileNames(self, "Επιλογή αρχείων για context στο chat", start_dir, "Όλα τα αρχεία (*.*)")
    if not files:
        return
    current = list(getattr(self, "_attachment_paths", []))
    for file_path in files:
        if file_path not in current:
            current.append(file_path)
    self._attachment_paths = current[:CHAT_ATTACHMENT_MAX_FILES]
    self._refresh_attachment_view()
    self._set_status(f"Προστέθηκαν {len(files)} αρχεία στο context του chat.")


def _studio_chat_remove_selected_attachments(self) -> None:
    items = self.attachments_tree.selectedItems() if hasattr(self, "attachments_tree") else []
    if not items:
        return
    to_remove = {str(item.data(0, Qt.UserRole) or "") for item in items}
    self._attachment_paths = [path for path in getattr(self, "_attachment_paths", []) if path not in to_remove]
    self._refresh_attachment_view()


def _studio_chat_clear_attachments(self) -> None:
    self._attachment_paths = []
    self._refresh_attachment_view()


def _studio_chat_read_attachment_payload(self, path: Path) -> tuple[str, str]:
    if not path.exists() or not path.is_file():
        return "", f"{path.name}: δεν βρέθηκε"
    size = path.stat().st_size
    summary = f"{path.name} ({max(1, int(round(size / 1024)))} KB)"
    if size > 2_500_000:
        return "", f"{summary}: παραλείφθηκε επειδή είναι πολύ μεγάλο"
    try:
        raw = _studio_read_text_file(path)
    except Exception as exc:
        return "", f"{summary}: αδυναμία ανάγνωσης ({exc})"
    raw = raw.replace("\x00", " ").strip()
    if not raw:
        return "", f"{summary}: κενό ή μη αναγνώσιμο περιεχόμενο"
    trimmed = raw[:CHAT_ATTACHMENT_MAX_CHARS_PER_FILE]
    if len(raw) > len(trimmed):
        trimmed += "\n\n[... το περιεχόμενο περικόπηκε ...]"
    block = (
        f"\n\n[Συνημμένο αρχείο: {path.name}]\n"
        f"Διαδρομή: {path}\n"
        f"Περιεχόμενο:\n{trimmed}\n"
    )
    return block, summary


def _studio_chat_collect_attachment_context(self) -> tuple[str, list[str], list[str]]:
    parts: list[str] = []
    labels: list[str] = []
    notes: list[str] = []
    current_len = 0
    for raw_path in list(getattr(self, "_attachment_paths", []))[:CHAT_ATTACHMENT_MAX_FILES]:
        path = Path(raw_path)
        payload, summary = self._read_attachment_payload(path)
        if summary:
            labels.append(path.name)
            notes.append(summary)
        if not payload:
            continue
        if current_len + len(payload) > CHAT_ATTACHMENT_MAX_TOTAL_CHARS:
            notes.append("Έγινε περικοπή του συνολικού attachment context για να παραμείνει διαχειρίσιμο.")
            break
        parts.append(payload)
        current_len += len(payload)
    return "".join(parts).strip(), labels, notes


def _studio_chat_refresh_attachment_view(self) -> None:
    tree = getattr(self, "attachments_tree", None)
    if tree is None:
        return
    tree.clear()
    for raw_path in getattr(self, "_attachment_paths", []):
        path = Path(raw_path)
        size_text = "—"
        try:
            size_text = f"{max(1, int(round(path.stat().st_size / 1024)))} KB"
        except Exception:
            pass
        item = QTreeWidgetItem([path.name, size_text, str(path.parent)])
        item.setData(0, Qt.UserRole, str(path))
        tree.addTopLevelItem(item)
    for idx in range(3):
        tree.resizeColumnToContents(idx)
    status_label = getattr(self, "attachment_info_label", None)
    if status_label is not None:
        count = len(getattr(self, "_attachment_paths", []))
        status_label.setText(f"Συνημμένα αρχεία στο context: {count}/{CHAT_ATTACHMENT_MAX_FILES}")


def _studio_chat_build_generation_messages(self) -> list[dict[str, str]]:
    history_limit = max(1, int(self.history_turns_spin.value())) * 2
    history = self._messages[-history_limit:]
    messages: list[dict[str, str]] = []
    last_user_text = _studio_chat_find_last_user_text(history)
    system_prompt = self.system_prompt_edit.toPlainText().strip()
    if _studio_chat_is_python_request(last_user_text):
        extra_instruction = (
            "For the next reply, if you provide Python code, return only one complete ```python``` block "
            "and nothing before or after it. Do not add headings, explanations, duplicate code, or split "
            "the solution into multiple blocks."
        )
        system_prompt = f"{system_prompt}\n\n{extra_instruction}".strip() if system_prompt else extra_instruction
    if system_prompt:
        messages.append({"role": "system", "content": system_prompt})
    for item in history:
        role = str(item.get("role") or "user")
        content = str(item.get("content") or "").strip()
        if role == "user":
            attachment_context = str(item.get("attachment_context") or "").strip()
            if attachment_context:
                content = (
                    f"{content}\n\n"
                    f"Χρησιμοποίησε και τα παρακάτω συνημμένα αρχεία ως context για την απάντηση:\n"
                    f"{attachment_context}"
                ).strip()
        if content:
            messages.append({"role": role, "content": content})
    return messages


def _studio_chat_refresh_view(self) -> None:

    parts = [
        "<div style='font-family:Segoe UI; font-size:13px; line-height:1.55; padding:6px 4px 10px 4px; background:#eaf2fb;'>"
    ]
    if not self._messages:
        parts.append(
            "<div style='margin:10px 6px 14px 6px; text-align:left; background:#eaf2fb;'>"
            "<div style='display:inline-block; max-width:94%; padding:14px 16px; border:1px solid #eaf2fb; border-radius:18px; background:#eaf2fb; color:#5b7698;'>"
            "Ξεκίνα νέα συνομιλία με το επιλεγμένο μοντέλο. Μπορείς να αλλάξεις μοντέλο από τη βιβλιοθήκη εκπαιδευμένων exports, να επισυνάψεις αρχεία και να ρυθμίσεις generation από το δεξί πάνελ."
            "</div></div>"
        )
    for item in self._messages:
        role = str(item.get("role") or "user")
        content = html.escape(str(item.get("content") or "")).replace("\n", "<br>")
        labels = [html.escape(str(x)) for x in list(item.get("attachment_labels") or [])]
        notes = [html.escape(str(x)) for x in list(item.get("attachment_notes") or [])[:3]]

        if role == "user":
            bubble_bg = "#dbeafe"
            title = "Εσύ"
            align = "right"
        else:
            bubble_bg = "#eaf2fb"
            title = "Μοντέλο"
            align = "left"

        meta_html = f"<div style='font-size:11px; color:#5b7698; font-weight:700; margin-bottom:8px; letter-spacing:0.2px; background:{bubble_bg};'>{title}</div>"
        chips_html = ""
        if labels:
            chips_html = "<div style='margin-top:10px; background:" + bubble_bg + ";'>" + "".join(
                f"<span style='display:inline-block; margin:3px 6px 0 0; padding:4px 8px; background:{bubble_bg}; border:1px solid {bubble_bg}; border-radius:999px; font-size:11px; color:#355070;'>{label}</span>"
                for label in labels
            ) + "</div>"
        note_html = ""
        if notes:
            note_html = "<div style='margin-top:8px; font-size:11px; color:#64748b; background:" + bubble_bg + ";'><b>Συνημμένα:</b> " + " • ".join(notes) + "</div>"

        bubble_html = (
            f"<div style='display:inline-block; max-width:94%; text-align:left; background:{bubble_bg}; border:1px solid {bubble_bg}; border-radius:18px; padding:12px 14px;'>"
            f"{meta_html}"
            f"<div style='white-space:pre-wrap; color:#0f172a; background:{bubble_bg};'>{content}</div>"
            f"{chips_html}{note_html}"
            f"</div>"
        )
        parts.append(f"<div style='margin:10px 0; text-align:{align}; background:#eaf2fb;'>{bubble_html}</div>")

    parts.append("</div>")
    self.chat_view.setHtml("".join(parts))
    cursor = self.chat_view.textCursor()
    cursor.movePosition(QTextCursor.End)
    self.chat_view.setTextCursor(cursor)
    self.chat_view.ensureCursorVisible()


def _studio_chat_set_busy(self, busy: bool, text: str = "") -> None:
    for widget_name in [
        "send_btn",
        "regen_btn",
        "new_chat_btn",
        "copy_last_btn",
        "attach_files_btn",
        "remove_attachment_btn",
        "clear_attachments_btn",
        "use_selected_model_btn",
        "refresh_model_list_btn",
        "_sb_send_btn",
        "_sb_regen_btn",
        "_sb_new_chat_btn",
    ]:
        widget = getattr(self, widget_name, None)
        if widget is not None:
            widget.setEnabled(not busy)
    if busy:
        self._set_status(text or "Το μοντέλο επεξεργάζεται το αίτημα...")
    elif text:
        self._set_status(text)


