def _studio_chat_send_message_v2(self) -> None:
    if self._chat_thread is not None:
        QMessageBox.information(self, APP_TITLE, "Περίμενε να ολοκληρωθεί η τρέχουσα απάντηση.")
        return
    model_dir = self.model_dir_edit.text().strip()
    if not model_dir:
        QMessageBox.warning(self, APP_TITLE, "Επίλεξε πρώτα φάκελο μοντέλου.")
        return
    if not Path(model_dir).exists():
        QMessageBox.warning(self, APP_TITLE, "Ο επιλεγμένος φάκελος μοντέλου δεν υπάρχει.")
        return
    user_text = self.input_edit.toPlainText().strip()
    attachment_context, attachment_labels, attachment_notes = self._collect_attachment_context()
    if not user_text and not attachment_context:
        QMessageBox.warning(self, APP_TITLE, "Γράψε μήνυμα ή επισύναψε αρχεία για context.")
        return
    visible_text = user_text or "Use the attached files as context and answer in detail."
    self._messages.append(
        {
            "role": "user",
            "content": visible_text,
            "attachment_context": attachment_context,
            "attachment_labels": attachment_labels,
            "attachment_notes": attachment_notes,
        }
    )
    self.input_edit.clear()
    self._refresh_chat_view()
    self._start_generation()


