# ===== FINAL CLEAN PATCH: progress + chat UI + main entrypoint =====

_STAGE_LABELS_BY_KEY = {value: label for label, value in STAGE_CHOICES}


def _studio_progress_ensure_timer(self) -> None:
    timer = getattr(self, "_progress_timer", None)
    if timer is None:
        timer = QTimer(self)
        timer.setInterval(500)
        timer.timeout.connect(lambda: self._progress_tick())
        self._progress_timer = timer


def _studio_progress_reset(self) -> None:
    self._progress_ensure_timer()
    timer = getattr(self, "_progress_timer", None)
    if timer is not None and timer.isActive():
        timer.stop()
    self._progress_state = {
        "mode": "",
        "title": "",
        "running": False,
        "current_stage": "",
        "last_value": 0,
    }
    try:
        self.progress.setRange(0, 100)
        self.progress.setValue(0)
        self.progress.setFormat("%p%")
        self.progress.update()
    except Exception:
        pass


def _studio_progress_begin(self, title: str = "", mode: str = "command") -> None:
    self._progress_reset()
    self._progress_state = {
        "mode": str(mode or ""),
        "title": str(title or ""),
        "running": True,
        "current_stage": "",
        "last_value": 3,
    }
    try:
        self.progress.setRange(0, 100)
        self.progress.setValue(3)
        short_title = (title[:28] + "…") if len(title) > 28 else title
        self.progress.setFormat(f"⏳ {short_title}  %p%" if short_title else "⏳ Εκτέλεση...  %p%")
        self.progress.setStyleSheet("")   # reset any error color
        self.progress.update()
    except Exception:
        pass
    timer = getattr(self, "_progress_timer", None)
    if timer is not None and not timer.isActive():
        timer.start()


def _studio_progress_tick(self) -> None:
    state = getattr(self, "_progress_state", None) or {}
    if not state.get("running"):
        return
    try:
        current = int(self.progress.value())
    except Exception:
        current = int(state.get("last_value") or 0)

    if state.get("current_stage"):
        cap = 92
        step = 2
    elif state.get("mode") == "background":
        cap = 82
        step = 2
    else:
        cap = 28
        step = 1

    if current < cap:
        current = min(cap, current + step)
        try:
            self.progress.setRange(0, 100)
            self.progress.setValue(current)
            self.progress.update()
        except Exception:
            pass
        state["last_value"] = current
        self._progress_state = state


def _studio_progress_bump(self, amount: int = 1, cap: int = 90) -> None:
    state = getattr(self, "_progress_state", None) or {}
    if not state.get("running"):
        return
    try:
        current = int(self.progress.value())
    except Exception:
        current = int(state.get("last_value") or 0)
    if current < cap:
        current = min(cap, current + max(1, int(amount)))
        try:
            self.progress.setRange(0, 100)
            self.progress.setValue(current)
            self.progress.update()
        except Exception:
            pass
        state["last_value"] = current
        self._progress_state = state


def _studio_progress_begin_stage(self, stage_key: str) -> None:
    self._progress_ensure_timer()
    label = _STAGE_LABELS_BY_KEY.get(stage_key, stage_key)
    state = getattr(self, "_progress_state", None) or {}
    state["running"] = True
    state["current_stage"] = str(stage_key or "")
    state["last_value"] = 4
    self._progress_state = state
    try:
        self.progress.setRange(0, 100)
        self.progress.setValue(4)
        self.progress.setFormat(f"⏳ {label}  %p%")
        self.progress.setStyleSheet("")   # reset error colour
        self.progress.update()
    except Exception:
        pass
    try:
        self._set_status_message(f"⏳  Στάδιο: {label}")
    except Exception:
        pass
    timer = getattr(self, "_progress_timer", None)
    if timer is not None and not timer.isActive():
        timer.start()


def _studio_progress_finish_stage(self, stage_key: str, success: bool = True) -> None:
    label = _STAGE_LABELS_BY_KEY.get(stage_key, stage_key)
    timer = getattr(self, "_progress_timer", None)
    if timer is not None and timer.isActive():
        timer.stop()
    try:
        self.progress.setRange(0, 100)
        self.progress.setValue(100 if success else 0)
        icon = "✓" if success else "❌"
        self.progress.setFormat(f"{icon} {label}  %p%")
        if not success:
            self.progress.setStyleSheet(
                "QProgressBar::chunk { background: qlineargradient(x1:0,y1:0,x2:1,y2:0,"
                "stop:0 #c04040, stop:1 #e06060); border-radius: 10px; }"
            )
        else:
            self.progress.setStyleSheet("")
        self.progress.update()
    except Exception:
        pass
    state = getattr(self, "_progress_state", None) or {}
    state["current_stage"] = ""
    state["last_value"] = 100 if success else 0
    self._progress_state = state
    try:
        icon = "✓" if success else "❌"
        self._set_status_message(
            f"{icon}  Στάδιο {'ολοκληρώθηκε' if success else 'απέτυχε'}: {label}"
        )
    except Exception:
        pass


def _studio_progress_finish(self, success: bool = True, message: str = "") -> None:
    timer = getattr(self, "_progress_timer", None)
    if timer is not None and timer.isActive():
        timer.stop()
    state = getattr(self, "_progress_state", None) or {}
    state["running"] = False
    state["current_stage"] = ""
    state["last_value"] = 100 if success else 0
    self._progress_state = state
    try:
        self.progress.setRange(0, 100)
        self.progress.setValue(100 if success else 0)
        if success:
            self.progress.setFormat("✓ Ολοκληρώθηκε  %p%")
            self.progress.setStyleSheet("")
        else:
            self.progress.setFormat("❌ Σφάλμα  %p%")
            self.progress.setStyleSheet(
                "QProgressBar::chunk { background: qlineargradient(x1:0,y1:0,x2:1,y2:0,"
                "stop:0 #c04040, stop:1 #e06060); border-radius: 10px; }"
            )
        self.progress.update()
    except Exception:
        pass
    if message:
        try:
            icon = "✓" if success else "❌"
            self._set_status_message(f"{icon}  {message}")
        except Exception:
            pass


def _studio_progress_update_from_message(self, message: str) -> None:
    payload = str(message or "").strip()
    if not payload:
        return

    if "[embedded] Εκκίνηση σταδίου:" in payload:
        stage_key = payload.split("[embedded] Εκκίνηση σταδίου:", 1)[1].strip().split()[0]
        self._progress_begin_stage(stage_key)
        return

    if "[embedded] Ολοκληρώθηκε το στάδιο:" in payload:
        stage_key = payload.split("[embedded] Ολοκληρώθηκε το στάδιο:", 1)[1].strip().split()[0]
        self._progress_finish_stage(stage_key, True)
        return

    if "[embedded] Αποτυχία σταδίου" in payload:
        stage_key = payload.split("[embedded] Αποτυχία σταδίου", 1)[1].strip().split(":", 1)[0].strip().split()[0]
        self._progress_finish_stage(stage_key, False)
        return

    state = getattr(self, "_progress_state", None) or {}
    if not state.get("running"):
        return

    if state.get("current_stage"):
        self._progress_bump(2, 90)
    elif state.get("mode") == "background":
        self._progress_bump(4, 88)
    else:
        self._progress_bump(1, 35)


def _studio_log_final(self, message: str) -> None:
    """Route single-line log calls through the same bulk path as _log_batch."""
    if message:
        self._log_batch(message)

# ── Ανάθεση _studio_progress_* μεθόδων στην κλάση ───────────────────────
PipelineStudioGUI._progress_ensure_timer       = _studio_progress_ensure_timer
PipelineStudioGUI._progress_reset              = _studio_progress_reset
PipelineStudioGUI._progress_begin              = _studio_progress_begin
PipelineStudioGUI._progress_tick               = _studio_progress_tick
PipelineStudioGUI._progress_bump               = _studio_progress_bump
PipelineStudioGUI._progress_begin_stage        = _studio_progress_begin_stage
PipelineStudioGUI._progress_finish_stage       = _studio_progress_finish_stage
PipelineStudioGUI._progress_finish             = _studio_progress_finish
PipelineStudioGUI._progress_update_from_message = _studio_progress_update_from_message

# ── Aliases που χρειάζονται οι _studio_*_final wrappers ──────────────────
_studio_old_run_background_final      = PipelineStudioGUI._run_background
_studio_old_background_finished_final = PipelineStudioGUI._background_finished
_studio_old_background_error_final    = PipelineStudioGUI._background_error
_studio_old_start_command_final       = PipelineStudioGUI._start_command
_studio_old_on_command_finished_final = PipelineStudioGUI._on_command_finished


def _studio_run_background_final(
    self,
    fn: Callable[..., Any],
    *args: Any,
    on_success: Callable[[object], None] | None = None,
    on_error: Callable[[str], None] | None = None,
) -> None:
    title = ""
    try:
        title = self._get_status_message()
    except Exception:
        title = ""
    self._progress_begin(title or "Εργασία υποβάθρου", mode="background")
    return _studio_old_run_background_final(
        self,
        fn,
        *args,
        on_success=on_success,
        on_error=on_error,
    )


def _studio_background_finished_final(self, result: object) -> None:
    _studio_old_background_finished_final(self, result)
    self._progress_finish(True, "Ολοκληρώθηκε")


def _studio_background_error_final(self, message: str) -> None:
    _studio_old_background_error_final(self, message)
    self._progress_finish(False, "Σφάλμα")


def _studio_start_command_final(self, command: list[str], title: str) -> None:
    self._progress_begin(title, mode="command")
    _studio_old_start_command_final(self, command, title)


def _studio_on_command_finished_final(self, code: int) -> None:
    _studio_old_on_command_finished_final(self, code)
    try:
        live_path = getattr(self, "_live_terminal_log_path", None)
        if live_path:
            status_text = "Η διεργασία ολοκληρώθηκε επιτυχώς." if int(code) == 0 else f"Η διεργασία τερματίστηκε με κωδικό εξόδου {int(code)}."
            prefix = "✓" if int(code) == 0 else "✗"
            _studio_append_live_terminal_line(live_path, f"[{time.strftime('%H:%M:%S')}] {prefix} {status_text}")
            _studio_append_live_terminal_line(live_path, _STUDIO_LIVE_TERMINAL_SENTINEL)
    except Exception:
        pass
    finally:
        self.__dict__.pop("_live_terminal_log_path", None)
        self.__dict__.pop("_live_terminal_title", None)
    self._progress_finish(int(code) == 0, "Ολοκληρώθηκε" if int(code) == 0 else "Σφάλμα διεργασίας")


# ── Ανάθεση στην κλάση (ο "FINAL" block ~13540 θα επανατοποθετήσει ορισμένες) ──
PipelineStudioGUI._run_background      = _studio_run_background_final
PipelineStudioGUI._background_finished = _studio_background_finished_final
PipelineStudioGUI._background_error    = _studio_background_error_final
PipelineStudioGUI._start_command       = _studio_start_command_final
PipelineStudioGUI._on_command_finished = _studio_on_command_finished_final


def _studio_chat_build_ui_final(self) -> None:
    self._attachment_paths = []
    self._trained_entries  = []
    self.setMinimumSize(900, 680)
    self.setWindowTitle("💬  Chat Μοντέλου — LLM Training Studio")

    # ── Theme palette ──────────────────────────────────────────────────────────
    base_qss = LIGHT_QSS
    try:
        base_qss = self.host.styleSheet() or LIGHT_QSS
    except Exception:
        pass
    _dark = "background: #141c2b" in base_qss

    def _make_chat_palette(is_dark: bool) -> dict:
        if is_dark:
            return dict(
                bg        = "#0f1622", card_bg   = "#192437", border    = "#253650",
                txt       = "#c8d8ee", txt_sub   = "#7a9ec2", input_bg  = "#111d2e",
                bubble_u  = "#1a2d48", bubble_bu = "#2a4168", bubble_a  = "#192437",
                bubble_ba = "#253650", code_bg   = "#141e2e", code_brd  = "#2a3e58",
                sep_col   = "#243454", hdr_stop0 = "#1a3060", hdr_stop1 = "#2a50a0",
                status_bg = "#111928",
            )
        return dict(
            bg        = "#f0f4f8", card_bg   = "#ffffff", border    = "#d0dce8",
            txt       = "#1f3655", txt_sub   = "#5b7698", input_bg  = "#f7fafd",
            bubble_u  = "#eef5ff", bubble_bu = "#cfe0f6", bubble_a  = "#ffffff",
            bubble_ba = "#d7e2ee", code_bg   = "#f0f7ff", code_brd  = "#d7ecff",
            sep_col   = "#d0dbe8", hdr_stop0 = "#1e4080", hdr_stop1 = "#2d6bc4",
            status_bg = "#e2ecf5",
        )

    def _make_chat_qss(base: str, p: dict) -> str:
        return base + f"""
        QMainWindow    {{ background: {p['bg']}; }}
        QWidget        {{ background: transparent; }}
        QGroupBox      {{ background: {p['card_bg']}; border: 1px solid {p['border']};
                          border-radius: 12px; margin-top: 20px; }}
        QGroupBox::title {{ color: {p['txt']}; font-size: 13px; font-weight: 700;
                            subcontrol-origin: margin; subcontrol-position: top left;
                            left: 12px; top: -2px; padding: 0 6px; }}
        QScrollArea, QScrollArea > QWidget > QWidget {{ background: transparent; border: none; }}
        QTextEdit#ChatTranscript, QTextEdit#SystemPromptBox, QTextEdit#ChatInputBox {{
            background: {p['input_bg']}; color: {p['txt']};
            border: 1px solid {p['border']}; border-radius: 10px; padding: 10px;
            selection-background-color: {p['bubble_bu']}; font-size: 14px;
        }}
        QTextBrowser#ChatTranscript {{
            background: {p['card_bg']}; color: {p['txt']};
            border: none; border-radius: 0; font-size: 14px;
        }}
        QTreeWidget#ChatAttachmentsTree {{
            background: {p['input_bg']}; color: {p['txt']};
            border: 1px solid {p['border']}; border-radius: 8px;
        }}
        QHeaderView::section {{
            background: {p['card_bg']}; color: {p['txt_sub']};
            border: none; border-bottom: 1px solid {p['border']};
            border-right: 1px solid {p['border']};
            padding: 4px 8px; font-weight: 600; font-size: 12px;
        }}
        QStatusBar {{ background: {p['status_bg']}; color: {p['txt_sub']}; font-size: 12px; }}
        QLabel {{ background: transparent; color: {p['txt']}; }}
        QGroupBox#ChatModelCard QPushButton {{
            min-height: 24px; max-height: 28px; padding: 2px 10px;
            font-size: 12px; border-radius: 6px;
        }}
        QGroupBox#ChatModelCard QLineEdit, QGroupBox#ChatModelCard QComboBox {{
            min-height: 24px; max-height: 28px; font-size: 12px;
        }}
        """

    self._chat_make_palette = _make_chat_palette
    self._chat_make_qss     = _make_chat_qss
    self._chat_is_dark      = _dark

    p = _make_chat_palette(_dark)
    _bg        = p['bg'];     _card_bg   = p['card_bg']; _border    = p['border']
    _txt       = p['txt'];    _txt_sub   = p['txt_sub']; _input_bg  = p['input_bg']
    _sep_col   = p['sep_col']; _hdr_stop0 = p['hdr_stop0']; _hdr_stop1 = p['hdr_stop1']
    _status_bg = p['status_bg']

    self.setStyleSheet(_make_chat_qss(base_qss, p))

    # ── Root ──────────────────────────────────────────────────────────────────
    root_widget = QWidget()
    root_widget.setObjectName("ChatRoot")
    root_layout = QHBoxLayout(root_widget)
    root_layout.setContentsMargins(0, 0, 0, 0)
    root_layout.setSpacing(0)

    # ════════════════════════════════════════════════════════════════════════
    # SIDEBAR
    # ════════════════════════════════════════════════════════════════════════
    sidebar = QFrame()
    sidebar.setObjectName("Sidebar")
    sidebar.setFixedWidth(232)
    sidebar.setStyleSheet(
        f"QFrame#Sidebar {{ border-right: 1px solid {_sep_col}; border-radius: 0; }}"
    )
    self._chat_sidebar = sidebar
    sb_lay = QVBoxLayout(sidebar)
    sb_lay.setContentsMargins(12, 16, 12, 12)
    sb_lay.setSpacing(3)

    self._chat_dyn_seps = []
    def _sep():
        f = QFrame(); f.setFrameShape(QFrame.HLine)
        f.setStyleSheet(f"background:{_sep_col};max-height:1px;border:none;")
        self._chat_dyn_seps.append(f); return f

    def _sec(text):
        lbl = QLabel(text); lbl.setObjectName("SectionTitle")
        lbl.setStyleSheet("font-size:9px;font-weight:700;letter-spacing:1.2px;padding:2px 0;opacity:0.7;")
        return lbl

    def _sb_btn(label, slot, obj="SidebarButton", tip=""):
        btn = QPushButton(label); btn.setObjectName(obj)
        btn.setMinimumHeight(38); btn.setMinimumWidth(0)
        btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        if tip: btn.setToolTip(tip)
        btn.clicked.connect(slot); return btn

    # Header
    hdr_lbl = QLabel("💬  Chat Studio")
    hdr_lbl.setStyleSheet("font-size:15px;font-weight:700;padding:2px 0;")
    self._sidebar_model_label = QLabel("Χωρίς μοντέλο")
    self._sidebar_model_label.setWordWrap(True)
    self._sidebar_model_label.setAlignment(Qt.AlignCenter)
    self._sidebar_model_label.setObjectName("HeroBadge")
    self._sidebar_model_label.setStyleSheet(
        "font-size:11px;font-weight:600;border-radius:8px;padding:5px 8px;"
    )
    sb_lay.addWidget(hdr_lbl)
    sb_lay.addSpacing(4)
    sb_lay.addWidget(self._sidebar_model_label)
    sb_lay.addSpacing(10)
    sb_lay.addWidget(_sep())
    sb_lay.addSpacing(8)

    # Actions
    sb_lay.addWidget(_sec("ΕΝΕΡΓΕΙΕΣ"))
    sb_lay.addSpacing(3)
    self._sb_send_btn = _sb_btn("🚀  Αποστολή", self.send_message, "PrimaryButton",
                                 "Αποστολή μηνύματος  [Ctrl+Enter]")
    sb_lay.addWidget(self._sb_send_btn)
    self._sb_regen_btn = _sb_btn("🔄  Επαναδημιουργία", self.regenerate_last_answer,
                                  tip="Νέα απάντηση για το τελευταίο μήνυμα")
    sb_lay.addWidget(self._sb_regen_btn)
    self._sb_new_chat_btn = _sb_btn("✨  Νέα συνομιλία", self.clear_chat,
                                     tip="Καθαρίζει το ιστορικό")
    sb_lay.addWidget(self._sb_new_chat_btn)
    sb_lay.addWidget(_sb_btn("📋  Αντιγραφή τελευταίας", self.copy_last_answer,
                              tip="Αντιγράφει την τελευταία απάντηση"))
    sb_lay.addSpacing(8); sb_lay.addWidget(_sep()); sb_lay.addSpacing(8)

    # Model
    sb_lay.addWidget(_sec("ΜΟΝΤΕΛΟ"))
    sb_lay.addSpacing(3)
    sb_lay.addWidget(_sb_btn("📁  Άνοιγμα φακέλου", self.open_model_folder,
                              tip="Άνοιγμα στον explorer"))
    sb_lay.addWidget(_sb_btn("🧹  Εκκαθάριση cache", self.clear_selected_model_cache,
                              tip="Εκ νέου φόρτωση μοντέλου"))
    sb_lay.addSpacing(8); sb_lay.addWidget(_sep()); sb_lay.addSpacing(8)

    # Attachments
    sb_lay.addWidget(_sec("ΣΥΝΗΜΜΈΝΑ"))
    sb_lay.addSpacing(3)
    sb_lay.addWidget(_sb_btn("📎  Προσθήκη αρχείων", self.browse_attachments,
                              tip="Επισυνάπτει αρχεία ως context"))
    sb_lay.addWidget(_sb_btn("🗑  Καθαρισμός", self.clear_attachments,
                              tip="Αφαιρεί όλα τα συνημμένα"))
    sb_lay.addSpacing(8); sb_lay.addWidget(_sep()); sb_lay.addSpacing(8)

    # Theme
    sb_lay.addWidget(_sec("ΘΕΜΑ"))
    sb_lay.addSpacing(3)
    for th_lbl, th_val in [("☀  Light", "light"), ("🌙  Dark", "dark")]:
        tb = QPushButton(th_lbl)
        tb.setMinimumHeight(34); tb.setMinimumWidth(0)
        tb.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        tb.clicked.connect(lambda _=None, v=th_val:
            self.host.apply_theme(v) if getattr(self, 'host', None) else None)
        sb_lay.addWidget(tb)

    sb_lay.addStretch(1)
    sb_lay.addWidget(_sep()); sb_lay.addSpacing(5)
    self._sidebar_status = QLabel("⏳ Έτοιμο.")
    self._sidebar_status.setWordWrap(True)
    self._sidebar_status.setStyleSheet("font-size:11px;padding:2px 0;")
    sb_lay.addWidget(self._sidebar_status)
    root_layout.addWidget(sidebar)

    # ════════════════════════════════════════════════════════════════════════
    # MAIN PANEL
    # ════════════════════════════════════════════════════════════════════════
    main_panel = QFrame()
    main_panel.setObjectName("ChatMainPanel")
    main_panel.setStyleSheet("QFrame#ChatMainPanel{border:none;}")
    main_lay = QVBoxLayout(main_panel)
    main_lay.setContentsMargins(0, 0, 0, 0)
    main_lay.setSpacing(0)

    # ── Header ────────────────────────────────────────────────────────────────
    header_frame = QFrame()
    header_frame.setObjectName("ChatHeader")
    header_frame.setFixedHeight(64)
    header_frame.setStyleSheet(
        f"QFrame#ChatHeader{{background:qlineargradient(x1:0,y1:0,x2:1,y2:0,"
        f"stop:0 {_hdr_stop0},stop:0.6 {_hdr_stop1},stop:1 {_hdr_stop0});border:none;}}"
        " QFrame#ChatHeader QLabel{background:transparent;}"
    )
    self._chat_header_frame = header_frame
    hdr_lay = QHBoxLayout(header_frame)
    hdr_lay.setContentsMargins(20, 0, 20, 0)
    hdr_lay.setSpacing(12)
    ic = QLabel("🧠"); ic.setStyleSheet("font-size:26px;background:transparent;"); ic.setFixedWidth(36)
    hdr_lay.addWidget(ic)
    hdr_t = QVBoxLayout(); hdr_t.setSpacing(1)
    t1 = QLabel("Chat Εκπαιδευμένου Μοντέλου")
    t1.setStyleSheet("color:#fff;font-size:16px;font-weight:700;background:transparent;")
    t2 = QLabel("Multi-turn · System prompt · Attachments · Realtime streaming")
    t2.setStyleSheet("color:rgba(255,255,255,0.65);font-size:11px;background:transparent;")
    hdr_t.addWidget(t1); hdr_t.addWidget(t2)
    hdr_lay.addLayout(hdr_t, 1)
    self._hdr_model_badge = QLabel("")
    self._hdr_model_badge.setStyleSheet(
        "background:rgba(255,255,255,0.18);color:#e8f4ff;"
        "border:1px solid rgba(255,255,255,0.30);border-radius:8px;"
        "padding:3px 12px;font-size:11px;font-weight:600;"
    )
    self._hdr_model_badge.hide()
    hdr_lay.addWidget(self._hdr_model_badge)
    main_lay.addWidget(header_frame)

    # ── Content ───────────────────────────────────────────────────────────────
    content_widget = QWidget()
    content_widget.setStyleSheet(f"background:{_bg};")
    self._chat_content_widget = content_widget
    content_lay = QVBoxLayout(content_widget)
    content_lay.setContentsMargins(12, 8, 12, 8)
    content_lay.setSpacing(8)

    # ── Model card (compact) ──────────────────────────────────────────────────
    model_card = QGroupBox("🤖  Μοντέλο")
    model_card.setObjectName("ChatModelCard")
    mc_lay = QVBoxLayout(model_card)
    mc_lay.setContentsMargins(10, 20, 10, 8)
    mc_lay.setSpacing(4)

    # Row 1: Library picker
    lib_row = QHBoxLayout(); lib_row.setSpacing(6)
    lib_row.addWidget(QLabel("Βιβλιοθήκη:"))
    self.trained_model_combo = QComboBox()
    self.trained_model_combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
    self.trained_model_combo.setMaximumHeight(28)
    self.trained_model_combo.setToolTip("Τοπικά εκπαιδευμένα μοντέλα")
    lib_row.addWidget(self.trained_model_combo, 1)
    self.refresh_model_list_btn = QPushButton("🔄")
    self.refresh_model_list_btn.setFixedSize(28, 28)
    self.refresh_model_list_btn.setToolTip("Ανανέωση λίστας")
    self.refresh_model_list_btn.clicked.connect(lambda: self.refresh_model_list())
    lib_row.addWidget(self.refresh_model_list_btn)
    self.use_selected_model_btn = QPushButton("✓  Χρήση")
    self.use_selected_model_btn.setObjectName("PrimaryButton")
    self.use_selected_model_btn.setMaximumHeight(28)
    self.use_selected_model_btn.setMinimumWidth(0)
    self.use_selected_model_btn.clicked.connect(self.use_selected_library_model)
    lib_row.addWidget(self.use_selected_model_btn)
    mc_lay.addLayout(lib_row)

    # Row 2: Path field + buttons
    dir_row = QHBoxLayout(); dir_row.setSpacing(6)
    self.model_dir_edit = QLineEdit()
    self.model_dir_edit.setPlaceholderText("Path εκπαιδευμένου μοντέλου...")
    self.model_dir_edit.setMinimumHeight(26); self.model_dir_edit.setMaximumHeight(28)
    dir_row.addWidget(self.model_dir_edit, 1)
    for lbl, slot, tip in [
        ("📂", self.browse_model_dir,           "Επιλογή φακέλου"),
        ("📤", self.use_final_model,            "Τελευταίο export"),
        ("➡", self.use_current_main_selection, "Από καρτέλα δοκιμής"),
    ]:
        b = QPushButton(lbl); b.setFixedSize(28, 28); b.setToolTip(tip)
        b.clicked.connect(slot); dir_row.addWidget(b)
    mc_lay.addLayout(dir_row)

    self.model_info_label = QLabel("Επίλεξε μοντέλο για να ξεκινήσεις.")
    self.model_info_label.setWordWrap(True)
    self.model_info_label.setStyleSheet("font-size:11px;color:#5b7698;padding-top:2px;")
    mc_lay.addWidget(self.model_info_label)
    content_lay.addWidget(model_card)

    # ── Main splitter: [chat+settings] / [compose] ───────────────────────────
    body_splitter = QSplitter(Qt.Vertical)
    body_splitter.setChildrenCollapsible(False)
    body_splitter.setHandleWidth(6)

    top_splitter = QSplitter(Qt.Horizontal)
    top_splitter.setChildrenCollapsible(False)
    top_splitter.setHandleWidth(6)

    # ── Chat transcript ───────────────────────────────────────────────────────
    chat_frame = QFrame()
    chat_frame.setObjectName("ChatTranscriptFrame")
    chat_frame.setStyleSheet(
        f"QFrame#ChatTranscriptFrame{{background:{_card_bg};"
        f"border:1px solid {_border};border-radius:12px;}}"
    )
    chat_frame_lay = QVBoxLayout(chat_frame)
    chat_frame_lay.setContentsMargins(0, 0, 0, 0)
    chat_frame_lay.setSpacing(0)

    # Title bar inside chat frame
    chat_title_bar = QFrame()
    chat_title_bar.setFixedHeight(36)
    chat_title_bar.setStyleSheet(
        f"QFrame{{background:{_card_bg};border-bottom:1px solid {_border};"
        f"border-top-left-radius:12px;border-top-right-radius:12px;}}"
    )
    ctb_lay = QHBoxLayout(chat_title_bar)
    ctb_lay.setContentsMargins(14, 0, 10, 0)
    ctb_lay.setSpacing(8)
    ctb_title = QLabel("💬  Συνομιλία")
    ctb_title.setStyleSheet(f"font-size:12px;font-weight:700;color:{_txt};")
    ctb_lay.addWidget(ctb_title, 1)
    # Token counter pill
    self._token_counter_lbl = QLabel("")
    self._token_counter_lbl.setStyleSheet(
        f"font-size:10px;color:{_txt_sub};"
        f"background:{_input_bg};border:1px solid {_border};"
        f"border-radius:8px;padding:2px 8px;"
    )
    self._token_counter_lbl.hide()
    ctb_lay.addWidget(self._token_counter_lbl)
    chat_frame_lay.addWidget(chat_title_bar)

    self.chat_view = QTextEdit()
    self.chat_view.setObjectName("ChatTranscript")
    self.chat_view.setReadOnly(True)
    self.chat_view.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
    self.chat_view.setFrameShape(QFrame.NoFrame)
    self.chat_view.setStyleSheet("QTextEdit{border:none;border-radius:0;padding:12px;}")
    try:
        self.chat_view.document().setDocumentMargin(8)
        self.chat_view.setWordWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
    except Exception:
        pass
    chat_frame_lay.addWidget(self.chat_view, 1)

    # Inline status strip at bottom of chat
    self.chat_status_label = QLabel("⏳ Έτοιμο για συνομιλία.")
    self.chat_status_label.setStyleSheet(
        f"font-size:11px;padding:5px 14px;"
        f"background:{_status_bg};"
        f"border-top:1px solid {_border};"
        f"border-bottom-left-radius:12px;border-bottom-right-radius:12px;"
    )
    self.chat_status_label.setWordWrap(True)
    chat_frame_lay.addWidget(self.chat_status_label)
    top_splitter.addWidget(chat_frame)

    # ── Settings panel ────────────────────────────────────────────────────────
    settings_scroll = QScrollArea()
    settings_scroll.setWidgetResizable(True)
    settings_scroll.setFrameShape(QFrame.NoFrame)
    settings_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
    settings_panel = QWidget()
    settings_lay = QVBoxLayout(settings_panel)
    settings_lay.setContentsMargins(4, 0, 0, 0)
    settings_lay.setSpacing(8)

    # System prompt card
    sys_card = QGroupBox("🧠  System Prompt")
    sys_lay = QVBoxLayout(sys_card)
    sys_lay.setContentsMargins(10, 22, 10, 10)
    sys_lay.setSpacing(6)
    self.system_prompt_edit = QTextEdit()
    self.system_prompt_edit.setObjectName("SystemPromptBox")
    self.system_prompt_edit.setPlaceholderText("System prompt (optional)...")
    self.system_prompt_edit.setMinimumHeight(90)
    self.system_prompt_edit.setFrameShape(QFrame.NoFrame)
    self.system_prompt_edit.setPlainText(SYSTEM_PROMPT_DEFAULT_EN)
    sys_lay.addWidget(self.system_prompt_edit)
    h_row = QHBoxLayout()
    h_row.addWidget(QLabel("Ιστορικό (γύροι):"))
    self.history_turns_spin = QSpinBox()
    self.history_turns_spin.setRange(1, 50); self.history_turns_spin.setValue(12)
    self.history_turns_spin.setToolTip("Ζεύγη ερώτηση-απάντηση στη μνήμη")
    self.history_turns_spin.setFixedWidth(60)
    h_row.addWidget(self.history_turns_spin); h_row.addStretch()
    sys_lay.addLayout(h_row)
    settings_lay.addWidget(sys_card)

    # Generation params card
    gen_card = QGroupBox("🎛  Παράμετροι")
    gen_grid = QGridLayout(gen_card)
    gen_grid.setContentsMargins(10, 22, 10, 10)
    gen_grid.setHorizontalSpacing(8); gen_grid.setVerticalSpacing(6)
    param_rows = [
        ("max_new_tokens",    "Max tokens",    "QSpinBox",       (16, 8192), 2048,  0.0,  "Μέγιστος αριθμός νέων tokens"),
        ("temperature",       "Temperature",   "QDoubleSpinBox", (0.0, 2.0), 0.7,   0.05, "0=απόλυτα στατικό · 1=δημιουργικό"),
        ("top_p",             "Top-p",         "QDoubleSpinBox", (0.05,1.0), 0.9,   0.05, "Nucleus sampling (0.9 συνιστάται)"),
        ("top_k",             "Top-k",         "QSpinBox",       (0, 500),   40,    0.0,  "Top-k sampling (0=απενεργοποίηση)"),
        ("repetition_penalty","Rep. penalty",  "QDoubleSpinBox", (1.0, 3.0), 1.05,  0.05, "Αποφυγή επανάληψης (1.0=καμία)"),
    ]
    for r, (attr, lbl, kind, rng, val, step, tip) in enumerate(param_rows):
        lbl_w = QLabel(lbl); lbl_w.setStyleSheet("font-size:12px;")
        gen_grid.addWidget(lbl_w, r, 0)
        if kind == "QSpinBox":
            w = QSpinBox(); w.setRange(int(rng[0]), int(rng[1])); w.setValue(int(val))
        else:
            w = QDoubleSpinBox(); w.setRange(*rng); w.setSingleStep(step)
            w.setDecimals(2); w.setValue(float(val))
        w.setToolTip(tip); w.setMinimumHeight(28)
        setattr(self, f"{attr}_spin", w)
        gen_grid.addWidget(w, r, 1)
    gen_grid.setColumnStretch(1, 1)
    self.do_sample_check = QCheckBox("Sampling (do_sample)")
    self.do_sample_check.setChecked(True)
    self.do_sample_check.setToolTip("False = greedy decoding")
    gen_grid.addWidget(self.do_sample_check, len(param_rows), 0, 1, 2)
    settings_lay.addWidget(gen_card)

    # Attachments card
