def _studio_chat_apply_theme(self, name: str) -> None:
    """Re-theme the chat window to match the main app's light/dark theme.

    Called either by the sidebar buttons (→ host.apply_theme → propagates here)
    or directly when the window is first shown with a different theme than default.
    Updates:
      • The main QSS cascade (base_qss + dynamic chat overrides)
      • Inline-styled widgets that QSS cascade cannot reach:
          - sidebar border  (QFrame#Sidebar inline style)
          - header gradient (QFrame#ChatHeader inline style)
          - content_widget background
          - action_frame top-border
          - all _sep() separator frames
    Also re-renders the chat HTML so bubble colours match.
    """
    is_dark = (name == "dark")
    self._chat_is_dark = is_dark

    try:
        make_pal = getattr(self, '_chat_make_palette', None)
        make_qss = getattr(self, '_chat_make_qss', None)
        if make_pal is None or make_qss is None:
            return
        p = make_pal(is_dark)
        base_qss = (DARK_QSS if is_dark else LIGHT_QSS)
        self.setStyleSheet(make_qss(base_qss, p))
    except Exception:
        return

    # ── Re-apply inline styles that override QSS cascade ────────────────
    try:
        s = getattr(self, '_chat_sidebar', None)
        if s:
            s.setStyleSheet(
                f"QFrame#Sidebar {{ border-right: 1px solid {p['sep_col']}; border-radius: 0px; }}"
            )
    except Exception:
        pass

    try:
        hf = getattr(self, '_chat_header_frame', None)
        if hf:
            hf.setStyleSheet(
                "QFrame#ChatHeader { background: qlineargradient(x1:0,y1:0,x2:1,y2:0,"
                f"stop:0 {p['hdr_stop0']}, stop:0.5 {p['hdr_stop1']}, stop:1 {p['hdr_stop0']}); border: none; }}"
                " QFrame#ChatHeader QLabel { background: transparent; }"
            )
    except Exception:
        pass

    try:
        cw = getattr(self, '_chat_content_widget', None)
        if cw:
            cw.setStyleSheet(f"background: {p['bg']};")
    except Exception:
        pass

    try:
        af = getattr(self, '_chat_action_frame', None)
        if af:
            af.setStyleSheet(
                f"QFrame {{ border-top: 1px solid {p['sep_col']}; border-radius: 0px; }}"
            )
    except Exception:
        pass

    try:
        for f in getattr(self, '_chat_dyn_seps', []):
            try:
                f.setStyleSheet(f"background: {p['sep_col']}; max-height: 1px; border: none;")
            except Exception:
                pass
    except Exception:
        pass

    # ── Re-render chat HTML so bubble colours match ──────────────────────
    try:
        self._refresh_chat_view()
    except Exception:
        pass


StudioModelChatWindow.apply_theme = _studio_chat_apply_theme


# ===== STUDIO SETTINGS / SAFE SCROLL PATCH =====

def _studio_settings_store():
    from PySide6.QtCore import QSettings
    RUNTIME_CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    return QSettings(str(RUNTIME_CONFIG_DIR / "studio_gui_settings.ini"), QSettings.IniFormat)


def _studio_safe_scroll_to_bottom(widget: Any) -> None:
    if widget is None:
        return
    try:
        bar = widget.verticalScrollBar()
        if bar is not None:
            bar.setValue(bar.maximum())
    except RuntimeError:
        return
    except Exception:
        return


def _studio_gui_defer_scroll_to_bottom(self, view: Any | None = None) -> None:
    target = view if view is not None else getattr(self, "logs", None)
    if target is None:
        return
    try:
        QTimer.singleShot(0, lambda target=target: _studio_safe_scroll_to_bottom(target))
    except Exception:
        pass


def _studio_chat_defer_scroll_to_bottom(self, view: Any | None = None) -> None:
    """Scroll to bottom — synchronously first, then verify with a deferred check."""
    target = view if view is not None else getattr(self, "chat_view", None)
    if target is None:
        return
    # Try immediate synchronous scroll first (no timer → no flash)
    try:
        bar = target.verticalScrollBar()
        if bar is not None:
            bar.setValue(bar.maximum())
    except Exception:
        pass
    # One deferred verify in case layout hasn't settled yet
    try:
        QTimer.singleShot(80, lambda t=target: _studio_safe_scroll_to_bottom(t))
    except Exception:
        pass


def _studio_save_main_window_settings(self) -> None:
    settings = _studio_settings_store()
    try:
        settings.setValue("main/geometry", self.saveGeometry())
    except Exception:
        pass

    field_writers = [
        ("main/python_exec", getattr(self, "python_edit", None), "text"),
        ("main/config_path", getattr(self, "config_edit", None), "text"),
        ("main/profile_name", getattr(self, "profile_combo", None), "currentText"),
        ("main/search_terms", getattr(self, "search_terms_edit", None), "text"),
        ("main/custom_model_id", getattr(self, "custom_model_edit", None), "text"),
        ("main/infer_model_dir", getattr(self, "infer_model_edit", None), "text"),
        ("main/hf_token", getattr(self, "hf_token_edit", None), "text"),
    ]
    for key, widget, getter_name in field_writers:
        if widget is None:
            continue
        try:
            settings.setValue(key, getattr(widget, getter_name)())
        except Exception:
            pass

    prompt_widget = getattr(self, "infer_prompt", None)
    if prompt_widget is not None:
        try:
            settings.setValue("main/infer_prompt", prompt_widget.toPlainText())
        except Exception:
            pass

    # Save training hyperparameter spinbox values
    spinbox_map = [
        ("train/epochs",        "param_epochs",        "value"),
        ("train/learning_rate", "param_lr",            "value"),
        ("train/max_length",    "param_max_len",       "value"),
        ("train/micro_batch",   "param_micro_batch",   "value"),
        ("train/grad_accum",    "param_grad_accum",    "value"),
        ("train/warmup",        "param_warmup",        "value"),
        ("train/lora_r",        "param_lora_r",        "value"),
        ("train/lora_alpha",    "param_lora_alpha",    "value"),
        ("train/lora_dropout",  "param_lora_dropout",  "value"),
        ("infer/max_tokens",    "infer_max_tokens",    "value"),
        ("infer/temperature",   "infer_temperature",   "value"),
        ("infer/top_p",         "infer_top_p",         "value"),
    ]
    for key, attr, getter in spinbox_map:
        widget = getattr(self, attr, None)
        if widget is not None:
            try:
                settings.setValue(key, getattr(widget, getter)())
            except Exception:
                pass

    for key, widget in [
        ("main/auto_search_on_start", getattr(self, "auto_search_check", None)),
        ("main/auto_prepare_model", getattr(self, "auto_prepare_check", None)),
        ("main/include_gated", getattr(self, "include_gated_check", None)),
    ]:
        if widget is None:
            continue
        try:
            settings.setValue(key, bool(widget.isChecked()))
        except Exception:
            pass

    try:
        settings.setValue("main/theme_name", str(getattr(self, "_theme_name", DEFAULT_THEME) or DEFAULT_THEME))
    except Exception:
        pass

    try:
        settings.sync()
    except Exception:
        pass


def _studio_restore_main_window_settings(self) -> None:
    settings = _studio_settings_store()

    def _read_bool(key: str, default: bool) -> bool:
        value = settings.value(key, default)
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() in {"1", "true", "yes", "on"}

    try:
        theme_name = str(settings.value("main/theme_name", DEFAULT_THEME) or DEFAULT_THEME).strip().lower()
        if theme_name in {"light", "dark"}:
            self.apply_theme(theme_name)
    except Exception:
        pass

    widget_values = [
        (getattr(self, "python_edit", None), settings.value("main/python_exec", getattr(self, "python_exec", sys.executable))),
        (getattr(self, "config_edit", None), settings.value("main/config_path", getattr(self, "config_path", ""))),
        (getattr(self, "search_terms_edit", None), settings.value("main/search_terms", "coder, python, code")),
        (getattr(self, "custom_model_edit", None), settings.value("main/custom_model_id", "")),
        (getattr(self, "infer_model_edit", None), settings.value("main/infer_model_dir", str(ARTIFACTS_DIR / "final_model"))),
        (getattr(self, "hf_token_edit", None), settings.value("main/hf_token", "")),
    ]
    for widget, value in widget_values:
        if widget is None or value is None:
            continue
        try:
            old = widget.blockSignals(True)
            widget.setText(str(value))
            widget.blockSignals(old)
        except Exception:
            pass

    prompt_value = settings.value("main/infer_prompt", None)
    if prompt_value is not None and getattr(self, "infer_prompt", None) is not None:
        try:
            old = self.infer_prompt.blockSignals(True)
            self.infer_prompt.setPlainText(str(prompt_value))
            self.infer_prompt.blockSignals(old)
        except Exception:
            pass

    profile_name = str(settings.value("main/profile_name", getattr(self, "profile_name", PROFILE_SAFE)) or PROFILE_SAFE)
    if getattr(self, "profile_combo", None) is not None:
        try:
            old = self.profile_combo.blockSignals(True)
            index = self.profile_combo.findText(profile_name)
            if index >= 0:
                self.profile_combo.setCurrentIndex(index)
            self.profile_combo.blockSignals(old)
        except Exception:
            pass

    checkbox_values = [
        (getattr(self, "auto_search_check", None), _read_bool("main/auto_search_on_start", True)),
        (getattr(self, "auto_prepare_check", None), _read_bool("main/auto_prepare_model", True)),
        (getattr(self, "include_gated_check", None), _read_bool("main/include_gated", False)),
    ]
    for widget, value in checkbox_values:
        if widget is None:
            continue
        try:
            old = widget.blockSignals(True)
            widget.setChecked(bool(value))
            widget.blockSignals(old)
        except Exception:
            pass

    # Restore training hyperparameter spinbox values
    spinbox_restore_map = [
        ("train/epochs",        "param_epochs",        "setInt",   1),
        ("train/learning_rate", "param_lr",            "setFloat", 2e-4),
        ("train/max_length",    "param_max_len",       "setInt",   2048),
        ("train/micro_batch",   "param_micro_batch",   "setInt",   1),
        ("train/grad_accum",    "param_grad_accum",    "setInt",   8),
        ("train/warmup",        "param_warmup",        "setFloat", 0.03),
        ("train/lora_r",        "param_lora_r",        "setInt",   16),
        ("train/lora_alpha",    "param_lora_alpha",    "setInt",   32),
        ("train/lora_dropout",  "param_lora_dropout",  "setFloat", 0.05),
        ("infer/max_tokens",    "infer_max_tokens",    "setInt",   512),
        ("infer/temperature",   "infer_temperature",   "setFloat", 0.7),
        ("infer/top_p",         "infer_top_p",         "setFloat", 0.9),
    ]
    for key, attr, kind, default in spinbox_restore_map:
        widget = getattr(self, attr, None)
        if widget is None:
            continue
        try:
            raw = settings.value(key, default)
            if kind == "setInt":
                widget.setValue(int(float(raw)))
            else:
                widget.setValue(float(raw))
        except Exception:
            pass

    try:
        self.apply_hf_token_from_ui(log_message=False)
    except Exception:
        pass

    geometry = settings.value("main/geometry", None)
    if geometry is not None:
        try:
            self.restoreGeometry(geometry)
        except Exception:
            pass

    try:
        self._refresh_hf_token_status_label()
    except Exception:
        pass

    try:
        self._update_selected_model_state()
    except Exception:
        pass
    try:
        current = self._current_selected_model()
        if current:
            self._apply_model_autotune(current["repo_id"], force=True)
    except Exception:
        pass
    try:
        self._refresh_inference_trained_models_combo()
    except Exception:
        pass


def _studio_connect_main_window_settings_signals(self) -> None:
    if getattr(self, "_settings_signals_connected", False):
        return
    self._settings_signals_connected = True

    signal_specs = [
        (getattr(self, "python_edit", None), "textChanged"),
        (getattr(self, "config_edit", None), "textChanged"),
        (getattr(self, "profile_combo", None), "currentTextChanged"),
        (getattr(self, "search_terms_edit", None), "textChanged"),
        (getattr(self, "custom_model_edit", None), "textChanged"),
        (getattr(self, "infer_model_edit", None), "textChanged"),
        (getattr(self, "hf_token_edit", None), "textChanged"),
        (getattr(self, "infer_prompt", None), "textChanged"),
        (getattr(self, "auto_search_check", None), "toggled"),
        (getattr(self, "auto_prepare_check", None), "toggled"),
        (getattr(self, "include_gated_check", None), "toggled"),
    ]
    for widget, signal_name in signal_specs:
        if widget is None:
            continue
        try:
            getattr(widget, signal_name).connect(self.save_ui_settings)
        except Exception:
            pass


def _studio_refresh_hf_token_status_label(self) -> None:
    label = getattr(self, "hf_token_status_label", None)
    if label is None:
        return
    try:
        label.setText(get_hf_auth_status_message())
    except Exception:
        pass


def _studio_toggle_hf_token_visibility(self, checked: bool) -> None:
    edit = getattr(self, "hf_token_edit", None)
    button = getattr(self, "hf_token_toggle_btn", None)
    if edit is None:
        return
    try:
        edit.setEchoMode(QLineEdit.Normal if checked else QLineEdit.Password)
    except Exception:
        return
    if button is not None:
        try:
            button.setText("Απόκρυψη" if checked else "Εμφάνιση")
        except Exception:
            pass


def _studio_apply_hf_token_from_ui(self, log_message: bool = True) -> None:
    edit = getattr(self, "hf_token_edit", None)
    token_value = ""
    if edit is not None:
        try:
            token_value = str(edit.text() or "").strip()
        except Exception:
            token_value = ""

    apply_runtime_hf_token_override(token_value)

    try:
        self._refresh_hf_token_status_label()
    except Exception:
        pass

    if getattr(self, "_settings_restore_in_progress", False):
        return

    try:
        self.save_ui_settings()
    except Exception:
        pass

    if not log_message:
        return

    if token_value:
        self.log("✓ Εφαρμόστηκε αποθηκευμένο HF_TOKEN από το GUI.")
    else:
        self.log("ℹ Καθαρίστηκε το HF_TOKEN του GUI. Η εφαρμογή θα χρησιμοποιεί μόνο τυχόν token από το περιβάλλον ή από το Hugging Face login.")


def _studio_clear_saved_hf_token(self) -> None:
    edit = getattr(self, "hf_token_edit", None)
    if edit is not None:
        try:
            old = edit.blockSignals(True)
            edit.clear()
            edit.blockSignals(old)
        except Exception:
            try:
                edit.clear()
            except Exception:
                pass
    apply_runtime_hf_token_override("")
    try:
        self._refresh_hf_token_status_label()
    except Exception:
        pass
    try:
        self.save_ui_settings()
    except Exception:
        pass
    self.log("ℹ Το αποθηκευμένο HF_TOKEN αφαιρέθηκε από τις ρυθμίσεις του GUI.")


def _studio_main_apply_theme_persist(self, theme_name: str) -> None:
    _studio_old_apply_theme_persist(self, theme_name)
    if getattr(self, "_settings_restore_in_progress", False):
        return
    try:
        self.save_ui_settings()
    except Exception:
        pass
    # Broadcast theme to all open chat windows — use their own apply_theme
    # so inline-styled widgets (sidebar, header, content bg, separators) are
    # also updated correctly, and chat HTML bubbles re-render with new colours.
    for win in list(getattr(self, "_chat_windows", [])):
        try:
            if hasattr(win, "apply_theme"):
                win.apply_theme(theme_name)
            else:
                # Fallback for older windows without apply_theme
                _qss = DARK_QSS if (theme_name == "dark") else LIGHT_QSS
                win.setStyleSheet(_qss)
        except Exception:
            pass


def _studio_main_close_event_persist(self, event) -> None:  # type: ignore[override]
    if self._current_process is not None:
        reply = QMessageBox.question(
            self,
            APP_TITLE,
            "Υπάρχει ενεργή διεργασία. Θέλεις να τη σταματήσεις και να κλείσει η εφαρμογή;",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if reply == QMessageBox.No:
            event.ignore()
            return
        self.stop_current_job()
    try:
        self.save_ui_settings()
    except Exception:
        pass
    event.accept()


def _studio_main_init_persist(self, *args: Any, **kwargs: Any) -> None:
    try:
        preloaded_settings = _studio_settings_store()
        preloaded_token = str(preloaded_settings.value("main/hf_token", "") or "").strip()
        apply_runtime_hf_token_override(preloaded_token)
    except Exception:
        pass

    _studio_old_main_init_persist(self, *args, **kwargs)
    self._settings_restore_in_progress = True
    try:
        self.restore_ui_settings()
    finally:
        self._settings_restore_in_progress = False
    try:
        self.connect_ui_settings_signals()
    except Exception as exc:
        write_exception_report("Main settings signal binding failed", exc)
    try:
        self._refresh_hf_token_status_label()
    except Exception:
        pass


def _studio_refresh_online_models_safe(self, manual: bool = True) -> None:
    if self._job_thread:
        self.log("⚠ Υπάρχει ήδη ενεργή διεργασία. Σταμάτησέ την πρώτα αν χρειάζεται.")
        return
    terms = [term.strip() for term in self.search_terms_edit.text().split(",") if term.strip()]
    if not terms:
        terms = ["coder", "python", "code"]
    include_gated = False
    try:
        include_gated = bool(getattr(self, "include_gated_check", None) and self.include_gated_check.isChecked())
    except Exception:
        pass
    if manual:
        self.log(f"🔎 Online αναζήτηση μοντέλων με όρους: {', '.join(terms)}")
    self._set_status_message("Αναζήτηση online μοντέλων...")
    self.progress.setRange(0, 0)  # indeterminate

    def _on_success(results: object) -> None:
        try:
            self.progress.setRange(0, 100)
            self.progress.setValue(100)
            entries = results if isinstance(results, list) else []
            self._online_entries = entries
            self._rebuild_model_tree()
            n = len(entries)
            n_local = sum(1 for e in entries if self._local_dir_if_ready(e.get("repo_id", "") or ""))
            self.log(f"✓ Βρέθηκαν {n} μοντέλα ({n_local} τοπικά)")
            self._set_status_message(f"✓ {n} μοντέλα — {n_local} τοπικά", 5000)
        except Exception as exc:
            write_exception_report("_studio_refresh_online_models_safe on_success failed", exc)

    def _on_error(msg: str) -> None:
        try:
            self.progress.setRange(0, 100)
            self.progress.setValue(0)
            self.log(f"⚠ Αναζήτηση Hub απέτυχε: {msg}")
            self._set_status_message("⚠ Αναζήτηση απέτυχε — δείτε το log.", 6000)
            # Load any cached or local results so the tree is not empty
            fallback: list[dict[str, Any]] = []
            try:
                if MODEL_DISCOVERY_CACHE.exists():
                    fallback = json.loads(MODEL_DISCOVERY_CACHE.read_text(encoding="utf-8"))
            except Exception:
                pass
            if not fallback:
                try:
                    fallback = list_local_models_embedded(BASE_MODELS_DIR)
                except Exception:
                    pass
            if fallback:
                self._online_entries = fallback
                self._rebuild_model_tree()
                self.log(f"ℹ Εμφανίζονται {len(fallback)} cached/τοπικά μοντέλα.")
        except Exception as exc:
            write_exception_report("_studio_refresh_online_models_safe on_error failed", exc)

    self._run_background(self._discover_models_worker, terms, include_gated,
                         on_success=_on_success, on_error=_on_error)


def _studio_discover_models_worker_safe(self, terms: list[str], include_gated: bool = False, progress_callback: Callable[[str], None] | None = None) -> list[dict[str, Any]]:
    if progress_callback:
        progress_callback("Σύνδεση με Hugging Face Hub...")
    try:
        token = get_hf_token()
        results = discover_supported_models_embedded(
            search_terms=terms,
            limit_per_term=20,
            gated=None if include_gated else False,
            token=token,
            progress_callback=progress_callback,
        )
        if results:
            try:
                MODEL_DISCOVERY_CACHE.write_text(
                    json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8"
                )
            except Exception:
                pass
            return results
        return list_local_models_embedded(BASE_MODELS_DIR)
    except BaseException as exc:
        write_exception_report("_studio_discover_models_worker_safe failed", exc)
        if progress_callback:
            progress_callback(f"⚠ Σφάλμα αναζήτησης: {exc} — φορτώνονται τοπικά μοντέλα.")
        try:
            if MODEL_DISCOVERY_CACHE.exists():
                return json.loads(MODEL_DISCOVERY_CACHE.read_text(encoding="utf-8"))
        except Exception:
            pass
        try:
            return list_local_models_embedded(BASE_MODELS_DIR)
        except Exception:
            return []


def _studio_log_final_safe(self, message: str) -> None:
    """Thread-safe single-line log — routes through _log_batch."""
    if message:
        self._log_batch(message)

def _studio_chat_refresh_view_safe(self) -> None:

    parts = [
        "<div style='font-family:Segoe UI; font-size:13px; line-height:1.58; padding:8px 6px 10px 6px; background:#ffffff;'>"
    ]
    if not self._messages:
        parts.append(
            "<div style='margin:8px 4px 12px 4px; text-align:left; background:#ffffff;'>"
            "<div style='display:inline-block; max-width:94%; padding:14px 16px; border:1px solid #d7e2ee; border-radius:14px; background:#ffffff; color:#5b7698;'>"
            "Ξεκίνα νέα συνομιλία με το επιλεγμένο μοντέλο. Μπορείς να αλλάξεις μοντέλο από τη βιβλιοθήκη, να επισυνάψεις αρχεία και να ρυθμίσεις το generation από τα δεξιά."
            "</div></div>"
        )

    for item in self._messages:
        role = str(item.get("role") or "user")
        content = html.escape(str(item.get("content") or "")).replace("\n", "<br>")
        labels = [html.escape(str(x)) for x in list(item.get("attachment_labels") or [])]
        notes = [html.escape(str(x)) for x in list(item.get("attachment_notes") or [])[:3]]

        if role == "user":
            bubble_bg = "#eef5ff"
            bubble_border = "#cfe0f6"
            title = "Εσύ"
            align = "right"
        else:
            bubble_bg = "#ffffff"
            bubble_border = "#d7e2ee"
            title = "Μοντέλο"
            align = "left"

        chips_html = ""
        if labels:
            chips_html = "<div style='margin-top:10px; background:" + bubble_bg + ";'>" + "".join(
                f"<span style='display:inline-block; margin:3px 6px 0 0; padding:4px 8px; background:#ffffff; border:1px solid {bubble_border}; border-radius:999px; font-size:11px; color:#355070;'>{label}</span>"
                for label in labels
            ) + "</div>"

        note_html = ""
        if notes:
            note_html = "<div style='margin-top:8px; font-size:11px; color:#64748b; background:" + bubble_bg + ";'><b>Συνημμένα:</b> " + " • ".join(notes) + "</div>"

        bubble_html = (
            f"<div style='display:inline-block; max-width:94%; text-align:left; background:{bubble_bg}; border:1px solid {bubble_border}; border-radius:14px; padding:12px 14px;'>"
            f"<div style='font-size:11px; color:#5b7698; font-weight:700; margin-bottom:8px; letter-spacing:0.2px; background:{bubble_bg};'>{title}</div>"
            f"<div style='white-space:pre-wrap; color:#0f172a; background:{bubble_bg};'>{content}</div>"
            f"{chips_html}{note_html}"
            f"</div>"
        )
        parts.append(f"<div style='margin:10px 0; text-align:{align}; background:#ffffff;'>{bubble_html}</div>")

    parts.append("</div>")
    self.chat_view.setHtml("".join(parts))
    self.chat_defer_scroll_to_bottom()


def _studio_save_chat_window_settings(self) -> None:
    settings = _studio_settings_store()
    try:
        settings.setValue("chat/geometry", self.saveGeometry())
    except Exception:
        pass

    pairs = [
        ("chat/model_dir", getattr(self, "model_dir_edit", None), "text"),
        ("chat/system_prompt", getattr(self, "system_prompt_edit", None), "toPlainText"),
        ("chat/input_draft", getattr(self, "input_edit", None), "toPlainText"),
        ("chat/history_turns", getattr(self, "history_turns_spin", None), "value"),
        ("chat/max_new_tokens", getattr(self, "max_new_tokens_spin", None), "value"),
        ("chat/temperature", getattr(self, "temperature_spin", None), "value"),
        ("chat/top_p", getattr(self, "top_p_spin", None), "value"),
        ("chat/top_k", getattr(self, "top_k_spin", None), "value"),
        ("chat/repetition_penalty", getattr(self, "repetition_penalty_spin", None), "value"),
    ]
    for key, widget, getter_name in pairs:
        if widget is None:
            continue
        try:
            settings.setValue(key, getattr(widget, getter_name)())
        except Exception:
            pass

    widget = getattr(self, "do_sample_check", None)
    if widget is not None:
        try:
            settings.setValue("chat/do_sample", bool(widget.isChecked()))
        except Exception:
            pass

    try:
        settings.sync()
    except Exception:
        pass


def _studio_restore_chat_window_settings(self, keep_model_dir: bool = False) -> None:
    settings = _studio_settings_store()

    def _read_bool(key: str, default: bool) -> bool:
        value = settings.value(key, default)
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() in {"1", "true", "yes", "on"}

    pairs = [
        (not keep_model_dir, getattr(self, "model_dir_edit", None), settings.value("chat/model_dir", self.model_dir_edit.text() if getattr(self, "model_dir_edit", None) is not None else ""), "setText", str),
        (True, getattr(self, "system_prompt_edit", None), settings.value("chat/system_prompt", None), "setPlainText", str),
        (True, getattr(self, "input_edit", None), settings.value("chat/input_draft", None), "setPlainText", str),
        (True, getattr(self, "history_turns_spin", None), settings.value("chat/history_turns", 12), "setValue", int),
        (True, getattr(self, "max_new_tokens_spin", None), settings.value("chat/max_new_tokens", 8192), "setValue", int),
        (True, getattr(self, "temperature_spin", None), settings.value("chat/temperature", 0.2), "setValue", float),
        (True, getattr(self, "top_p_spin", None), settings.value("chat/top_p", 0.95), "setValue", float),
        (True, getattr(self, "top_k_spin", None), settings.value("chat/top_k", 50), "setValue", int),
        (True, getattr(self, "repetition_penalty_spin", None), settings.value("chat/repetition_penalty", 1.05), "setValue", float),
    ]
    for enabled, widget, value, setter_name, caster in pairs:
        if not enabled or widget is None or value is None:
            continue
        try:
            old = widget.blockSignals(True)
            getattr(widget, setter_name)(caster(value))
            widget.blockSignals(old)
        except Exception:
            pass

    if getattr(self, "do_sample_check", None) is not None:
        try:
            old = self.do_sample_check.blockSignals(True)
            self.do_sample_check.setChecked(_read_bool("chat/do_sample", True))
            self.do_sample_check.blockSignals(old)
        except Exception:
            pass

    geometry = settings.value("chat/geometry", None)
    if geometry is not None:
        try:
            self.restoreGeometry(geometry)
        except Exception:
            pass

    try:
        self._update_window_title()
    except Exception:
        pass


def _studio_connect_chat_window_settings_signals(self) -> None:
    if getattr(self, "_chat_settings_signals_connected", False):
        return
    self._chat_settings_signals_connected = True
    signal_specs = [
        (getattr(self, "model_dir_edit", None), "textChanged"),
        (getattr(self, "system_prompt_edit", None), "textChanged"),
        (getattr(self, "input_edit", None), "textChanged"),
        (getattr(self, "history_turns_spin", None), "valueChanged"),
        (getattr(self, "max_new_tokens_spin", None), "valueChanged"),
        (getattr(self, "temperature_spin", None), "valueChanged"),
        (getattr(self, "top_p_spin", None), "valueChanged"),
        (getattr(self, "top_k_spin", None), "valueChanged"),
        (getattr(self, "repetition_penalty_spin", None), "valueChanged"),
        (getattr(self, "do_sample_check", None), "toggled"),
    ]
    for widget, signal_name in signal_specs:
        if widget is None:
            continue
        try:
            getattr(widget, signal_name).connect(self.save_chat_settings)
        except Exception:
            pass


def _studio_chat_init_persist(self, host: "PipelineStudioGUI", initial_model_dir: str = "") -> None:
    _studio_old_chat_init_persist(self, host, initial_model_dir)
    # Κεντράρισμα chat παραθύρου
    try:
        from PySide6.QtWidgets import QApplication as _QApp
        screen = _QApp.primaryScreen()
        if screen is not None:
            avail = screen.availableGeometry()
            fg = self.frameGeometry()
            x = avail.x() + (avail.width() - fg.width()) // 2
            y = avail.y() + (avail.height() - fg.height()) // 2
            self.move(max(avail.x(), x), max(avail.y(), y))
    except Exception:
        pass
    self._settings_restore_in_progress = True
    try:
        self.restore_chat_settings(keep_model_dir=bool(initial_model_dir))
    finally:
        self._settings_restore_in_progress = False
    try:
        self.connect_chat_settings_signals()
    except Exception as exc:
        write_exception_report("Chat settings signal binding failed", exc)
    try:
        self._refresh_chat_view()
    except Exception:
        pass


def _studio_chat_close_event_persist(self, event) -> None:  # type: ignore[override]
    if self._chat_thread is not None:
        QMessageBox.information(self, APP_TITLE, "Περίμενε να ολοκληρωθεί η τρέχουσα απάντηση πριν κλείσεις το chat.")
        event.ignore()
        return
    try:
        self.save_chat_settings()
    except Exception:
        pass
    super().closeEvent(event)


