# ===== FINAL AUTO / THREAD-SAFE STARTUP PATCH =====

class _StudioGuiThreadBridge(QObject):
    log_message    = Signal(str)
    background_finished = Signal(object)
    background_error    = Signal(str)
    command_line   = Signal(str)    # single line (kept for compat)
    command_batch  = Signal(str)    # newline-separated batch from worker
    command_started  = Signal()
    command_finished = Signal(int)


def _studio_final_runner_script_path(self) -> Path:
    # Always run via the current script — run_pipeline.py no longer needed.
    return Path(__file__).resolve()


def _studio_final_internal_python_command(self, *args: str) -> list[str]:
    runner = self._runner_script_path()
    return [self._python_exec(), "-u", str(runner), *[str(arg) for arg in args]]


def _studio_final_init_with_bridge(self, *args: Any, **kwargs: Any) -> None:
    _studio_prev_init_for_final_patch(self, *args, **kwargs)
    self._deferred_background_callback = None
    self._thread_bridge = _StudioGuiThreadBridge(self)
    self._thread_bridge.log_message.connect(self.log, Qt.QueuedConnection)
    self._thread_bridge.background_finished.connect(self._background_finished, Qt.QueuedConnection)
    self._thread_bridge.background_error.connect(self._background_error, Qt.QueuedConnection)
    self._thread_bridge.command_line.connect(self.log, Qt.QueuedConnection)
    self._thread_bridge.command_batch.connect(self._log_batch, Qt.QueuedConnection)
    self._thread_bridge.command_started.connect(self._on_command_started, Qt.QueuedConnection)
    self._thread_bridge.command_finished.connect(self._on_command_finished, Qt.QueuedConnection)


def _studio_final_invoke_deferred_background_callback(self) -> None:
    payload = getattr(self, "_deferred_background_callback", None)
    self._deferred_background_callback = None
    if not payload:
        return
    kind, callback, value = payload
    if not callback:
        return
    try:
        callback(value)
    except Exception as exc:
        write_exception_report(f"Deferred background {kind} callback failed", exc)
        try:
            self.log(f"❌ Αποτυχία στο callback εργασίας: {exc}")
        except Exception:
            pass


def _studio_final_run_background(
    self,
    fn: Callable[..., Any],
    *args: Any,
    on_success: Callable[[object], None] | None = None,
    on_error: Callable[[str], None] | None = None,
) -> None:
    if getattr(self, "_job_thread", None) is not None:
        QMessageBox.warning(self, APP_TITLE, "Υπάρχει ήδη ενεργή εργασία. Περίμενε να ολοκληρωθεί πρώτα.")
        return
    self._background_success_callback = on_success
    self._background_error_callback = on_error
    self._deferred_background_callback = None
    title = ""
    try:
        title = self._get_status_message()
    except Exception:
        title = ""
    try:
        self._progress_begin(title or "Εργασία υποβάθρου", mode="background")
    except Exception:
        pass
    self._job_thread = QThread(self)
    worker = BackgroundWorker(fn, *args)
    self._job_worker = worker
    worker.moveToThread(self._job_thread)
    self._job_thread.started.connect(worker.run)
    worker.progress.connect(self._thread_bridge.log_message, Qt.QueuedConnection)
    worker.error.connect(self._thread_bridge.background_error, Qt.QueuedConnection)
    worker.finished.connect(self._thread_bridge.background_finished, Qt.QueuedConnection)
    worker.finished.connect(self._job_thread.quit, Qt.QueuedConnection)
    worker.error.connect(self._job_thread.quit, Qt.QueuedConnection)
    self._job_thread.finished.connect(self._clear_background_job, Qt.QueuedConnection)
    self._job_thread.start()


def _studio_final_background_error(self, message: str) -> None:
    if "getaddrinfo failed" in str(message).lower():
        message = (
            "Αποτυχία δικτυακής σύνδεσης προς Hugging Face. "
            "Ελέγξτε Internet / DNS / proxy / firewall και δοκιμάστε ξανά. "
            f"Λεπτομέρειες: {message}"
        )
    self.log(f"❌ {message}")
    write_exception_report("Background worker error", message)
    try:
        self.progress.setRange(0, 100)
        self.progress.setValue(0)
    except Exception:
        pass
    try:
        self._set_status_message("Σφάλμα")
    except Exception:
        pass
    callback = self._background_error_callback
    self._background_error_callback = None
    self._background_success_callback = None
    self._deferred_background_callback = ("error", callback, message)
    try:
        self._progress_finish(False, "Σφάλμα")
    except Exception:
        pass


def _studio_final_background_finished(self, result: object) -> None:
    try:
        self.progress.setRange(0, 100)
        self.progress.setValue(100)
        self._set_status_message("Ολοκληρώθηκε")
    except Exception:
        pass

    if isinstance(result, list):
        self._online_entries = result
        self._rebuild_model_tree()
    elif isinstance(result, dict) and str(result.get("local_dir") or ""):
        local_dir = str(result.get("local_dir") or "")
        resolved_repo_id = str(result.get("repo_id") or "").strip()
        requested_repo_id = str(result.get("requested_repo_id") or "").strip()
        if resolved_repo_id:
            self.custom_model_edit.setText(resolved_repo_id)
        if requested_repo_id and resolved_repo_id and requested_repo_id != resolved_repo_id:
            self.log(f"ℹ Το ζητούμενο model id '{requested_repo_id}' αντιστοιχίστηκε στο '{resolved_repo_id}'.")
        self.log(f"✓ Η λήψη ολοκληρώθηκε: {local_dir}")
        self._refresh_local_models()
        self._update_selected_model_state()
        self.infer_model_edit.setText(local_dir)
    elif isinstance(result, str) and Path(result).exists():
        self.log(f"✓ Η λήψη ολοκληρώθηκε: {result}")
        self._refresh_local_models()
        self._update_selected_model_state()
        self.infer_model_edit.setText(result)
    else:
        self.log("✓ Η εργασία υποβάθρου ολοκληρώθηκε.")

    callback = self._background_success_callback
    self._background_success_callback = None
    self._background_error_callback = None
    self._deferred_background_callback = ("success", callback, result)
    try:
        self._progress_finish(True, "Ολοκληρώθηκε")
    except Exception:
        pass


def _studio_final_clear_background_job(self) -> None:
    self._job_thread = None
    self._job_worker = None
    self._current_process = None
    self._invoke_deferred_background_callback()


def _studio_final_on_command_started(self) -> None:
    self.log("ℹ Η διεργασία ξεκίνησε.")


def _studio_final_start_command(self, command: list[str], title: str) -> None:
    if self._current_process is not None or (self._job_thread is not None and isinstance(self._job_worker, CommandStreamWorker)):
        QMessageBox.warning(self, APP_TITLE, "Υπάρχει ήδη ενεργή διεργασία. Σταμάτησέ την πρώτα.")
        return
    self.log(f"🚀 Εκκίνηση: {title}")
    self.log("$ " + " ".join(self._quote_part(part) for part in command))
    self._set_status_message(title)
    self.progress.setRange(0, 100)

    thread = QThread(self)
    worker = CommandStreamWorker(command, cwd=PROJECT_ROOT)
    worker.extra_env = {
        "PYTHONIOENCODING": "utf-8",
        "PYTHONUTF8": "1",
    }
    self._job_thread = thread
    self._job_worker = worker
    self._current_process = worker
    worker.moveToThread(thread)
    thread.started.connect(worker.run)
    worker.batch_lines.connect(self._thread_bridge.command_batch, Qt.QueuedConnection)
    worker.started.connect(self._thread_bridge.command_started, Qt.QueuedConnection)
    worker.finished.connect(self._thread_bridge.command_finished, Qt.QueuedConnection)
    worker.finished.connect(thread.quit, Qt.QueuedConnection)
    thread.finished.connect(self._clear_command_job, Qt.QueuedConnection)
    thread.start()
    try:
        self._progress_begin(title, mode="command")
    except Exception:
        pass


def _studio_final_auto_prepare_and_run_pipeline(self) -> None:
    if self._current_process or self._job_thread:
        QMessageBox.warning(self, APP_TITLE, "Υπάρχει ήδη ενεργή εργασία. Περίμενε να ολοκληρωθεί πρώτα.")
        return

    def after_download(_result: object | None = None) -> None:
        try:
            self.generate_runtime_config()
        except Exception as exc:
            write_exception_report("Auto generate runtime config failed", exc)
            QMessageBox.critical(self, APP_TITLE, f"Αποτυχία δημιουργίας runtime config:\n{exc}")
            return
        self.log("✓ Το Auto ολοκλήρωσε την προετοιμασία και ξεκινά το pipeline.")
        self.run_full_pipeline()

    def after_search(_result: object | None = None) -> None:
        current = self._current_selected_model()
        if not current:
            QMessageBox.warning(self, APP_TITLE, "Δεν έχει επιλεγεί μοντέλο για το Auto.")
            return
        if self.auto_prepare_check.isChecked() and not current.get("local_dir"):
            self.log(f"⬇ Auto: θα γίνει λήψη του {current['repo_id']}")
            self.download_selected_model_then(after_download)
            return
        after_download()

    def on_error(message: str) -> None:
        self.log(f"❌ Το Auto σταμάτησε: {message}")

    if self.auto_search_check.isChecked():
        terms = [term.strip() for term in self.search_terms_edit.text().split(",") if term.strip()]
        include_gated = bool(getattr(self, "include_gated_check", None).isChecked()) if getattr(self, "include_gated_check", None) is not None else False
        self.log("🤖 Auto: έναρξη online αναζήτησης μοντέλων...")
        self._set_status_message("Auto: αναζήτηση μοντέλων")
        self.progress.setRange(0, 100)
        self._run_background(self._discover_models_worker, terms, include_gated, on_success=after_search, on_error=on_error)
    else:
        after_search()


