# ===== DEFINITIVE RESPONSIVENESS PATCH =====
# This block runs LAST and wins over every previous assignment.
# It replaces the entire log + command-streaming pipeline with a
# single clean implementation that never blocks the main thread.

import time as _resp_time

class _BatchStreamWorker(QObject):
    """Subprocess reader that emits output in 100ms batches.

    Emitting one Qt signal per stdout line when training outputs hundreds of
    lines/second floods the Qt event queue and freezes the UI.  This worker
    accumulates lines in a plain Python list and emits ONE signal every 100 ms
    (or when the batch hits 150 lines), so the main thread event loop is free
    between flushes.
    """
    batch  = Signal(str)    # newline-joined batch of stdout lines
    done   = Signal(int)    # subprocess return code
    started = Signal()

    FLUSH_INTERVAL = 0.10   # seconds
    MAX_BATCH      = 150    # lines before forced flush

    def __init__(self, command, cwd=None, extra_env=None):
        super().__init__()
        self._command   = command
        self._cwd       = str(cwd or PROJECT_ROOT)
        self._extra_env = extra_env or {}
        self._stop      = False
        self.process    = None

    def run(self):
        self.started.emit()

        env = os.environ.copy()
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"]       = "1"
        for k, v in self._extra_env.items():
            if v is not None:
                env[str(k)] = str(v)

        flags = 0
        if os.name == "nt":
            flags = subprocess.CREATE_NO_WINDOW  # type: ignore[attr-defined]

        self.process = subprocess.Popen(
            self._command,
            cwd=self._cwd,
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, bufsize=1,
            encoding="utf-8", errors="replace",
            creationflags=flags, env=env,
        )

        pending   = []
        last_emit = _resp_time.monotonic()

        for raw in self.process.stdout:
            pending.append(raw.rstrip())
            now = _resp_time.monotonic()
            if (now - last_emit) >= self.FLUSH_INTERVAL or len(pending) >= self.MAX_BATCH:
                self.batch.emit("\n".join(pending))
                pending.clear()
                last_emit = now
            if self._stop:
                break

        if pending:
            self.batch.emit("\n".join(pending))

        if self._stop and self.process.poll() is None:
            try:
                _studio_terminate_process_tree(self.process)
            except Exception:
                try:
                    self.process.terminate()
                except Exception:
                    pass

        code = self.process.wait()
        self.done.emit(code)

    def stop(self):
        self._stop = True
        if self.process and self.process.poll() is None:
            try:
                _studio_terminate_process_tree(self.process)
            except Exception:
                try:
                    self.process.terminate()
                except Exception:
                    pass


def _resp_log_batch(self, text: str) -> None:
    """Receive a batch from _BatchStreamWorker.  Returns in microseconds.

    Rules:
    - NO per-line iteration on the hot path
    - ONE bulk list extend
    - ONE file write for the whole batch
    - Progress-bar update from last line only
    - QTimer armed once; no-op if already ticking
    """
    if not text:
        return
    raw_lines = text.split("\n")
    if not raw_lines:
        return

    ts      = _resp_time.strftime("%H:%M:%S")
    stamped = [f"[{ts}] {ln}" for ln in raw_lines if ln]
    if not stamped:
        return

    # persistent buffer
    buf = self.__dict__.setdefault("_log_buffer", [])
    buf.extend(stamped)
    if len(buf) > 5000:
        del buf[:-4000]

    # pending UI batch
    self.__dict__.setdefault("_log_pending_batch", []).extend(stamped)

    # single file write
    try:
        targets = []
        session_path = getattr(self, "_session_log_path", None)
        if session_path:
            targets.append(Path(session_path))
        live_path = getattr(self, "_live_terminal_log_path", None)
        if live_path:
            live_target = Path(live_path)
            if all(str(Path(existing)) != str(live_target) for existing in targets):
                targets.append(live_target)
        for p in targets:
            p.parent.mkdir(parents=True, exist_ok=True)
            with p.open("a", encoding="utf-8") as fh:
                fh.write("\n".join(stamped) + "\n")
    except Exception:
        pass

    # progress (cheap — last line only)
    try:
        self._progress_update_from_message(raw_lines[-1])
    except Exception:
        pass

    # arm flush timer
    t = self.__dict__.get("_log_flush_timer")
    if t is None:
        t = QTimer(self)
        t.setInterval(80)
        t.timeout.connect(self._resp_flush)
        self.__dict__["_log_flush_timer"] = t
    if not t.isActive():
        t.start()


def _resp_flush(self) -> None:
    """Flush pending lines to QPlainTextEdit in ONE appendPlainText call.
    Trims the widget to 3000 lines so it never gets sluggish.
    """
    MAX_LINES = 3000

    batch = self.__dict__.get("_log_pending_batch")
    if not batch:
        t = self.__dict__.get("_log_flush_timer")
        if t and t.isActive():
            t.stop()
        return

    self.__dict__["_log_pending_batch"] = []
    t = self.__dict__.get("_log_flush_timer")
    if t:
        t.stop()

    block = "\n".join(batch)

    views = []
    if getattr(self, "logs", None) is not None:
        views.append(self.logs)
    for v in list(getattr(self, "_log_views", []) or []):
        if v not in views:
            views.append(v)

    alive = []
    for view in views:
        try:
            view.appendPlainText(block)
            doc = view.document()
            if doc.blockCount() > MAX_LINES:
                cur = view.textCursor()
                cur.movePosition(QTextCursor.Start)
                cur.movePosition(QTextCursor.Down, QTextCursor.KeepAnchor,
                                 doc.blockCount() - MAX_LINES)
                cur.removeSelectedText()
            cur2 = view.textCursor()
            cur2.movePosition(QTextCursor.End)
            view.setTextCursor(cur2)
            view.ensureCursorVisible()
            alive.append(view)
        except Exception:
            pass

    self._log_views = alive
    if alive:
        self.logs = alive[0]


def _resp_log(self, message: str) -> None:
    """Single-line log — routes through the same batch path."""
    if message:
        _resp_log_batch(self, message)


def _resp_start_command(self, command: list[str], title: str) -> None:
    """Start a subprocess in a QThread using _BatchStreamWorker."""
    if self._current_process is not None or (
        self._job_thread is not None
        and isinstance(self._job_worker, (_BatchStreamWorker, CommandStreamWorker))
    ):
        from PySide6.QtWidgets import QMessageBox as _QMB
        _QMB.warning(self, APP_TITLE, "Υπάρχει ήδη ενεργή διεργασία. Σταμάτησέ την πρώτα.")
        return

    self.__dict__.pop("_live_terminal_log_path", None)
    self.__dict__.pop("_live_terminal_title", None)

    live_terminal_path: Path | None = None
    live_terminal_opened = False
    if _studio_is_live_terminal_command(command):
        live_terminal_path = _studio_live_terminal_log_path(title)
        self._live_terminal_log_path = live_terminal_path
        self._live_terminal_title = f"LLM Studio - {title}"
        try:
            live_terminal_path.parent.mkdir(parents=True, exist_ok=True)
            live_terminal_path.touch(exist_ok=True)
        except Exception:
            pass
        live_terminal_opened = _studio_open_live_terminal_window(live_terminal_path, self._live_terminal_title)

    self.log(f"🚀 Εκκίνηση: {title}")
    self.log("$ " + " ".join(self._quote_part(p) for p in command))
    if live_terminal_path is not None:
        if live_terminal_opened:
            self.log(f"🖥 Live terminal: {live_terminal_path}")
        else:
            self.log(f"📝 Live log αρχείο: {live_terminal_path}")
    self._set_status_message(title)
    self.progress.setRange(0, 100)
    self.progress.setValue(3)

    thread = QThread(self)
    worker = _BatchStreamWorker(command, cwd=PROJECT_ROOT)

    self._job_thread = thread
    self._job_worker = worker
    self._current_process = worker

    worker.moveToThread(thread)
    thread.started.connect(worker.run)

    worker.batch.connect(self._log_batch, Qt.QueuedConnection)

    worker.started.connect(self._thread_bridge.command_started, Qt.QueuedConnection)
    worker.done.connect(self._thread_bridge.command_finished, Qt.QueuedConnection)
    worker.done.connect(self._on_command_finished, Qt.QueuedConnection)
    worker.done.connect(thread.quit, Qt.QueuedConnection)
    thread.finished.connect(self._clear_command_job, Qt.QueuedConnection)

    thread.start()
    try:
        self._progress_begin(title, mode="command")
    except Exception:
        pass


# ── Wire everything onto the classes ────────────────────────────────────────
PipelineStudioGUI.log          = _resp_log
PipelineStudioGUI._log_batch   = _resp_log_batch
PipelineStudioGUI._resp_flush  = _resp_flush
PipelineStudioGUI._flush_log_batch = _resp_flush   # keep old name working too
PipelineStudioGUI._start_command   = _resp_start_command

# ===== END DEFINITIVE RESPONSIVENESS PATCH =====


# ===== FINAL REALTIME CHAT / INFERENCE / SCROLL PATCH =====

_STUDIO_STREAM_STATUS_PREFIX = "__STUDIO_STATUS__:"
_STUDIO_STREAM_CHUNK_PREFIX = "__STUDIO_CHUNK__:"


def _studio_stream_status(progress_callback: Callable[[str], None] | None, message: str) -> None:
    if progress_callback:
        progress_callback(f"{_STUDIO_STREAM_STATUS_PREFIX}{message}")


def _studio_stream_chunk(progress_callback: Callable[[str], None] | None, chunk: str) -> None:
    if progress_callback and chunk:
        progress_callback(f"{_STUDIO_STREAM_CHUNK_PREFIX}{chunk}")


def _studio_streaming_generate_text(
    tokenizer: Any,
    model: Any,
    inputs: dict[str, Any],
    generation_kwargs: dict[str, Any],
    progress_callback: Callable[[str], None] | None = None,
) -> str:
    import torch
    from transformers import TextIteratorStreamer

    streamer = TextIteratorStreamer(tokenizer, skip_prompt=True, skip_special_tokens=True)
    call_kwargs = dict(inputs)
    call_kwargs.update(generation_kwargs)
    call_kwargs["streamer"] = streamer

    generation_error: list[BaseException] = []

    def _generate() -> None:
        try:
            with torch.inference_mode():
                model.generate(**call_kwargs)
        except BaseException as exc:  # pragma: no cover
            generation_error.append(exc)

    thread = threading.Thread(target=_generate, daemon=True)
    thread.start()

    chunks: list[str] = []
    for piece in streamer:
        if piece:
            chunks.append(piece)
            _studio_stream_chunk(progress_callback, piece)

    thread.join()
    if generation_error:
        raise generation_error[0]
    return "".join(chunks).strip()


def _studio_chat_generate_worker_streaming(
    model_dir: str,
    messages: list[dict[str, str]],
    generation_options: dict[str, Any],
    progress_callback: Callable[[str], None] | None = None,
) -> dict[str, Any]:

    _studio_stream_status(progress_callback, 'Φόρτωση runtime και έναρξη παραγωγής...')
    tokenizer, model, info = get_cached_or_load_inference_runtime(Path(model_dir))
    prompt_text = build_chat_prompt(tokenizer, messages)
    inputs = _studio_prepare_inputs_for_generation(tokenizer, model, prompt_text)
    generation_kwargs = _studio_resolve_generation_kwargs(
        generation_options,
        default_max_new_tokens=1024,
        default_temperature=0.2,
        default_top_p=0.95,
        default_top_k=50,
        default_repetition_penalty=1.05,
        default_do_sample=True,
    )
    pad_token_id = _studio_align_padding_for_generation(tokenizer, model)
    if pad_token_id is not None:
        generation_kwargs['pad_token_id'] = pad_token_id

    _studio_stream_status(progress_callback, 'Το μοντέλο απαντά σε realtime...')
    text = _studio_streaming_generate_text(tokenizer, model, inputs, generation_kwargs, progress_callback=progress_callback)
    if not text:
        _studio_stream_status(progress_callback, 'Το μοντέλο δεν επέστρεψε ορατό κείμενο.')
        text = '(Το μοντέλο δεν επέστρεψε κείμενο.)'
    else:
        _studio_stream_status(progress_callback, 'Η απάντηση ολοκληρώθηκε.')

    return {
        'text': text,
        'resolved_model_dir': info.get('base_model_dir') or '',
        'note': info.get('note') or '',
        'from_cache': bool(info.get('from_cache')),
        'adapter_dir': info.get('adapter_dir') or '',
    }


def _studio_inference_stream_worker(
    model_dir: str,
    prompt: str,
    generation_options: dict[str, Any] | None = None,
    progress_callback: Callable[[str], None] | None = None,
) -> dict[str, Any]:

    options = generation_options or {}
    _studio_stream_status(progress_callback, 'Φόρτωση runtime για δοκιμή μοντέλου...')
    tokenizer, model, info = get_cached_or_load_inference_runtime(Path(model_dir))
    prompt_text = build_chat_prompt(tokenizer, _studio_prompt_to_messages(prompt))
    inputs = _studio_prepare_inputs_for_generation(tokenizer, model, prompt_text)
    generation_kwargs = _studio_resolve_generation_kwargs(
        options,
        default_max_new_tokens=1024,
        default_temperature=0.2,
        default_top_p=0.95,
        default_top_k=50,
        default_repetition_penalty=1.05,
        default_do_sample=True,
    )
    pad_token_id = _studio_align_padding_for_generation(tokenizer, model)
    if pad_token_id is not None:
        generation_kwargs['pad_token_id'] = pad_token_id

    _studio_stream_status(progress_callback, 'Η δοκιμή παράγει απάντηση σε realtime...')
    text = _studio_streaming_generate_text(tokenizer, model, inputs, generation_kwargs, progress_callback=progress_callback)
    if not text:
        text = '(Το μοντέλο δεν επέστρεψε κείμενο.)'
    _studio_stream_status(progress_callback, 'Η δοκιμή ολοκληρώθηκε.')
    return {
        'text': text,
        'resolved_model_dir': info.get('base_model_dir') or str(model_dir),
        'note': info.get('note') or '',
        'from_cache': bool(info.get('from_cache')),
        'adapter_dir': info.get('adapter_dir') or '',
    }

def _studio_chat_flush_stream_chunks(self) -> None:
    pending = getattr(self, "_stream_pending_chunks", None) or []
    if not pending:
        return
    chunk = "".join(pending)
    self._stream_pending_chunks = []
    if self._messages and self._messages[-1].get("role") == "assistant":
        current = str(self._messages[-1].get("content") or "")
        self._messages[-1]["content"] = current + chunk
        self._messages[-1]["streaming"] = True
        self._refresh_chat_view()


def _studio_chat_ensure_stream_timer(self) -> None:
    timer = getattr(self, "_stream_flush_timer", None)
    if timer is None:
        timer = QTimer(self)
        timer.setInterval(200)   # 200ms — fewer redraws per second → less flicker
        timer.timeout.connect(lambda: self._flush_stream_chunks())
        self._stream_flush_timer = timer


def _studio_chat_start_generation_realtime(self) -> None:
    model_dir = self.model_dir_edit.text().strip()
    messages = self._build_generation_messages()
    options = self._current_generation_options()
    self._stream_pending_chunks = []
    self._set_busy(True, "Φόρτωση runtime και παραγωγή απάντησης...")
    self._messages.append({"role": "assistant", "content": "", "streaming": True})
    self._refresh_chat_view()
    self._chat_thread = QThread(self)
    worker = BackgroundWorker(_studio_chat_generate_worker_streaming, model_dir, copy.deepcopy(messages), copy.deepcopy(options))
    self._chat_worker = worker
    worker.moveToThread(self._chat_thread)
    self._chat_thread.started.connect(worker.run)
    worker.progress.connect(self._on_generation_progress, Qt.QueuedConnection)
    worker.finished.connect(self._on_generation_finished, Qt.QueuedConnection)
    worker.error.connect(self._on_generation_error, Qt.QueuedConnection)
    worker.finished.connect(self._chat_thread.quit, Qt.QueuedConnection)
    worker.error.connect(self._chat_thread.quit, Qt.QueuedConnection)
    self._chat_thread.finished.connect(self._clear_generation_thread, Qt.QueuedConnection)
    self._chat_thread.start()


def _studio_chat_on_generation_progress_realtime(self, message: str) -> None:
    if not isinstance(message, str):
        self._set_status(str(message))
        return
    if message.startswith(_STUDIO_STREAM_CHUNK_PREFIX):
        chunk = message[len(_STUDIO_STREAM_CHUNK_PREFIX):]
        if chunk:
            if not hasattr(self, "_stream_pending_chunks") or self._stream_pending_chunks is None:
                self._stream_pending_chunks = []
            self._stream_pending_chunks.append(chunk)
            self._chat_ensure_stream_timer()
            if not self._stream_flush_timer.isActive():
                self._stream_flush_timer.start()
        return
    if message.startswith(_STUDIO_STREAM_STATUS_PREFIX):
        self._set_status(message[len(_STUDIO_STREAM_STATUS_PREFIX):])
        return
    self._set_status(message)


def _studio_chat_on_generation_finished_realtime(self, result: object) -> None:
    try:
        self._flush_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, "_stream_flush_timer", None)
    if timer is not None and timer.isActive():
        timer.stop()

    payload = result if isinstance(result, dict) else {"text": str(result)}
    text = str(payload.get("text") or "").strip() or "(Το μοντέλο δεν επέστρεψε κείμενο.)"
    if self._messages and self._messages[-1].get("role") == "assistant":
        self._messages[-1]["content"] = text
        self._messages[-1].pop("streaming", None)
    else:
        self._messages.append({"role": "assistant", "content": text})
    self._last_result = payload
    resolved_model_dir = str(payload.get("resolved_model_dir") or self.model_dir_edit.text().strip())
    adapter_dir = str(payload.get("adapter_dir") or "")
    note = str(payload.get("note") or "")
    cache_note = "από cache runtime" if bool(payload.get("from_cache")) else "με νέα φόρτωση runtime"
    info_parts = [f"Απάντηση από: {resolved_model_dir}", cache_note]
    if adapter_dir:
        info_parts.append(f"adapter: {adapter_dir}")
    if note:
        info_parts.append(note)
    info_text = " | ".join(info_parts)
    self._refresh_chat_view()
    self._set_busy(False, info_text)
    try:
        self.host.log(f"💬 Ολοκληρώθηκε απάντηση chat για μοντέλο: {resolved_model_dir}")
    except Exception:
        pass


def _studio_chat_on_generation_error_realtime(self, message: str) -> None:
    try:
        self._flush_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, "_stream_flush_timer", None)
    if timer is not None and timer.isActive():
        timer.stop()
    if self._messages and self._messages[-1].get("role") == "assistant" and not str(self._messages[-1].get("content") or "").strip():
        self._messages.pop()
    self._refresh_chat_view()
    self._set_busy(False, f"Σφάλμα chat: {message}")
    QMessageBox.critical(self, APP_TITLE, message)
    try:
        self.host.log(f"❌ Σφάλμα chat μοντέλου: {message}")
    except Exception:
        pass


def _studio_build_inference_tab_realtime(self) -> QWidget:
    page = _studio_build_inference_tab_v2(self)
    root = page.layout()
    if root is None:
        return page

    if root.count() >= 1:
        item = root.takeAt(0)
        top = item.widget() if item is not None else None
        if top is not None:
            scroll = QScrollArea()
            scroll.setWidgetResizable(True)
            scroll.setFrameShape(QFrame.NoFrame)
            scroll_host = QWidget()
            scroll_lay = QVBoxLayout(scroll_host)
            scroll_lay.setContentsMargins(0, 0, 0, 0)
            scroll_lay.setSpacing(0)
            scroll_lay.addWidget(top)
            scroll_lay.addStretch(1)
            scroll.setWidget(scroll_host)
            root.insertWidget(0, scroll, 2)

    self.infer_prompt.setMinimumHeight(260)

    output_card = self._card_group("Realtime έξοδος δοκιμής μοντέλου")
    output_lay = QVBoxLayout(output_card)
    info = QLabel("Η απάντηση του μοντέλου θα εμφανίζεται εδώ σε realtime.")
    info.setWordWrap(True)
    info.setStyleSheet("color:#5b7698;")
    output_lay.addWidget(info)
    self.infer_output = QTextEdit()
    self.infer_output.setReadOnly(True)
    self.infer_output.setPlaceholderText("Εκτέλεσε δοκιμή μοντέλου για να δεις την απάντηση εδώ...")
    self.infer_output.setMinimumHeight(320)
    self.infer_output.setObjectName("InferenceOutputBox")
    self.infer_output.setStyleSheet(
        "QTextEdit{background:#ffffff; color:#18324f; border:1px solid #cad7e6; border-radius:14px; padding:12px; font-family:'Cascadia Code','Consolas','Courier New',monospace; font-size:13px;}"
    )
    output_lay.addWidget(self.infer_output)
    root.insertWidget(1, output_card, 1)
    return page


def _studio_inference_current_options(self) -> dict[str, Any]:
    return {
        "max_new_tokens": 4096,
        "temperature": 0.2,
        "top_p": 0.95,
        "top_k": 50,
        "repetition_penalty": 1.05,
        "do_sample": True,
    }


def _studio_flush_inference_stream_chunks(self) -> None:
    pending = getattr(self, "_infer_stream_pending_chunks", None) or []
    if not pending:
        return
    text = "".join(pending)
    self._infer_stream_pending_chunks = []
    view = getattr(self, "infer_output", None)
    if view is not None:
        cursor = view.textCursor()
        cursor.movePosition(QTextCursor.End)
        cursor.insertText(text)
        view.setTextCursor(cursor)
        view.ensureCursorVisible()


def _studio_ensure_inference_stream_timer(self) -> None:
    timer = getattr(self, "_infer_stream_timer", None)
    if timer is None:
        timer = QTimer(self)
        timer.setInterval(60)
        timer.timeout.connect(lambda: self._flush_inference_stream_chunks())
        self._infer_stream_timer = timer


def _studio_run_inference_realtime(self, title: str = "Inference") -> None:
    model_dir = self.infer_model_edit.text().strip()
    prompt = self.infer_prompt.toPlainText().strip()
    if not model_dir:
        QMessageBox.warning(self, APP_TITLE, "Επίλεξε φάκελο μοντέλου για inference.")
        return
    if not prompt:
        QMessageBox.warning(self, APP_TITLE, "Γράψε prompt για δοκιμή μοντέλου.")
        return
    if getattr(self, "_infer_thread", None) is not None:
        QMessageBox.information(self, APP_TITLE, "Υπάρχει ήδη ενεργή δοκιμή μοντέλου.")
        return
    if getattr(self, "_current_process", None) is not None or getattr(self, "_job_thread", None) is not None:
        QMessageBox.information(self, APP_TITLE, "Υπάρχει ήδη ενεργή εργασία. Περίμενε να ολοκληρωθεί πρώτα.")
        return

    if hasattr(self, "infer_output"):
        self.infer_output.clear()
        self.infer_output.setPlainText("⏳ Φόρτωση runtime και έναρξη realtime απάντησης...\n\n")
    self._infer_stream_pending_chunks = []
    self._set_status_message(title)
    try:
        self._progress_begin(title, mode="background")
    except Exception:
        pass
    self.log(f"🚀 Εκκίνηση realtime δοκιμής μοντέλου: {model_dir}")

    self._infer_thread = QThread(self)
    worker = BackgroundWorker(_studio_inference_stream_worker, model_dir, prompt, _studio_inference_current_options(self))
    self._infer_worker = worker
    worker.moveToThread(self._infer_thread)
    self._infer_thread.started.connect(worker.run)
    worker.progress.connect(self._on_inference_progress, Qt.QueuedConnection)
    worker.finished.connect(self._on_inference_finished, Qt.QueuedConnection)
    worker.error.connect(self._on_inference_error, Qt.QueuedConnection)
    worker.finished.connect(self._infer_thread.quit, Qt.QueuedConnection)
    worker.error.connect(self._infer_thread.quit, Qt.QueuedConnection)
    self._infer_thread.finished.connect(self._clear_inference_thread, Qt.QueuedConnection)
    self._infer_thread.start()


def _studio_on_inference_progress(self, message: str) -> None:
    if not isinstance(message, str):
        self._set_status_message(str(message))
        return
    if message.startswith(_STUDIO_STREAM_CHUNK_PREFIX):
        chunk = message[len(_STUDIO_STREAM_CHUNK_PREFIX):]
        if chunk:
            if not hasattr(self, "_infer_stream_pending_chunks") or self._infer_stream_pending_chunks is None:
                self._infer_stream_pending_chunks = []
            self._infer_stream_pending_chunks.append(chunk)
            self._ensure_inference_stream_timer()
            if not self._infer_stream_timer.isActive():
                self._infer_stream_timer.start()
        return
    if message.startswith(_STUDIO_STREAM_STATUS_PREFIX):
        clean = message[len(_STUDIO_STREAM_STATUS_PREFIX):]
        self._set_status_message(clean)
        view = getattr(self, "infer_output", None)
        if view is not None and "realtime" not in clean.lower():
            cursor = view.textCursor()
            cursor.movePosition(QTextCursor.End)
            cursor.insertText(f"\n[{clean}]\n")
            view.setTextCursor(cursor)
            view.ensureCursorVisible()
        return
    self._set_status_message(message)


def _studio_on_inference_finished(self, result: object) -> None:
    try:
        self._flush_inference_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, "_infer_stream_timer", None)
    if timer is not None and timer.isActive():
        timer.stop()
    payload = result if isinstance(result, dict) else {"text": str(result)}
    text = str(payload.get("text") or "").strip() or "(Το μοντέλο δεν επέστρεψε κείμενο.)"
    view = getattr(self, "infer_output", None)
    if view is not None:
        current = view.toPlainText().rstrip()
        if not current.endswith(text):
            cursor = view.textCursor()
            cursor.movePosition(QTextCursor.End)
            if current:
                cursor.insertText("\n")
            cursor.insertText(text)
            view.setTextCursor(cursor)
            view.ensureCursorVisible()
    resolved = str(payload.get("resolved_model_dir") or self.infer_model_edit.text().strip())
    self.log(f"✅ Ολοκληρώθηκε η realtime δοκιμή μοντέλου: {resolved}")
    try:
        self._progress_finish(True, "Ολοκληρώθηκε")
    except Exception:
        pass
    self._set_status_message("Ολοκληρώθηκε")


def _studio_on_inference_error(self, message: str) -> None:
    try:
        self._flush_inference_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, "_infer_stream_timer", None)
    if timer is not None and timer.isActive():
        timer.stop()
    view = getattr(self, "infer_output", None)
    if view is not None:
        cursor = view.textCursor()
        cursor.movePosition(QTextCursor.End)
        cursor.insertText(f"\n\n[Σφάλμα] {message}\n")
        view.setTextCursor(cursor)
        view.ensureCursorVisible()
    self.log(f"❌ Σφάλμα realtime δοκιμής μοντέλου: {message}")
    try:
        self._progress_finish(False, "Σφάλμα")
    except Exception:
        pass
    self._set_status_message("Σφάλμα")
    QMessageBox.critical(self, APP_TITLE, message)


def _studio_clear_inference_thread(self) -> None:
    self._infer_thread = None
    self._infer_worker = None


StudioModelChatWindow._flush_stream_chunks = _studio_chat_flush_stream_chunks
StudioModelChatWindow._chat_ensure_stream_timer = _studio_chat_ensure_stream_timer
StudioModelChatWindow._start_generation = _studio_chat_start_generation_realtime
