    self.infer_output.setPlaceholderText("Εκτέλεσε inference για να δεις εδώ την απάντηση σε realtime...")
    self.infer_output.setMinimumHeight(320)
    self.infer_output.setObjectName("InferenceOutputBox")
    self.infer_output.setStyleSheet(
        "QTextEdit{background:#ffffff; color:#18324f; border:1px solid #cad7e6;"
        "border-radius:14px; padding:12px;"
        "font-family:'Cascadia Code','Consolas','Courier New',monospace; font-size:13px;}"
    )
    output_lay.addWidget(self.infer_output)
    # Output action buttons
    out_btn_row = QHBoxLayout()
    out_btn_row.setSpacing(8)
    copy_out = QPushButton("📋  Αντιγραφή")
    copy_out.setToolTip("Αντιγράφει την απάντηση στο clipboard.")
    copy_out.clicked.connect(lambda: QApplication.clipboard().setText(self.infer_output.toPlainText()))
    clear_out = QPushButton("🗑  Καθαρισμός")
    clear_out.setToolTip("Καθαρίζει την απάντηση.")
    clear_out.clicked.connect(self.infer_output.clear)
    save_out = QPushButton("💾  Αποθήκευση")
    save_out.setToolTip("Αποθηκεύει την απάντηση σε αρχείο κειμένου.")
    def _save_infer_output():
        path, _ = QFileDialog.getSaveFileName(None, "Αποθήκευση απάντησης", str(ARTIFACTS_DIR / "inference_output.txt"), "Text Files (*.txt)")
        if path:
            Path(path).write_text(self.infer_output.toPlainText(), encoding="utf-8")
    save_out.clicked.connect(_save_infer_output)
    for b in (copy_out, clear_out, save_out):
        b.setMinimumHeight(36)
        b.setMinimumWidth(0)
        b.setSizePolicy(QSizePolicy.Minimum, QSizePolicy.Fixed)
        out_btn_row.addWidget(b)
    out_btn_row.addStretch(1)
    output_lay.addLayout(out_btn_row)
    lay.addWidget(output_card)

    scroll_lay.addWidget(top)
    scroll_lay.addStretch(1)

    root.addWidget(self._build_logs_card(), 1)
    self._refresh_inference_trained_models_combo()
    return page


