# ===== FINAL THREAD-SAFE REALTIME / FONT / ENTRYPOINT HOTFIX =====

def _studio_safe_positive_fonts(widget: QWidget, min_pt: float = 11.0) -> None:
    try:
        targets = [widget, *widget.findChildren(QWidget)]
    except Exception:
        targets = [widget]
    for target in targets:
        try:
            font = target.font()
            size = float(font.pointSizeF())
            if size <= 0:
                if not str(font.family() or '').strip():
                    font.setFamily('Segoe UI')
                font.setPointSizeF(float(min_pt))
                target.setFont(font)
        except Exception:
            continue


def _studio_is_object_in_gui_thread(obj: QObject | None = None) -> bool:
    try:
        app = QApplication.instance()
        gui_thread = app.thread() if app is not None else None
        current = QThread.currentThread()
        if obj is not None:
            try:
                return current == obj.thread()
            except Exception:
                pass
        return gui_thread is not None and current == gui_thread
    except Exception:
        return True


def _studio_chat_flush_stream_chunks_threadsafe(self) -> None:
    lock = getattr(self, '_stream_pending_lock', None)
    if lock is None:
        lock = threading.Lock()
        self._stream_pending_lock = lock
    with lock:
        pending_chunks = list(getattr(self, '_stream_pending_chunks', []) or [])
        pending_statuses = list(getattr(self, '_stream_pending_statuses', []) or [])
        self._stream_pending_chunks = []
        self._stream_pending_statuses = []
    if pending_chunks and self._messages and self._messages[-1].get('role') == 'assistant':
        chunk = ''.join(pending_chunks)
        current = str(self._messages[-1].get('content') or '')
        self._messages[-1]['content'] = current + chunk
        self._messages[-1]['streaming'] = True
        self._refresh_chat_view()
    if pending_statuses:
        try:
            self._set_status(str(pending_statuses[-1]))
        except Exception:
            pass


def _studio_chat_ensure_stream_timer_threadsafe(self) -> None:
    timer = getattr(self, '_stream_flush_timer', None)
    if timer is None:
        timer = QTimer(self)
        timer.setInterval(200)   # 200ms — fewer redraws per second → less flicker
        timer.timeout.connect(lambda: self._flush_stream_chunks())
        self._stream_flush_timer = timer


def _studio_chat_start_generation_realtime_threadsafe(self) -> None:
    model_dir = self.model_dir_edit.text().strip()
    messages = self._build_generation_messages()
    options = self._current_generation_options()
    self._stream_pending_chunks = []
    self._stream_pending_statuses = []
    self._stream_pending_lock = threading.Lock()
    self._chat_ensure_stream_timer()
    if not self._stream_flush_timer.isActive():
        self._stream_flush_timer.start()
    self._set_busy(True, 'Φόρτωση runtime και παραγωγή απάντησης...')
    self._messages.append({'role': 'assistant', 'content': '', 'streaming': True})
    self._refresh_chat_view()
    self._chat_thread = QThread(self)
    worker = BackgroundWorker(_studio_chat_generate_worker_streaming, model_dir, copy.deepcopy(messages), copy.deepcopy(options))
    self._chat_worker = worker
    worker.moveToThread(self._chat_thread)
    self._chat_thread.started.connect(worker.run)
    worker.progress.connect(self._on_generation_progress, Qt.QueuedConnection)
    worker.finished.connect(self._on_generation_finished, Qt.QueuedConnection)
    worker.error.connect(self._on_generation_error, Qt.QueuedConnection)
    worker.finished.connect(self._chat_thread.quit, Qt.QueuedConnection)
    worker.error.connect(self._chat_thread.quit, Qt.QueuedConnection)
    self._chat_thread.finished.connect(self._clear_generation_thread, Qt.QueuedConnection)
    self._chat_thread.start()


def _studio_chat_on_generation_progress_realtime_threadsafe(self, message: str) -> None:
    lock = getattr(self, '_stream_pending_lock', None)
    if lock is None:
        lock = threading.Lock()
        self._stream_pending_lock = lock
    if not isinstance(message, str):
        with lock:
            statuses = list(getattr(self, '_stream_pending_statuses', []) or [])
            statuses.append(str(message))
            self._stream_pending_statuses = statuses[-20:]
        return
    if message.startswith(_STUDIO_STREAM_CHUNK_PREFIX):
        chunk = message[len(_STUDIO_STREAM_CHUNK_PREFIX):]
        if chunk:
            with lock:
                chunks = list(getattr(self, '_stream_pending_chunks', []) or [])
                chunks.append(chunk)
                self._stream_pending_chunks = chunks
        return
    clean = message[len(_STUDIO_STREAM_STATUS_PREFIX):] if message.startswith(_STUDIO_STREAM_STATUS_PREFIX) else message
    with lock:
        statuses = list(getattr(self, '_stream_pending_statuses', []) or [])
        statuses.append(clean)
        self._stream_pending_statuses = statuses[-20:]


def _studio_chat_on_generation_finished_realtime_threadsafe(self, result: object) -> None:
    try:
        self._flush_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, '_stream_flush_timer', None)
    if timer is not None and timer.isActive():
        timer.stop()
    payload = dict(result) if isinstance(result, dict) else {'text': str(result)}
    last_user_text = _studio_chat_find_last_user_text(getattr(self, '_messages', []))
    text = str(payload.get('text') or '').strip() or '(Το μοντέλο δεν επέστρεψε κείμενο.)'
    text = _studio_chat_normalize_python_reply(text, last_user_text) or '(Το μοντέλο δεν επέστρεψε κείμενο.)'
    payload['text'] = text
    self._chat_stream_chars_since_render = 0
    self._chat_stream_last_visible_ts = 0.0
    if self._messages and self._messages[-1].get('role') == 'assistant':
        self._messages[-1]['content'] = text
        self._messages[-1].pop('streaming', None)
    else:
        self._messages.append({'role': 'assistant', 'content': text})
    self._last_result = payload
    resolved_model_dir = str(payload.get('resolved_model_dir') or self.model_dir_edit.text().strip())
    adapter_dir = str(payload.get('adapter_dir') or '')
    note = str(payload.get('note') or '')
    cache_note = 'από cache runtime' if bool(payload.get('from_cache')) else 'με νέα φόρτωση runtime'
    info_parts = [f'Απάντηση από: {resolved_model_dir}', cache_note]
    if adapter_dir:
        info_parts.append(f'adapter: {adapter_dir}')
    if note:
        info_parts.append(note)
    _studio_chat_schedule_refresh(self, force=True)
    self._set_busy(False, ' | '.join(info_parts))
    _studio_chat_sync_action_buttons(self, True)
    try:
        self.host.log(f'💬 Ολοκληρώθηκε απάντηση chat για μοντέλο: {resolved_model_dir}')
    except Exception:
        pass

def _studio_chat_on_generation_error_realtime_threadsafe(self, message: str) -> None:
    try:
        self._flush_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, '_stream_flush_timer', None)
    if timer is not None and timer.isActive():
        timer.stop()
    if self._messages and self._messages[-1].get('role') == 'assistant' and not str(self._messages[-1].get('content') or '').strip():
        self._messages.pop()
    _studio_chat_schedule_refresh(self, force=True)
    self._set_busy(False, f'Σφάλμα chat: {message}')
    _studio_chat_sync_action_buttons(self, True)
    QMessageBox.critical(self, APP_TITLE, message)
    try:
        self.host.log(f'❌ Σφάλμα chat μοντέλου: {message}')
    except Exception:
        pass

def _studio_flush_inference_stream_chunks_threadsafe(self) -> None:
    lock = getattr(self, '_infer_stream_lock', None)
    if lock is None:
        lock = threading.Lock()
        self._infer_stream_lock = lock
    with lock:
        pending_chunks = list(getattr(self, '_infer_stream_pending_chunks', []) or [])
        pending_statuses = list(getattr(self, '_infer_pending_statuses', []) or [])
        self._infer_stream_pending_chunks = []
        self._infer_pending_statuses = []
    view = getattr(self, 'infer_output', None)
    if pending_statuses:
        try:
            self._set_status_message(str(pending_statuses[-1]))
        except Exception:
            pass
        if view is not None:
            for clean in pending_statuses:
                if 'realtime' in str(clean).lower():
                    continue
                cursor = view.textCursor()
                cursor.movePosition(QTextCursor.End)
                cursor.insertText(f'\n[{clean}]\n')
                view.setTextCursor(cursor)
                view.ensureCursorVisible()
    if pending_chunks and view is not None:
        text = ''.join(pending_chunks)
        cursor = view.textCursor()
        cursor.movePosition(QTextCursor.End)
        cursor.insertText(text)
        view.setTextCursor(cursor)
        view.ensureCursorVisible()


def _studio_ensure_inference_stream_timer_threadsafe(self) -> None:
    timer = getattr(self, '_infer_stream_timer', None)
    if timer is None:
        timer = QTimer(self)
        timer.setInterval(60)
        timer.timeout.connect(lambda: self._flush_inference_stream_chunks())
        self._infer_stream_timer = timer


def _studio_run_inference_realtime_threadsafe(self, title: str = 'Inference') -> None:
    model_dir = self.infer_model_edit.text().strip()
    prompt = self.infer_prompt.toPlainText().strip()
    if not model_dir:
        QMessageBox.warning(self, APP_TITLE, 'Επίλεξε φάκελο μοντέλου για inference.')
        return
    if not prompt:
        QMessageBox.warning(self, APP_TITLE, 'Γράψε prompt για δοκιμή μοντέλου.')
        return
    if getattr(self, '_infer_thread', None) is not None:
        QMessageBox.information(self, APP_TITLE, 'Υπάρχει ήδη ενεργή δοκιμή μοντέλου.')
        return
    if getattr(self, '_current_process', None) is not None or getattr(self, '_job_thread', None) is not None:
        QMessageBox.information(self, APP_TITLE, 'Υπάρχει ήδη ενεργή εργασία. Περίμενε να ολοκληρωθεί πρώτα.')
        return
    if hasattr(self, 'infer_output'):
        self.infer_output.clear()
        self.infer_output.setPlainText('⏳ Φόρτωση runtime και έναρξη realtime απάντησης...\n\n')
    self._infer_stream_pending_chunks = []
    self._infer_pending_statuses = []
    self._infer_stream_lock = threading.Lock()
    self._infer_stop_event = threading.Event()  # allows _studio_stop_inference_generation to work
    self._ensure_inference_stream_timer()
    if not self._infer_stream_timer.isActive():
        self._infer_stream_timer.start()
    self._set_status_message(title)
    try:
        self._progress_begin(title, mode='background')
    except Exception:
        pass
    self.log(f'🚀 Εκκίνηση realtime δοκιμής μοντέλου: {model_dir}')
    self._infer_thread = QThread(self)
    worker = BackgroundWorker(_studio_inference_stream_worker, model_dir, prompt, _studio_inference_current_options(self))
    self._infer_worker = worker
    worker.moveToThread(self._infer_thread)
    self._infer_thread.started.connect(worker.run)
    worker.progress.connect(self._on_inference_progress, Qt.QueuedConnection)
    worker.finished.connect(self._on_inference_finished, Qt.QueuedConnection)
    worker.error.connect(self._on_inference_error, Qt.QueuedConnection)
    worker.finished.connect(self._infer_thread.quit, Qt.QueuedConnection)
    worker.error.connect(self._infer_thread.quit, Qt.QueuedConnection)
    self._infer_thread.finished.connect(self._clear_inference_thread, Qt.QueuedConnection)
    self._infer_thread.start()


def _studio_on_inference_progress_threadsafe(self, message: str) -> None:
    lock = getattr(self, '_infer_stream_lock', None)
    if lock is None:
        lock = threading.Lock()
        self._infer_stream_lock = lock
    if not isinstance(message, str):
        with lock:
            statuses = list(getattr(self, '_infer_pending_statuses', []) or [])
            statuses.append(str(message))
            self._infer_pending_statuses = statuses[-20:]
        return
    if message.startswith(_STUDIO_STREAM_CHUNK_PREFIX):
        chunk = message[len(_STUDIO_STREAM_CHUNK_PREFIX):]
        if chunk:
            with lock:
                chunks = list(getattr(self, '_infer_stream_pending_chunks', []) or [])
                chunks.append(chunk)
                self._infer_stream_pending_chunks = chunks
        return
    clean = message[len(_STUDIO_STREAM_STATUS_PREFIX):] if message.startswith(_STUDIO_STREAM_STATUS_PREFIX) else message
    with lock:
        statuses = list(getattr(self, '_infer_pending_statuses', []) or [])
        statuses.append(clean)
        self._infer_pending_statuses = statuses[-20:]


def _studio_on_inference_finished_threadsafe(self, result: object) -> None:
    try:
        self._flush_inference_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, '_infer_stream_timer', None)
    if timer is not None and timer.isActive():
        timer.stop()
    payload = result if isinstance(result, dict) else {'text': str(result)}
    text = str(payload.get('text') or '').strip() or '(Το μοντέλο δεν επέστρεψε κείμενο.)'
    view = getattr(self, 'infer_output', None)
    if view is not None:
        current = view.toPlainText().rstrip()
        if not current.endswith(text):
            cursor = view.textCursor()
            cursor.movePosition(QTextCursor.End)
            if current:
                cursor.insertText('\n')
            cursor.insertText(text)
            view.setTextCursor(cursor)
            view.ensureCursorVisible()
    resolved = str(payload.get('resolved_model_dir') or self.infer_model_edit.text().strip())
    self.log(f'✅ Ολοκληρώθηκε η realtime δοκιμή μοντέλου: {resolved}')
    try:
        self._progress_finish(True, 'Ολοκληρώθηκε')
    except Exception:
        pass
    self._set_status_message('Ολοκληρώθηκε')


def _studio_on_inference_error_threadsafe(self, message: str) -> None:
    try:
        self._flush_inference_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, '_infer_stream_timer', None)
    if timer is not None and timer.isActive():
        timer.stop()
    view = getattr(self, 'infer_output', None)
    if view is not None:
        cursor = view.textCursor()
        cursor.movePosition(QTextCursor.End)
        cursor.insertText(f'\n\n[Σφάλμα] {message}\n')
        view.setTextCursor(cursor)
        view.ensureCursorVisible()
    self.log(f'❌ Σφάλμα realtime δοκιμής μοντέλου: {message}')
    try:
        self._progress_finish(False, 'Σφάλμα')
    except Exception:
        pass
    self._set_status_message('Σφάλμα')
    QMessageBox.critical(self, APP_TITLE, message)


def _studio_open_model_chat_window_fontsafe(self) -> None:
    model_dir = self.infer_model_edit.text().strip() or str(ARTIFACTS_DIR / 'final_model')
    win = StudioModelChatWindow(self, model_dir)
    if not hasattr(self, '_chat_windows'):
        self._chat_windows = []
    self._chat_windows.append(win)
    def _cleanup(*_args: Any) -> None:
        try:
            self._chat_windows = [item for item in getattr(self, '_chat_windows', []) if item is not win]
        except Exception:
            pass
    win.destroyed.connect(_cleanup)
    try:
        _studio_safe_positive_fonts(win)
        QTimer.singleShot(0, lambda w=win: _studio_safe_positive_fonts(w))
    except Exception:
        pass
    win.show()
    win.raise_()
    win.activateWindow()
    self.log(f'💬 Άνοιξε νέο παράθυρο chat για μοντέλο: {model_dir}')


