# ===== LATEST CHAT COPY-CODE / LOW-FLICKER / SIZE PATCH =====

def _studio_chat_handle_anchor(self, url: object) -> None:
    try:
        href = url.toString() if hasattr(url, 'toString') else str(url or '')
    except Exception:
        href = str(url or '')
    if href.startswith('copycode:'):
        key = href.split(':', 1)[1].strip()
        code_map = getattr(self, '_chat_code_block_map', {}) or {}
        code_text = str(code_map.get(key) or '')
        if code_text:
            try:
                QApplication.clipboard().setText(code_text)
                self._set_status('Αντιγράφηκε το επιλεγμένο code block.')
            except Exception:
                pass
        return
    try:
        QDesktopServices.openUrl(url if isinstance(url, QUrl) else QUrl(href))
    except Exception:
        pass


def _studio_chat_find_last_user_text(messages: object) -> str:
    try:
        for item in reversed(list(messages or [])):
            if str(getattr(item, 'get', lambda *_: '')('role') or '').strip().lower() == 'user':
                return str(getattr(item, 'get', lambda *_: '')('content') or '')
    except Exception:
        pass
    return ''


def _studio_chat_is_python_request(user_text: str) -> bool:
    low = str(user_text or '').casefold()
    if not low:
        return False
    has_python = any(token in low for token in (
        'python', '```python', 'py script', 'torch', 'pytorch', 'κώδικ', 'κωδικ', 'script', 'πρόγραμμα', 'εφαρμογ'
    ))
    wants_code = any(token in low for token in (
        ' code', 'code ', 'full code', 'complete code', 'entire code', 'whole code', 'source code',
        'single block', 'one block', 'single code block', 'code only', 'only code',
        'κώδικ', 'ενιαίο block', 'ένα block', 'μονο κωδικ', 'μόνο κώδικ'
    ))
    return bool(has_python and wants_code) or ('python' in low and any(token in low for token in ('write', 'give', 'create', 'generate', 'implement', 'show')))


def _studio_chat_extract_fenced_code_blocks(raw_text: str) -> list[tuple[str, str]]:

    text = str(raw_text or '')
    block_re = re.compile(r"```([^\n`]*)\n?([\s\S]*?)```")
    blocks: list[tuple[str, str]] = []
    for match in block_re.finditer(text):
        lang = str(match.group(1) or '').strip().lower()
        code = str(match.group(2) or '').replace('\r\n', '\n').replace('\r', '\n')
        blocks.append((lang, code))
    return blocks


def _studio_chat_looks_like_python_code(text: str) -> bool:
    sample = str(text or '').replace('\r\n', '\n').replace('\r', '\n').strip()
    if not sample:
        return False
    score = 0
    checks = [
        'import ', 'from ', 'def ', 'class ', 'if __name__ == "__main__":', "if __name__ == '__main__':",
        'return ', 'print(', 'torch.', 'nn.', 'plt.', 'for ', 'while ', 'with ', 'try:', 'except',
        'DataLoader', 'device =', 'model =', 'optimizer =', 'criterion =', 'transforms.'
    ]
    for token in checks:
        if token in sample:
            score += 1
    lines = [ln for ln in sample.split('\n') if ln.strip()]
    colon_lines = sum(1 for ln in lines if ln.rstrip().endswith(':'))
    indented_lines = sum(1 for ln in lines if ln.startswith(('    ', '\t')))
    if colon_lines >= 2:
        score += 1
    if indented_lines >= 3:
        score += 1
    return score >= 3


def _studio_chat_dedupe_python_chunks(chunks: list[str]) -> list[str]:
    result: list[str] = []
    seen: set[str] = set()
    for chunk in chunks:
        normalized = str(chunk or '').replace('\r\n', '\n').replace('\r', '\n').strip('\n')
        if not normalized:
            continue
        key = '\n'.join(line.rstrip() for line in normalized.split('\n')).strip()
        if not key or key in seen:
            continue
        seen.add(key)
        result.append(normalized)
    return result


def _studio_chat_collapse_repeated_python_script(code: str) -> str:
    text = str(code or '').replace('\r\n', '\n').replace('\r', '\n').strip('\n')
    if not text:
        return ''
    lines = text.split('\n')
    for divisor in (2, 3):
        if len(lines) >= 40 and len(lines) % divisor == 0:
            chunk_len = len(lines) // divisor
            first = '\n'.join(lines[:chunk_len]).strip()
            if first and all('\n'.join(lines[i * chunk_len:(i + 1) * chunk_len]).strip() == first for i in range(1, divisor)):
                return first
    for split in range(len(lines) // 3, (2 * len(lines)) // 3 + 1):
        if split < 25 or split * 2 > len(lines):
            continue
        first = '\n'.join(lines[:split]).strip()
        second = '\n'.join(lines[split:split * 2]).strip()
        if first and first == second:
            return first
    return text


def _studio_chat_extract_pythonish_tail(raw_text: str) -> str:
    lines = str(raw_text or '').replace('\r\n', '\n').replace('\r', '\n').split('\n')
    if not lines:
        return ''
    def _is_code_line(line: str) -> bool:
        stripped = line.strip()
        if not stripped:
            return True
        starters = ('import ', 'from ', 'def ', 'class ', 'if ', 'elif ', 'else:', 'for ', 'while ', 'with ', 'try:', 'except', 'return ', 'print(', '@', '#')
        return (
            stripped.startswith(starters)
            or '=' in stripped
            or stripped.endswith(':')
            or stripped.startswith(('model.', 'torch.', 'nn.', 'plt.', 'train_', 'test_'))
            or stripped in {'pass', 'break', 'continue'}
        )
    first_idx = None
    for idx, line in enumerate(lines):
        if _is_code_line(line):
            first_idx = idx
            break
    if first_idx is None:
        return ''
    candidate = '\n'.join(lines[first_idx:]).strip('\n')
    return candidate if _studio_chat_looks_like_python_code(candidate) else ''


def _studio_chat_format_python_code(code: str) -> str:
    """Best-effort Python formatter for chat replies.

    This implementation is intentionally stdlib-only so it also works inside
    packaged environments where optional tools such as black or autopep8 are
    not installed.

    Strategy:
      1. Normalize newlines, tabs and trailing whitespace.
      2. If the code already parses, keep its structure and only normalize.
      3. Rescale shallow indentation (for example 1-space or 2-space code) to
         4 spaces.
      4. Apply heuristic reindentation for flattened block bodies.
    """
    import ast
    import math

    text = str(code or '').replace('\r\n', '\n').replace('\r', '\n').strip('\n')
    if not text:
        return ''

    def _normalize_basic(src: str) -> str:
        normalized_lines: list[str] = []
        for raw_line in src.split('\n'):
            raw_line = raw_line.rstrip()
            leading_match = re.match(r'^[ \t]*', raw_line)
            leading_raw = leading_match.group(0) if leading_match else ''
            rest = raw_line[len(leading_raw):]
            leading = leading_raw.replace('\t', '    ')
            normalized_lines.append(f'{leading}{rest}')
        return '\n'.join(normalized_lines).rstrip('\n')

    def _is_parseable(src: str) -> bool:
        try:
            ast.parse(src + '\n')
            return True
        except Exception:
            return False

    def _heuristic_reindent(src: str) -> str:
        lines = src.split('\n')
        out: list[str] = []
        header_stack: list[tuple[int, int]] = []  # (original_indent_width, target_indent_level)
        prev_orig_width: int | None = None
        prev_target_level = 0
        prev_ended_colon = False
        dedent_before = ('elif ', 'else:', 'except', 'finally:')
        block_headers = ('def ', 'class ', 'elif ', 'else:', 'except', 'finally:', 'case ')

        for line in lines:
            if not line.strip():
                out.append('')
                continue

            match = re.match(r'^([ \t]*)(.*)$', line)
            leading_raw, stripped = match.groups() if match else ('', line.strip())
            orig_width = len(leading_raw.replace('\t', '    '))

            if stripped.startswith(dedent_before) and header_stack:
                header_stack.pop()

            if prev_ended_colon:
                target_level = prev_target_level + 1
            else:
                if orig_width == 0:
                    header_stack.clear()
                    target_level = 0
                elif prev_orig_width is not None and orig_width == prev_orig_width:
                    if stripped.startswith(block_headers) and any(w == orig_width for w, _lvl in header_stack):
                        while header_stack and header_stack[-1][0] >= orig_width:
                            header_stack.pop()
                        target_level = (header_stack[-1][1] + 1) if header_stack else 1
                    else:
                        target_level = prev_target_level
                else:
                    while header_stack and orig_width <= header_stack[-1][0]:
                        header_stack.pop()
                    if header_stack:
                        target_level = header_stack[-1][1] + 1
                    else:
                        target_level = 1 if orig_width > 0 else 0

            out.append((' ' * 4 * max(0, target_level)) + stripped)
            ends_colon = stripped.endswith(':') and not stripped.startswith('#')
            if ends_colon:
                header_stack.append((orig_width, target_level))
            prev_orig_width = orig_width
            prev_target_level = target_level
            prev_ended_colon = ends_colon

        return '\n'.join(out).rstrip('\n')

    text = _normalize_basic(text)
    if _is_parseable(text):
        return text

    # First, try simple indent-width rescaling for 1-space / 2-space code.
    lines = text.split('\n')
    indent_widths: list[int] = []
    for line in lines:
        if not line.strip():
            continue
        match = re.match(r'^[ \t]*', line)
        leading = (match.group(0) if match else '').replace('\t', '    ')
        width = len(leading)
        if width > 0:
            indent_widths.append(width)

    if indent_widths:
        step = indent_widths[0]
        for width in indent_widths[1:]:
            step = math.gcd(step, width)
        if 0 < step < 4:
            scaled: list[str] = []
            for line in lines:
                match = re.match(r'^([ \t]*)(.*)$', line)
                if not match:
                    scaled.append(line)
                    continue
                leading_raw, rest = match.groups()
                leading = leading_raw.replace('\t', '    ')
                width = len(leading)
                if width > 0 and width % step == 0:
                    leading = ' ' * ((width // step) * 4)
                scaled.append(f'{leading}{rest}')
            scaled_text = _normalize_basic('\n'.join(scaled).rstrip('\n'))
            if _is_parseable(scaled_text):
                return scaled_text
            text = scaled_text

    heuristic = _normalize_basic(_heuristic_reindent(text))
    if _is_parseable(heuristic):
        return heuristic
    return heuristic or text


def _studio_chat_normalize_python_reply(raw_text: str, user_text: str = '') -> str:
    text = str(raw_text or '').replace('\r\n', '\n').replace('\r', '\n').strip()
    if not text:
        return text

    force_python_only = _studio_chat_is_python_request(user_text)
    blocks = _studio_chat_extract_fenced_code_blocks(text)
    python_blocks = [code.strip('\n') for lang, code in blocks if lang in {'python', 'py'}]
    generic_blocks = [code.strip('\n') for lang, code in blocks if not lang]

    if python_blocks:
        merged_chunks = _studio_chat_dedupe_python_chunks(python_blocks)
        merged_code = _studio_chat_collapse_repeated_python_script('\n\n'.join(merged_chunks)).strip('\n')
        merged_code = _studio_chat_format_python_code(merged_code)
        if merged_code and (force_python_only or len(blocks) >= 1):
            return f"```python\n{merged_code}\n```"

    if force_python_only and generic_blocks:
        merged_chunks = _studio_chat_dedupe_python_chunks(generic_blocks)
        merged_code = _studio_chat_collapse_repeated_python_script('\n\n'.join(merged_chunks)).strip('\n')
        merged_code = _studio_chat_format_python_code(merged_code)
        if merged_code and _studio_chat_looks_like_python_code(merged_code):
            return f"```python\n{merged_code}\n```"

    if force_python_only:
        tail = _studio_chat_extract_pythonish_tail(text)
        if tail:
            merged_code = _studio_chat_collapse_repeated_python_script(tail).strip('\n')
            merged_code = _studio_chat_format_python_code(merged_code)
            return f"```python\n{merged_code}\n```"
        if _studio_chat_looks_like_python_code(text):
            merged_code = _studio_chat_collapse_repeated_python_script(text).strip('\n')
            merged_code = _studio_chat_format_python_code(merged_code)
            return f"```python\n{merged_code}\n```"

    return text


def _studio_chat_merge_python_fenced_blocks(raw_text: str) -> str:
    """Merge multiple fenced Python blocks into one single ```python``` block.

    Keeps the surrounding explanatory text in place, but removes duplicate Python
    fenced sections after folding their contents into the first Python block.
    """

    text = str(raw_text or '')
    if '```' not in text:
        return text

    block_re = re.compile(r"```([^\n`]*)\n([\s\S]*?)```")
    matches = list(block_re.finditer(text))
    if not matches:
        return text

    python_langs = {'python', 'py'}
    py_matches = []
    for m in matches:
        lang = (m.group(1) or '').strip().lower()
        if lang in python_langs:
            py_matches.append(m)

    if len(py_matches) <= 1:
        return text

    merged_chunks: list[str] = []
    for m in py_matches:
        code = (m.group(2) or '').replace('\r\n', '\n').replace('\r', '\n').strip('\n')
        if code:
            merged_chunks.append(code)

    if not merged_chunks:
        return text

    merged_block = "```python\n" + "\n\n".join(merged_chunks) + "\n```"

    out_parts: list[str] = []
    cursor = 0
    inserted = False

    for m in matches:
        out_parts.append(text[cursor:m.start()])
        lang = (m.group(1) or '').strip().lower()
        if lang in python_langs:
            if not inserted:
                out_parts.append(merged_block)
                inserted = True
        else:
            out_parts.append(m.group(0))
        cursor = m.end()

    out_parts.append(text[cursor:])
    return ''.join(out_parts)




def _studio_chat_render_streaming_python_preview(
    raw_text: str,
    *,
    inline_code_style: str,
    code_wrap_style: str,
    header_style: str,
    code_block_style: str,
    lang_badge_style: str,
    copy_btn_style: str,
    message_index: int,
) -> tuple[str, dict[str, str]]:
    """Render partial Python/code output as a real code block during streaming.

    This avoids waiting for the final normalization pass before the user sees
    Consolas + proper indentation.
    """

    text = str(raw_text or '').replace('\r\n', '\n').replace('\r', '\n')
    code_map: dict[str, str] = {}
    if not text.strip():
        return '', code_map

    prefix = ''
    code_text = text
    lang = ''

    if '```' in text and (text.count('```') % 2 == 1):
        before, after = text.split('```', 1)
        prefix = before
        code_text = after
        if '\n' in code_text:
            first_line, rest = code_text.split('\n', 1)
            candidate = first_line.strip()
            if candidate and len(candidate) <= 32 and all(ch.isalnum() or ch in '_+-#.' for ch in candidate):
                lang = candidate
                code_text = rest
    elif not _studio_chat_looks_like_python_code(text):
        return '', code_map

    try:
        code_text = _studio_chat_format_python_code(code_text)
    except Exception:
        pass

    block_id = f'm{message_index}_stream_preview'
    code_map[block_id] = code_text.rstrip('\n')

    lang_name = '🐍 Python' if (lang.lower() in {'python', 'py'} or _studio_chat_looks_like_python_code(code_text)) else (lang.upper() if lang else 'CODE')
    line_count = code_text.count('\n') + 1
    lines_badge = f' · {line_count} γραμμές' if line_count > 1 else ''
    lang_html = (
        f'<span style="{lang_badge_style}">{html.escape(lang_name)}</span>'
        f'<span style="font-size:10.5px;color:inherit;margin-left:8px;font-family:Segoe UI,Arial,sans-serif;">{lines_badge}</span>'
    )
    copy_html = f'<a href="copycode:{block_id}" style="{copy_btn_style}">📋&nbsp;Αντιγραφή</a>'
    prefix_html = _studio_chat_render_plain_with_inline_code(prefix, inline_style=inline_code_style) if prefix else ''

    body_html = (
        f'<div style="{code_wrap_style}">'
        f'<div style="{header_style}"><span>{lang_html}</span><span>{copy_html}</span></div>'
        f'<pre style="{code_block_style}">{html.escape(code_text.rstrip(chr(10)))}</pre>'
        f'</div>'
    )
    return prefix_html + body_html, code_map

def _studio_chat_render_message_html_with_copy(
    self, raw_text: str, role: str = 'assistant',
    streaming: bool = False, message_index: int = 0
) -> tuple[str, dict[str, str]]:
    """Convert raw markdown-like text to HTML with syntax-highlighted code blocks.
    Code blocks get a one-click 📋 Copy button. Only code uses Consolas.
    """

    raw_text = str(raw_text or '')
    if role == 'assistant':
        prior_user_text = ''
        try:
            local_messages = list(getattr(self, '_messages', []) or [])
            if 0 <= int(message_index) < len(local_messages):
                for prev_item in reversed(local_messages[:int(message_index)]):
                    if str(prev_item.get('role') or '').strip().lower() == 'user':
                        prior_user_text = str(prev_item.get('content') or '')
                        break
        except Exception:
            prior_user_text = ''
        raw_text = _studio_chat_normalize_python_reply(raw_text, prior_user_text)
        raw_text = _studio_chat_merge_python_fenced_blocks(raw_text)
    code_map: dict[str, str] = {}
    if not raw_text:
        return ("<span style='opacity:0.65;font-style:italic;'>✍ Γράφει…</span>"
                if streaming else ''), code_map

    # ── Detect dark theme ────────────────────────────────────────────────
    _dark = False
    try:
        host = getattr(self, 'host', None)
        if host:
            _dark = getattr(host, '_theme_name', 'light') == 'dark'
    except Exception:
        pass

    # ── Design tokens ────────────────────────────────────────────────────
    CODE_FONT   = "'Consolas','Cascadia Code','Courier New',monospace"
    if _dark:
        CODE_BG      = '#0d1b2a'
        CODE_BORDER  = '#1e3a58'
        CODE_TXT     = '#a8d8f0'
        HEADER_BG    = '#0a1520'
        HEADER_TXT   = '#5a90d8'
        BADGE_BG     = '#1e304c'
        BADGE_BORDER = '#2e5090'
        BADGE_TXT    = '#7eb8f7'
        COPY_BG      = '#1e304c'
        COPY_BORDER  = '#2e5090'
        COPY_TXT     = '#7eb8f7'
        INLINE_BG    = '#0d1b2a'
        INLINE_TXT   = '#7eb8f7'
        INLINE_BORDER= '#1e3a58'
    else:
        CODE_BG      = '#f4f8fc'
        CODE_BORDER  = '#c8dff0'
        CODE_TXT     = '#0f2840'
        HEADER_BG    = '#e8f2fc'
        HEADER_TXT   = '#1e5a9a'
        BADGE_BG     = '#dbeafe'
        BADGE_BORDER = '#93c5fd'
        BADGE_TXT    = '#1d4ed8'
        COPY_BG      = '#dbeafe'
        COPY_BORDER  = '#93c5fd'
        COPY_TXT     = '#1d4ed8'
        INLINE_BG    = '#eff6ff'
        INLINE_TXT   = '#1e40af'
        INLINE_BORDER= '#bfdbfe'

    code_wrap_style = (
        f'margin:14px 0 10px 0;'
        f'background:{CODE_BG};'
        f'border:1px solid {CODE_BORDER};'
        f'border-radius:14px;'
    )
    header_style = (
        f'background:{HEADER_BG};'
        f'padding:8px 14px;'
        f'border-bottom:1px solid {CODE_BORDER};'
        f'display:flex;justify-content:space-between;align-items:center;'
    )
    code_block_style = (
        f'margin:0;padding:14px 16px 14px 16px;'
        f'background:{CODE_BG};border:none;'
        f'font-family:{CODE_FONT};'
        f'font-size:14px;line-height:1.65;'
        f'color:{CODE_TXT};'
        f'white-space:pre;'
        f'overflow-x:auto;'
        f'tab-size:4;'
    )
    lang_badge_style = (
        f'display:inline-block;padding:3px 10px;'
        f'background:{BADGE_BG};border:1px solid {BADGE_BORDER};'
        f'border-radius:999px;font-size:11px;font-weight:700;'
        f'color:{BADGE_TXT};letter-spacing:0.4px;'
        f'font-family:Segoe UI,Arial,sans-serif;'
    )
    copy_btn_style = (
        f'display:inline-block;padding:4px 12px;'
        f'background:{COPY_BG};border:1px solid {COPY_BORDER};'
        f'border-radius:8px;font-size:11.5px;font-weight:700;'
        f'color:{COPY_TXT};text-decoration:none;'
        f'font-family:Segoe UI,Arial,sans-serif;'
    )
    inline_code_style = (
        f'font-family:{CODE_FONT};font-size:13.5px;'
        f'background:{INLINE_BG};color:{INLINE_TXT};'
        f'border:1px solid {INLINE_BORDER};border-radius:5px;'
        f'padding:1px 5px;'
    )

    # ── Split on ``` delimiters ──────────────────────────────────────────
    parts = raw_text.split('```')
    if len(parts) == 1:
        if role == 'assistant':
            if streaming:
                preview_html, preview_codes = _studio_chat_render_streaming_python_preview(
                    raw_text,
                    inline_code_style=inline_code_style,
                    code_wrap_style=code_wrap_style,
                    header_style=header_style,
                    code_block_style=code_block_style,
                    lang_badge_style=lang_badge_style,
                    copy_btn_style=copy_btn_style,
                    message_index=message_index,
                )
                if preview_html:
                    return preview_html, preview_codes
            return _studio_chat_render_plain_with_inline_code(raw_text, inline_style=inline_code_style), code_map
        return html.escape(raw_text).replace('\n', '<br>'), code_map

    rendered: list[str] = []
    code_idx = 0
    for idx, part in enumerate(parts):
        if idx % 2 == 0:
            if part:
                if role == 'assistant':
                    rendered.append(_studio_chat_render_plain_with_inline_code(part, inline_style=inline_code_style))
                else:
                    rendered.append(html.escape(part).replace('\n', '<br>'))
            continue

        # ── Code block ───────────────────────────────────────────────────
        lang = ''
        code_text = part
        if '\n' in part:
            first_line, rest = part.split('\n', 1)
            candidate = first_line.strip()
            if candidate and len(candidate) <= 32 and all(ch.isalnum() or ch in '_+-#.' for ch in candidate):
                lang = candidate
                code_text = rest

        if role == 'assistant' and (lang.lower() in {'python', 'py'} or _studio_chat_looks_like_python_code(code_text)):
            try:
                code_text = _studio_chat_format_python_code(code_text)
            except Exception:
                pass

        block_id = f'm{message_index}_c{code_idx}'
        code_idx += 1
        code_map[block_id] = code_text.rstrip('\n')

        # ── Language display name ────────────────────────────────────────
        LANG_ICONS = {
            'python': '🐍 Python', 'py': '🐍 Python',
            'javascript': '📜 JavaScript', 'js': '📜 JavaScript',
            'typescript': '📘 TypeScript', 'ts': '📘 TypeScript',
            'bash': '🖥 Bash', 'sh': '🖥 Shell',
            'sql': '🗃 SQL',
            'json': '📋 JSON',
            'yaml': '⚙ YAML', 'yml': '⚙ YAML',
            'html': '🌐 HTML',
            'css': '🎨 CSS',
            'markdown': '📝 Markdown', 'md': '📝 Markdown',
            'cpp': '⚙ C++', 'c': '⚙ C',
            'java': '☕ Java',
            'rust': '🦀 Rust',
            'go': '🐹 Go',
        }
        lang_display = LANG_ICONS.get(lang.lower(), lang.upper() if lang else 'CODE')

        # ── Line count badge ─────────────────────────────────────────────
        line_count = code_text.count('\n') + 1
        lines_badge = f' · {line_count} γραμμές' if line_count > 1 else ''

        lang_html = (
            f'<span style="{lang_badge_style}">{html.escape(lang_display)}</span>'
            f'<span style="font-size:10.5px;color:{HEADER_TXT};margin-left:8px;'
            f'font-family:Segoe UI,Arial,sans-serif;">{lines_badge}</span>'
        )
        copy_html = (
            f'<a href="copycode:{block_id}" style="{copy_btn_style}">📋&nbsp;Αντιγραφή</a>'
            if role == 'assistant' else ''
        )

        rendered.append(
            f'<div style="{code_wrap_style}">'
            # Header row
            f'<div style="{header_style}">'
            f'<span>{lang_html}</span>'
            f'<span>{copy_html}</span>'
            f'</div>'
            # Code body
            f'<pre style="{code_block_style}">'
            f'{html.escape(code_text.rstrip(chr(10)))}'
            f'</pre>'
            f'</div>'
        )

    return ''.join(rendered), code_map


def _studio_chat_build_html_for_messages(self, messages, code_map_out=None) -> str:
    """Build full HTML for the chat transcript. Theme-aware, rich bubble design."""

    # ── Detect dark theme ────────────────────────────────────────────────
    _dark = False
    try:
        host = getattr(self, 'host', None)
        if host:
            _dark = getattr(host, '_theme_name', 'light') == 'dark'
    except Exception:
        pass

    # ── Theme tokens ─────────────────────────────────────────────────────
    PAGE_BG      = 'transparent'
    if _dark:
        USER_BG      = '#1a2d48'
        USER_BORDER  = '#2a4878'
        USER_TXT     = '#c8d8ee'
        USER_TITLE   = '#5a90d8'
        USER_AVATAR  = '👤'
        BOT_BG       = '#111d2e'
        BOT_BORDER   = '#1e3555'
        BOT_TXT      = '#b0cce8'
        BOT_TITLE    = '#7eb8f7'
        BOT_AVATAR   = '🤖'
        EMPTY_TXT    = '#3a6090'
        SHADOW       = 'rgba(0,0,0,0.35)'
        CHIP_BG      = '#1e304c'
        CHIP_BORDER  = '#2e5090'
        CHIP_TXT     = '#7eb8f7'
    else:
        USER_BG      = '#eaf4ff'   # παστέλ γαλάζιο — ανοιχτόχρωμο
        USER_BORDER  = '#c2ddf6'
        USER_TXT     = '#1a3a60'
        USER_TITLE   = '#2563eb'
        USER_AVATAR  = '👤'
        BOT_BG       = '#f5f9fe'   # λευκό-γαλάζιο — ανοιχτόχρωμο
        BOT_BORDER   = '#cce3f8'
        BOT_TXT      = '#0f2840'
        BOT_TITLE    = '#1a56d6'
        BOT_AVATAR   = '🤖'
        EMPTY_TXT    = '#7a9ec2'
        SHADOW       = 'rgba(0,40,100,0.05)'
        CHIP_BG      = '#e8f4ff'
        CHIP_BORDER  = '#b3d4f5'
        CHIP_TXT     = '#1d4ed8'

    parts = [
        f"<div style='font-family:\"Segoe UI\",Arial,sans-serif;font-size:13.5px;"
        f"line-height:1.72;padding:16px 12px 24px 12px;background:{PAGE_BG};'>"
    ]
    code_map: dict[str, str] = {}

    if not messages:
        parts.append(
            f"<div style='margin:40px 8px;text-align:center;'>"
            f"<div style='display:inline-block;max-width:480px;padding:28px 32px;"
            f"border-radius:20px;background:{'#0d1b2a' if _dark else '#eaf4ff'};"
            f"border:1px solid {'#1e3a58' if _dark else '#b8d8f8'};'>"
            f"<div style='font-size:36px;margin-bottom:12px;'>💬</div>"
            f"<div style='font-size:15px;font-weight:600;color:{EMPTY_TXT};margin-bottom:8px;'>"
            f"Ξεκίνα νέα συνομιλία</div>"
            f"<div style='font-size:13px;color:{EMPTY_TXT};opacity:0.75;'>"
            f"Επίλεξε μοντέλο και γράψε το πρώτο μήνυμα.</div>"
            f"</div></div>"
        )
    else:
        for msg_idx, item in enumerate(messages):
            role      = str(item.get('role') or 'user')
            streaming = bool(item.get('streaming'))
            raw       = str(item.get('content') or '')
            labels    = [html.escape(str(x)) for x in list(item.get('attachment_labels') or [])]
            notes     = [html.escape(str(x)) for x in list(item.get('attachment_notes') or [])[:3]]

            rendered, item_codes = _studio_chat_render_message_html_with_copy(
                self, raw, role=role, streaming=streaming, message_index=msg_idx
            )
            code_map.update(item_codes)

            if role == 'user':
                bg = USER_BG; border = USER_BORDER; txt = USER_TXT
                title_col = USER_TITLE; avatar = USER_AVATAR
                align = 'right'; margin_side = 'margin-left:10%;margin-right:0;'
                bubble_radius = '20px 4px 20px 20px'
            else:
                bg = BOT_BG; border = BOT_BORDER; txt = BOT_TXT
                title_col = BOT_TITLE; avatar = BOT_AVATAR
                align = 'left'; margin_side = 'margin-right:10%;margin-left:0;'
                bubble_radius = '4px 20px 20px 20px'

            title_text = (
                '<span style="color:#3b82f6;margin-right:4px;">⚡</span>'
                'Μοντέλο <span style="font-style:italic;opacity:0.75;">γράφει…</span>'
            ) if streaming else (
                f'<span style="margin-right:5px;">{avatar}</span>'
                f'{"Εσύ" if role == "user" else "Μοντέλο"}'
            )

            chips_html = ''
            if labels:
                chips_html = (
                    "<div style='margin-top:10px;display:flex;flex-wrap:wrap;gap:6px;'>"
                    + ''.join(
                        f"<span style='padding:3px 10px;background:{CHIP_BG};"
                        f"border:1px solid {CHIP_BORDER};border-radius:999px;"
                        f"font-size:11px;color:{CHIP_TXT};'>📎 {lbl}</span>"
                        for lbl in labels
                    )
                    + "</div>"
                )
            note_html = ''
            if notes:
                note_html = (
                    "<div style='margin-top:7px;font-size:11px;opacity:0.72;'>"
                    "<b>Συνημμένα:</b> " + ' • '.join(notes) + "</div>"
                )

            streaming_cursor = (
                "<span style='color:#3b82f6;margin-left:2px;'>▊</span>"
                if streaming else ""
            )

            parts.append(
                f"<div style='margin:12px 0;text-align:{align};'>"
                f"<div style='"
                f"display:inline-block;max-width:88%;text-align:left;"
                f"background:{bg};border:1px solid {border};"
                f"border-radius:{bubble_radius};"
                f"padding:14px 18px 14px 18px;"
                f"box-shadow:0 2px 8px {SHADOW};"
                f"{margin_side}"
                f"'>"
                # Title row
                f"<div style='font-size:11.5px;font-weight:700;color:{title_col};"
                f"margin-bottom:8px;letter-spacing:0.3px;'>{title_text}</div>"
                # Content — only code snippets use Consolas; normal chat text stays in UI font
                + (
                    f"<div style='color:{txt};word-break:break-word;"
                    f"font-family:\"Segoe UI\",Arial,sans-serif;"
                    f"font-size:13.5px;line-height:1.72;'>"
                    if role != 'user' else
                    f"<div style='color:{txt};word-break:break-word;font-family:\"Segoe UI\",Arial,sans-serif;'>"
                )
                + f"{rendered}{streaming_cursor}</div>"
                f"{chips_html}{note_html}"
                f"</div>"
                f"</div>"
            )

    parts.append('</div>')
    result = ''.join(parts)
    if code_map_out is not None:
        code_map_out.update(code_map)
    return result


def _studio_chat_refresh_view_low_flicker(self) -> None:
    """Re-render the chat transcript with zero visible flicker.

    Core technique:
      1. Build the new HTML off-screen into a QTextDocument.
      2. Skip entirely if the HTML is identical to last render.
      3. Freeze all updates (parent groupbox + view + viewport).
      4. Swap the document atomically with setDocument().
      5. Restore the scroll position *synchronously* inside the frozen window.
      6. Unfreeze in one step → single clean repaint, no white flash.
    """
    view = getattr(self, 'chat_view', None)
    if view is None:
        return

    messages = list(getattr(self, '_messages', []) or [])

    # ── Build HTML entirely off-screen ───────────────────────────────────
    code_map: dict[str, str] = {}
    html_out = _studio_chat_build_html_for_messages(self, messages, code_map_out=code_map)

    # ── Guard: nothing changed → nothing to do ────────────────────────────
    if getattr(self, '_last_chat_html', '') == html_out:
        return

    # ── Capture scroll state BEFORE freezing ─────────────────────────────
    bar        = None
    at_bottom  = True
    saved_val  = 0
    saved_max  = 0
    try:
        bar       = view.verticalScrollBar()
        saved_max = bar.maximum()
        saved_val = bar.value()
        # Threshold: 120px — αρκετό για να διακριθεί "σχεδόν κάτω" από "μέσα"
        at_bottom = (saved_val >= max(0, saved_max - 120))
    except Exception:
        pass

    # Κατά τη streaming απάντηση: πάντα scroll στο κάτω ─────────────────────
    # Ελέγχουμε αν η τελευταία εγγραφή βρίσκεται σε streaming κατάσταση.
    try:
        last_msg = (getattr(self, '_messages', []) or [None])[-1]
        if last_msg and last_msg.get('streaming'):
            at_bottom = True
    except Exception:
        pass

    # ── Collect only the minimum widgets to freeze ───────────────────────
    # Freezing parent containers tends to amplify flashing on some systems.
    # Keeping the freeze local to the transcript viewport is visually steadier.
    freeze_targets = [view]
    try:
        vp = view.viewport()
        if vp is not None:
            freeze_targets.append(vp)
    except Exception:
        pass

    for w in freeze_targets:
        try:
            w.setUpdatesEnabled(False)
        except Exception:
            pass

    try:
        # ── Build off-screen document ─────────────────────────────────────
        from PySide6.QtGui import QTextDocument
        from PySide6.QtCore import QSizeF
        new_doc = QTextDocument(view)
        try:
            new_doc.setDefaultFont(view.document().defaultFont())
        except Exception:
            pass
        try:
            new_doc.setDocumentMargin(10)
        except Exception:
            pass
        try:
            new_doc.setDefaultStyleSheet(
                "code, pre { font-family: 'Consolas','Cascadia Code','Courier New',monospace !important; }"
                "body { font-family: 'Segoe UI',Arial,sans-serif; }"
            )
        except Exception:
            pass
        new_doc.setHtml(html_out)   # ← off-screen; no visual effect

        # ── Atomic document swap ──────────────────────────────────────────
        view.setDocument(new_doc)   # ← one pointer swap, no clear→parse visible cycle

        # Re-attach anchor handler to new document
        try:
            view.anchorClicked.disconnect()
        except Exception:
            pass
        try:
            view.anchorClicked.connect(
                lambda url, s=self: _studio_chat_handle_anchor(s, url)
            )
        except Exception:
            pass

        # ── Force synchronous layout so bar.maximum() is accurate ────────
        # After setDocument() Qt defers layout until the next paint.
        # setPageSize() forces an immediate layout pass so the scrollbar
        # range is correct BEFORE we read it — eliminating the "flash to
        # top then scroll down" artifact entirely.
        try:
            vp = view.viewport()
            if vp is not None:
                new_doc.setPageSize(QSizeF(vp.width(), new_doc.pageSize().height()))
        except Exception:
            pass

        # ── Restore scroll SYNCHRONOUSLY (still frozen, no paint yet) ────
        if bar is not None:
            try:
                new_max = bar.maximum()
                if at_bottom:
                    bar.setValue(new_max)
                elif saved_max > 0:
                    # Keep proportional scroll position
                    bar.setValue(int(new_max * saved_val / saved_max))
                else:
                    bar.setValue(min(saved_val, new_max))
            except Exception:
                pass

    except Exception:
        # ── Fallback: setHtml with viewport freeze ────────────────────────
        try:
            view.setHtml(html_out)
            # Force layout in fallback path too
            try:
                vp = view.viewport()
                if vp is not None:
                    view.document().setPageSize(QSizeF(vp.width(), view.document().pageSize().height()))
            except Exception:
                pass
            if bar is not None:
                try:
                    new_max = bar.maximum()
                    bar.setValue(new_max if at_bottom else min(saved_val, new_max))
                except Exception:
                    pass
        except Exception:
            pass

    finally:
        # ── Unfreeze in reverse order → one clean repaint ─────────────────
        for w in reversed(freeze_targets):
            try:
                w.setUpdatesEnabled(True)
            except Exception:
                pass
        try:
            vp = view.viewport()
            if vp is not None:
                vp.update()
        except Exception:
            pass

    self._last_chat_html      = html_out
    self._chat_code_block_map = code_map
    # NOTE: Deferred QTimer scroll removed — synchronous layout via setPageSize()
    # guarantees bar.maximum() is already correct before unfreezing, so the
    # single setValue() above is sufficient and no visible post-paint jump occurs.


def _studio_chat_upgrade_view_to_browser(self) -> None:
    old_view = getattr(self, 'chat_view', None)
    if old_view is None or isinstance(old_view, QTextBrowser):
        return
    parent = old_view.parentWidget()
    layout = parent.layout() if parent is not None else None
    new_view = QTextBrowser(parent)
    new_view.setObjectName(old_view.objectName() or 'ChatTranscript')
    new_view.setOpenLinks(False)
    new_view.setOpenExternalLinks(False)
    new_view.setReadOnly(True)
    try:
        new_view.setTextInteractionFlags(
            Qt.TextSelectableByMouse
            | Qt.TextSelectableByKeyboard
            | Qt.LinksAccessibleByMouse
            | Qt.LinksAccessibleByKeyboard
        )
    except Exception:
        pass
    new_view.setFrameShape(QFrame.NoFrame)
    try:
        new_view.setUndoRedoEnabled(False)
    except Exception:
        pass
    try:
        new_view.setLineWrapMode(QTextEdit.WidgetWidth)
    except Exception:
        pass
    try:
        vp = new_view.viewport()
        if vp is not None:
            vp.setAutoFillBackground(True)
            vp.setAttribute(Qt.WA_OpaquePaintEvent, True)
            vp.setAttribute(Qt.WA_NoSystemBackground, False)
    except Exception:
        pass
    new_view.setSizePolicy(old_view.sizePolicy())
    new_view.setMinimumSize(old_view.minimumSize())
    new_view.setMinimumHeight(max(520, old_view.minimumHeight()))
    new_view.setStyleSheet(old_view.styleSheet())
    try:
        new_view.document().setDocumentMargin(12)
        new_view.document().setDefaultStyleSheet(
            "code, pre { font-family: 'Consolas','Cascadia Code','Courier New',monospace !important; }"
            "body { font-family: 'Segoe UI',Arial,sans-serif; }"
        )
    except Exception:
        pass
    try:
        new_view.setWordWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
    except Exception:
        pass
    try:
        new_view.setHtml(old_view.toHtml())
    except Exception:
        pass
    try:
        new_view.setOpenLinks(False)
        new_view.setOpenExternalLinks(False)
        new_view.anchorClicked.connect(lambda url, s=self: _studio_chat_handle_anchor(s, url))
    except Exception:
        pass
    if layout is not None:
        try:
            layout.replaceWidget(old_view, new_view)
        except Exception:
            try:
                layout.addWidget(new_view)
            except Exception:
                pass
    try:
        old_view.hide()
        old_view.deleteLater()
    except Exception:
        pass
    self.chat_view = new_view


def _studio_chat_reduce_button_sizes(self) -> None:
    # No-op: button sizing is now handled uniformly via QSS (same as main app)
    pass


def _studio_chat_build_ui_latest(self) -> None:
    _studio_chat_build_ui_scrolling_realtime(self)
    _studio_chat_upgrade_view_to_browser(self)
    _studio_chat_reduce_button_sizes(self)
    try:
        self.max_new_tokens_spin.blockSignals(True)
        if int(self.max_new_tokens_spin.value()) == 4096:
            self.max_new_tokens_spin.setValue(8192)
        self.max_new_tokens_spin.blockSignals(False)
    except Exception:
        pass
    # QTextBrowser styling is now handled by _chat_extra — no override needed here
    pass
    try:
        view = getattr(self, 'chat_view', None)
        if view is not None:
            view.setFont(QFont('Segoe UI', 10))
    except Exception:
        pass


def _studio_chat_flush_stream_chunks_low_flicker(self) -> None:
    lock = getattr(self, '_stream_pending_lock', None)
    if lock is None:
        lock = threading.Lock()
        self._stream_pending_lock = lock
    with lock:
        pending_chunks = list(getattr(self, '_stream_pending_chunks', []) or [])
        pending_statuses = list(getattr(self, '_stream_pending_statuses', []) or [])
        self._stream_pending_chunks = []
        self._stream_pending_statuses = []

    render_needed = False
    if pending_chunks and self._messages and self._messages[-1].get('role') == 'assistant':
        chunk = ''.join(pending_chunks)
        if chunk:
            current = str(self._messages[-1].get('content') or '')
            self._messages[-1]['content'] = current + chunk
            self._messages[-1]['streaming'] = True

            chars_since_render = int(getattr(self, '_chat_stream_chars_since_render', 0) or 0) + len(chunk)
            self._chat_stream_chars_since_render = chars_since_render

            last_visible_ts = float(getattr(self, '_chat_stream_last_visible_ts', 0.0) or 0.0)
            now = time.monotonic()
            max_silence_s = float(getattr(self, '_chat_stream_max_silence_s', 0.65) or 0.65)
            min_chars = int(getattr(self, '_chat_stream_min_chars_before_render', 72) or 72)

            content_trigger = (
                '\n' in chunk
                or '```' in chunk
                or chunk.endswith(('.', '!', '?', ':', ';'))
                or any(token in chunk for token in ('\n#', '\ndef ', '\nclass ', '\nimport ', '\nfrom '))
            )
            time_trigger = (last_visible_ts <= 0.0) or ((now - last_visible_ts) >= max_silence_s)
            size_trigger = chars_since_render >= min_chars

            render_needed = bool(content_trigger or time_trigger or size_trigger)
            if render_needed:
                self._chat_stream_chars_since_render = 0
                self._chat_stream_last_visible_ts = now

    if render_needed:
        _studio_chat_schedule_refresh(self, force=False)
    if pending_statuses:
        try:
            self._set_status(str(pending_statuses[-1]))
        except Exception:
            pass

def _studio_chat_ensure_stream_timer_low_flicker(self) -> None:
    timer = getattr(self, '_stream_flush_timer', None)
    if timer is None:
        timer = QTimer(self)
        timer.setInterval(90)   # πιο άμεσο realtime χωρίς υπερβολικό redraw
        timer.timeout.connect(lambda: self._flush_stream_chunks())
        self._stream_flush_timer = timer


def _studio_chat_schedule_refresh(self, force: bool = False) -> None:
    if not _studio_is_object_in_gui_thread(self):
        _studio_run_on_gui_thread(lambda s=self, f=bool(force): _studio_chat_schedule_refresh(s, force=f))
        return
    try:
        now = time.monotonic()
        min_interval = float(getattr(self, '_chat_render_min_interval_s', 0.10) or 0.10)
        last = float(getattr(self, '_chat_last_render_ts', 0.0) or 0.0)
        if force or (now - last) >= min_interval:
            self._chat_last_render_ts = now
            _studio_chat_refresh_view_low_flicker(self)
            return
        timer = getattr(self, '_chat_render_timer', None)
        if timer is None:
            timer = QTimer(self)
            timer.setSingleShot(True)
            timer.timeout.connect(lambda s=self: _studio_chat_schedule_refresh(s, force=True))
            self._chat_render_timer = timer
        remaining_ms = max(1, int(round((min_interval - max(0.0, now - last)) * 1000.0)))
        if (not timer.isActive()) or timer.remainingTime() > remaining_ms:
            timer.start(remaining_ms)
    except Exception:
        _studio_chat_refresh_view_low_flicker(self)


def _studio_chat_refresh_view_low_flicker_gui_safe(self) -> None:
    _studio_chat_schedule_refresh(self, force=False)


def _studio_chat_flush_stream_chunks_low_flicker_gui_safe(self) -> None:
    if not _studio_is_object_in_gui_thread(self):
        _studio_run_on_gui_thread(lambda s=self: _studio_chat_flush_stream_chunks_low_flicker_gui_safe(s))
        return
    _studio_chat_flush_stream_chunks_low_flicker(self)


StudioModelChatWindow._build_ui = _studio_chat_build_ui_latest
StudioModelChatWindow._refresh_chat_view = _studio_chat_refresh_view_low_flicker_gui_safe
StudioModelChatWindow._flush_stream_chunks = _studio_chat_flush_stream_chunks_low_flicker_gui_safe
StudioModelChatWindow._chat_ensure_stream_timer = _studio_chat_ensure_stream_timer_low_flicker
StudioModelChatWindow.handle_chat_anchor = _studio_chat_handle_anchor


