def _studio_parse_lines_to_list(raw: object) -> list[str]:
    text = str(raw or "").replace("\r\n", "\n").replace("\r", "\n")
    items: list[str] = []
    seen: set[str] = set()
    for part in text.split("\n"):
        piece = str(part).strip()
        if not piece:
            continue
        if "," in piece and not piece.startswith("http"):
            sub_items = [x.strip() for x in piece.split(",") if x.strip()]
        else:
            sub_items = [piece]
        for sub in sub_items:
            key = sub.lower()
            if key in seen:
                continue
            seen.add(key)
            items.append(sub)
    return items


def _studio_url_domain(url: str) -> str:
    try:
        return (_studio_urlparse(str(url or "")).netloc or "").lower()
    except Exception:
        return ""


def _studio_infer_language_from_url(url: str) -> str:
    lowered = str(url or "").strip().lower()
    domain = _studio_url_domain(lowered)
    if domain.endswith(".gr"):
        return "el"
    if domain.endswith(".cn") or "/zh/" in lowered or "lang=zh" in lowered:
        return "zh"
    return "en"


def _studio_is_greek_gr_url(url: str) -> bool:
    return _studio_url_domain(url).endswith('.gr')


def _studio_is_english_url(url: str) -> bool:
    domain = _studio_url_domain(url)
    lowered = str(url or '').strip().lower()
    if not domain or domain.endswith('.gr') or domain.endswith('.cn'):
        return False
    if '/zh/' in lowered or 'lang=zh' in lowered:
        return False
    return True


def _studio_make_source_entry(url: str, title: str | None = None, language: str | None = None) -> dict[str, Any]:
    detected = str(language or _studio_infer_language_from_url(url)).strip().lower()
    return {
        'title': str(title or url).strip() or url,
        'url': str(url).strip(),
        'language': detected if detected in {'en', 'el'} else 'en',
    }


def _studio_default_seed_urls(enabled_en: bool = True, enabled_el: bool = True) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    if enabled_en:
        entries.extend(copy.deepcopy(DEFAULT_ENGLISH_SOURCE_URLS_V2))
    if enabled_el:
        entries.extend(copy.deepcopy(DEFAULT_GREEK_SOURCE_URLS_V2))
    return _studio_merge_source_url_entries(entries)


def _studio_filter_source_url_entries_en_el(entries: Any, enabled_en: bool = True, enabled_el: bool = True) -> list[dict[str, Any]]:
    merged = _studio_merge_source_url_entries(entries)
    result: list[dict[str, Any]] = []
    seen: set[str] = set()
    for entry in merged:
        url = str(entry.get('url') or '').strip()
        if not url:
            continue
        lang = str(entry.get('language') or _studio_infer_language_from_url(url)).strip().lower()
        if lang == 'zh':
            continue
        if lang == 'el':
            if not enabled_el or not _studio_is_greek_gr_url(url):
                continue
        else:
            lang = 'en'
            if not enabled_en or not _studio_is_english_url(url):
                continue
        key = url.lower()
        if key in seen:
            continue
        seen.add(key)
        item = dict(entry)
        item['url'] = url
        item['title'] = str(entry.get('title') or url).strip() or url
        item['language'] = lang
        result.append(item)
    return result


def _studio_parse_text_widget(widget: object) -> str:
    if widget is None:
        return ''
    try:
        if hasattr(widget, 'toPlainText'):
            return str(widget.toPlainText() or '')
        if hasattr(widget, 'text'):
            return str(widget.text() or '')
    except Exception:
        pass
    return ''


def _studio_collect_compose_source_urls_from_ui(self) -> list[dict[str, Any]]:
    enabled_en = bool(getattr(self, 'collect_enable_english_check', None).isChecked()) if getattr(self, 'collect_enable_english_check', None) is not None else True
    enabled_el = bool(getattr(self, 'collect_enable_greek_check', None).isChecked()) if getattr(self, 'collect_enable_greek_check', None) is not None else True
    manual_raw = _studio_parse_text_widget(getattr(self, 'collect_manual_urls_edit', None))
    manual_urls = []
    for url in _studio_parse_lines_to_list(manual_raw):
        manual_urls.append(_studio_make_source_entry(url))
    seeds = _studio_default_seed_urls(enabled_en=enabled_en, enabled_el=enabled_el)
    return _studio_filter_source_url_entries_en_el(seeds + manual_urls, enabled_en=enabled_en, enabled_el=enabled_el)


def _studio_collect_selected_file_lines(self) -> list[str]:
    return _studio_parse_lines_to_list(_studio_parse_text_widget(getattr(self, 'collect_source_files_edit', None)))


def _studio_collect_selected_dir_lines(self) -> list[str]:
    return _studio_parse_lines_to_list(_studio_parse_text_widget(getattr(self, 'collect_source_dirs_edit', None)))


def _studio_set_text_widget_lines(widget: object, values: list[str]) -> None:
    text = '\n'.join(values)
    try:
        if hasattr(widget, 'setPlainText'):
            widget.setPlainText(text)
            return
        if hasattr(widget, 'setText'):
            widget.setText(text)
            return
    except Exception:
        pass


def _studio_merge_path_lines(existing: list[str], new_values: list[str]) -> list[str]:
    merged: list[str] = []
    seen: set[str] = set()
    for item in list(existing) + list(new_values):
        path = str(item or '').strip()
        if not path:
            continue
        key = path.lower()
        if key in seen:
            continue
        seen.add(key)
        merged.append(path)
    return merged


def _studio_browse_collect_source_dir(self) -> None:
    path = QFileDialog.getExistingDirectory(self, 'Επιλογή φακέλου πηγών για Collect', str(PROJECT_ROOT))
    if not path:
        return
    merged = _studio_merge_path_lines(_studio_collect_selected_dir_lines(self), [path])
    _studio_set_text_widget_lines(getattr(self, 'collect_source_dirs_edit', None), merged)


def _studio_clear_collect_source_files(self) -> None:
    _studio_set_text_widget_lines(getattr(self, 'collect_source_files_edit', None), [])


def _studio_clear_collect_source_dirs(self) -> None:
    _studio_set_text_widget_lines(getattr(self, 'collect_source_dirs_edit', None), [])


def _studio_extract_text_from_docx(path: Path) -> str:
    try:
        import docx  # type: ignore
        doc = docx.Document(str(path))
        parts = [p.text for p in doc.paragraphs if str(p.text).strip()]
        return '\n'.join(parts).strip()
    except Exception:
        pass
    try:
        import zipfile
        from xml.etree import ElementTree as ET
        with zipfile.ZipFile(path, 'r') as zf:
            data = zf.read('word/document.xml')
        root = ET.fromstring(data)
        texts = []
        for elem in root.iter():
            if elem.tag.endswith('}t') and elem.text:
                texts.append(elem.text)
            elif elem.tag.endswith('}p'):
                texts.append('\n')
        text = ''.join(texts)
        text = re.sub(r'\n{3,}', '\n\n', text)
        return text.strip()
    except Exception as exc:
        raise RuntimeError(f'Αποτυχία ανάγνωσης DOCX: {exc}')


def _studio_extract_text_from_pdf(path: Path) -> str:
    errors: list[str] = []
    for module_name in ('pypdf', 'PyPDF2'):
        try:
            module = __import__(module_name)
            reader = getattr(module, 'PdfReader')(str(path))
            parts = []
            for page in getattr(reader, 'pages', []):
                try:
                    parts.append(page.extract_text() or '')
                except Exception:
                    continue
            text = '\n'.join(x for x in parts if str(x).strip()).strip()
            if text:
                return text
        except Exception as exc:
            errors.append(f'{module_name}: {exc}')
    raise RuntimeError('Δεν βρέθηκε διαθέσιμος PDF reader (pypdf/PyPDF2) ή το PDF δεν είχε εξαγώγιμο κείμενο.')


def _studio_read_text_file_v2(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix == '.pdf':
        return _studio_extract_text_from_pdf(path)
    if suffix == '.docx':
        return _studio_extract_text_from_docx(path)
    if suffix == '.doc':
        try:
            result = subprocess.run(['antiword', str(path)], capture_output=True, text=True, encoding='utf-8', errors='ignore', timeout=30)
            if result.returncode == 0 and str(result.stdout).strip():
                return result.stdout.strip()
        except Exception:
            pass
    if suffix in {'.html', '.htm', '.xml'}:
        for enc in ('utf-8', 'utf-8-sig', 'cp1253', 'cp1252', 'latin-1'):
            try:
                raw = path.read_text(encoding=enc)
                return _studio_strip_html_to_text(raw)
            except Exception:
                continue
    for encoding in ('utf-8', 'utf-8-sig', 'cp1253', 'cp1252', 'latin-1'):
        try:
            return path.read_text(encoding=encoding)
        except Exception:
            continue
    return path.read_bytes().decode('utf-8', errors='ignore')


_STUDIO_PREV_ENSURE_RUNTIME_DEFAULTS = _studio_ensure_runtime_defaults

def _studio_ensure_runtime_defaults_v3(config: dict[str, Any]) -> dict[str, Any]:
    config = _STUDIO_PREV_ENSURE_RUNTIME_DEFAULTS(config)
    dataset = config.setdefault('dataset', {})
    enabled_en = bool(dataset.get('web_discovery_enable_en', True))
    enabled_el = bool(dataset.get('web_discovery_enable_el', True))
    ext_order = list(dataset.get('source_extensions') or [])
    for ext in ['.pdf', '.doc', '.docx', '.html', '.htm', '.xml', '.txt', '.md', '.xlsx', '.xlsm']:
        if ext not in ext_order:
            ext_order.append(ext)
    dataset['source_extensions'] = ext_order
    dataset.setdefault('web_discovery_enable_en', True)
    dataset.setdefault('web_discovery_enable_el', True)
    dataset.setdefault('web_discovery_target_count_en', 100)
    dataset.setdefault('web_discovery_target_count_el', 100)
    dataset.setdefault('web_discovery_timeout_sec', 15)
    dataset.setdefault('web_discovery_require_language_match', True)
    dataset.setdefault('web_discovery_custom_keywords_el', [])
    dataset.setdefault('web_discovery_custom_keywords_en', [])
    dataset['web_discovery_languages'] = [lang for lang, enabled in [('en', enabled_en), ('el', enabled_el)] if enabled]
    dataset['web_discovery_queries'] = copy.deepcopy(dataset.get('web_discovery_queries') or DEFAULT_WEB_DISCOVERY_QUERIES_V2)
    dataset['web_discovery_excluded_domains'] = list(dict.fromkeys(list(dataset.get('web_discovery_excluded_domains') or []) + [
        'bing.com', 'google.com', 'duckduckgo.com', 'yahoo.com', 'facebook.com', 'instagram.com', 'x.com', 'twitter.com',
    ]))
    curated = _studio_default_seed_urls(enabled_en=enabled_en, enabled_el=enabled_el)
    existing = dataset.get('source_urls') or []
    dataset['source_urls'] = _studio_filter_source_url_entries_en_el(curated + list(existing), enabled_en=enabled_en, enabled_el=enabled_el)
    return config


_STUDIO_PREV_IS_DISCOVERY_URL_ALLOWED = _studio_is_discovery_url_allowed

def _studio_is_discovery_url_allowed_v2(url: str, excluded_domains: list[str] | None = None, language: str | None = None) -> bool:
    if not _STUDIO_PREV_IS_DISCOVERY_URL_ALLOWED(url, excluded_domains=excluded_domains):
        return False
    domain = _studio_url_domain(url)
    lowered = str(url or '').lower()
    if domain.endswith('.cn') or '/zh/' in lowered or 'lang=zh' in lowered:
        return False
    lang = str(language or '').strip().lower()
    if lang == 'el':
        return domain.endswith('.gr')
    if lang == 'en':
        return _studio_is_english_url(url)
    return domain.endswith('.gr') or _studio_is_english_url(url)


def _studio_discover_web_sources_v2(config: dict[str, Any]) -> list[dict[str, str]]:
    config = _studio_ensure_runtime_defaults(config)
    dataset = config.get('dataset', {})
    if not bool(dataset.get('auto_discover_web_sources', True)):
        return []
    enabled_langs = [lang for lang in ['en', 'el'] if bool(dataset.get(f'web_discovery_enable_{lang}', True))]
    timeout_sec = max(5, int(dataset.get('web_discovery_timeout_sec') or 15))
    excluded_domains = [str(x).strip().lower() for x in list(dataset.get('web_discovery_excluded_domains') or []) if str(x).strip()]
    base_queries = copy.deepcopy(dataset.get('web_discovery_queries') or DEFAULT_WEB_DISCOVERY_QUERIES_V2)
    custom_el = [kw for kw in list(dataset.get('web_discovery_custom_keywords_el') or []) if str(kw).strip()]
    custom_en = [kw for kw in list(dataset.get('web_discovery_custom_keywords_en') or []) if str(kw).strip()]
    if custom_el:
        extra = []
        for kw in custom_el:
            q = str(kw).strip()
            if q and 'site:.gr' not in q:
                q = f'site:.gr {q}'
            if q:
                extra.append(q)
        base_queries['el'] = list(dict.fromkeys(list(base_queries.get('el') or []) + extra))
    if custom_en:
        base_queries['en'] = list(dict.fromkeys(list(base_queries.get('en') or []) + [str(x).strip() for x in custom_en if str(x).strip()]))

    configured = _studio_filter_source_url_entries_en_el(dataset.get('source_urls') or [], enabled_en='en' in enabled_langs, enabled_el='el' in enabled_langs)
    existing_counts = {'en': 0, 'el': 0}
    for entry in configured:
        lang = str(entry.get('language') or _studio_infer_language_from_url(entry.get('url') or '')).lower()
        if lang in existing_counts:
            existing_counts[lang] += 1

    target_counts = {
        'en': max(0, int(dataset.get('web_discovery_target_count_en') or 0)),
        'el': max(0, int(dataset.get('web_discovery_target_count_el') or 0)),
    }
    results: list[dict[str, str]] = []
    seen: set[str] = {str(item.get('url') or '').lower() for item in configured}
    taken = {'en': 0, 'el': 0}
    for lang in enabled_langs:
        needed = max(0, target_counts.get(lang, 0) - existing_counts.get(lang, 0))
        if needed <= 0:
            continue
        for query in list(base_queries.get(lang) or []):
            if taken[lang] >= needed:
                break
            try:
                candidates = _studio_search_bing_rss(str(query), timeout_sec=timeout_sec)
            except Exception as exc:
                append_log(f"[collect] ! αποτυχία αναζήτησης web για '{query}': {exc}")
                continue
            for item in candidates:
                if taken[lang] >= needed:
                    break
                url = str(item.get('url') or '').strip()
                if not _studio_is_discovery_url_allowed_v2(url, excluded_domains=excluded_domains, language=lang):
                    continue
                key = url.lower()
                if key in seen:
                    continue
                seen.add(key)
                results.append({
                    'title': str(item.get('title') or url).strip() or url,
                    'url': url,
                    'language': lang,
                    'discovered_query': str(query),
                })
                taken[lang] += 1
    return results


_STUDIO_PREV_BUILD_RUNTIME_CONFIG_PAYLOAD = PipelineStudioGUI._build_runtime_config_payload

def _studio_build_runtime_config_payload_collect_ui(self) -> dict[str, Any]:
    config = _STUDIO_PREV_BUILD_RUNTIME_CONFIG_PAYLOAD(self)
    config = _studio_ensure_runtime_defaults(config)
    dataset = config.setdefault('dataset', {})
    enabled_en = bool(getattr(self, 'collect_enable_english_check', None).isChecked()) if getattr(self, 'collect_enable_english_check', None) is not None else True
    enabled_el = bool(getattr(self, 'collect_enable_greek_check', None).isChecked()) if getattr(self, 'collect_enable_greek_check', None) is not None else True
    dataset['web_discovery_enable_en'] = enabled_en
    dataset['web_discovery_enable_el'] = enabled_el
    dataset['web_discovery_languages'] = [lang for lang, enabled in [('en', enabled_en), ('el', enabled_el)] if enabled]
    dataset['web_discovery_target_count_en'] = int(getattr(self, 'collect_count_english_spin', None).value()) if getattr(self, 'collect_count_english_spin', None) is not None else 100
    dataset['web_discovery_target_count_el'] = int(getattr(self, 'collect_count_greek_spin', None).value()) if getattr(self, 'collect_count_greek_spin', None) is not None else 100
    dataset['web_discovery_custom_keywords_el'] = _studio_parse_lines_to_list(_studio_parse_text_widget(getattr(self, 'collect_greek_keywords_edit', None)))
    dataset['web_discovery_custom_keywords_en'] = _studio_parse_lines_to_list(_studio_parse_text_widget(getattr(self, 'collect_english_keywords_edit', None)))
    dataset['source_urls'] = _studio_collect_compose_source_urls_from_ui(self)
    dataset['source_files'] = _studio_collect_selected_file_lines(self)
    dataset['source_dirs'] = _studio_collect_selected_dir_lines(self) or [str(PROJECT_ROOT)]
    extensions_raw = _studio_parse_text_widget(getattr(self, 'collect_extensions_edit', None))
    ext_list = _studio_parse_lines_to_list(extensions_raw.replace(',', '\n'))
    cleaned_exts = []
    for ext in ext_list:
        piece = ext.strip()
        if not piece:
            continue
        if not piece.startswith('.'):
            piece = '.' + piece
        cleaned_exts.append(piece.lower())
    if cleaned_exts:
        dataset['source_extensions'] = cleaned_exts
    if getattr(self, 'collect_max_file_size_spin', None) is not None:
        dataset['max_file_size_bytes'] = int(self.collect_max_file_size_spin.value()) * 1024 * 1024
    return config


