class _StudioStopOnEventCriteria:
    def __init__(self, stop_event: threading.Event | None = None) -> None:
        self.stop_event = stop_event

    def __call__(self, input_ids, scores, **kwargs) -> bool:  # **kwargs: Transformers compat
        try:
            return bool(self.stop_event is not None and self.stop_event.is_set())
        except Exception:
            return False


def _studio_streaming_generate_text_v2(
    tokenizer: Any,
    model: Any,
    inputs: dict[str, Any],
    generation_kwargs: dict[str, Any],
    progress_callback: Callable[[str], None] | None = None,
    stop_event: threading.Event | None = None,
) -> str:
    import torch
    from transformers import TextIteratorStreamer
    try:
        from transformers import StoppingCriteriaList
    except Exception:
        StoppingCriteriaList = list  # type: ignore

    streamer = TextIteratorStreamer(tokenizer, skip_prompt=True, skip_special_tokens=True)
    call_kwargs = dict(inputs)
    call_kwargs.update(generation_kwargs)
    call_kwargs['streamer'] = streamer
    stop_criteria = _StudioStopOnEventCriteria(stop_event)
    existing_criteria = list(call_kwargs.get('stopping_criteria') or [])
    existing_criteria.append(stop_criteria)
    try:
        call_kwargs['stopping_criteria'] = StoppingCriteriaList(existing_criteria)
    except Exception:
        call_kwargs['stopping_criteria'] = existing_criteria

    generation_error: list[BaseException] = []

    def _generate() -> None:
        try:
            with torch.inference_mode():
                model.generate(**call_kwargs)
        except BaseException as exc:  # pragma: no cover
            generation_error.append(exc)

    thread = threading.Thread(target=_generate, daemon=True)
    thread.start()

    chunks: list[str] = []
    for piece in streamer:
        if stop_event is not None and stop_event.is_set() and not piece:
            break
        if piece:
            chunks.append(piece)
            _studio_stream_chunk(progress_callback, piece)
        if stop_event is not None and stop_event.is_set() and thread.is_alive() is False:
            break

    thread.join()
    if generation_error:
        raise generation_error[0]
    return ''.join(chunks).strip()


def _studio_chat_generate_worker_streaming_v2(
    model_dir: str,
    messages: list[dict[str, str]],
    generation_options: dict[str, Any],
    progress_callback: Callable[[str], None] | None = None,
    stop_event: threading.Event | None = None,
) -> dict[str, Any]:
    _studio_stream_status(progress_callback, 'Φόρτωση runtime και έναρξη παραγωγής...')
    tokenizer, model, info = get_cached_or_load_inference_runtime(Path(model_dir))
    prompt_text = build_chat_prompt(tokenizer, messages)
    inputs = tokenizer(prompt_text, return_tensors='pt')
    try:
        inputs = {k: v.to(getattr(model, 'device', 'cpu')) for k, v in inputs.items()}
    except Exception:
        pass
    max_new_tokens = int(generation_options.get('max_new_tokens') or 8192)
    temperature = float(generation_options.get('temperature') or 0.2)
    top_p = float(generation_options.get('top_p') or 0.95)
    top_k = int(generation_options.get('top_k') or 50)
    repetition_penalty = float(generation_options.get('repetition_penalty') or 1.05)
    do_sample = bool(generation_options.get('do_sample', True)) and temperature > 0.01
    generation_kwargs: dict[str, Any] = {
        'max_new_tokens': max_new_tokens,
        'do_sample': do_sample,
        'temperature': max(0.01, temperature) if do_sample else 1.0,
        'top_p': min(max(top_p, 0.05), 1.0),
        'top_k': max(0, top_k),
        'repetition_penalty': max(1.0, repetition_penalty),
    }
    pad_token_id = _studio_align_padding_for_generation(tokenizer, model)
    if pad_token_id is not None:
        generation_kwargs['pad_token_id'] = pad_token_id
    _studio_stream_status(progress_callback, 'Το μοντέλο απαντά σε realtime...')
    text = _studio_streaming_generate_text_v2(tokenizer, model, inputs, generation_kwargs, progress_callback=progress_callback, stop_event=stop_event)
    stopped = bool(stop_event is not None and stop_event.is_set())
    if not text:
        text = '(Η παραγωγή διακόπηκε από τον χρήστη.)' if stopped else '(Το μοντέλο δεν επέστρεψε κείμενο.)'
    _studio_stream_status(progress_callback, 'Η απάντηση διακόπηκε από τον χρήστη.' if stopped else 'Η απάντηση ολοκληρώθηκε.')
    return {
        'text': text,
        'resolved_model_dir': info.get('base_model_dir') or '',
        'note': ('Διακοπή από χρήστη' if stopped else (info.get('note') or '')),
        'from_cache': bool(info.get('from_cache')),
        'adapter_dir': info.get('adapter_dir') or '',
        'stopped': stopped,
    }


def _studio_inference_stream_worker_v2(
    model_dir: str,
    prompt: str,
    generation_options: dict[str, Any] | None = None,
    progress_callback: Callable[[str], None] | None = None,
    stop_event: threading.Event | None = None,
) -> dict[str, Any]:
    options = generation_options or {}
    _studio_stream_status(progress_callback, 'Φόρτωση runtime για δοκιμή μοντέλου...')
    tokenizer, model, info = get_cached_or_load_inference_runtime(Path(model_dir))
    prompt_text = build_chat_prompt(tokenizer, _studio_prompt_to_messages(prompt))
    inputs = _studio_prepare_inputs_for_generation(tokenizer, model, prompt_text)
    generation_kwargs = _studio_resolve_generation_kwargs(
        options,
        default_max_new_tokens=1024,
        default_temperature=0.2,
        default_top_p=0.95,
        default_top_k=50,
        default_repetition_penalty=1.05,
        default_do_sample=True,
    )
    pad_token_id = _studio_align_padding_for_generation(tokenizer, model)
    if pad_token_id is not None:
        generation_kwargs['pad_token_id'] = pad_token_id
    _studio_stream_status(progress_callback, 'Η δοκιμή παράγει απάντηση σε realtime...')
    text = _studio_streaming_generate_text_v2(tokenizer, model, inputs, generation_kwargs, progress_callback=progress_callback, stop_event=stop_event)
    stopped = bool(stop_event is not None and stop_event.is_set())
    if not text:
        text = '(Η δοκιμή διακόπηκε από τον χρήστη.)' if stopped else '(Το μοντέλο δεν επέστρεψε κείμενο.)'
    _studio_stream_status(progress_callback, 'Η δοκιμή διακόπηκε από τον χρήστη.' if stopped else 'Η δοκιμή ολοκληρώθηκε.')
    return {
        'text': text,
        'resolved_model_dir': info.get('base_model_dir') or str(model_dir),
        'note': ('Διακοπή από χρήστη' if stopped else (info.get('note') or '')),
        'from_cache': bool(info.get('from_cache')),
        'adapter_dir': info.get('adapter_dir') or '',
        'stopped': stopped,
    }


def _studio_chat_start_generation_realtime_buffered_with_stop(self) -> None:
    model_dir = self.model_dir_edit.text().strip()
    messages = self._build_generation_messages()
    options = self._current_generation_options()
    self._stream_pending_chunks = []
    self._stream_pending_statuses = []
    self._stream_pending_lock = threading.Lock()
    self._chat_stop_event = threading.Event()
    self._chat_render_min_interval_s = 0.30
    self._chat_stream_chars_since_render = 0
    self._chat_stream_last_visible_ts = 0.0
    self._chat_stream_min_chars_before_render = 72
    self._chat_stream_max_silence_s = 0.65
    self._chat_ensure_stream_timer()
    if not self._stream_flush_timer.isActive():
        self._stream_flush_timer.start()
    self._set_busy(True, 'Φόρτωση runtime και παραγωγή απάντησης...')
    self._messages.append({'role': 'assistant', 'content': '', 'streaming': True})
    _studio_chat_schedule_refresh(self, force=True)

    def _worker_fn(local_model_dir: str, local_messages: list[dict[str, str]], local_options: dict[str, Any], progress_callback: Callable[[str], None] | None = None) -> dict[str, Any]:
        _ = progress_callback
        return _studio_chat_generate_worker_streaming_v2(
            local_model_dir,
            local_messages,
            local_options,
            progress_callback=self._on_generation_progress,
            stop_event=self._chat_stop_event,
        )

    self._chat_thread = QThread(self)
    worker = BackgroundWorker(_worker_fn, model_dir, copy.deepcopy(messages), copy.deepcopy(options))
    self._chat_worker = worker
    worker.moveToThread(self._chat_thread)
    self._chat_thread.started.connect(worker.run)
    worker.finished.connect(self._on_generation_finished, Qt.QueuedConnection)
    worker.error.connect(self._on_generation_error, Qt.QueuedConnection)
    worker.finished.connect(self._chat_thread.quit, Qt.QueuedConnection)
    worker.error.connect(self._chat_thread.quit, Qt.QueuedConnection)
    self._chat_thread.finished.connect(self._clear_generation_thread, Qt.QueuedConnection)
    self._chat_thread.start()

def _studio_run_inference_realtime_buffered_with_stop(self, title: str = 'Inference') -> None:
    model_dir = self.infer_model_edit.text().strip()
    prompt = self.infer_prompt.toPlainText().strip()
    if not model_dir:
        QMessageBox.warning(self, APP_TITLE, 'Επίλεξε φάκελο μοντέλου για inference.')
        return
    if not prompt:
        QMessageBox.warning(self, APP_TITLE, 'Γράψε prompt για δοκιμή μοντέλου.')
        return
    if getattr(self, '_infer_thread', None) is not None:
        QMessageBox.information(self, APP_TITLE, 'Υπάρχει ήδη ενεργή δοκιμή μοντέλου.')
        return
    if getattr(self, '_current_process', None) is not None or getattr(self, '_job_thread', None) is not None:
        QMessageBox.information(self, APP_TITLE, 'Υπάρχει ήδη ενεργή εργασία. Περίμενε να ολοκληρωθεί πρώτα.')
        return
    if hasattr(self, 'infer_output'):
        self.infer_output.clear()
        self.infer_output.setPlainText('⏳ Φόρτωση runtime και έναρξη realtime απάντησης...\n\n')
    self._infer_stream_pending_chunks = []
    self._infer_pending_statuses = []
    self._infer_stream_lock = threading.Lock()
    self._infer_stop_event = threading.Event()
    self._ensure_inference_stream_timer()
    if not self._infer_stream_timer.isActive():
        self._infer_stream_timer.start()
    self._set_status_message(title)
    try:
        self._progress_begin(title, mode='background')
    except Exception:
        pass
    self.log(f'🚀 Εκκίνηση realtime δοκιμής μοντέλου: {model_dir}')
    _studio_stop_event_enabled(getattr(self, 'stop_infer_btn', None), True)

    def _worker_fn(local_model_dir: str, local_prompt: str, local_options: dict[str, Any] | None = None, progress_callback: Callable[[str], None] | None = None) -> dict[str, Any]:
        _ = progress_callback
        return _studio_inference_stream_worker_v2(
            local_model_dir,
            local_prompt,
            local_options,
            progress_callback=self._on_inference_progress,
            stop_event=self._infer_stop_event,
        )

    self._infer_thread = QThread(self)
    worker = BackgroundWorker(_worker_fn, model_dir, prompt, _studio_inference_current_options(self))
    self._infer_worker = worker
    worker.moveToThread(self._infer_thread)
    self._infer_thread.started.connect(worker.run)
    worker.finished.connect(self._on_inference_finished, Qt.QueuedConnection)
    worker.error.connect(self._on_inference_error, Qt.QueuedConnection)
    worker.finished.connect(self._infer_thread.quit, Qt.QueuedConnection)
    worker.error.connect(self._infer_thread.quit, Qt.QueuedConnection)
    self._infer_thread.finished.connect(self._clear_inference_thread, Qt.QueuedConnection)
    self._infer_thread.start()


