def _studio_chat_build_ui_with_stop(self) -> None:
    _studio_chat_build_ui_studio_style(self)
    # ── Προσθήκη κουμπιού Διακοπής στη γραμμή κουμπιών ──────────────────────
    try:
        self.stop_chat_btn = QPushButton('🛑  Διακοπή απάντησης')
        self.stop_chat_btn.setObjectName('DangerButton')
        self.stop_chat_btn.setMinimumHeight(38)
        self.stop_chat_btn.setMinimumWidth(0)
        self.stop_chat_btn.setSizePolicy(QSizePolicy.Minimum, QSizePolicy.Fixed)
        self.stop_chat_btn.setEnabled(False)
        self.stop_chat_btn.clicked.connect(self.stop_chat_generation)
        # Εισαγωγή αμέσως μετά το send_btn στη γραμμή κουμπιών του compose card
        send = getattr(self, 'send_btn', None)
        if send is not None:
            parent = send.parentWidget()
            if parent is not None and parent.layout() is not None:
                lay = parent.layout()
                idx = lay.indexOf(send)
                if idx >= 0:
                    lay.insertWidget(idx + 1, self.stop_chat_btn)
                else:
                    lay.insertWidget(0, self.stop_chat_btn)
    except Exception:
        pass
    # ── Προσθήκη κουμπιού Διακοπής στο sidebar ───────────────────────────────
    try:
        new_chat = getattr(self, '_sb_new_chat_btn', None)
        if new_chat is not None:
            sb_parent = new_chat.parentWidget()
            if sb_parent is not None and sb_parent.layout() is not None:
                sb_lay = sb_parent.layout()
                self._sb_stop_btn = QPushButton('🛑  Διακοπή')
                self._sb_stop_btn.setObjectName('DangerButton')
                self._sb_stop_btn.setMinimumHeight(38)
                self._sb_stop_btn.setMinimumWidth(0)
                self._sb_stop_btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                self._sb_stop_btn.setEnabled(False)
                self._sb_stop_btn.clicked.connect(self.stop_chat_generation)
                idx = sb_lay.indexOf(new_chat)
                sb_lay.insertWidget(idx + 1 if idx >= 0 else 0, self._sb_stop_btn)
    except Exception:
        pass


def _studio_ensure_runtime_defaults_v4(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults_v3(config)
    dataset = config.setdefault('dataset', {})
    dataset.setdefault('validate_source_completeness', True)
    dataset.setdefault('source_validation_min_chars_web', 1200)
    dataset.setdefault('source_validation_min_chars_file', 350)
    dataset.setdefault('source_validation_min_words_web', 160)
    dataset.setdefault('source_validation_min_words_file', 60)
    dataset.setdefault('source_validation_min_lines_web', 8)
    dataset.setdefault('source_validation_min_lines_file', 4)
    dataset.setdefault('source_validation_min_alpha_ratio', 0.42)
    dataset.setdefault('source_validation_min_unique_word_ratio', 0.10)
    dataset.setdefault('source_validation_max_short_line_ratio', 0.82)
    return config


def _studio_collect_word_tokens(text: str) -> list[str]:
    raw = re.findall(r"[A-Za-zΑ-ΩΆ-Ώα-ωά-ώ0-9_\-]{2,}", str(text or '').lower())
    return [tok for tok in raw if any(ch.isalpha() for ch in tok)]


def _studio_analyze_source_text(text: str) -> dict[str, Any]:
    raw = str(text or '')
    normalized = _studio_normalize_space(raw)
    lines = [ln.strip() for ln in raw.replace('\r\n', '\n').replace('\r', '\n').split('\n') if ln.strip()]
    tokens = _studio_collect_word_tokens(normalized)
    unique_tokens = set(tokens)
    non_space_chars = [ch for ch in normalized if not ch.isspace()]
    alpha_chars = [ch for ch in non_space_chars if ch.isalpha()]
    sentence_count = len(re.findall(r'[\.!\?;·…]+', normalized))
    short_lines = sum(1 for ln in lines if len(ln) < 40)
    avg_line_len = (sum(len(ln) for ln in lines) / len(lines)) if lines else 0.0
    alpha_ratio = (len(alpha_chars) / max(len(non_space_chars), 1)) if non_space_chars else 0.0
    unique_word_ratio = (len(unique_tokens) / max(len(tokens), 1)) if tokens else 0.0
    return {
        'char_count': len(normalized),
        'word_count': len(tokens),
        'line_count': len(lines),
        'sentence_count': sentence_count,
        'alpha_ratio': round(alpha_ratio, 4),
        'unique_word_ratio': round(unique_word_ratio, 4),
        'short_line_ratio': round(short_lines / max(len(lines), 1), 4) if lines else 1.0,
        'avg_line_len': round(avg_line_len, 2),
        'greek_ratio': round(_studio_greek_char_ratio(normalized), 4),
    }


def _studio_validate_source_completeness(
    text: str,
    *,
    dataset: dict[str, Any],
    source_kind: str,
    title: str = '',
    locator: str = '',
) -> dict[str, Any]:
    enabled = bool(dataset.get('validate_source_completeness', True))
    metrics = _studio_analyze_source_text(text)
    if not enabled:
        return {'complete': True, 'reason': '', 'metrics': metrics}

    min_chars = int(dataset.get('source_validation_min_chars_web' if source_kind == 'web' else 'source_validation_min_chars_file') or (1200 if source_kind == 'web' else 350))
    min_words = int(dataset.get('source_validation_min_words_web' if source_kind == 'web' else 'source_validation_min_words_file') or (160 if source_kind == 'web' else 60))
    min_lines = int(dataset.get('source_validation_min_lines_web' if source_kind == 'web' else 'source_validation_min_lines_file') or (8 if source_kind == 'web' else 4))
    min_alpha_ratio = float(dataset.get('source_validation_min_alpha_ratio') or 0.42)
    min_unique_word_ratio = float(dataset.get('source_validation_min_unique_word_ratio') or 0.10)
    max_short_line_ratio = float(dataset.get('source_validation_max_short_line_ratio') or 0.82)

    reasons: list[str] = []
    if metrics['char_count'] < min_chars:
        reasons.append(f"λίγοι χαρακτήρες ({metrics['char_count']} < {min_chars})")
    if metrics['word_count'] < min_words:
        reasons.append(f"λίγες λέξεις ({metrics['word_count']} < {min_words})")
    if metrics['line_count'] < min_lines and metrics['char_count'] < (min_chars * 2):
        reasons.append(f"λίγες γραμμές ({metrics['line_count']} < {min_lines})")
    if metrics['sentence_count'] < max(2, min_lines // 3) and metrics['char_count'] < (min_chars * 2):
        reasons.append('δείχνει αποσπασματικό ή μη συνεχές κείμενο')
    if metrics['alpha_ratio'] < min_alpha_ratio:
        reasons.append(f"πολύ μικρή αναλογία κανονικού κειμένου ({metrics['alpha_ratio']:.2f})")
    if metrics['word_count'] >= 40 and metrics['unique_word_ratio'] < min_unique_word_ratio:
        reasons.append(f"υπερβολικά επαναλαμβανόμενο κείμενο ({metrics['unique_word_ratio']:.2f})")
    if source_kind == 'web' and metrics['char_count'] < 5000 and metrics['short_line_ratio'] > max_short_line_ratio:
        reasons.append('μοιάζει με menu / boilerplate και όχι πλήρες άρθρο ή σελίδα')

    lower_title = f"{title} {locator}".lower()
    lower_text_head = _studio_normalize_space(str(text or '')).lower()[:2000]
    suspicious_markers = [
        '404', 'not found', 'page not found', 'access denied', 'forbidden', 'just a moment',
        'enable javascript', 'javascript required', 'sign in', 'log in', 'subscribe',
        'privacy policy', 'cookie policy', 'cookies', 'error', 'σφάλμα', 'δεν βρέθηκε',
        'απαγορεύεται', 'συνδεθείτε', 'πολιτική απορρήτου', 'cookies'
    ]
    suspicious_hits = sum(1 for marker in suspicious_markers if marker in lower_title or marker in lower_text_head)
    if suspicious_hits >= 2 and metrics['char_count'] < 4000:
        reasons.append('πιθανό error/login/cookie page αντί για πλήρες περιεχόμενο')

    complete = not reasons
    return {
        'complete': complete,
        'reason': '; '.join(reasons),
        'metrics': metrics,
    }


def collect_training_sources_v3(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults_v4(config)
    dataset = config.get('dataset', {})
    project_root = Path(config.get('project_root') or PROJECT_ROOT).resolve()
    collect_dir = Path(dataset.get('collect_dir') or (ARTIFACTS_DIR / '01_collect'))
    raw_dir = collect_dir / 'raw_sources'
    collect_dir.mkdir(parents=True, exist_ok=True)
    raw_dir.mkdir(parents=True, exist_ok=True)

    records: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    validation_report: list[dict[str, Any]] = []
    file_count = 0
    web_count = 0
    language_counts = {'en': 0, 'el': 0, 'mixed': 0}
    target_counts = {
        'en': max(0, int(dataset.get('web_discovery_target_count_en') or 0)),
        'el': max(0, int(dataset.get('web_discovery_target_count_el') or 0)),
    }
    allowed_langs = [lang for lang in ['en', 'el'] if bool(dataset.get(f'web_discovery_enable_{lang}', True))]
    require_language_match = bool(dataset.get('web_discovery_require_language_match', True))
    web_timeout_sec = max(5, int(dataset.get('web_discovery_timeout_sec') or 20))
    validation_rejections = {'file': 0, 'web': 0}

    for file_path in _studio_iter_collect_file_candidates(config):
        try:
            text = _studio_normalize_space(_studio_read_text_file(file_path))
            rel_path = str(file_path.resolve().relative_to(project_root)) if str(file_path.resolve()).startswith(str(project_root)) else str(file_path)
            validation = _studio_validate_source_completeness(text, dataset=dataset, source_kind='file', title=file_path.name, locator=rel_path)
            if not validation.get('complete'):
                validation_rejections['file'] += 1
                skipped.append({'path': str(file_path), 'reason': f"incomplete_source: {validation.get('reason')}", 'validation': validation.get('metrics', {})})
                validation_report.append({'kind': 'file', 'path': str(file_path), 'accepted': False, 'reason': validation.get('reason'), 'metrics': validation.get('metrics', {})})
                append_log(f"[collect] - παραλείφθηκε ελλιπές αρχείο: {rel_path} | {validation.get('reason')}")
                continue
            record_id = _studio_hash_text(rel_path + '|' + text[:500])
            record = {
                'id': f"file_{record_id[:16]}",
                'source_kind': 'file',
                'source_path': rel_path,
                'title': file_path.name,
                'text': text,
                'char_count': len(text),
                'sha1': _studio_hash_text(text),
                'validation': validation.get('metrics', {}),
            }
            records.append(record)
            validation_report.append({'kind': 'file', 'path': rel_path, 'accepted': True, 'reason': '', 'metrics': validation.get('metrics', {})})
            file_count += 1
            (raw_dir / f"{record['id']}.txt").write_text(text, encoding='utf-8')
            append_log(f"[collect] + αρχείο: {rel_path}")
        except Exception as exc:
            skipped.append({'path': str(file_path), 'reason': str(exc)})
            append_log(f"[collect] ! αποτυχία αρχείου: {file_path}")

    configured_web_entries = _studio_filter_source_url_entries_en_el(
        dataset.get('source_urls') or [],
        enabled_en='en' in allowed_langs,
        enabled_el='el' in allowed_langs,
    )
    discovered_web_entries: list[dict[str, Any]] = []
    if bool(dataset.get('auto_discover_web_sources', True)):
        discovered_web_entries = _studio_discover_web_sources(config)
        if discovered_web_entries:
            append_log(f"[collect] i βρέθηκαν {len(discovered_web_entries)} web πηγές από online αναζήτηση")
    merged_web_entries = _studio_merge_source_url_entries(configured_web_entries + discovered_web_entries)

    accepted_web_lang_counts = {'en': 0, 'el': 0}
    for index, entry in enumerate(merged_web_entries, start=1):
        url = str(entry.get('url') or '').strip()
        expected_language = str(entry.get('language') or _studio_infer_language_from_url(url)).strip().lower()
        if expected_language not in {'en', 'el'}:
            continue
        if expected_language not in allowed_langs:
            continue
        limit = target_counts.get(expected_language, 0)
        if limit > 0 and accepted_web_lang_counts.get(expected_language, 0) >= limit:
            continue
        try:
            fetched = _studio_fetch_web_text(url, timeout_sec=web_timeout_sec)
            text = fetched.get('text') or ''
            if len(text) < 50:
                raise RuntimeError('κενό ή πολύ μικρό περιεχόμενο')
            detected_language = _studio_guess_language(text)
            if expected_language == 'el' and not _studio_is_greek_gr_url(url):
                raise RuntimeError('η ελληνική πηγή δεν είναι σε .gr domain')
            if expected_language == 'en' and not _studio_is_english_url(url):
                raise RuntimeError('η αγγλική πηγή δεν ανήκει στις επιτρεπόμενες αγγλικές πηγές')
            if require_language_match:
                if expected_language == 'el' and detected_language not in {'el', 'mixed'}:
                    raise RuntimeError('η πηγή δεν φαίνεται να είναι ελληνική')
                if expected_language == 'en' and detected_language == 'el':
                    raise RuntimeError('η πηγή δεν φαίνεται να είναι αγγλική')
            title = str(entry.get('title') or fetched.get('title') or url).strip() or url
            validation = _studio_validate_source_completeness(text, dataset=dataset, source_kind='web', title=title, locator=url)
            if not validation.get('complete'):
                validation_rejections['web'] += 1
                skipped.append({
                    'url': url,
                    'reason': f"incomplete_source: {validation.get('reason')}",
                    'expected_language': expected_language,
                    'query': entry.get('discovered_query') or '',
                    'validation': validation.get('metrics', {}),
                })
                validation_report.append({'kind': 'web', 'url': url, 'accepted': False, 'reason': validation.get('reason'), 'metrics': validation.get('metrics', {}), 'language': expected_language})
                append_log(f"[collect] - παραλείφθηκε ελλιπής web πηγή: {title} | {validation.get('reason')}")
                continue
            record_id = _studio_hash_text(url + '|' + text[:500])
            record = {
                'id': f"web_{record_id[:16]}",
                'source_kind': 'web',
                'source_url': url,
                'title': title,
                'text': text,
                'char_count': len(text),
                'sha1': _studio_hash_text(text),
                'language': expected_language if expected_language in {'en', 'el'} else detected_language,
                'detected_language': detected_language,
                'discovered_query': entry.get('discovered_query') or '',
                'validation': validation.get('metrics', {}),
            }
            records.append(record)
            validation_report.append({'kind': 'web', 'url': url, 'accepted': True, 'reason': '', 'metrics': validation.get('metrics', {}), 'language': record['language']})
            web_count += 1
            accepted_web_lang_counts[expected_language] = accepted_web_lang_counts.get(expected_language, 0) + 1
            language_counts[record['language']] = language_counts.get(record['language'], 0) + 1
            (raw_dir / f"{record['id']}.txt").write_text(text, encoding='utf-8')
            if entry.get('discovered_query'):
                append_log(f"[collect] + web(discovery/{expected_language}): {title}")
            else:
                append_log(f"[collect] + web({expected_language}): {title}")
        except Exception as exc:
            skipped.append({
                'url': url,
                'reason': str(exc),
                'expected_language': expected_language,
                'query': entry.get('discovered_query') or '',
            })
            append_log(f"[collect] ! αποτυχία web πηγής: {url}")

    corpus_path = collect_dir / 'collected_corpus.jsonl'
    _studio_jsonl_dump(corpus_path, records)
    manifest = {
        'stage': 'collect',
        'status': 'completed' if records else 'empty',
        'records': len(records),
        'file_records': file_count,
        'web_records': web_count,
        'web_records_by_language': accepted_web_lang_counts,
        'skipped': len(skipped),
        'configured_web_sources': len(configured_web_entries),
        'discovered_web_sources': len(discovered_web_entries),
        'validation_enabled': bool(dataset.get('validate_source_completeness', True)),
        'validation_rejections': validation_rejections,
        'collect_dir': str(collect_dir.resolve()),
        'corpus_path': str(corpus_path.resolve()),
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    (collect_dir / 'collect_manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
    (collect_dir / 'skipped_files.json').write_text(json.dumps(skipped, ensure_ascii=False, indent=2), encoding='utf-8')
    (collect_dir / 'source_validation_report.json').write_text(json.dumps(validation_report, ensure_ascii=False, indent=2), encoding='utf-8')
    report_path = collect_dir / 'collect_report.json'
    report_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
    return manifest


# Activate patched symbols.
_studio_read_text_file = _studio_read_text_file_v2  # noqa: F811
