def _studio_chat_build_ui_studio_style(self) -> None:
    """
    Redesigned chat UI that is visually identical to the main application.
    Inherits the main QSS (LIGHT/DARK), uses the same GroupBox cards,
    Sidebar frame, gradient header, buttons and font — all from LIGHT_QSS/DARK_QSS.
    All functional widget attributes (model_dir_edit, chat_view, …) are preserved.
    """
    self._attachment_paths = []
    self._trained_entries  = []
    self.setMinimumSize(900, 680)
    self.setWindowTitle("💬  Chat Μοντέλου — LLM Training Studio")

    # ── Inherit host stylesheet so chat window is visually identical ───────────
    base_qss = LIGHT_QSS
    try:
        base_qss = self.host.styleSheet() or LIGHT_QSS
    except Exception:
        pass
    _dark = "background: #141c2b" in base_qss
    self.setStyleSheet(base_qss)
    self._chat_is_dark = _dark

    # Store palette factories so apply_theme can call them
    def _make_chat_palette(is_dark):
        if is_dark:
            return dict(
                bg="#0f1622", card_bg="#192437", border="#253650",
                txt="#c8d8ee", txt_sub="#7a9ec2", input_bg="#111d2e",
                bubble_u="#1a2d48", bubble_bu="#2a4168", bubble_a="#192437",
                bubble_ba="#253650", code_bg="#141e2e", code_brd="#2a3e58",
                sep_col="#243454", hdr_stop0="#1a3060", hdr_stop1="#2a50a0",
                status_bg="#111928",
            )
        return dict(
            bg="#eef2f6", card_bg="#f3f7fb", border="#c0cedd",
            txt="#23344d", txt_sub="#5b7698", input_bg="#f3f7fb",
            bubble_u="#eef5ff", bubble_bu="#cfe0f6", bubble_a="#f3f7fb",
            bubble_ba="#d7e2ee", code_bg="#f0f7ff", code_brd="#d7ecff",
            sep_col="#c4d4e4", hdr_stop0="#1e4080", hdr_stop1="#2d6bc4",
            status_bg="#dce8f4",
        )

    def _make_chat_qss(base, p):
        return base + f"""
        QMainWindow    {{ background: {p['bg']}; }}
        QTextBrowser#ChatTranscript {{
            background: {p['card_bg']}; color: {p['txt']};
            border: none; border-radius: 0; font-size: 14px;
        }}
        QTextEdit#ChatTranscript, QTextEdit#SystemPromptBox, QTextEdit#ChatInputBox {{
            background: {p['input_bg']}; color: {p['txt']};
            border: 1px solid {p['border']}; border-radius: 12px; padding: 8px;
            selection-background-color: {p['bubble_bu']}; font-size: 14px;
        }}
        QTreeWidget#ChatAttachmentsTree {{
            background: {p['input_bg']}; color: {p['txt']};
            border: 1px solid {p['border']}; border-radius: 12px;
        }}
        QLabel {{ background: transparent; color: {p['txt']}; }}
        QLabel#ChatStatus {{
            background: {p['status_bg']};
            border-top: 1px solid {p['border']};
            padding: 5px 14px; font-size: 12px; color: {p['txt_sub']};
            border-bottom-left-radius: 20px; border-bottom-right-radius: 20px;
        }}
        """

    self._chat_make_palette = _make_chat_palette
    self._chat_make_qss     = _make_chat_qss
    p = _make_chat_palette(_dark)
    self.setStyleSheet(_make_chat_qss(base_qss, p))

    _hdr0 = p['hdr_stop0']; _hdr1 = p['hdr_stop1']
    _sub  = p['txt_sub']
    _brd  = p['border']

    # ── Root: horizontal HBox (Sidebar | MainPanel) ────────────────────────────
    root_widget = QWidget(); root_widget.setObjectName("ChatRoot")
    root_layout = QHBoxLayout(root_widget)
    root_layout.setContentsMargins(0, 0, 0, 0)
    root_layout.setSpacing(0)

    # ════════════════════════════════════════════════════════════════════════════
    # SIDEBAR  (QFrame#Sidebar — matches main app's sidebar style from LIGHT_QSS)
    # ════════════════════════════════════════════════════════════════════════════
    sidebar = QFrame(); sidebar.setObjectName("Sidebar")
    sidebar.setFixedWidth(272)

    # Τυλίγουμε όλο το περιεχόμενο σε QScrollArea ώστε να μην στοιβάζεται
    # όταν το ύψος του παραθύρου δεν αρκεί.
    _sb_outer = QVBoxLayout(sidebar)
    _sb_outer.setContentsMargins(0, 0, 0, 0)
    _sb_outer.setSpacing(0)
    _sb_scroll = QScrollArea()
    _sb_scroll.setWidgetResizable(True)
    _sb_scroll.setFrameShape(QFrame.NoFrame)
    _sb_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
    _sb_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
    _sb_scroll.setStyleSheet(
        "QScrollArea{border:none;background:transparent;}"
        "QScrollBar:vertical{width:6px;margin:0;border-radius:3px;}"
        "QScrollBar::handle:vertical{border-radius:3px;min-height:20px;}"
    )
    _sb_content_widget = QWidget()
    _sb_outer.addWidget(_sb_scroll)

    sb_lay = QVBoxLayout(_sb_content_widget)
    sb_lay.setContentsMargins(14, 18, 14, 14)
    sb_lay.setSpacing(4)

    def _sep_line():
        f = QFrame(); f.setFrameShape(QFrame.HLine)
        return f

    def _sec_lbl(text):
        lbl = QLabel(text)
        lbl.setStyleSheet(
            "font-size:9px;font-weight:700;letter-spacing:1.2px;"
            "padding:4px 0 2px 0;opacity:0.65;"
        )
        return lbl

    def _sb_btn(label, slot, obj="SidebarButton", tip=""):
        btn = QPushButton(label); btn.setObjectName(obj)
        btn.setMinimumHeight(38); btn.setMinimumWidth(0)
        btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        if tip: btn.setToolTip(tip)
        btn.clicked.connect(slot); return btn

    # App logo / header
    logo_lbl = QLabel("🧠  Chat Studio")
    logo_lbl.setStyleSheet("font-size:15px;font-weight:700;padding:0;")
    self._sidebar_model_label = QLabel("Χωρίς μοντέλο")
    self._sidebar_model_label.setWordWrap(True)
    self._sidebar_model_label.setAlignment(Qt.AlignCenter)
    self._sidebar_model_label.setObjectName("HeroBadge")
    self._sidebar_model_label.setStyleSheet(
        "font-size:11px;font-weight:600;border-radius:10px;padding:5px 8px;"
    )
    sb_lay.addWidget(logo_lbl)
    sb_lay.addSpacing(4)
    sb_lay.addWidget(self._sidebar_model_label)
    sb_lay.addSpacing(8); sb_lay.addWidget(_sep_line()); sb_lay.addSpacing(6)

    # ── ΕΝΕΡΓΕΙΕΣ ────────────────────────────────────────────────────────────
    sb_lay.addWidget(_sec_lbl("ΕΝΕΡΓΕΙΕΣ"))
    self._sb_send_btn = _sb_btn(
        "🚀  Αποστολή", self.send_message, "PrimaryButton", "Ctrl+Enter"
    )
    sb_lay.addWidget(self._sb_send_btn)
    self._sb_regen_btn = _sb_btn(
        "🔄  Επαναδημιουργία", self.regenerate_last_answer,
        tip="Νέα απάντηση για το τελευταίο μήνυμα"
    )
    sb_lay.addWidget(self._sb_regen_btn)
    self._sb_new_chat_btn = _sb_btn(
        "✨  Νέα συνομιλία", self.clear_chat, tip="Καθαρίζει το ιστορικό"
    )
    sb_lay.addWidget(self._sb_new_chat_btn)
    sb_lay.addWidget(_sb_btn(
        "📋  Αντιγραφή τελευταίας", self.copy_last_answer,
        tip="Αντιγράφει την τελευταία απάντηση"
    ))
    sb_lay.addSpacing(8); sb_lay.addWidget(_sep_line()); sb_lay.addSpacing(6)

    # ── ΜΟΝΤΕΛΟ ──────────────────────────────────────────────────────────────
    sb_lay.addWidget(_sec_lbl("ΜΟΝΤΕΛΟ"))

    lib_row = QHBoxLayout(); lib_row.setSpacing(4)
    self.trained_model_combo = QComboBox()
    self.trained_model_combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
    self.trained_model_combo.setMinimumHeight(30)
    self.trained_model_combo.setToolTip("Τοπικά εκπαιδευμένα μοντέλα")
    lib_row.addWidget(self.trained_model_combo, 1)
    ref_btn = QPushButton("🔄"); ref_btn.setFixedSize(28, 28)
    ref_btn.setToolTip("Ανανέωση λίστας")
    ref_btn.clicked.connect(lambda: self.refresh_model_list())
    self.refresh_model_list_btn = ref_btn
    lib_row.addWidget(ref_btn)
    sb_lay.addLayout(lib_row)

    use_sel_btn = QPushButton("✓  Χρήση επιλεγμένου")
    use_sel_btn.setObjectName("PrimaryButton")
    use_sel_btn.setMinimumHeight(34); use_sel_btn.setMinimumWidth(0)
    use_sel_btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
    use_sel_btn.clicked.connect(self.use_selected_library_model)
    self.use_selected_model_btn = use_sel_btn
    sb_lay.addWidget(use_sel_btn)

    dir_row = QHBoxLayout(); dir_row.setSpacing(4)
    self.model_dir_edit = QLineEdit()
    self.model_dir_edit.setPlaceholderText("Path μοντέλου…")
    self.model_dir_edit.setMinimumHeight(30)
    dir_row.addWidget(self.model_dir_edit, 1)
    for icon, slot, tip in [
        ("📂", self.browse_model_dir,           "Επιλογή φακέλου"),
        ("📤", self.use_final_model,            "Τελευταίο export"),
        ("➡", self.use_current_main_selection, "Από καρτέλα δοκιμής"),
    ]:
        b = QPushButton(icon); b.setFixedSize(28, 28); b.setToolTip(tip)
        b.clicked.connect(slot); dir_row.addWidget(b)
    sb_lay.addLayout(dir_row)

    self.model_info_label = QLabel("Επίλεξε μοντέλο για να ξεκινήσεις.")
    self.model_info_label.setWordWrap(True)
    self.model_info_label.setStyleSheet(f"font-size:11px;color:{_sub};padding:2px 0;")
    sb_lay.addWidget(self.model_info_label)

    sb_lay.addWidget(_sb_btn("📁  Άνοιγμα φακέλου", self.open_model_folder,
                              tip="Άνοιγμα στον explorer"))
    sb_lay.addWidget(_sb_btn("🧹  Εκκαθάριση cache", self.clear_selected_model_cache,
                              tip="Εκ νέου φόρτωση μοντέλου"))
