    # ── ΡΥΘΜΙΣΕΙΣ (System prompt + gen params) ───────────────────────────────
    sb_lay.addWidget(_sec_lbl("ΡΥΘΜΙΣΕΙΣ"))

    sys_lbl = QLabel("System Prompt")
    sys_lbl.setStyleSheet("font-size:11px;font-weight:600;")
    sb_lay.addWidget(sys_lbl)
    self.system_prompt_edit = QTextEdit()
    self.system_prompt_edit.setObjectName("SystemPromptBox")
    self.system_prompt_edit.setPlaceholderText("System prompt (optional)...")
    self.system_prompt_edit.setMinimumHeight(80)
    self.system_prompt_edit.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
    self.system_prompt_edit.setPlainText(SYSTEM_PROMPT_DEFAULT_EN)
    sb_lay.addWidget(self.system_prompt_edit)

    hist_row = QHBoxLayout()
    hist_row.addWidget(QLabel("Ιστορικό (γύροι):"))
    self.history_turns_spin = QSpinBox()
    self.history_turns_spin.setRange(1, 50); self.history_turns_spin.setValue(12)
    self.history_turns_spin.setToolTip("Ζεύγη ερώτηση-απάντηση στη μνήμη")
    self.history_turns_spin.setFixedWidth(64)
    hist_row.addWidget(self.history_turns_spin); hist_row.addStretch()
    sb_lay.addLayout(hist_row)

    # Generation params — compact 2-column grid
    gen_group = QGroupBox("Παράμετροι generation")
    gen_group.setStyleSheet("QGroupBox{margin-top:18px;}")
    gen_grid = QGridLayout(gen_group)
    gen_grid.setContentsMargins(8, 20, 8, 8)
    gen_grid.setSpacing(4)
    param_rows = [
        ("max_new_tokens", "max_tokens",    "QSpinBox",      (16, 8192), 8192, 1,    "Max output tokens"),
        ("temperature",    "temperature",   "QDoubleSpinBox",(0.0, 2.0), 0.2,  0.05, "Τυχαιότητα"),
        ("top_p",          "top_p",         "QDoubleSpinBox",(0.05,1.0), 0.95, 0.05, "Nucleus sampling"),
        ("top_k",          "top_k",         "QSpinBox",      (0, 500),   50,   1,    "Top-k"),
        ("repetition_penalty","rep. penalty","QDoubleSpinBox",(1.0, 3.0),1.05, 0.05, "Repetition penalty"),
    ]
    for r, (attr, lbl, kind, rng, val, step, tip) in enumerate(param_rows):
        lw = QLabel(lbl); lw.setStyleSheet("font-size:11px;")
        gen_grid.addWidget(lw, r, 0)
        if kind == "QSpinBox":
            w = QSpinBox(); w.setRange(int(rng[0]), int(rng[1])); w.setValue(int(val))
        else:
            w = QDoubleSpinBox(); w.setRange(*rng)
            w.setSingleStep(step); w.setDecimals(2); w.setValue(float(val))
        w.setToolTip(tip); w.setMinimumHeight(26)
        setattr(self, f"{attr}_spin", w)
        gen_grid.addWidget(w, r, 1)
    gen_grid.setColumnStretch(1, 1)
    self.do_sample_check = QCheckBox("Sampling (do_sample)")
    self.do_sample_check.setChecked(True)
    gen_grid.addWidget(self.do_sample_check, len(param_rows), 0, 1, 2)
    sb_lay.addWidget(gen_group)
    sb_lay.addSpacing(8); sb_lay.addWidget(_sep_line()); sb_lay.addSpacing(6)

    # ── ΣΥΝΗΜΜΕΝΑ ────────────────────────────────────────────────────────────
    sb_lay.addWidget(_sec_lbl("ΣΥΝΗΜΜΈΝΑ"))
    self.attachments_tree = QTreeWidget()
    self.attachments_tree.setObjectName("ChatAttachmentsTree")
    self.attachments_tree.setHeaderLabels(["📄 Αρχείο", "📦 Μέγεθος"])
    self.attachments_tree.setRootIsDecorated(False)
    self.attachments_tree.setAlternatingRowColors(False)
    self.attachments_tree.setUniformRowHeights(True)
    self.attachments_tree.setMinimumHeight(60)
    self.attachments_tree.setMaximumHeight(100)
    self.attachments_tree.setFrameShape(QFrame.NoFrame)
    self.attachments_tree.setItemDelegate(
        SoftBlueGridItemDelegate(self.attachments_tree, "#d7ecff")
    )
    ah = self.attachments_tree.header()
    ah.setStretchLastSection(True)
    try:
        ah.setSectionResizeMode(0, QHeaderView.Stretch)
        ah.setSectionResizeMode(1, QHeaderView.ResizeToContents)
    except Exception:
        pass
    sb_lay.addWidget(self.attachments_tree)

    att_row = QHBoxLayout(); att_row.setSpacing(4)
    self.attach_files_btn = QPushButton("📎  Προσθήκη")
    self.attach_files_btn.clicked.connect(self.browse_attachments)
    self.remove_attachment_btn = QPushButton("✂")
    self.remove_attachment_btn.setToolTip("Αφαίρεση επιλεγμένου")
    self.remove_attachment_btn.clicked.connect(self.remove_selected_attachments)
    self.clear_attachments_btn = QPushButton("🗑")
    self.clear_attachments_btn.setObjectName("DangerButton")
    self.clear_attachments_btn.setToolTip("Καθαρισμός όλων")
    self.clear_attachments_btn.clicked.connect(self.clear_attachments)
    for btn in [self.attach_files_btn, self.remove_attachment_btn, self.clear_attachments_btn]:
        btn.setMinimumHeight(30); btn.setMinimumWidth(0)
        btn.setSizePolicy(QSizePolicy.Minimum, QSizePolicy.Fixed)
        att_row.addWidget(btn)
    att_row.addStretch()
    sb_lay.addLayout(att_row)
    self.attachment_info_label = QLabel("Συνημμένα: 0 αρχεία")
    self.attachment_info_label.setStyleSheet(f"font-size:11px;color:{_sub};")
    sb_lay.addWidget(self.attachment_info_label)
    sb_lay.addSpacing(8); sb_lay.addWidget(_sep_line()); sb_lay.addSpacing(6)

    # ── ΘΕΜΑ ─────────────────────────────────────────────────────────────────
    sb_lay.addWidget(_sec_lbl("ΘΕΜΑ"))
    theme_row = QHBoxLayout(); theme_row.setSpacing(4)
    for th_lbl, th_val in [("☀  Light", "light"), ("🌙  Dark", "dark")]:
        tb = QPushButton(th_lbl)
        tb.setMinimumHeight(34); tb.setMinimumWidth(0)
        tb.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        tb.clicked.connect(
            lambda _=None, v=th_val:
                self.host.apply_theme(v) if getattr(self, "host", None) else None
        )
        theme_row.addWidget(tb)
    sb_lay.addLayout(theme_row)

    sb_lay.addStretch(1)
    sb_lay.addWidget(_sep_line()); sb_lay.addSpacing(4)
    self._sidebar_status = QLabel("⏳ Έτοιμο.")
    self._sidebar_status.setWordWrap(True)
    self._sidebar_status.setStyleSheet(f"font-size:11px;color:{_sub};")
    sb_lay.addWidget(self._sidebar_status)
    _sb_scroll.setWidget(_sb_content_widget)
    root_layout.addWidget(sidebar)

    # ════════════════════════════════════════════════════════════════════════════
    # MAIN PANEL
    # ════════════════════════════════════════════════════════════════════════════
    main_panel = QFrame(); main_panel.setObjectName("ChatMainPanel")
    main_panel.setStyleSheet("QFrame#ChatMainPanel{border:none;}")
    main_lay = QVBoxLayout(main_panel)
    main_lay.setContentsMargins(0, 0, 0, 0)
    main_lay.setSpacing(0)

    # ── Gradient header (identical to main app hero gradient) ─────────────────
    header_frame = QFrame(); header_frame.setObjectName("ChatHeader")
    header_frame.setFixedHeight(60)
    header_frame.setStyleSheet(
        f"QFrame#ChatHeader{{background:qlineargradient(x1:0,y1:0,x2:1,y2:0,"
        f"stop:0 {_hdr0},stop:0.6 {_hdr1},stop:1 {_hdr0});border:none;}}"
        " QFrame#ChatHeader QLabel{background:transparent;}"
    )
    self._chat_header_frame = header_frame
    hdr_lay = QHBoxLayout(header_frame)
    hdr_lay.setContentsMargins(18, 0, 18, 0); hdr_lay.setSpacing(12)
    ic = QLabel("🧠"); ic.setStyleSheet("font-size:24px;"); ic.setFixedWidth(34)
    hdr_lay.addWidget(ic)
    hdr_t = QVBoxLayout(); hdr_t.setSpacing(0)
    t1 = QLabel("Chat Εκπαιδευμένου Μοντέλου")
    t1.setStyleSheet("color:#fff;font-size:15px;font-weight:700;")
    t2 = QLabel("Multi-turn · System prompt · Attachments · Realtime streaming")
    t2.setStyleSheet("color:rgba(255,255,255,0.65);font-size:11px;")
    hdr_t.addWidget(t1); hdr_t.addWidget(t2)
    hdr_lay.addLayout(hdr_t, 1)
    self._hdr_model_badge = QLabel("")
    self._hdr_model_badge.setStyleSheet(
        "background:rgba(255,255,255,0.18);color:#e8f4ff;"
        "border:1px solid rgba(255,255,255,0.30);border-radius:8px;"
        "padding:3px 12px;font-size:11px;font-weight:600;"
    )
    self._hdr_model_badge.hide()
    hdr_lay.addWidget(self._hdr_model_badge)
    main_lay.addWidget(header_frame)

    # ── Content area ──────────────────────────────────────────────────────────
    content_widget = QWidget()
    content_lay = QVBoxLayout(content_widget)
    content_lay.setContentsMargins(12, 10, 12, 10)
    content_lay.setSpacing(8)

    # ── Chat transcript card (GroupBox matching main app style) ───────────────
    chat_card = QGroupBox("💬  Συνομιλία")
    chat_card.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
    chat_card_lay = QVBoxLayout(chat_card)
    chat_card_lay.setContentsMargins(0, 22, 0, 0)
    chat_card_lay.setSpacing(0)

    self.chat_view = QTextEdit()
    self.chat_view.setObjectName("ChatTranscript")
    self.chat_view.setReadOnly(True)
    self.chat_view.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
    self.chat_view.setMinimumHeight(340)
    self.chat_view.setFrameShape(QFrame.NoFrame)
    self.chat_view.setStyleSheet("QTextEdit{border:none;border-radius:0;padding:12px;}")
    try:
        self.chat_view.document().setDocumentMargin(8)
        self.chat_view.setWordWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
        self.chat_view.document().setDefaultStyleSheet(
            "code, pre { font-family: 'Consolas','Cascadia Code','Courier New',monospace !important; }"
            "body { font-family: 'Segoe UI',Arial,sans-serif; }"
        )
    except Exception:
        pass
    # Token counter pill
    self._token_counter_lbl = QLabel("")
    self._token_counter_lbl.setObjectName("HeroBadge")
    self._token_counter_lbl.setStyleSheet(
        f"font-size:10px;color:{_sub};"
        f"background:{p['input_bg']};border:1px solid {_brd};"
        "border-radius:8px;padding:2px 8px;"
    )
    self._token_counter_lbl.hide()
    chat_card_lay.addWidget(self.chat_view, 1)
    # Status strip (matches main app's status bar style)
    self.chat_status_label = QLabel("⏳ Έτοιμο για συνομιλία.")
    self.chat_status_label.setObjectName("ChatStatus")
    self.chat_status_label.setWordWrap(True)
    chat_card_lay.addWidget(self.chat_status_label)
    content_lay.addWidget(chat_card, 1)

    # ── Compose card (GroupBox) ───────────────────────────────────────────────
    compose_card = QGroupBox("✏️  Μήνυμα")
    compose_card_lay = QVBoxLayout(compose_card)
    compose_card_lay.setContentsMargins(10, 24, 10, 10)
    compose_card_lay.setSpacing(6)

    self.input_edit = QTextEdit()
    self.input_edit.setObjectName("ChatInputBox")
    self.input_edit.setPlaceholderText(
        "Γράψε το μήνυμά σου…  (Ctrl+Enter = Αποστολή, Shift+Enter = νέα γραμμή)"
    )
    self.input_edit.setMinimumHeight(80)
    self.input_edit.setMaximumHeight(160)
    self.input_edit.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
    self.input_edit.setFrameShape(QFrame.NoFrame)
    try:
        QShortcut(QKeySequence("Ctrl+Return"), self.input_edit).activated.connect(
            self.send_message
        )
    except Exception:
        pass
    compose_card_lay.addWidget(self.input_edit)

    btn_row = QHBoxLayout(); btn_row.setSpacing(8)
    self.send_btn = QPushButton("🚀  Αποστολή")
    self.send_btn.setObjectName("PrimaryButton")
    self.send_btn.setToolTip("Αποστολή  [Ctrl+Enter]")
    self.send_btn.clicked.connect(self.send_message)
    self.send_btn.setMinimumHeight(38); self.send_btn.setMinimumWidth(130)

    self.regen_btn = QPushButton("🔄  Επανάληψη")
    self.regen_btn.setToolTip("Νέα απάντηση για το τελευταίο μήνυμα")
    self.regen_btn.clicked.connect(self.regenerate_last_answer)
    self.regen_btn.setMinimumHeight(38)

    self.new_chat_btn = QPushButton("✨  Νέο chat")
    self.new_chat_btn.setToolTip("Καθαρίζει το ιστορικό")
    self.new_chat_btn.clicked.connect(self.clear_chat)
    self.new_chat_btn.setMinimumHeight(38)

    self.copy_last_btn = QPushButton("📋  Αντιγραφή")
    self.copy_last_btn.setToolTip("Αντιγράφει την τελευταία απάντηση")
    self.copy_last_btn.clicked.connect(self.copy_last_answer)
    self.copy_last_btn.setMinimumHeight(38)

    _export_btn = QPushButton("💾  Εξαγωγή")
    _export_btn.setToolTip("Αποθηκεύει τη συνομιλία σε .txt")
    _export_btn.setMinimumHeight(38)
    def _do_export():
        try:
            path, _ = QFileDialog.getSaveFileName(
                self, "Αποθήκευση συνομιλίας",
                str(ARTIFACTS_DIR / "chat_export.txt"), "Text Files (*.txt)"
            )
            if path:
                lines = []
                for m in getattr(self, "_messages", []):
                    role = "Εσύ" if m.get("role") == "user" else "Μοντέλο"
                    lines.append(f"[{role}]\n{m.get('content','')}\n")
                Path(path).write_text("\n".join(lines), encoding="utf-8")
                self._set_status(f"✓ Εξαγωγή: {Path(path).name}")
        except Exception as exc:
            self._set_status(f"❌ {exc}")
    _export_btn.clicked.connect(_do_export)

    for btn in [self.send_btn, self.regen_btn, self.new_chat_btn,
                self.copy_last_btn, _export_btn]:
        btn.setMinimumWidth(0)
        btn.setSizePolicy(QSizePolicy.Minimum, QSizePolicy.Fixed)
        btn_row.addWidget(btn)
    btn_row.addStretch(1)

    self._char_counter_lbl = QLabel("")
    self._char_counter_lbl.setStyleSheet(f"font-size:11px;color:{_sub};")
    btn_row.addWidget(self._char_counter_lbl)
    try:
        def _upd():
            n = len(self.input_edit.toPlainText())
            self._char_counter_lbl.setText(f"{n} χαρ." if n > 0 else "")
        self.input_edit.textChanged.connect(_upd)
    except Exception:
        pass

    compose_card_lay.addLayout(btn_row)
    content_lay.addWidget(compose_card)

    main_lay.addWidget(content_widget, 1)
    root_layout.addWidget(main_panel, 1)
    self.setCentralWidget(root_widget)

    # ── Compatibility aliases for apply_theme ─────────────────────────────────
    self._chat_sidebar        = sidebar       # QFrame#Sidebar
    self._chat_header_frame   = header_frame  # gradient header
    self._chat_content_widget = content_widget
    self._chat_action_frame   = compose_card  # compose GroupBox (for border-top update)
    self._chat_dyn_seps       = []            # no manual HLine separators in new layout

    self.refresh_model_list()
    self._refresh_attachment_view()


