def _studio_default_seed_urls_v4(enabled_en: bool = True, enabled_el: bool = True) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    if enabled_en:
        entries.extend(copy.deepcopy(DEFAULT_ENGLISH_SOURCE_URLS_V3))
    if enabled_el:
        entries.extend(copy.deepcopy(DEFAULT_GREEK_SOURCE_URLS_V3))
    return _studio_merge_source_url_entries(entries)


_STUDIO_PREV_BUILD_RUNTIME_CONFIG_PAYLOAD_COLLECT_V2 = _studio_build_runtime_config_payload_collect_ui

def _studio_build_runtime_config_payload_collect_ui_v2(self) -> dict[str, Any]:
    config = _STUDIO_PREV_BUILD_RUNTIME_CONFIG_PAYLOAD_COLLECT_V2(self)
    config = _studio_ensure_runtime_defaults_v5(config)
    dataset = config.setdefault('dataset', {})
    enabled_en = bool(getattr(self, 'collect_enable_english_check', None).isChecked()) if getattr(self, 'collect_enable_english_check', None) is not None else True
    enabled_el = bool(getattr(self, 'collect_enable_greek_check', None).isChecked()) if getattr(self, 'collect_enable_greek_check', None) is not None else True
    dataset['web_discovery_enable_en'] = enabled_en
    dataset['web_discovery_enable_el'] = enabled_el
    dataset['web_discovery_languages'] = [lang for lang, enabled in [('en', enabled_en), ('el', enabled_el)] if enabled]
    dataset['web_discovery_target_count_en'] = int(getattr(self, 'collect_count_english_spin', None).value()) if getattr(self, 'collect_count_english_spin', None) is not None else 200
    dataset['web_discovery_target_count_el'] = int(getattr(self, 'collect_count_greek_spin', None).value()) if getattr(self, 'collect_count_greek_spin', None) is not None else 200
    dataset['auto_discover_web_sources'] = bool(getattr(self, 'collect_auto_discovery_check', None).isChecked()) if getattr(self, 'collect_auto_discovery_check', None) is not None else True
    preview_entries = list(getattr(self, '_collect_discovered_preview_entries', []) or [])
    if getattr(self, 'collect_use_preview_urls_check', None) is not None and self.collect_use_preview_urls_check.isChecked() and preview_entries:
        dataset['source_urls'] = _studio_filter_source_url_entries_en_el(
            list(dataset.get('source_urls') or []) + preview_entries,
            enabled_en=enabled_en,
            enabled_el=enabled_el,
        )
    return config


def _studio_collect_preview_discovery_worker(config: dict[str, Any], progress_callback: Callable[[str], None] | None = None) -> dict[str, Any]:
    cfg = _studio_ensure_runtime_defaults_v5(copy.deepcopy(config))
    dataset = cfg.setdefault('dataset', {})
    if progress_callback:
        progress_callback('Εκκίνηση online preview αναζήτησης πηγών...')
    entries = _studio_discover_web_sources_v2(cfg)
    if progress_callback:
        counts_preview = {'en': 0, 'el': 0}
        for entry in entries:
            lang = str(entry.get('language') or '').strip().lower()
            if lang in counts_preview:
                counts_preview[lang] += 1
        progress_callback(f"Βρέθηκαν preview πηγές: English={counts_preview.get('en', 0)} · Ελληνικά={counts_preview.get('el', 0)}")
    counts = {'en': 0, 'el': 0}
    for entry in entries:
        lang = str(entry.get('language') or '').strip().lower()
        if lang in counts:
            counts[lang] += 1
    return {
        'kind': 'collect_discovery_preview',
        'entries': entries,
        'counts': counts,
        'targets': {
            'en': int(dataset.get('web_discovery_target_count_en') or 0),
            'el': int(dataset.get('web_discovery_target_count_el') or 0),
        },
        'auto_discover': bool(dataset.get('auto_discover_web_sources', True)),
    }


def _studio_collect_clear_preview(self) -> None:
    self._collect_discovered_preview_entries = []
    tree = getattr(self, 'collect_discovery_tree', None)
    if tree is not None:
        tree.clear()
    label = getattr(self, 'collect_discovery_status_label', None)
    if label is not None:
        label.setText('Δεν υπάρχει ακόμη preview αναζήτησης πηγών.')


def _studio_collect_apply_preview_urls(self) -> None:
    preview_entries = list(getattr(self, '_collect_discovered_preview_entries', []) or [])
    if not preview_entries:
        QMessageBox.information(self, APP_TITLE, 'Δεν υπάρχουν preview URLs για προσθήκη.')
        return
    existing_lines = _studio_parse_lines_to_list(_studio_parse_text_widget(getattr(self, 'collect_manual_urls_edit', None)))
    manual_entries = [_studio_make_source_entry(url) for url in existing_lines]
    enabled_en = bool(getattr(self, 'collect_enable_english_check', None).isChecked()) if getattr(self, 'collect_enable_english_check', None) is not None else True
    enabled_el = bool(getattr(self, 'collect_enable_greek_check', None).isChecked()) if getattr(self, 'collect_enable_greek_check', None) is not None else True
    merged = _studio_filter_source_url_entries_en_el(manual_entries + preview_entries, enabled_en=enabled_en, enabled_el=enabled_el)
    _studio_set_text_widget_lines(getattr(self, 'collect_manual_urls_edit', None), [str(item.get('url') or '').strip() for item in merged if str(item.get('url') or '').strip()])
    QMessageBox.information(self, APP_TITLE, f'Προστέθηκαν/συγχωνεύθηκαν {len(preview_entries)} preview URLs στο πεδίο πρόσθετων URLs.')


def _studio_collect_render_preview_results(self, payload: dict[str, Any]) -> None:
    entries = list(payload.get('entries') or [])
    self._collect_discovered_preview_entries = entries
    tree = getattr(self, 'collect_discovery_tree', None)
    if tree is not None:
        tree.clear()
        for entry in entries:
            lang = str(entry.get('language') or '').strip().lower() or '-'
            title = str(entry.get('title') or entry.get('url') or '').strip()
            url = str(entry.get('url') or '').strip()
            query = str(entry.get('discovered_query') or '').strip()
            status = 'Θα ελεγχθεί για πληρότητα στο Collect'
            item = QTreeWidgetItem([
                'Ελληνικά' if lang == 'el' else 'English',
                title,
                url,
                query,
                status,
            ])
            tree.addTopLevelItem(item)
        for col in range(max(0, tree.columnCount() - 1)):
            try:
                tree.resizeColumnToContents(col)
            except Exception:
                pass
    label = getattr(self, 'collect_discovery_status_label', None)
    if label is not None:
        counts = payload.get('counts') or {}
        targets = payload.get('targets') or {}
        label.setText(
            f"Preview online αναζήτησης: English {counts.get('en', 0)}/{targets.get('en', 0)} · Ελληνικά {counts.get('el', 0)}/{targets.get('el', 0)} · "
            f"Όλες οι πηγές θα περάσουν έλεγχο πληρότητας πριν μπουν στο corpus."
        )
    btn = getattr(self, 'collect_apply_preview_btn', None)
    if btn is not None:
        btn.setEnabled(bool(entries))
    clear_btn = getattr(self, 'collect_clear_preview_btn', None)
    if clear_btn is not None:
        clear_btn.setEnabled(bool(entries))


def _studio_collect_preview_discovery(self) -> None:
    try:
        config = self._build_runtime_config_payload()
    except Exception as exc:
        QMessageBox.critical(self, APP_TITLE, str(exc))
        return
    btn = getattr(self, 'collect_preview_btn', None)
    if btn is not None:
        btn.setEnabled(False)
    self.progress.setRange(0, 100)

    self.progress.setValue(3)
    self._set_status_message('Αναζήτηση online πηγών Collect...')
    self.log('🔎 Εκκίνηση preview αναζήτησης online πηγών για Collect...')

    def _on_success(result: object) -> None:
        if btn is not None:
            btn.setEnabled(True)
        self.progress.setRange(0, 100)
        self.progress.setValue(100)
        if isinstance(result, dict) and result.get('kind') == 'collect_discovery_preview':
            self._render_collect_preview_results(result)
            counts = result.get('counts') or {}
            self.log(f"✓ Preview πηγών: English={counts.get('en', 0)} · Ελληνικά={counts.get('el', 0)}")

    def _on_error(_message: str) -> None:
        if btn is not None:
            btn.setEnabled(True)
        self.progress.setRange(0, 100)
        self.progress.setValue(0)

    self._run_background(_studio_collect_preview_discovery_worker, config, on_success=_on_success, on_error=_on_error)


