def _studio_ensure_runtime_defaults_v5(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults_v4(config)
    dataset = config.setdefault('dataset', {})
    for key in ('web_discovery_target_count_en', 'web_discovery_target_count_el'):
        try:
            current_value = int(dataset.get(key))
        except Exception:
            current_value = 0
        if current_value in (0, 100):
            dataset[key] = 200
    dataset.setdefault('auto_discover_web_sources', True)
    dataset['web_discovery_queries'] = copy.deepcopy(dataset.get('web_discovery_queries') or DEFAULT_WEB_DISCOVERY_QUERIES_V3)
    dataset['web_discovery_excluded_domains'] = list(dict.fromkeys(list(dataset.get('web_discovery_excluded_domains') or []) + [
        'bing.com', 'google.com', 'duckduckgo.com', 'yahoo.com', 'baidu.com', 'zhihu.com', 'bilibili.com', 'aliyun.com',
        'weibo.com', 'facebook.com', 'instagram.com', 'x.com', 'twitter.com',
    ]))
    enabled_en = bool(dataset.get('web_discovery_enable_en', True))
    enabled_el = bool(dataset.get('web_discovery_enable_el', True))
    curated = _studio_default_seed_urls_v4(enabled_en=enabled_en, enabled_el=enabled_el)
    dataset['source_urls'] = _studio_filter_source_url_entries_en_el(curated + list(dataset.get('source_urls') or []), enabled_en=enabled_en, enabled_el=enabled_el)
    return config


def collect_training_sources_v4(config: dict[str, Any]) -> dict[str, Any]:
    return collect_training_sources_v3(_studio_ensure_runtime_defaults_v5(copy.deepcopy(config)))


