# ---- Fix: robust Greek (.gr) discovery preview with fallback seeds ----
def _studio_collect_seed_preview_entries(config: dict[str, Any], language: str, limit: int = 25) -> list[dict[str, Any]]:
    cfg = _studio_ensure_runtime_defaults_v5(copy.deepcopy(config))
    dataset = cfg.setdefault('dataset', {})
    lang = str(language or '').strip().lower()
    enabled_en = bool(dataset.get('web_discovery_enable_en', True))
    enabled_el = bool(dataset.get('web_discovery_enable_el', True))
    configured = _studio_filter_source_url_entries_en_el(
        list(dataset.get('source_urls') or []),
        enabled_en=enabled_en,
        enabled_el=enabled_el,
    )
    if lang == 'el':
        pool = list(DEFAULT_GREEK_SOURCE_URLS_V3) + configured
    elif lang == 'en':
        pool = list(DEFAULT_ENGLISH_SOURCE_URLS_V3) + configured
    else:
        pool = configured
    merged = _studio_merge_source_url_entries(pool)
    results: list[dict[str, Any]] = []
    seen: set[str] = set()
    for entry in merged:
        url = str(entry.get('url') or '').strip()
        if not url:
            continue
        detected_lang = str(entry.get('language') or _studio_infer_language_from_url(url)).strip().lower()
        if detected_lang != lang:
            continue
        key = url.lower()
        if key in seen:
            continue
        seen.add(key)
        item = dict(entry)
        item['language'] = lang
        item['discovery_source'] = 'seed_fallback'
        item.setdefault('discovered_query', '')
        results.append(item)
        if len(results) >= max(1, int(limit or 25)):
            break
    return results


def _studio_build_discovery_queries_v4(config: dict[str, Any], language: str) -> list[str]:
    cfg = _studio_ensure_runtime_defaults_v5(copy.deepcopy(config))
    dataset = cfg.setdefault('dataset', {})
    lang = str(language or '').strip().lower()
    base_queries = copy.deepcopy(dataset.get('web_discovery_queries') or DEFAULT_WEB_DISCOVERY_QUERIES_V3)
    queries = [str(q).strip() for q in list(base_queries.get(lang) or []) if str(q).strip()]
    if lang == 'el':
        custom = [str(kw).strip() for kw in list(dataset.get('web_discovery_custom_keywords_el') or []) if str(kw).strip()]
        for kw in custom:
            if 'site:.gr' not in kw and 'site:' not in kw:
                queries.append(f'site:.gr {kw}')
            queries.append(kw)
        greek_domains: list[str] = []
        for entry in list(DEFAULT_GREEK_SOURCE_URLS_V3) + list(dataset.get('source_urls') or []):
            if isinstance(entry, dict):
                domain = _studio_url_domain(str(entry.get('url') or ''))
            else:
                domain = _studio_url_domain(str(entry or ''))
            if domain.endswith('.gr') and domain not in greek_domains:
                greek_domains.append(domain)
        for domain in greek_domains[:40]:
            for kw in (
                'Python',
                'τεχνητή νοημοσύνη',
                'μηχανική μάθηση',
                'βαθιά μάθηση',
                'νευρωνικά δίκτυα',
                'μεγάλα γλωσσικά μοντέλα',
                'εκπαίδευση μοντέλων llm',
                'αξιολόγηση μοντέλων llm',
                'transformers Python',
                'μάθημα Python',
            ):
                queries.append(f'site:{domain} {kw}')
    elif lang == 'en':
        custom = [str(kw).strip() for kw in list(dataset.get('web_discovery_custom_keywords_en') or []) if str(kw).strip()]
        queries.extend(custom)
        english_domains: list[str] = []
        for entry in list(DEFAULT_ENGLISH_SOURCE_URLS_V3) + list(dataset.get('source_urls') or []):
            if isinstance(entry, dict):
                domain = _studio_url_domain(str(entry.get('url') or ''))
            else:
                domain = _studio_url_domain(str(entry or ''))
            if domain and not domain.endswith('.gr') and not domain.endswith('.cn') and domain not in english_domains:
                english_domains.append(domain)
        for domain in english_domains[:40]:
            for kw in (
                'Python tutorial',
                'machine learning',
                'deep learning',
                'LLM training',
                'LLM evaluation',
                'transformers',
                'fine tuning',
                'RAG Python',
            ):
                queries.append(f'site:{domain} {kw}')
    deduped: list[str] = []
    seen: set[str] = set()
    for query in queries:
        key = query.lower()
        if key in seen:
            continue
        seen.add(key)
        deduped.append(query)
    return deduped


def _studio_discover_web_sources_v3(config: dict[str, Any]) -> list[dict[str, str]]:
    config = _studio_ensure_runtime_defaults_v5(copy.deepcopy(config))
    dataset = config.get('dataset', {})
    if not bool(dataset.get('auto_discover_web_sources', True)):
        return []
    enabled_langs = [lang for lang in ['en', 'el'] if bool(dataset.get(f'web_discovery_enable_{lang}', True))]
    timeout_sec = max(5, int(dataset.get('web_discovery_timeout_sec') or 15))
    excluded_domains = [str(x).strip().lower() for x in list(dataset.get('web_discovery_excluded_domains') or []) if str(x).strip()]

    preview_ignore_existing = bool(dataset.get('web_discovery_preview_ignore_existing', False))
    configured = [] if preview_ignore_existing else _studio_filter_source_url_entries_en_el(
        dataset.get('source_urls') or [],
        enabled_en='en' in enabled_langs,
        enabled_el='el' in enabled_langs,
    )
    existing_counts = {'en': 0, 'el': 0}
    for entry in configured:
        lang = str(entry.get('language') or _studio_infer_language_from_url(entry.get('url') or '')).lower()
        if lang in existing_counts:
            existing_counts[lang] += 1

    target_counts = {
        'en': max(0, int(dataset.get('web_discovery_target_count_en') or 0)),
        'el': max(0, int(dataset.get('web_discovery_target_count_el') or 0)),
    }
    results: list[dict[str, str]] = []
    seen_result_urls: set[str] = set()
    taken = {'en': 0, 'el': 0}

    for lang in enabled_langs:
        needed = max(0, target_counts.get(lang, 0) - existing_counts.get(lang, 0))
        if needed <= 0:
            continue
        queries = _studio_build_discovery_queries_v4(config, lang)
        for query in queries:
            if taken[lang] >= needed:
                break
            try:
                candidates = _studio_search_bing_rss(str(query), timeout_sec=timeout_sec)
            except Exception as exc:
                append_log(f"[collect] ! αποτυχία αναζήτησης web για '{query}': {exc}")
                continue
            for item in candidates:
                if taken[lang] >= needed:
                    break
                url = str(item.get('url') or '').strip()
                if not _studio_is_discovery_url_allowed_v2(url, excluded_domains=excluded_domains, language=lang):
                    continue
                key = url.lower()
                if key in seen_result_urls:
                    continue
                seen_result_urls.add(key)
                results.append({
                    'title': str(item.get('title') or url).strip() or url,
                    'url': url,
                    'language': lang,
                    'discovered_query': str(query),
                    'discovery_source': 'search',
                })
                taken[lang] += 1

        if taken[lang] == 0:
            fallback_limit = max(1, min(int(target_counts.get(lang, 0) or 0), 50))
            for entry in _studio_collect_seed_preview_entries(config, lang, limit=fallback_limit):
                url = str(entry.get('url') or '').strip()
                key = url.lower()
                if not url or key in seen_result_urls:
                    continue
                seen_result_urls.add(key)
                item = dict(entry)
                item['language'] = lang
                item['discovery_source'] = 'seed_fallback'
                item.setdefault('discovered_query', '')
                results.append(item)
                taken[lang] += 1
    return results


def _studio_collect_preview_discovery_worker_v2(config: dict[str, Any], progress_callback: Callable[[str], None] | None = None) -> dict[str, Any]:
    cfg = _studio_ensure_runtime_defaults_v5(copy.deepcopy(config))
    dataset = cfg.setdefault('dataset', {})
    if progress_callback:
        progress_callback('Εκκίνηση online preview αναζήτησης πηγών...')
    entries = _studio_discover_web_sources_v3(cfg)
    counts = {'en': 0, 'el': 0}
    sources = {'search': 0, 'seed_fallback': 0}
    for entry in entries:
        lang = str(entry.get('language') or '').strip().lower()
        if lang in counts:
            counts[lang] += 1
        src = str(entry.get('discovery_source') or '').strip().lower()
        if src in sources:
            sources[src] += 1
    if progress_callback:
        progress_callback(
            f"Βρέθηκαν preview πηγές: English={counts.get('en', 0)} · Ελληνικά={counts.get('el', 0)} · online={sources.get('search', 0)} · fallback={sources.get('seed_fallback', 0)}"
        )
    return {
        'kind': 'collect_discovery_preview',
        'entries': entries,
        'counts': counts,
        'targets': {
            'en': int(dataset.get('web_discovery_target_count_en') or 0),
            'el': int(dataset.get('web_discovery_target_count_el') or 0),
        },
        'source_breakdown': sources,
        'auto_discover': bool(dataset.get('auto_discover_web_sources', True)),
    }


def _studio_collect_render_preview_results_v2(self, payload: dict[str, Any]) -> None:
    entries = list(payload.get('entries') or [])
    self._collect_discovered_preview_entries = entries
    tree = getattr(self, 'collect_discovery_tree', None)
    if tree is not None:
        tree.clear()
        for entry in entries:
            lang = str(entry.get('language') or '').strip().lower() or '-'
            title = str(entry.get('title') or entry.get('url') or '').strip()
            url = str(entry.get('url') or '').strip()
            query = str(entry.get('discovered_query') or '').strip()
            source = str(entry.get('discovery_source') or '').strip().lower()
            if source == 'seed_fallback':
                status = 'Fallback από έτοιμες έγκυρες πηγές · θα ελεγχθεί στο Collect'
                if not query:
                    query = 'curated seed fallback'
            else:
                status = 'Βρέθηκε online · θα ελεγχθεί για πληρότητα στο Collect'
            item = QTreeWidgetItem([
                'Ελληνικά' if lang == 'el' else 'English',
                title,
                url,
                query,
                status,
            ])
            tree.addTopLevelItem(item)
        for col in range(max(0, tree.columnCount() - 1)):
            try:
                tree.resizeColumnToContents(col)
            except Exception:
                pass
    label = getattr(self, 'collect_discovery_status_label', None)
    if label is not None:
        counts = payload.get('counts') or {}
        targets = payload.get('targets') or {}
        src = payload.get('source_breakdown') or {}
        label.setText(
            f"Preview online αναζήτησης: English {counts.get('en', 0)}/{targets.get('en', 0)} · Ελληνικά {counts.get('el', 0)}/{targets.get('el', 0)} · "
            f"Online ευρήματα: {src.get('search', 0)} · fallback έγκυρων seeds: {src.get('seed_fallback', 0)} · "
            f"Όλες οι πηγές θα περάσουν έλεγχο πληρότητας πριν μπουν στο corpus."
        )
    btn = getattr(self, 'collect_apply_preview_btn', None)
    if btn is not None:
        btn.setEnabled(bool(entries))
    clear_btn = getattr(self, 'collect_clear_preview_btn', None)
    if clear_btn is not None:
        clear_btn.setEnabled(bool(entries))


# Activate the newest Greek-discovery preview patch.
_studio_discover_web_sources = _studio_discover_web_sources_v3
_studio_collect_preview_discovery_worker = _studio_collect_preview_discovery_worker_v2  # noqa: F811
PipelineStudioGUI._render_collect_preview_results = _studio_collect_render_preview_results_v2
collect_training_sources = collect_training_sources_v4


# ---- Patch: stronger EN/EL discovery relevance, selectable preview sources, robust English-only fallback ----
from html import unescape as _html_unescape_collect_patch
from urllib.request import Request as _CollectPatchRequest, urlopen as _collect_patch_urlopen


def _studio_collect_normalize_keyword(text: str) -> str:
    return ' '.join(str(text or '').strip().lower().replace('/', ' ').split())


def _studio_collect_keyword_sets(config: dict[str, Any], language: str) -> list[str]:
    cfg = _studio_ensure_runtime_defaults_v5(copy.deepcopy(config))
    dataset = cfg.setdefault('dataset', {})
    lang = str(language or '').strip().lower()
    if lang == 'el':
        base = list(DEFAULT_VISIBLE_GREEK_KEYWORDS_V1)
        custom = list(dataset.get('web_discovery_custom_keywords_el') or [])
    else:
        base = list(DEFAULT_VISIBLE_ENGLISH_KEYWORDS_V1)
        custom = list(dataset.get('web_discovery_custom_keywords_en') or [])
    merged: list[str] = []
    seen: set[str] = set()
    for item in list(base) + list(custom):
        kw = _studio_collect_normalize_keyword(item)
        if not kw or kw in seen:
            continue
        seen.add(kw)
        merged.append(kw)
    return merged


def _studio_collect_fetch_page_title(url: str, timeout_sec: int = 5) -> str:
    url = str(url or '').strip()
    if not url:
        return ''
    try:
        req = _CollectPatchRequest(url, headers={
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/146.0 Safari/537.36',
            'Accept-Language': 'el,en;q=0.9',
        })
        with _collect_patch_urlopen(req, timeout=max(2, int(timeout_sec))) as resp:
            content_type = str(resp.headers.get('Content-Type') or '').lower()
            raw = resp.read(120000)
        if 'text/html' not in content_type and b'<html' not in raw[:5000].lower():
            return ''
        html_text = ''
        for enc in ('utf-8', 'utf-8-sig', 'cp1253', 'cp1252', 'latin-1'):
            try:
                html_text = raw.decode(enc)
                break
            except Exception:
                html_text = ''
        if not html_text:
            return ''
        m = re.search(r'<title[^>]*>(.*?)</title>', html_text, re.IGNORECASE | re.DOTALL)
        if not m:
            return ''
        title = _html_unescape_collect_patch(re.sub(r'\s+', ' ', m.group(1))).strip()
        return title[:300]
    except Exception:
        return ''


def _studio_collect_entry_relevance(entry: dict[str, Any], language: str, config: dict[str, Any]) -> tuple[int, str]:
    lang = str(language or '').strip().lower() or str(entry.get('language') or '').strip().lower() or 'en'
    title = str(entry.get('title') or '').strip()
    page_title = str(entry.get('page_title') or '').strip()
    query = str(entry.get('discovered_query') or '').strip()
    url = str(entry.get('url') or '').strip()
    combined = ' '.join([title, page_title, query, url]).lower()
    keywords = _studio_collect_keyword_sets(config, lang)
    score = 0
    matched: list[str] = []
    for kw in keywords:
        if kw and kw in combined:
            matched.append(kw)
            score += 12 if len(kw.split()) >= 2 else 7
    domain = _studio_url_domain(url)
    strong_domains = {
        'docs.python.org', 'docs.pytorch.org', 'pytorch.org', 'scikit-learn.org', 'tensorflow.org', 'keras.io',
        'huggingface.co', 'fastapi.tiangolo.com', 'docs.pytest.org', 'docs.pydantic.dev', 'lightning.ai',
        'mlflow.org', 'wandb.ai', 'csd.uoc.gr', 'uoa.gr', 'aueb.gr', 'uoi.gr', 'ionio.gr', 'unipi.gr',
        'auth.gr', 'uoc.gr', 'grnet.gr', 'gov.gr', 'openclass.org.gr', 'sch.gr'
    }
    if any(domain == d or domain.endswith('.' + d) for d in strong_domains):
        score += 18
    if lang == 'el' and domain.endswith('.gr'):
        score += 14
    if lang == 'en' and _studio_is_english_url(url):
        score += 10
    if any(tok in combined for tok in ('python code', 'source code', 'python script', 'κώδικας python', 'παραδείγματα κώδικα')):
        score += 14
    if any(tok in combined for tok in ('machine learning', 'deep learning', 'llm', 'transformers', 'rag', 'μηχανική μάθηση', 'βαθιά μάθηση', 'γλωσσικ')):
        score += 14
    noise_tokens = (
        'cookie', 'privacy policy', 'terms of use', 'login', 'sign in', 'αναζήτηση', 'επικοινωνία', 'calendar',
        'newsroom', 'ανακοινώσεις', 'γενικά νέα', 'home page', 'homepage', 'front page'
    )
    if any(tok in combined for tok in noise_tokens):
        score -= 25
    if page_title and page_title.lower() not in title.lower():
        score += 4
    reason = ', '.join(matched[:4]) if matched else ('page-title' if page_title else 'generic')
    return score, reason


def _studio_collect_seed_preview_entries_fill(config: dict[str, Any], lang: str, limit: int = 25, existing_urls: set[str] | None = None) -> list[dict[str, Any]]:
    existing = {str(x).strip().lower() for x in list(existing_urls or set()) if str(x).strip()}
    results = _studio_collect_seed_preview_entries(config, lang, limit=max(1, int(limit or 25) * 3))
    rescored: list[dict[str, Any]] = []
    for entry in results:
        url = str(entry.get('url') or '').strip()
        if not url or url.lower() in existing:
            continue
        score, reason = _studio_collect_entry_relevance(entry, lang, config)
        item = dict(entry)
        item['relevance_score'] = score
        item['relevance_reason'] = reason
        rescored.append(item)
    rescored.sort(key=lambda x: (-int(x.get('relevance_score') or 0), str(x.get('title') or '')))
    return rescored[:max(1, int(limit or 25))]


def _studio_discover_web_sources_v4(config: dict[str, Any]) -> list[dict[str, str]]:
    config = _studio_ensure_runtime_defaults_v5(copy.deepcopy(config))
    dataset = config.get('dataset', {})
    if not bool(dataset.get('auto_discover_web_sources', True)):
        return []
    enabled_langs = [lang for lang in ['en', 'el'] if bool(dataset.get(f'web_discovery_enable_{lang}', True))]
    timeout_sec = max(5, int(dataset.get('web_discovery_timeout_sec') or 15))
    excluded_domains = [str(x).strip().lower() for x in list(dataset.get('web_discovery_excluded_domains') or []) if str(x).strip()]
    preview_ignore_existing = bool(dataset.get('web_discovery_preview_ignore_existing', False))
    configured = [] if preview_ignore_existing else _studio_filter_source_url_entries_en_el(
        dataset.get('source_urls') or [],
        enabled_en='en' in enabled_langs,
        enabled_el='el' in enabled_langs,
    )
    existing_counts = {'en': 0, 'el': 0}
    for entry in configured:
        lang = str(entry.get('language') or _studio_infer_language_from_url(entry.get('url') or '')).lower()
        if lang in existing_counts:
            existing_counts[lang] += 1

    target_counts = {
        'en': max(0, int(dataset.get('web_discovery_target_count_en') or 0)),
        'el': max(0, int(dataset.get('web_discovery_target_count_el') or 0)),
    }
    final_results: list[dict[str, str]] = []
    global_seen: set[str] = set()

    for lang in enabled_langs:
        needed = max(0, target_counts.get(lang, 0) - existing_counts.get(lang, 0))
        if needed <= 0:
            continue
        lang_candidates: list[dict[str, Any]] = []
        local_seen: set[str] = set()
        title_fetch_budget = 30
        for query in _studio_build_discovery_queries_v4(config, lang):
            if len(lang_candidates) >= max(needed * 3, 40):
                break
            try:
                candidates = _studio_search_bing_rss(str(query), timeout_sec=timeout_sec)
            except Exception as exc:
                append_log(f"[collect] ! αποτυχία αναζήτησης web για '{query}': {exc}")
                continue
            for item in candidates:
                url = str(item.get('url') or '').strip()
                if not _studio_is_discovery_url_allowed_v2(url, excluded_domains=excluded_domains, language=lang):
                    continue
                key = url.lower()
                if not url or key in local_seen or key in global_seen:
                    continue
                candidate = {
                    'title': str(item.get('title') or url).strip() or url,
                    'url': url,
                    'language': lang,
                    'discovered_query': str(query),
                    'discovery_source': 'search',
                }
                if title_fetch_budget > 0:
                    page_title = _studio_collect_fetch_page_title(url, timeout_sec=min(timeout_sec, 5))
                    if page_title:
                        candidate['page_title'] = page_title
                        # prefer page title if it is more descriptive than feed title
                        if len(page_title) > len(candidate['title']) or candidate['title'].strip().lower() in {'home', 'index', url.lower()}:
                            candidate['title'] = page_title
                    title_fetch_budget -= 1
                score, reason = _studio_collect_entry_relevance(candidate, lang, config)
                candidate['relevance_score'] = score
                candidate['relevance_reason'] = reason
                local_seen.add(key)
                lang_candidates.append(candidate)
        lang_candidates.sort(key=lambda x: (-int(x.get('relevance_score') or 0), str(x.get('title') or '')))
        chosen: list[dict[str, Any]] = []
        for cand in lang_candidates:
            if len(chosen) >= needed:
                break
            # discard obviously irrelevant weak hits when we have better seeds/fallbacks available
            if int(cand.get('relevance_score') or 0) < 8:
                continue
            chosen.append(cand)
            global_seen.add(str(cand.get('url') or '').strip().lower())
        if len(chosen) < needed:
            for seed in _studio_collect_seed_preview_entries_fill(config, lang, limit=needed - len(chosen), existing_urls=global_seen):
                url = str(seed.get('url') or '').strip()
                key = url.lower()
                if not url or key in global_seen:
                    continue
                chosen.append(seed)
                global_seen.add(key)
                if len(chosen) >= needed:
                    break
        final_results.extend(chosen)
    return final_results


def _studio_collect_get_checked_preview_entries(self) -> list[dict[str, Any]]:
    tree = getattr(self, 'collect_discovery_tree', None)
    entries = list(getattr(self, '_collect_discovered_preview_entries', []) or [])
    if tree is None or not entries:
        return entries
    selected: list[dict[str, Any]] = []
    for i in range(tree.topLevelItemCount()):
        item = tree.topLevelItem(i)
        try:
            checked = item.checkState(0) == Qt.Checked
        except Exception:
            checked = True
        if checked and i < len(entries):
            selected.append(entries[i])
    return selected


def _studio_collect_set_preview_checks(self, language: str | None = None, checked: bool = True) -> None:
    tree = getattr(self, 'collect_discovery_tree', None)
    if tree is None:
        return
    lang_filter = str(language or '').strip().lower()
    state = Qt.Checked if checked else Qt.Unchecked
    for i in range(tree.topLevelItemCount()):
        item = tree.topLevelItem(i)
        entry_lang = 'el' if 'Ελλην' in str(item.text(0)) else 'en'
        if lang_filter and entry_lang != lang_filter:
            continue
        item.setCheckState(0, state)
    if hasattr(self, '_update_collect_preview_selection_status'):
        self._update_collect_preview_selection_status()


def _studio_collect_update_preview_selection_status(self) -> None:
    label = getattr(self, 'collect_discovery_status_label', None)
    tree = getattr(self, 'collect_discovery_tree', None)
    if label is None or tree is None:
        return
    total = tree.topLevelItemCount()
    checked = 0
    en_checked = 0
    el_checked = 0
    for i in range(total):
        item = tree.topLevelItem(i)
        if item.checkState(0) == Qt.Checked:
            checked += 1
            if 'Ελλην' in str(item.text(0)):
                el_checked += 1
            else:
                en_checked += 1
    base = getattr(self, '_collect_preview_base_status_text', '')
    extra = f" Επιλεγμένες τώρα: {checked}/{total} (English {en_checked}, Ελληνικά {el_checked})."
    label.setText((base or 'Preview αναζήτησης πηγών.') + extra)


def _studio_collect_apply_preview_urls_v2(self) -> None:
    preview_entries = self._collect_get_checked_preview_entries() if hasattr(self, '_collect_get_checked_preview_entries') else list(getattr(self, '_collect_discovered_preview_entries', []) or [])
    if not preview_entries:
        QMessageBox.information(self, APP_TITLE, 'Δεν υπάρχουν επιλεγμένα preview URLs για προσθήκη.')
        return
    existing_lines = _studio_parse_lines_to_list(_studio_parse_text_widget(getattr(self, 'collect_manual_urls_edit', None)))
    manual_entries = [_studio_make_source_entry(url) for url in existing_lines]
    enabled_en = bool(getattr(self, 'collect_enable_english_check', None).isChecked()) if getattr(self, 'collect_enable_english_check', None) is not None else True
    enabled_el = bool(getattr(self, 'collect_enable_greek_check', None).isChecked()) if getattr(self, 'collect_enable_greek_check', None) is not None else True
    merged = _studio_filter_source_url_entries_en_el(manual_entries + preview_entries, enabled_en=enabled_en, enabled_el=enabled_el)
    _studio_set_text_widget_lines(getattr(self, 'collect_manual_urls_edit', None), [str(item.get('url') or '').strip() for item in merged if str(item.get('url') or '').strip()])
    QMessageBox.information(self, APP_TITLE, f'Προστέθηκαν/συγχωνεύθηκαν {len(preview_entries)} επιλεγμένα preview URLs στο πεδίο πρόσθετων URLs.')


def _studio_build_runtime_config_payload_collect_ui_v3(self) -> dict[str, Any]:
    config = _STUDIO_PREV_BUILD_RUNTIME_CONFIG_PAYLOAD_COLLECT_V2(self)
    config = _studio_ensure_runtime_defaults_v5(config)
    dataset = config.setdefault('dataset', {})
    enabled_en = bool(getattr(self, 'collect_enable_english_check', None).isChecked()) if getattr(self, 'collect_enable_english_check', None) is not None else True
    enabled_el = bool(getattr(self, 'collect_enable_greek_check', None).isChecked()) if getattr(self, 'collect_enable_greek_check', None) is not None else True
    dataset['web_discovery_enable_en'] = enabled_en
    dataset['web_discovery_enable_el'] = enabled_el
    dataset['web_discovery_languages'] = [lang for lang, enabled in [('en', enabled_en), ('el', enabled_el)] if enabled]
    dataset['web_discovery_target_count_en'] = int(getattr(self, 'collect_count_english_spin', None).value()) if getattr(self, 'collect_count_english_spin', None) is not None else 200
    dataset['web_discovery_target_count_el'] = int(getattr(self, 'collect_count_greek_spin', None).value()) if getattr(self, 'collect_count_greek_spin', None) is not None else 200
    dataset['auto_discover_web_sources'] = bool(getattr(self, 'collect_auto_discovery_check', None).isChecked()) if getattr(self, 'collect_auto_discovery_check', None) is not None else True
    preview_entries = self._collect_get_checked_preview_entries() if hasattr(self, '_collect_get_checked_preview_entries') else list(getattr(self, '_collect_discovered_preview_entries', []) or [])
    if getattr(self, 'collect_use_preview_urls_check', None) is not None and self.collect_use_preview_urls_check.isChecked() and preview_entries:
        dataset['source_urls'] = _studio_filter_source_url_entries_en_el(
            list(dataset.get('source_urls') or []) + preview_entries,
            enabled_en=enabled_en,
            enabled_el=enabled_el,
        )
    return config


def _studio_collect_render_preview_results_v3(self, payload: dict[str, Any]) -> None:
    entries = list(payload.get('entries') or [])
    self._collect_discovered_preview_entries = entries
    tree = getattr(self, 'collect_discovery_tree', None)
    if tree is not None:
        try:
            tree.blockSignals(True)
        except Exception:
            pass
        tree.clear()
        for entry in entries:
            lang = str(entry.get('language') or '').strip().lower() or '-'
            title = str(entry.get('title') or entry.get('page_title') or entry.get('url') or '').strip()
            url = str(entry.get('url') or '').strip()
            query = str(entry.get('discovered_query') or '').strip()
            score = str(entry.get('relevance_score') or '')
            source = str(entry.get('discovery_source') or '').strip().lower()
            source_label = 'online' if source == 'search' else 'fallback'
            status = 'Πλήρες relevance από τίτλο/URL/query · θα γίνει και έλεγχος πληρότητας'
            item = QTreeWidgetItem([
                'Ελληνικά' if lang == 'el' else 'English',
                title,
                url,
                query,
                f'{source_label} · score {score}' if score else source_label,
            ])
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable | Qt.ItemIsSelectable | Qt.ItemIsEnabled)
            item.setCheckState(0, Qt.Checked)
            tooltip = status
            page_title = str(entry.get('page_title') or '').strip()
            reason = str(entry.get('relevance_reason') or '').strip()
            if page_title:
                tooltip += f'\nPage title: {page_title}'
            if reason:
                tooltip += f'\nRelevance: {reason}'
            for col in range(5):
                item.setToolTip(col, tooltip)
            tree.addTopLevelItem(item)
        try:
            tree.blockSignals(False)
        except Exception:
            pass
        for col in range(max(0, tree.columnCount() - 1)):
            try:
                tree.resizeColumnToContents(col)
            except Exception:
                pass
    counts = payload.get('counts') or {}
    targets = payload.get('targets') or {}
    src = payload.get('source_breakdown') or {}
    self._collect_preview_base_status_text = (
        f"Preview online αναζήτησης: English {counts.get('en', 0)}/{targets.get('en', 0)} · Ελληνικά {counts.get('el', 0)}/{targets.get('el', 0)} · "
        f"Online ευρήματα: {src.get('search', 0)} · fallback έγκυρων seeds: {src.get('seed_fallback', 0)} · "
        f"Οι πηγές βαθμολογήθηκαν με βάση τίτλο/URL/query και θα περάσουν έλεγχο πληρότητας πριν μπουν στο corpus."
    )
    if hasattr(self, '_update_collect_preview_selection_status'):
        self._update_collect_preview_selection_status()
    btn = getattr(self, 'collect_apply_preview_btn', None)
    if btn is not None:
        btn.setEnabled(bool(entries))
    clear_btn = getattr(self, 'collect_clear_preview_btn', None)
    if clear_btn is not None:
        clear_btn.setEnabled(bool(entries))


def _studio_collect_preview_discovery_worker_v3(config: dict[str, Any], progress_callback: Callable[[str], None] | None = None) -> dict[str, Any]:
    cfg = _studio_ensure_runtime_defaults_v5(copy.deepcopy(config))
    dataset = cfg.setdefault('dataset', {})
    dataset['web_discovery_preview_ignore_existing'] = True
    if progress_callback:
        progress_callback('Εκκίνηση online preview αναζήτησης πηγών με relevance από τίτλους και metadata...')
    entries = _studio_discover_web_sources_v4(cfg)
    counts = {'en': 0, 'el': 0}
    sources = {'search': 0, 'seed_fallback': 0}
    for entry in entries:
        lang = str(entry.get('language') or '').strip().lower()
        if lang in counts:
            counts[lang] += 1
        src = str(entry.get('discovery_source') or '').strip().lower()
        if src in sources:
            sources[src] += 1
    if progress_callback:
        progress_callback(f"Preview πηγών: English={counts.get('en', 0)} · Ελληνικά={counts.get('el', 0)} · online={sources.get('search', 0)} · fallback={sources.get('seed_fallback', 0)}")
    return {
        'kind': 'collect_discovery_preview',
        'entries': entries,
        'counts': counts,
        'targets': {
            'en': int(dataset.get('web_discovery_target_count_en') or 0),
            'el': int(dataset.get('web_discovery_target_count_el') or 0),
        },
        'source_breakdown': sources,
        'auto_discover': bool(dataset.get('auto_discover_web_sources', True)),
    }


def _studio_build_runtime_card_collect_sources_v4b(self, collect_lay):
    _STUDIO_PREV_BUILD_RUNTIME_CARD_COLLECT_V3(self)
    tree = getattr(self, 'collect_discovery_tree', None)
    if tree is not None:
        tree.setSelectionMode(QAbstractItemView.ExtendedSelection)
        tree.setAllColumnsShowFocus(True)
    preview_lay = tree.parentWidget().layout() if tree is not None and tree.parentWidget() is not None else None
    if preview_lay is not None and getattr(self, 'collect_preview_select_all_btn', None) is None:
        select_row = QHBoxLayout()
        self.collect_preview_select_all_btn = QPushButton('Επιλογή όλων')
        self.collect_preview_select_none_btn = QPushButton('Καμία επιλογή')
        self.collect_preview_select_en_btn = QPushButton('Μόνο English')
