# ---- Patch: in-app browser-style preview for discovered Collect links ----
from html import escape as _studio_collect_escape_html


def _studio_collect_find_preview_tree_item_by_url(self, url: str):
    tree = getattr(self, 'collect_discovery_tree', None)
    target = str(url or '').strip().lower()
    if tree is None or not target:
        return None
    for i in range(tree.topLevelItemCount()):
        item = tree.topLevelItem(i)
        try:
            candidate = str(item.text(2) or '').strip().lower()
        except Exception:
            candidate = ''
        if candidate == target:
            return item
    return None


def _studio_collect_mark_preview_url_kept(self, keep: bool) -> None:
    url = str(getattr(self, '_collect_link_preview_current_url', '') or '').strip()
    item = self._collect_find_preview_tree_item_by_url(url) if hasattr(self, '_collect_find_preview_tree_item_by_url') else None
    if item is None:
        QMessageBox.information(self, APP_TITLE, 'Δεν βρέθηκε αντίστοιχη πηγή στη λίστα preview.')
        return
    try:
        item.setCheckState(0, Qt.Checked if keep else Qt.Unchecked)
    except Exception:
        pass
    tree = getattr(self, 'collect_discovery_tree', None)
    if tree is not None:
        try:
            tree.setCurrentItem(item)
            item.setSelected(True)
        except Exception:
            pass
    if hasattr(self, '_update_collect_preview_selection_status'):
        self._update_collect_preview_selection_status()
    self.log(('✅ Κρατήθηκε' if keep else '🚫 Απορρίφθηκε') + f' η πηγή: {url}')


