def _studio_collect_preview_fetch_worker(url: str, progress_callback: Callable[[str], None] | None = None) -> dict[str, Any]:
    from urllib.request import Request, urlopen

    target_url = str(url or '').strip()
    if not target_url:
        raise ValueError('Δεν δόθηκε URL για προεπισκόπηση.')
    if progress_callback:
        progress_callback(f'Φόρτωση προεπισκόπησης: {target_url}')
    req = Request(target_url, headers={
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/146.0 Safari/537.36',
        'Accept-Language': 'el,en;q=0.9',
    })
    with urlopen(req, timeout=20) as resp:
        final_url = str(resp.geturl() or target_url)
        content_type = str(resp.headers.get('Content-Type') or '').lower()
        raw = resp.read(900000)
    if progress_callback:
        progress_callback(f'Λήφθηκαν {len(raw)} bytes για προεπισκόπηση από: {final_url}')

    charset = ''
    if 'charset=' in content_type:
        charset = content_type.split('charset=', 1)[1].split(';', 1)[0].strip()
    html = ''
    for enc in [charset, 'utf-8', 'utf-8-sig', 'cp1253', 'cp1252', 'latin-1']:
        enc = str(enc or '').strip()
        if not enc:
            continue
        try:
            html = raw.decode(enc)
            break
        except Exception:
            html = ''
    if not html:
        html = raw.decode('utf-8', errors='replace')

    title = ''
    try:
        m = re.search(r'<title[^>]*>(.*?)</title>', html, re.IGNORECASE | re.DOTALL)
        if m:
            title = ' '.join(m.group(1).replace('\n', ' ').replace('\r', ' ').split())[:300]
    except Exception:
        title = ''

    is_html = ('text/html' in content_type) or ('<html' in html[:5000].lower()) or ('<body' in html[:5000].lower())
    if not is_html:
        snippet = _studio_collect_escape_html(html[:12000])
        html = (
            '<html><body style="font-family:Segoe UI, Arial; padding:18px;">'
            '<h3>Δεν βρέθηκε κανονική HTML σελίδα για inline προεπισκόπηση</h3>'
            f'<p><b>URL:</b> {_studio_collect_escape_html(final_url)}</p>'
            f'<p><b>Content-Type:</b> {_studio_collect_escape_html(content_type or "unknown")}</p>'
            '<p>Παρουσιάζεται απόσπασμα του περιεχομένου. Μπορείς να ανοίξεις το link και εξωτερικά.</p>'
            f'<pre style="white-space:pre-wrap; background:#f7fbff; border:1px solid #d7ecff; padding:12px; border-radius:8px;">{snippet}</pre>'
            '</body></html>'
        )
    return {
        'kind': 'collect_link_preview',
        'url': target_url,
        'final_url': final_url,
        'title': title,
        'content_type': content_type,
        'html': html,
        'byte_count': len(raw),
    }


def _studio_collect_normalize_preview_url(raw_url: str) -> str:
    text = str(raw_url or '').strip()
    if not text:
        return ''
    try:
        qurl = QUrl.fromUserInput(text)
        normalized = str(qurl.toString() or '').strip()
        if normalized:
            return normalized
    except Exception:
        pass
    return text


def _studio_collect_render_browser_preview_payload(self, payload: dict[str, Any]) -> None:
    win = self._ensure_collect_browser_preview_window()
    browser = getattr(self, 'collect_link_preview_browser', None)
    addr = getattr(self, 'collect_link_preview_address_edit', None)
    meta = getattr(self, 'collect_link_preview_meta_label', None)
    status = getattr(self, 'collect_link_preview_status_label', None)
    if browser is None or addr is None:
        return
    final_url = str(payload.get('final_url') or payload.get('url') or '').strip()
    title = str(payload.get('title') or '').strip()
    html = str(payload.get('html') or '')
    content_type = str(payload.get('content_type') or '').strip()
    byte_count = int(payload.get('byte_count') or 0)
    self._collect_link_preview_current_url = final_url
    addr.setText(final_url)
    try:
        browser.document().setBaseUrl(QUrl(final_url))
    except Exception:
        pass
    browser.setHtml(html)
    if meta is not None:
        meta.setText(
            f"<b>Τίτλος:</b> {_studio_collect_escape_html(title or '(χωρίς τίτλο)')} &nbsp;&nbsp; "
            f"<b>Τύπος:</b> {_studio_collect_escape_html(content_type or 'unknown')} &nbsp;&nbsp; "
            f"<b>Μέγεθος:</b> {byte_count} bytes"
        )
    if status is not None:
        status.setText('Η προεπισκόπηση φορτώθηκε. Τώρα μπορείς να αποφασίσεις αν θα κρατήσεις την πηγή.')
    win.show()
    win.raise_()
    win.activateWindow()


def _studio_collect_preview_link_in_browser_window(self, url: str) -> None:
    target_url = _studio_collect_normalize_preview_url(url)
    if not target_url:
        QMessageBox.information(self, APP_TITLE, 'Δεν υπάρχει URL για προεπισκόπηση.')
        return
    win = self._ensure_collect_browser_preview_window()
    status = getattr(self, 'collect_link_preview_status_label', None)
    browser = getattr(self, 'collect_link_preview_browser', None)
    addr = getattr(self, 'collect_link_preview_address_edit', None)
    if addr is not None:
        addr.setText(target_url)
    if browser is not None:
        browser.setHtml('<html><body style="font-family:Segoe UI, Arial; padding:18px;"><h3>Φόρτωση προεπισκόπησης...</h3><p>Γίνεται λήψη της σελίδας μέσα από την εφαρμογή.</p></body></html>')
    if status is not None:
        status.setText(f'Γίνεται φόρτωση: {target_url}')
    win.show()
    win.raise_()
    win.activateWindow()

    def _on_success(result: object) -> None:
        self.progress.setRange(0, 100)
        self.progress.setValue(100)
        if isinstance(result, dict) and result.get('kind') == 'collect_link_preview':
            self._render_collect_browser_preview_payload(result)
            self.log(f"✓ Φορτώθηκε προεπισκόπηση για: {result.get('final_url') or target_url}")

    def _on_error(message: str) -> None:
        self.progress.setRange(0, 100)
        self.progress.setValue(0)
        if status is not None:
            status.setText(f'Αποτυχία προεπισκόπησης: {message}')
        if browser is not None:
            browser.setHtml(
                '<html><body style="font-family:Segoe UI, Arial; padding:18px;">'
                '<h3>Αποτυχία φόρτωσης προεπισκόπησης</h3>'
                f'<p>{_studio_collect_escape_html(message)}</p>'
                f'<p><b>URL:</b> {_studio_collect_escape_html(target_url)}</p>'
                '</body></html>'
            )

    self.progress.setRange(0, 100)


    self.progress.setValue(3)
    self._set_status_message('Φόρτωση προεπισκόπησης link Collect...')
    self.log(f'🌐 Προεπισκόπηση link μέσα από την εφαρμογή: {target_url}')
    self._run_background(_studio_collect_preview_fetch_worker, target_url, on_success=_on_success, on_error=_on_error)


def _studio_collect_preview_selected_tree_link(self) -> None:
    tree = getattr(self, 'collect_discovery_tree', None)
    if tree is None:
        return
    item = tree.currentItem()
    if item is None:
        selected = tree.selectedItems()
        item = selected[0] if selected else None
    if item is None:
        QMessageBox.information(self, APP_TITLE, 'Επίλεξε πρώτα μία πηγή από το preview list.')
        return
    self.collect_preview_tree_item_in_browser(item, 0)


def _studio_collect_extract_tree_item_url(item) -> str:
    if item is None:
        return ''
    url = ''
    try:
        url = str(item.text(2) or '').strip()
    except Exception:
        url = ''
    if not url:
        try:
            entry = item.data(2, Qt.UserRole) or {}
            if isinstance(entry, dict):
                url = str(entry.get('url') or '').strip()
        except Exception:
            url = ''
    return _studio_collect_normalize_preview_url(url)


def _studio_collect_preview_tree_item_in_browser(self, item, _column: int = 0) -> None:
    url = _studio_collect_extract_tree_item_url(item)
    if not url:
        QMessageBox.information(self, APP_TITLE, 'Η επιλεγμένη γραμμή δεν έχει έγκυρο URL.')
        return
    self.collect_preview_link_in_browser_window(url)


def _studio_collect_open_tree_item_external(self, item, _column: int = 0) -> None:
    url = _studio_collect_extract_tree_item_url(item)
