def _studio_ensure_runtime_defaults_collect_local_only(config: dict[str, Any]) -> dict[str, Any]:
    config = _STUDIO_PREV_ENSURE_RUNTIME_DEFAULTS_LOCAL_ONLY(config)
    dataset = config.setdefault('dataset', {})
    dataset['source_urls'] = []
    dataset['source_globs'] = []
    dataset['auto_discover_web_sources'] = False
    dataset['web_discovery_enable_en'] = False
    dataset['web_discovery_enable_el'] = False
    dataset['web_discovery_languages'] = []
    dataset['web_discovery_target_count_en'] = 0
    dataset['web_discovery_target_count_el'] = 0
    dataset['web_discovery_custom_keywords_el'] = []
    dataset['web_discovery_custom_keywords_en'] = []
    dataset['web_discovery_queries'] = {'en': [], 'el': []}
    dataset['source_files'] = [str(x).strip() for x in list(dataset.get('source_files') or []) if str(x).strip()]
    dataset['source_dirs'] = [str(x).strip() for x in list(dataset.get('source_dirs') or []) if str(x).strip()]
    # Για local/file-only Collect δεν απορρίπτουμε αρχεία κώδικα ή δομημένων δεδομένων
    # με heuristics που είναι φτιαγμένα για συνεχές κείμενο / web άρθρα.
    dataset['validate_source_completeness'] = False
    return config


def _studio_build_runtime_config_payload_collect_local_only(self) -> dict[str, Any]:
    config = _STUDIO_PREV_BUILD_RUNTIME_CONFIG_PAYLOAD_LOCAL_ONLY(self)
    config = _studio_ensure_runtime_defaults_collect_local_only(config)
    dataset = config.setdefault('dataset', {})
    dataset['source_urls'] = []
    dataset['source_globs'] = []
    dataset['auto_discover_web_sources'] = False
    dataset['web_discovery_enable_en'] = False
    dataset['web_discovery_enable_el'] = False
    dataset['web_discovery_languages'] = []
    dataset['web_discovery_target_count_en'] = 0
    dataset['web_discovery_target_count_el'] = 0
    dataset['web_discovery_custom_keywords_el'] = []
    dataset['web_discovery_custom_keywords_en'] = []
    dataset['web_discovery_queries'] = {'en': [], 'el': []}
    dataset['source_files'] = _studio_collect_selected_file_lines(self)
    dataset['source_dirs'] = _studio_collect_selected_dir_lines(self)
    dataset['validate_source_completeness'] = False

    extensions_raw = _studio_parse_text_widget(getattr(self, 'collect_extensions_edit', None))
    ext_list = _studio_parse_lines_to_list(str(extensions_raw).replace(',', '\n'))
    cleaned_exts: list[str] = []
    seen_exts: set[str] = set()
    for ext in ext_list:
        piece = str(ext).strip().lower()
        if not piece:
            continue
        if not piece.startswith('.'):
            piece = '.' + piece
        if piece in seen_exts:
            continue
        seen_exts.add(piece)
        cleaned_exts.append(piece)
    if cleaned_exts:
        dataset['source_extensions'] = cleaned_exts

    if getattr(self, 'collect_max_file_size_spin', None) is not None:
        dataset['max_file_size_bytes'] = int(self.collect_max_file_size_spin.value()) * 1024 * 1024
    return config


