# ===== CPT / COMMAND COMPLETION LOG VISIBILITY FIX =====
_studio_prev_on_command_finished_cpt_log_fix = PipelineStudioGUI._on_command_finished

def _studio_on_command_finished_cpt_log_fix(self, code: int) -> None:
    before_count = len(list(getattr(self, "_log_buffer", []) or []))
    _studio_prev_on_command_finished_cpt_log_fix(self, code)

    expected_line = (
        "✓ Η διεργασία ολοκληρώθηκε επιτυχώς."
        if int(code) == 0
        else f"❌ Η διεργασία ολοκληρώθηκε με κωδικό εξόδου {code}."
    )

    try:
        buffer_lines = list(getattr(self, "_log_buffer", []) or [])
        recent_lines = buffer_lines[max(0, before_count - 5):]
        if not any(expected_line in line for line in recent_lines):
            if hasattr(self, "_log_batch"):
                self._log_batch(expected_line)
            else:
                self.log(expected_line)
    except Exception:
        pass

    try:
        flush_fn = getattr(self, "_resp_flush", None) or getattr(self, "_flush_log_batch", None)
        if callable(flush_fn):
            flush_fn()
    except Exception:
        pass

PipelineStudioGUI._on_command_finished = _studio_on_command_finished_cpt_log_fix


# ===== GUI-THREAD QTimer SAFETY FIX =====
_studio_prev_resp_log_batch_qtimer_fix = getattr(PipelineStudioGUI, '_log_batch', None)
_studio_prev_resp_flush_qtimer_fix = getattr(PipelineStudioGUI, '_resp_flush', None) or getattr(PipelineStudioGUI, '_flush_log_batch', None)
_studio_prev_resp_log_qtimer_fix = getattr(PipelineStudioGUI, 'log', None)
_studio_prev_on_command_finished_qtimer_fix = PipelineStudioGUI._on_command_finished


def _studio_log_batch_gui_thread_safe(self, text: str) -> None:
    if not isinstance(text, str) or not text:
        return
    if not _studio_is_object_in_gui_thread(self):
        _studio_run_on_gui_thread(lambda s=self, t=str(text): _studio_log_batch_gui_thread_safe(s, t))
        return
    try:
        if callable(_studio_prev_resp_log_batch_qtimer_fix):
            _studio_prev_resp_log_batch_qtimer_fix(self, text)
    except Exception:
        try:
            if hasattr(self, '_log_buffer') and self._log_buffer is not None:
                self._log_buffer.append(str(text))
        except Exception:
            pass


def _studio_resp_flush_gui_thread_safe(self) -> None:
    if not _studio_is_object_in_gui_thread(self):
        _studio_run_on_gui_thread(lambda s=self: _studio_resp_flush_gui_thread_safe(s))
        return
    try:
        if callable(_studio_prev_resp_flush_qtimer_fix):
            _studio_prev_resp_flush_qtimer_fix(self)
    except Exception:
        pass


def _studio_log_gui_thread_safe(self, message: str) -> None:
    if not isinstance(message, str) or not message:
        return
    if not _studio_is_object_in_gui_thread(self):
        _studio_run_on_gui_thread(lambda s=self, m=str(message): _studio_log_batch_gui_thread_safe(s, m))
        return
    _studio_log_batch_gui_thread_safe(self, message)


def _studio_on_command_finished_qtimer_safe(self, code: int) -> None:
    if not _studio_is_object_in_gui_thread(self):
        _studio_run_on_gui_thread(lambda s=self, c=int(code): _studio_on_command_finished_qtimer_safe(s, c))
        return
    _studio_prev_on_command_finished_qtimer_fix(self, code)
    try:
        _studio_resp_flush_gui_thread_safe(self)
    except Exception:
        pass


PipelineStudioGUI._log_batch = _studio_log_batch_gui_thread_safe
PipelineStudioGUI._resp_flush = _studio_resp_flush_gui_thread_safe
PipelineStudioGUI._flush_log_batch = _studio_resp_flush_gui_thread_safe
PipelineStudioGUI.log = _studio_log_gui_thread_safe
PipelineStudioGUI._on_command_finished = _studio_on_command_finished_qtimer_safe

