def _studio_detect_model_dtype(model: Any) -> str:
    try:
        import torch as _t
        for p in model.parameters():
            if p.dtype == _t.bfloat16:  return "bf16"
            elif p.dtype == _t.float16: return "fp16"
            else:                        return "fp32"
    except Exception:
        pass
    return "fp32"


