def _studio_chat_copy_selected_text(self) -> None:
    view = getattr(self, 'chat_view', None)
    if view is None:
        return
    text = ''
    try:
        cursor = view.textCursor()
        text = str(cursor.selectedText() or '')
    except Exception:
        text = ''
    text = text.replace('\u2029', '\n').replace('\u2028', '\n').strip()
    if not text:
        QMessageBox.information(self, APP_TITLE, 'Δεν υπάρχει επιλεγμένο κείμενο για αντιγραφή.')
        return
    QApplication.clipboard().setText(text)
    self._set_status('Αντιγράφηκε το επιλεγμένο κείμενο από τη συνομιλία.')


def _studio_chat_extract_last_code_block(self) -> str:

    for item in reversed(list(getattr(self, '_messages', []) or [])):
        if str(item.get('role') or '') != 'assistant':
            continue
        raw = str(item.get('content') or '')
        if not raw.strip():
            continue
        matches = re.findall(r"```(?:[^\n`]*)\n?(.*?)```", raw, flags=re.DOTALL)
        if matches:
            return str(matches[-1]).strip('\n')
    return ''


def _studio_chat_copy_last_code_block(self) -> None:
    code_text = _studio_chat_extract_last_code_block(self)
    if not code_text:
        QMessageBox.information(self, APP_TITLE, 'Δεν βρέθηκε fenced code block στην τελευταία απάντηση.')
        return
    QApplication.clipboard().setText(code_text)
    self._set_status('Αντιγράφηκε το τελευταίο code block.')


