    def _do_export_chat() -> None:
        try:
            path, _ = QFileDialog.getSaveFileName(
                self,
                'Αποθήκευση συνομιλίας',
                str(ARTIFACTS_DIR / 'chat_export.txt'),
                'Text Files (*.txt)'
            )
            if not path:
                return
            lines: list[str] = []
            for m in getattr(self, '_messages', []) or []:
                role = 'Εσύ' if m.get('role') == 'user' else 'Μοντέλο'
                lines.append(f"[{role}]\n{m.get('content', '')}\n")
            Path(path).write_text('\n'.join(lines), encoding='utf-8')
            self._set_status(f'✓ Εξαγωγή συνομιλίας: {Path(path).name}')
        except Exception as exc:
            self._set_status(f'❌ Αποτυχία εξαγωγής: {exc}')

