    def _add_param(row: int, attr: str, label: str, kind: str, rng, value, step, tip: str) -> None:
        lbl = QLabel(label)
        lbl.setStyleSheet('font-size:11px;font-weight:700;')
        gen_lay.addWidget(lbl, row, 0)
        if kind == 'int':
            w = QSpinBox()
            w.setRange(int(rng[0]), int(rng[1]))
            w.setValue(int(value))
        else:
            w = QDoubleSpinBox()
            w.setRange(float(rng[0]), float(rng[1]))
            w.setSingleStep(float(step))
            w.setDecimals(2)
            w.setValue(float(value))
        w.setToolTip(tip)
        setattr(self, attr, w)
        gen_lay.addWidget(w, row, 1)

    _add_param(0, 'max_new_tokens_spin', 'max_new_tokens', 'int', (16, 8192), 8192, 1, 'Μέγιστοι νέοι tokens')
    _add_param(1, 'temperature_spin', 'temperature', 'float', (0.0, 2.0), 0.2, 0.05, 'Τυχαιότητα')
    _add_param(2, 'top_p_spin', 'top_p', 'float', (0.05, 1.0), 0.95, 0.05, 'Nucleus sampling')
    _add_param(3, 'top_k_spin', 'top_k', 'int', (0, 500), 50, 1, 'Top-k')
    _add_param(4, 'repetition_penalty_spin', 'repetition_penalty', 'float', (1.0, 3.0), 1.05, 0.05, 'Repetition penalty')

