    composer_outer.addWidget(self.input_edit)

    try:
        QShortcut(QKeySequence('Ctrl+Return'), self.input_edit).activated.connect(self.send_message)
    except Exception:
        pass

    action_grid = QGridLayout()
    action_grid.setHorizontalSpacing(8)
    action_grid.setVerticalSpacing(8)

    self.send_btn = QPushButton('🚀 Αποστολή')
    self.send_btn.setObjectName('PrimaryButton')
    self.send_btn.setMinimumHeight(38)
    self.send_btn.clicked.connect(self.send_message)

    self.stop_chat_btn = QPushButton('🛑 Διακοπή')
    self.stop_chat_btn.setObjectName('DangerButton')
    self.stop_chat_btn.setMinimumHeight(38)
    self.stop_chat_btn.setEnabled(False)
    self.stop_chat_btn.clicked.connect(self.stop_chat_generation)

    self.regen_btn = QPushButton('🔄 Νέα απάντηση')
    self.regen_btn.setMinimumHeight(38)
    self.regen_btn.clicked.connect(self.regenerate_last_answer)

    self.new_chat_btn = QPushButton('✨ Νέα συνομιλία')
    self.new_chat_btn.setMinimumHeight(38)
    self.new_chat_btn.clicked.connect(self.clear_chat)

    self.copy_last_btn = QPushButton('📋 Αντιγραφή απάντησης')
    self.copy_last_btn.setMinimumHeight(38)
    self.copy_last_btn.clicked.connect(self.copy_last_answer)

    self.export_chat_btn_main = QPushButton('💾 Εξαγωγή')
    self.export_chat_btn_main.setMinimumHeight(38)
    self.export_chat_btn_main.clicked.connect(_do_export_chat)

    action_btns = [
        self.send_btn,
        self.stop_chat_btn,
        self.regen_btn,
        self.new_chat_btn,
        self.copy_last_btn,
        self.export_chat_btn_main,
    ]
    for idx, btn in enumerate(action_btns):
        btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        action_grid.addWidget(btn, idx // 3, idx % 3)
    composer_outer.addLayout(action_grid)
    content_splitter.addWidget(composer_shell)

    content_splitter.setStretchFactor(0, 8)
    content_splitter.setStretchFactor(1, 3)
    content_splitter.setSizes([640, 250])
    right_content_lay.addWidget(content_splitter, 1)

    right_lay.addWidget(right_content, 1)
    body_splitter.addWidget(right_panel)
    body_splitter.setStretchFactor(0, 0)
    body_splitter.setStretchFactor(1, 1)
    body_splitter.setSizes([380, 820])

    root_lay.addWidget(body_splitter, 1)
    self.setCentralWidget(root)

    self._chat_sidebar = left_panel
    self._chat_header_frame = header_frame
    self._chat_content_widget = right_content
    self._chat_action_frame = composer_shell
    self._chat_dyn_seps = []

    def _sync_chat_badges() -> None:
        model_dir = self.model_dir_edit.text().strip()
        model_name = Path(model_dir).name if model_dir else 'Χωρίς μοντέλο'
        self._sidebar_model_label.setText(model_name)
        if model_dir:
            self._hdr_model_badge.setText(f'📦 {model_name}')
            self._hdr_model_badge.show()
        else:
            self._hdr_model_badge.hide()
        try:
            self._update_window_title()
        except Exception:
            pass

    try:
        self.model_dir_edit.textChanged.connect(_sync_chat_badges)
    except Exception:
        pass

    try:
        def _update_char_count() -> None:
            n = len(self.input_edit.toPlainText())
            self._char_counter_lbl.setText(f'{n} χαρακτήρες' if n > 0 else '')
        self.input_edit.textChanged.connect(_update_char_count)
        _update_char_count()
    except Exception:
        pass

    _sync_chat_badges()
    self.refresh_model_list()
    self._refresh_attachment_view()


