def _studio_chat_build_ui_ultra_compact_sidebar(self) -> None:
    """Χτίζει το UI και μετά ανασυνθέτει το αριστερό control panel σε ultra-compact μορφή."""
    _studio_chat_build_ui_full_relayout_v2(self)

    try:
        self.setMinimumSize(900, 680)
    except Exception:
        pass

    root = self.centralWidget()
    if root is None:
        return

    body_splitter = None
    for sp in root.findChildren(QSplitter):
        try:
            if sp.orientation() == Qt.Horizontal and sp.count() >= 2:
                body_splitter = sp
                break
        except Exception:
            pass
    old_sidebar = getattr(self, '_chat_sidebar', None)
    if body_splitter is None or old_sidebar is None:
        return

    def _find_button(fragment: str):
        fragment = fragment.strip().lower()
        for btn in old_sidebar.findChildren(QPushButton):
            txt = ' '.join(str(btn.text()).split()).lower()
            if fragment in txt:
                return btn
        return None

    def _compact_button(btn, left_align: bool = True) -> None:
        if btn is None:
            return
        try:
            btn.setMinimumHeight(26)
            btn.setMaximumHeight(28)
            btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            f = btn.font()
            if f.pointSize() > 0:
                f.setPointSize(max(9, f.pointSize() - 1))
            else:
                f.setPointSize(10)
            btn.setFont(f)
            if left_align:
                btn.setStyleSheet((btn.styleSheet() or '') + ' text-align:left; padding:3px 8px;')
        except Exception:
            pass

    def _compact_edit(w, h: int = 24) -> None:
        if w is None:
            return
        try:
            w.setMinimumHeight(h)
            w.setMaximumHeight(h)
            f = w.font()
            if f.pointSize() > 0:
                f.setPointSize(max(9, f.pointSize() - 1))
            else:
                f.setPointSize(10)
            w.setFont(f)
        except Exception:
            pass

    browse_model_btn = _find_button('περιήγηση')
    final_model_btn = _find_button('τελικό μοντέλο')
    current_selection_btn = _find_button('από δοκιμή')
    open_folder_btn = _find_button('άνοιγμα φακέλου')
    clear_cache_btn = _find_button('εκκαθάριση cache')
    light_btn = _find_button('light')
    dark_btn = _find_button('dark')

    for b in [
        getattr(self, 'import_prompt_btn', None),
        getattr(self, 'copy_selection_btn', None),
        getattr(self, 'copy_last_code_btn', None),
        getattr(self, 'export_chat_btn', None),
        getattr(self, 'use_selected_model_btn', None),
        browse_model_btn,
        final_model_btn,
        current_selection_btn,
        open_folder_btn,
        clear_cache_btn,
        getattr(self, 'attach_files_btn', None),
        getattr(self, 'remove_attachment_btn', None),
        getattr(self, 'clear_attachments_btn', None),
        light_btn,
        dark_btn,
    ]:
        _compact_button(b)

    for w in [
        getattr(self, 'trained_model_combo', None),
        getattr(self, 'model_dir_edit', None),
        getattr(self, 'history_turns_spin', None),
        getattr(self, 'max_new_tokens_spin', None),
        getattr(self, 'temperature_spin', None),
        getattr(self, 'top_p_spin', None),
        getattr(self, 'top_k_spin', None),
        getattr(self, 'repetition_penalty_spin', None),
    ]:
        _compact_edit(w, 24)

    if getattr(self, 'refresh_model_list_btn', None) is not None:
        try:
            self.refresh_model_list_btn.setFixedSize(28, 28)
        except Exception:
            pass

    if getattr(self, 'system_prompt_edit', None) is not None:
        try:
            self.system_prompt_edit.setMinimumHeight(92)
            self.system_prompt_edit.setMaximumHeight(122)
            f = self.system_prompt_edit.font()
            if f.pointSize() > 0:
                f.setPointSize(max(9, f.pointSize() - 1))
            else:
                f.setPointSize(10)
            self.system_prompt_edit.setFont(f)
        except Exception:
            pass

    if getattr(self, 'attachments_tree', None) is not None:
        try:
            self.attachments_tree.setMinimumHeight(130)
            self.attachments_tree.setMaximumHeight(180)
        except Exception:
            pass

    left_panel = QFrame()
    left_panel.setObjectName('Sidebar')
    left_panel.setMinimumWidth(250)
    left_panel.setMaximumWidth(320)
    left_panel.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Expanding)
    left_panel.setStyleSheet("""
        QFrame#Sidebar QLabel { font-size:10px; }
        QFrame#Sidebar QLabel#SidebarTitle { font-size:13px; font-weight:800; }
        QFrame#Sidebar QLabel#SidebarHint { font-size:9px; }
        QFrame#Sidebar QGroupBox { margin-top:14px; border-radius:14px; }
        QFrame#Sidebar QGroupBox::title { left:10px; padding:0 4px; font-size:11px; }
        QFrame#Sidebar QPushButton { min-height:26px; max-height:28px; padding:3px 8px; font-size:10px; text-align:left; }
        QFrame#Sidebar QLineEdit,
        QFrame#Sidebar QComboBox,
        QFrame#Sidebar QSpinBox,
        QFrame#Sidebar QDoubleSpinBox { min-height:24px; max-height:24px; padding:2px 6px; font-size:10px; }
        QFrame#Sidebar QTextEdit#SystemPromptBox { font-size:10px; padding:6px; }
        QFrame#Sidebar QTreeWidget#ChatAttachmentsTree { font-size:10px; }
        QFrame#Sidebar QHeaderView::section { padding:4px; font-size:10px; }
        QFrame#Sidebar QCheckBox { font-size:10px; }
    """)

    outer = QVBoxLayout(left_panel)
    outer.setContentsMargins(0, 0, 0, 0)
    outer.setSpacing(0)

    scroll = QScrollArea()
    scroll.setWidgetResizable(True)
    scroll.setFrameShape(QFrame.NoFrame)
    try:
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
    except Exception:
        pass
    outer.addWidget(scroll)

    content = QWidget()
    scroll.setWidget(content)
    lay = QVBoxLayout(content)
    lay.setContentsMargins(10, 10, 10, 10)
    lay.setSpacing(8)

    brand = QLabel('🧠 Chat Studio')
    brand.setObjectName('SidebarTitle')
    lay.addWidget(brand)

    hint = QLabel('Compact control panel για να χωράνε όλα καθαρά.')
    hint.setObjectName('SidebarHint')
    hint.setWordWrap(True)
    lay.addWidget(hint)

    if getattr(self, '_sidebar_model_label', None) is not None:
        try:
            self._sidebar_model_label.setWordWrap(True)
            self._sidebar_model_label.setMaximumHeight(42)
        except Exception:
            pass
        lay.addWidget(self._sidebar_model_label)

    quick_box = QGroupBox('Γρήγορα')
    quick_lay = QVBoxLayout(quick_box)
    quick_lay.setContentsMargins(8, 18, 8, 8)
    quick_lay.setSpacing(6)
    for w in [
        getattr(self, 'import_prompt_btn', None),
        getattr(self, 'copy_selection_btn', None),
        getattr(self, 'copy_last_code_btn', None),
        getattr(self, 'export_chat_btn', None),
    ]:
        if w is not None:
            quick_lay.addWidget(w)
    lay.addWidget(quick_box)

    model_box = QGroupBox('Μοντέλο')
    model_lay = QVBoxLayout(model_box)
    model_lay.setContentsMargins(8, 18, 8, 8)
    model_lay.setSpacing(6)

    combo_row = QHBoxLayout()
    combo_row.setSpacing(4)
    if getattr(self, 'trained_model_combo', None) is not None:
        combo_row.addWidget(self.trained_model_combo, 1)
    if getattr(self, 'refresh_model_list_btn', None) is not None:
        combo_row.addWidget(self.refresh_model_list_btn, 0)
    model_lay.addLayout(combo_row)

    for w in [
        getattr(self, 'use_selected_model_btn', None),
        getattr(self, 'model_dir_edit', None),
        browse_model_btn,
        final_model_btn,
        current_selection_btn,
        open_folder_btn,
        getattr(self, 'model_info_label', None),
        clear_cache_btn,
    ]:
        if w is not None:
            try:
                if isinstance(w, QLabel):
                    w.setWordWrap(True)
                if isinstance(w, QLineEdit):
                    w.setPlaceholderText('Φάκελος model…')
            except Exception:
                pass
            model_lay.addWidget(w)
    lay.addWidget(model_box)

    prompt_box = QGroupBox('Prompt / History')
    prompt_lay = QVBoxLayout(prompt_box)
    prompt_lay.setContentsMargins(8, 18, 8, 8)
    prompt_lay.setSpacing(6)
    if getattr(self, 'system_prompt_edit', None) is not None:
        prompt_lay.addWidget(self.system_prompt_edit)
    hist_lbl = QLabel('Ιστορικό (γύροι)')
    hist_lbl.setStyleSheet('font-weight:700;')
    prompt_lay.addWidget(hist_lbl)
    if getattr(self, 'history_turns_spin', None) is not None:
        prompt_lay.addWidget(self.history_turns_spin)
    lay.addWidget(prompt_box)

    gen_box = QGroupBox('Generation')
    gen_lay = QVBoxLayout(gen_box)
    gen_lay.setContentsMargins(8, 18, 8, 8)
    gen_lay.setSpacing(5)

    def _param_row(label_text: str, widget) -> None:
        if widget is None:
            return
        lbl = QLabel(label_text)
        lbl.setStyleSheet('font-weight:700;')
        gen_lay.addWidget(lbl)
        gen_lay.addWidget(widget)

    _param_row('max_new_tokens', getattr(self, 'max_new_tokens_spin', None))
    _param_row('temperature', getattr(self, 'temperature_spin', None))
    _param_row('top_p', getattr(self, 'top_p_spin', None))
    _param_row('top_k', getattr(self, 'top_k_spin', None))
    _param_row('repetition_penalty', getattr(self, 'repetition_penalty_spin', None))
    if getattr(self, 'do_sample_check', None) is not None:
        gen_lay.addWidget(self.do_sample_check)
    lay.addWidget(gen_box)

    theme_box = QGroupBox('Θέμα')
    theme_lay = QVBoxLayout(theme_box)
    theme_lay.setContentsMargins(8, 18, 8, 8)
    theme_lay.setSpacing(6)
    for w in [light_btn, dark_btn]:
        if w is not None:
            theme_lay.addWidget(w)
    lay.addWidget(theme_box)

    attach_box = QGroupBox('Συνημμένα')
    attach_lay = QVBoxLayout(attach_box)
    attach_lay.setContentsMargins(8, 18, 8, 8)
    attach_lay.setSpacing(6)
    if getattr(self, 'attachments_tree', None) is not None:
        attach_lay.addWidget(self.attachments_tree)
    for w in [
        getattr(self, 'attach_files_btn', None),
        getattr(self, 'remove_attachment_btn', None),
        getattr(self, 'clear_attachments_btn', None),
        getattr(self, 'attachment_info_label', None),
    ]:
        if w is not None:
            try:
                if isinstance(w, QLabel):
                    w.setWordWrap(True)
            except Exception:
                pass
            attach_lay.addWidget(w)
    lay.addWidget(attach_box)

    if getattr(self, '_sidebar_status', None) is not None:
        try:
            self._sidebar_status.setWordWrap(True)
        except Exception:
            pass
        lay.addWidget(self._sidebar_status)

    lay.addStretch(1)

    body_splitter.insertWidget(0, left_panel)
    try:
        old_sidebar.hide()
        old_sidebar.setParent(None)
        old_sidebar.deleteLater()
    except Exception:
        pass

    self._chat_sidebar = left_panel

    try:
        body_splitter.setStretchFactor(0, 0)
        body_splitter.setStretchFactor(1, 1)
        body_splitter.setSizes([280, max(600, self.width() - 280)])
        QTimer.singleShot(0, lambda sp=body_splitter: sp.setSizes([280, max(600, self.width() - 280)]))
    except Exception:
        pass


