def _studio_chat_find_horizontal_splitter(widget):
    if widget is None:
        return None
    try:
        for sp in widget.findChildren(QSplitter):
            try:
                if sp.orientation() == Qt.Horizontal and sp.count() >= 2:
                    return sp
            except Exception:
                pass
    except Exception:
        pass
    return None




class _StudioScrollBoundaryForwarder(QObject):
    """Forward wheel scrolling to the outer form when an inner view hits an edge."""

    def __init__(self, owner: QObject, outer_scroll: QScrollArea) -> None:
        super().__init__(owner)
        self._outer_scroll = outer_scroll

    def eventFilter(self, watched: QObject, event: object) -> bool:  # type: ignore[override]
        try:
            if event is None or getattr(event, 'type', lambda: None)() != QEvent.Wheel:
                return False
            outer = self._outer_scroll
            if outer is None:
                return False
            child_bar = watched.verticalScrollBar() if hasattr(watched, 'verticalScrollBar') else None
            outer_bar = outer.verticalScrollBar() if hasattr(outer, 'verticalScrollBar') else None
            if child_bar is None or outer_bar is None:
                return False
            delta = 0
            try:
                delta = int(event.angleDelta().y())
            except Exception:
                delta = 0
            if delta == 0:
                try:
                    delta = int(event.pixelDelta().y())
                except Exception:
                    delta = 0
            if delta == 0:
                return False
            wants_up = delta > 0
            wants_down = delta < 0
            at_top = child_bar.value() <= child_bar.minimum()
            at_bottom = child_bar.value() >= child_bar.maximum()
            if not ((wants_up and at_top) or (wants_down and at_bottom)):
                return False
            step_units = abs(delta) // 120 if abs(delta) >= 120 else 1
            step = max(36, outer_bar.singleStep() or 36) * max(1, step_units)
            if wants_up:
                outer_bar.setValue(max(outer_bar.minimum(), outer_bar.value() - step))
            else:
                outer_bar.setValue(min(outer_bar.maximum(), outer_bar.value() + step))
            try:
                event.accept()
            except Exception:
                pass
            return True
        except Exception:
            return False


def _studio_chat_install_outer_scroll_forwarding(self) -> None:
    try:
        outer_scroll = getattr(self, '_chat_form_scroll', None)
        view = getattr(self, 'chat_view', None)
        if outer_scroll is None or view is None:
            return
        forwarder = getattr(self, '_chat_scroll_edge_forwarder', None)
        if forwarder is None:
            forwarder = _StudioScrollBoundaryForwarder(self, outer_scroll)
            self._chat_scroll_edge_forwarder = forwarder
        try:
            view.removeEventFilter(forwarder)
        except Exception:
            pass
        view.installEventFilter(forwarder)
        try:
            view.viewport().removeEventFilter(forwarder)
        except Exception:
            pass
        try:
            view.viewport().installEventFilter(forwarder)
        except Exception:
            pass
        try:
            outer_scroll.verticalScrollBar().setSingleStep(36)
            outer_scroll.verticalScrollBar().setPageStep(max(outer_scroll.viewport().height() - 64, 180))
        except Exception:
            pass
        try:
            view.verticalScrollBar().setSingleStep(28)
            view.verticalScrollBar().setPageStep(max(view.viewport().height() - 48, 160))
        except Exception:
            pass
    except Exception as exc:
        write_exception_report('Chat outer scroll forwarding install failed', exc)

def _studio_chat_apply_sidebar_wide_uniform_scroll_pass(self) -> None:
    sidebar = getattr(self, '_chat_sidebar', None)
    if sidebar is None:
        return

    # Slightly larger, clearer text in the left control panel.
    try:
        extra_qss = """
        QFrame#Sidebar QLabel { font-size: 13px; }
        QFrame#Sidebar QLabel#SidebarTitle { font-size: 16px; font-weight: 800; }
        QFrame#Sidebar QLabel#SidebarHint { font-size: 12px; }
        QFrame#Sidebar QGroupBox { margin-top: 16px; }
        QFrame#Sidebar QGroupBox::title { font-size: 12px; }
        QFrame#Sidebar QPushButton {
            font-size: 14px;
            min-height: 34px;
            max-height: 36px;
            padding: 3px 10px;
        }
        QFrame#Sidebar QLineEdit,
        QFrame#Sidebar QComboBox,
        QFrame#Sidebar QSpinBox,
        QFrame#Sidebar QDoubleSpinBox {
            font-size: 13px;
            min-height: 32px;
            max-height: 34px;
            padding: 2px 8px;
        }
        QFrame#Sidebar QTextEdit,
        QFrame#Sidebar QTextEdit#SystemPromptBox {
            font-size: 13px;
            padding: 6px 8px;
        }
        QFrame#Sidebar QCheckBox { font-size: 13px; spacing: 6px; }
        QFrame#Sidebar QTreeWidget#ChatAttachmentsTree,
        QFrame#Sidebar QTreeWidget { font-size: 12px; }
        """
        sidebar.setStyleSheet((sidebar.styleSheet() or '') + extra_qss)
    except Exception:
        pass

    # Sidebar is freely resizable via the splitter handle, down to 0.
    try:
        sidebar.setMinimumWidth(0)
        sidebar.setMaximumWidth(16777215)
    except Exception:
        pass

    # Wider spacing inside the scrolled sidebar.
    try:
        for scroll in sidebar.findChildren(QScrollArea):
            content = scroll.widget()
            if content is not None and content.layout() is not None:
                content.layout().setContentsMargins(14, 14, 14, 12)
                content.layout().setSpacing(8)
                try:
                    scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                    scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                except Exception:
                    pass
    except Exception:
        pass

    try:
        for group in sidebar.findChildren(QGroupBox):
            lay = group.layout()
            if lay is not None:
                lay.setContentsMargins(10, 20, 10, 10)
                lay.setSpacing(7)
    except Exception:
        pass

    # ── Ομοιόμορφο μέγεθος: Expanding width, fixed height για ΟΛΑ ──
    ELEM_H = 34  # κοινό ύψος για buttons / inputs / spinboxes

    # Buttons — πλήρες πλάτος sidebar, ίδιο ύψος
    try:
        for btn in sidebar.findChildren(QPushButton):
            if btn.parentWidget() is None:
                continue
            btn.setFixedHeight(ELEM_H)
            btn.setMinimumWidth(0)
            btn.setMaximumWidth(16777215)
            btn.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            try:
                btn.setStyleSheet((btn.styleSheet() or '') + ' text-align:left; padding-left:8px;')
            except Exception:
                pass
    except Exception:
        pass

    # QLineEdit — πλήρες πλάτος
    try:
        for edit in sidebar.findChildren(QLineEdit):
            edit.setFixedHeight(ELEM_H)
            edit.setMinimumWidth(0)
            edit.setMaximumWidth(16777215)
            edit.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
    except Exception:
        pass

    # QComboBox — πλήρες πλάτος
    try:
        for combo in sidebar.findChildren(QComboBox):
            combo.setFixedHeight(ELEM_H)
            combo.setMinimumWidth(0)
            combo.setMaximumWidth(16777215)
            combo.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
    except Exception:
        pass

    # QSpinBox + QDoubleSpinBox — πλήρες πλάτος (αντί για 96/104px)
    try:
        for spin in list(sidebar.findChildren(QSpinBox)) + list(sidebar.findChildren(QDoubleSpinBox)):
            spin.setFixedHeight(ELEM_H)
            spin.setMinimumWidth(0)
            spin.setMaximumWidth(16777215)
            spin.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
    except Exception:
        pass

    # QCheckBox — πλήρες πλάτος
    try:
        for check in sidebar.findChildren(QCheckBox):
            check.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
    except Exception:
        pass

    # System prompt textarea — πλήρες πλάτος
    try:
        sp = getattr(self, 'system_prompt_edit', None)
        if sp is not None:
            sp.setMinimumHeight(92)
            sp.setMaximumHeight(130)
            sp.setMinimumWidth(0)
            sp.setMaximumWidth(16777215)
            sp.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
    except Exception:
        pass

    # Attachments tree — πλήρες πλάτος
    try:
        tree = getattr(self, 'attachments_tree', None)
        if tree is not None:
            tree.setMinimumHeight(96)
            tree.setMaximumHeight(128)
            tree.setMinimumWidth(0)
            tree.setMaximumWidth(16777215)
            tree.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
    except Exception:
        pass

    # Labels — wrap και expanding
    try:
        info = getattr(self, 'attachment_info_label', None)
        if info is not None:
            info.setWordWrap(True)
            info.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
    except Exception:
        pass

    try:
        for attr in ('_sidebar_model_label', '_sidebar_status'):
            lbl = getattr(self, attr, None)
            if lbl is not None:
                lbl.setWordWrap(True)
                lbl.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
    except Exception:
        pass

    # Splitter: sidebar freely resizable, chat area takes remaining space.
    try:
        container = self.centralWidget()
        root_widget = container.widget() if isinstance(container, QScrollArea) else container
        body_splitter = _studio_chat_find_horizontal_splitter(root_widget)
        if body_splitter is not None:
            self._chat_body_splitter = body_splitter
            body_splitter.setHandleWidth(6)
            body_splitter.setChildrenCollapsible(True)
            body_splitter.setStretchFactor(0, 0)
            body_splitter.setStretchFactor(1, 1)
            body_splitter.setSizes([300, max(600, self.width() - 300)])
    except Exception:
        pass

    # Wrap the entire form in an outer scroll area so the full chat window can scroll.
    try:
        current = self.centralWidget()
        if current is not None and not isinstance(current, QScrollArea):
            root_widget = current
            root_widget.setMinimumSize(900, 680)
            outer_scroll = QScrollArea()
            outer_scroll.setWidgetResizable(True)
            outer_scroll.setFrameShape(QFrame.NoFrame)
            outer_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
            outer_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
            outer_scroll.setWidget(root_widget)
            self.setCentralWidget(outer_scroll)
            self._chat_form_scroll = outer_scroll
        elif isinstance(current, QScrollArea):
            self._chat_form_scroll = current
            try:
                current.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                current.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
                root_widget = current.widget()
                if root_widget is not None:
                    root_widget.setMinimumSize(900, 680)
            except Exception:
                pass
    except Exception:
        pass

    try:
        _studio_chat_install_outer_scroll_forwarding(self)
    except Exception:
        pass

    try:
        self.setMinimumSize(900, 680)
    except Exception:
        pass


