# ===== CONSOLIDATED FINAL SHUTDOWN / STABILIZATION PATCH =====================
# =============================================================================


def _studio_safe_thread_shutdown(thread_obj: Any, wait_ms: int = 1500) -> None:
    """Σταματά με ασφάλεια QThread ή Python thread χωρίς να ρίχνει την εφαρμογή."""
    if thread_obj is None:
        return
    try:
        if hasattr(thread_obj, 'isRunning'):
            running = bool(thread_obj.isRunning())
            if running and hasattr(thread_obj, 'requestInterruption'):
                try:
                    thread_obj.requestInterruption()
                except Exception:
                    pass
            if running and hasattr(thread_obj, 'quit'):
                try:
                    thread_obj.quit()
                except Exception:
                    pass
            if running and hasattr(thread_obj, 'wait'):
                try:
                    thread_obj.wait(wait_ms)
                except Exception:
                    pass
            return
    except RuntimeError:
        return
    except Exception:
        pass

    try:
        if hasattr(thread_obj, 'is_alive') and thread_obj.is_alive() and hasattr(thread_obj, 'join'):
            try:
                thread_obj.join(wait_ms / 1000.0)
            except Exception:
                pass
    except Exception:
        pass


def _studio_stop_timer_attr(obj: Any, attr_name: str) -> None:
    """Σταματά με ασφάλεια QTimer-like attribute αν υπάρχει."""
    try:
        timer = getattr(obj, attr_name, None)
    except Exception:
        timer = None
    try:
        if timer is not None and hasattr(timer, 'isActive') and timer.isActive():
            timer.stop()
    except Exception:
        pass


def _studio_delete_later_attr(obj: Any, attr_name: str) -> None:
    """Καλεί deleteLater() όπου είναι διαθέσιμο και μηδενίζει το reference."""
    try:
        value = getattr(obj, attr_name, None)
    except Exception:
        value = None
    try:
        if value is not None and hasattr(value, 'deleteLater'):
            value.deleteLater()
    except Exception:
        pass
    try:
        setattr(obj, attr_name, None)
    except Exception:
        pass


def _studio_signal_stop_event_attr(obj: Any, attr_name: str) -> None:
    """Σηματοδοτεί threading.Event-like αντικείμενα πριν το shutdown."""
    try:
        ev = getattr(obj, attr_name, None)
    except Exception:
        ev = None
    try:
        if ev is not None and hasattr(ev, 'set'):
            ev.set()
    except Exception:
        pass


def _studio_chat_cleanup_runtime_objects_final(self) -> None:
    """Πλήρες cleanup για chat παράθυρο."""
    for attr in (
        '_stream_flush_timer',
        '_chat_render_timer',
        '_stream_coalesce_timer',
        '_progress_timer',
    ):
        _studio_stop_timer_attr(self, attr)

    _studio_signal_stop_event_attr(self, '_chat_stop_event')

    try:
        self._stream_pending_chunks = []
        self._stream_pending_statuses = []
    except Exception:
        pass

    try:
        _studio_safe_thread_shutdown(getattr(self, '_chat_thread', None))
    except Exception:
        pass

    _studio_delete_later_attr(self, '_chat_worker')

    for attr in ('_chat_thread', '_chat_stop_event'):
        try:
            setattr(self, attr, None)
        except Exception:
            pass

    try:
        _studio_stop_event_enabled(getattr(self, 'stop_chat_btn', None), False)
        _studio_stop_event_enabled(getattr(self, '_sb_stop_btn', None), False)
    except Exception:
        pass


def _studio_main_cleanup_runtime_objects_final(self) -> None:
    """Πλήρες cleanup για κύριο παράθυρο, Hub, inference, child chat windows
    και τερματισμό τυχόν ανοιχτών training/stage terminal windows.
    Εκτελείται μόνο μία φορά ανά κύριο παράθυρο, γιατί μπορεί να κληθεί
    και από closeEvent και από aboutToQuit.
    """
    if getattr(self, '_studio_final_cleanup_done', False):
        return

    try:
        self._studio_final_cleanup_done = True
    except Exception:
        pass

    try:
        _studio_prune_stage_terminal_processes()
    except Exception:
        pass

    try:
        _studio_close_all_stage_terminals(force=True)
    except Exception as exc:
        write_exception_report('Close stage terminals during final cleanup failed', exc)

    try:
        self._hub_list_refresh_token = None
        self._hub_repo_refresh_pending = False
    except Exception:
        pass

    for attr in (
        '_hub_busy_timer',
        '_hub_drain_timer',
        '_hub_status_drain_timer',
        '_log_flush_timer',
        '_status_clear_timer',
        '_progress_timer',
        '_infer_stream_timer',
    ):
        _studio_stop_timer_attr(self, attr)

    _studio_signal_stop_event_attr(self, '_infer_stop_event')

    try:
        self._hub_busy_running = False
        self._hub_stop_busy_timer()
        self._hub_set_repo_refresh_button_busy(False)
    except Exception:
        pass

    try:
        for win in list(getattr(self, '_chat_windows', []) or []):
            try:
                _studio_chat_cleanup_runtime_objects_final(win)
            except Exception:
                pass
    except Exception:
        pass

    for attr in (
        '_hub_dedicated_thread',
        '_hub_list_thread',
        '_hub_test_thread',
        '_hub_upload_thread2',
        '_job_thread',
        '_infer_thread',
    ):
        try:
            _studio_safe_thread_shutdown(getattr(self, attr, None), wait_ms=450)
        except Exception:
            pass
        try:
            setattr(self, attr, None)
        except Exception:
            pass

    for attr in (
        '_hub_list_worker',
        '_hub_dedicated_worker',
        '_hub_test_worker',
        '_hub_upload_worker2',
        '_job_worker',
        '_infer_worker',
    ):
        _studio_delete_later_attr(self, attr)

    try:
        self._infer_stop_event = None
    except Exception:
        pass

    if _STUDIO_GPU_CLEANUP_ONLY_ON_APP_EXIT:
        try:
            released = _studio_release_gpu_memory("κλείσιμο εφαρμογής")
            if released:
                try:
                    self.log("🧹 Η VRAM της GPU καθαρίστηκε κατά το κλείσιμο της εφαρμογής.")
                except Exception:
                    pass
        except Exception as exc:
            write_exception_report('GPU cleanup on app close failed', exc)


def _studio_main_close_event_final(self, event) -> None:  # type: ignore[override]
    if getattr(self, '_current_process', None) is not None:
        reply = QMessageBox.question(
            self,
            APP_TITLE,
            'Υπάρχει ενεργή διεργασία. Θέλεις να τη σταματήσεις και να κλείσει η εφαρμογή;',
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if reply == QMessageBox.No:
            event.ignore()
            return
        try:
            self.stop_current_job()
        except Exception as exc:
            write_exception_report('Stop current job during final close failed', exc)

    try:
        _studio_main_cleanup_runtime_objects_final(self)
    except Exception as exc:
        write_exception_report('Main final cleanup failed', exc)

    try:
        self.save_ui_settings()
    except Exception:
        pass

    try:
        from PySide6.QtCore import QSettings
        settings = QSettings(str(RUNTIME_CONFIG_DIR / 'studio_gui_settings.ini'), QSettings.IniFormat)
        settings.setValue('main/geometry', self.saveGeometry())
        settings.sync()
    except Exception:
        pass

    try:
        self.log('Η εφαρμογή κλείνει με ενοποιημένο cleanup για Hub / inference / chat.')
    except Exception:
        pass

    QMainWindow.closeEvent(self, event)


def _studio_chat_close_event_final(self, event) -> None:  # type: ignore[override]
    if getattr(self, '_chat_thread', None) is not None:
        QMessageBox.information(self, APP_TITLE, 'Περίμενε να ολοκληρωθεί η τρέχουσα απάντηση πριν κλείσεις το chat.')
        event.ignore()
        return

    try:
        self.save_chat_settings()
    except Exception:
        pass

    try:
        _studio_chat_cleanup_runtime_objects_final(self)
    except Exception as exc:
        write_exception_report('Chat final cleanup failed', exc)

    QMainWindow.closeEvent(self, event)


def _studio_main_init_with_final_cleanup(self, *args: Any, **kwargs: Any) -> None:
    _studio_prev_main_init_with_final_cleanup(self, *args, **kwargs)
    try:
        if not getattr(self, '_studio_about_to_quit_cleanup_connected', False):
            app = QApplication.instance()
            if app is not None:
                app.aboutToQuit.connect(lambda s=self: _studio_main_cleanup_runtime_objects_final(s))
                self._studio_about_to_quit_cleanup_connected = True
    except Exception as exc:
        write_exception_report('Binding final aboutToQuit cleanup failed', exc)


