def _studio_preserve_training_text(text: Any) -> str:
    value = str(text or "").replace("\ufeff", "").replace("\r\n", "\n").replace("\r", "\n")
    value = value.expandtabs(4)
    lines = [line.rstrip() for line in value.split("\n")]
    compact: list[str] = []
    blank_count = 0
    for line in lines:
        if not line.strip():
            blank_count += 1
            if blank_count <= 2:
                compact.append("")
            continue
        blank_count = 0
        compact.append(line)
    while compact and not compact[0].strip():
        compact.pop(0)
    while compact and not compact[-1].strip():
        compact.pop()
    return "\n".join(compact)


def _studio_is_python_code_path(path: Path | str | None) -> bool:
    try:
        suffix = Path(path).suffix.lower()
    except Exception:
        suffix = str(path or '').strip().lower()
        if suffix and not suffix.startswith('.'):
            suffix = '.' + suffix.rsplit('.', 1)[-1]
    return suffix in {'.py', '.pyi', '.pyw'}


def _studio_should_preserve_record_formatting(record: dict[str, Any]) -> bool:
    source_kind = str(record.get('source_kind') or '').strip().lower()
    source_path = record.get('source_path') or record.get('source_dataset_path') or record.get('title') or ''
    return (
        bool(record.get('preserve_formatting'))
        or bool(record.get('structured_example'))
        or bool(record.get('code_file'))
        or source_kind in {'structured_dataset_row', 'code_file'}
        or _studio_is_python_code_path(source_path)
    )


def _studio_row_to_lower_map(row: Any) -> dict[str, Any]:
    if not isinstance(row, dict):
        return {}
    lowered: dict[str, Any] = {}
    for key, value in row.items():
        normalized_key = str(key or "").strip().lower()
        if normalized_key:
            lowered[normalized_key] = value
    return lowered


def _studio_row_value_as_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, (list, dict)):
        try:
            return json.dumps(value, ensure_ascii=False, indent=2)
        except Exception:
            return str(value)
    return str(value)



_STUDIO_RESPONSE_CONTAMINATION_PATTERNS = [
    r'you\s+are\s+qwen',
    r'created\s+by\s+alibaba\s+cloud',
    r'\byou\s+are\s+a\s+helpful\s+assistant\b',
    r'<\|im_start\|>',
    r'<\|im_end\|>',
    r'<\|repo_name\|>',
    r'<\|file_sep\|>',
    r'<\|assistant\|>',
    r'<\|user\|>',
    r'<\|system\|>',
    r'<\s*\|\s*[^>\n]{1,60}\s*\|\s*>',
    r'\b(?:repo_name|repository|filename|file_name)\b\s*[:=]',
    r'@\{\s*@?"',
    r'_+\s*qwen\b',
]

_STUDIO_RESPONSE_CONTAMINATION_REGEXES = [
    re.compile(pattern, flags=re.IGNORECASE)
    for pattern in _STUDIO_RESPONSE_CONTAMINATION_PATTERNS
]


def _studio_detect_contamination_reasons(value: Any) -> list[str]:
    text = _studio_preserve_training_text(value)
    if not text:
        return []
    lowered = text.casefold()
    reasons: list[str] = []
    substring_checks = [
        ('substring:@{@', '@{@'),
        ('substring:@{@"', '@{@"'),
        ('substring:you are qwen', 'you are qwen'),
        ('substring:alibaba cloud', 'alibaba cloud'),
        ('substring:helpful assistant', 'helpful assistant'),
        ('substring:<|repo_name|>', '<|repo_name|>'),
        ('substring:< | repo_name | >', '< | repo_name | >'),
        ('substring:<|im_start|>', '<|im_start|>'),
        ('substring:<|im_end|>', '<|im_end|>'),
        ('substring:_qwen', '_qwen'),
    ]
    for label, needle in substring_checks:
        if needle in lowered:
            reasons.append(label)
    for regex in _STUDIO_RESPONSE_CONTAMINATION_REGEXES:
        if regex.search(text):
            reasons.append(f'regex:{regex.pattern}')
    return list(dict.fromkeys(reasons))


def _studio_text_contains_contamination(value: Any) -> bool:
    return bool(_studio_detect_contamination_reasons(value))


def _studio_strip_response_contamination_lines(value: Any) -> str:
    text = _studio_preserve_training_text(value)
    if not text:
        return ''
    cleaned_lines: list[str] = []
    for raw_line in text.split('\n'):
        line = str(raw_line or '').strip()
        if not line:
            cleaned_lines.append('')
            continue
        if _studio_detect_contamination_reasons(line):
            continue
        cleaned_lines.append(raw_line)
    return _studio_preserve_training_text("\n".join(cleaned_lines))


def _studio_detect_echo_reasons(prompt_text: Any, completion_text: Any) -> list[str]:
    prompt = _studio_compact_text_for_near_dedupe(prompt_text)
    completion = _studio_compact_text_for_near_dedupe(completion_text)
    if not prompt or not completion:
        return []
    reasons: list[str] = []
    if completion.startswith(prompt):
        reasons.append('completion_starts_with_prompt')
    prompt_words = prompt.split()
    completion_words = completion.split()
    if prompt_words and completion_words:
        overlap = len(set(prompt_words) & set(completion_words))
        ratio = overlap / max(1, min(len(prompt_words), len(completion_words)))
        if ratio >= 0.92 and len(completion_words) <= len(prompt_words) + 12:
            reasons.append(f'high_overlap_ratio={ratio:.3f}')
    return reasons


def _studio_prompt_completion_looks_like_echo(prompt_text: Any, completion_text: Any) -> bool:
    return bool(_studio_detect_echo_reasons(prompt_text, completion_text))


def _studio_clean_structured_prompt_text(value: Any) -> str:
    text = _studio_preserve_training_text(value).strip().lstrip("\ufeff")
    if not text:
        return ""
    text = re.sub(r'^\s*(?:#+\s*)?(?:user|prompt|question|instruction|task)\s*:\s*', '', text, flags=re.IGNORECASE)
    return _studio_preserve_training_text(text)


def _studio_unwrap_single_field_serialized_text(value: str) -> str:
    text = str(value or '').strip()
    if not text:
        return ''

    candidates: list[str] = [text]
    if text.startswith('@{') or '@"' in text or "@'" in text:
        candidates.append(text.replace('@{', '{').replace('@"', '"').replace("@'", "'"))

    for candidate in candidates:
        try:
            payload = json.loads(candidate)
        except Exception:
            payload = None
        if isinstance(payload, dict) and len(payload) == 1:
            only_value = next(iter(payload.values()))
            if isinstance(only_value, str) and only_value.strip():
                return only_value.strip()
        if isinstance(payload, list) and len(payload) == 1 and isinstance(payload[0], str) and payload[0].strip():
            return payload[0].strip()

    patterns = [
        r'^\s*@?\{\s*@?"[^"]+"\s*:\s*"(?P<value>(?:\\.|[^"\\])*)"\s*\}\s*$',
        r"^\s*@?\{\s*@?'[^']+'\s*:\s*'(?P<value>(?:\\.|[^'\\])*)'\s*\}\s*$",
        r'^\s*@?\{\s*@?"[^"]+"\s*:\s*@?"(?P<value>.*)"\s*\}\s*$',
    ]
    for pattern in patterns:
        match = re.match(pattern, text, flags=re.DOTALL)
        if not match:
            continue
        inner = match.group('value')
        try:
            inner = bytes(inner, 'utf-8').decode('unicode_escape')
        except Exception:
            pass
        inner = inner.strip()
        if inner:
            return inner
    return text


def _studio_clean_structured_response_text(value: Any) -> str:
    text = _studio_preserve_training_text(value).strip().lstrip("\ufeff")
    if not text:
        return ""
    previous = None
    for _ in range(5):
        text = _studio_unwrap_single_field_serialized_text(text)
        text = _studio_strip_response_contamination_lines(text)
        text = re.sub(
            r'_?\s*Qwen\s+You\s+are\s+Qwen,\s*created\s+by\s+Alibaba\s+Cloud\.\s*You\s+are\s+a\s+helpful\s+assistant\.?',
            ' ',
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r'You\s+are\s+Qwen,\s*created\s+by\s+Alibaba\s+Cloud\.\s*You\s+are\s+a\s+helpful\s+assistant\.?',
            ' ',
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(r'<\s*\|\s*[^>\n]{1,60}\s*\|\s*>', ' ', text, flags=re.IGNORECASE)
        text = re.sub(
            r'^\s*(?:#+\s*)?(?:assistant|response|output|completion|answer|final answer)\s*:\s*',
            '',
            text,
            flags=re.IGNORECASE,
        ).strip()
        text = re.sub(r'^(?:`{3}(?:python|json|text|bash)?\s*)+', '', text, flags=re.IGNORECASE).strip()
        text = re.sub(r'\s{3,}', '  ', text)
        if text == previous:
            break
        previous = text
    return _studio_preserve_training_text(text)


def _studio_compact_text_for_near_dedupe(value: Any) -> str:
    text = _studio_preserve_training_text(value)
    if not text:
        return ''
    text = text.casefold()
    text = re.sub(r'```(?:python|json|text|bash)?', '```', text, flags=re.IGNORECASE)
    text = re.sub(r'\b(?:assistant|response|output|completion|answer|user|prompt|instruction)\s*:', ' ', text, flags=re.IGNORECASE)
    text = re.sub(r'[_\W]+', ' ', text, flags=re.UNICODE)
    text = re.sub(r'\s+', ' ', text).strip()
    return text


def _studio_trim_debug_text(value: Any, limit: int = 600) -> str:
    text = _studio_preserve_training_text(value)
    text = text.replace('\r', ' ').replace('\n', '\\n').strip()
    if len(text) > limit:
        return text[:limit] + '...'
    return text


def _studio_record_debug_snapshot(record: dict[str, Any], *, reasons: list[str] | None = None, label: str = '') -> dict[str, Any]:
    pair = None
    try:
        pair = _studio_extract_prompt_completion_pair(record)
    except Exception:
        pair = None
    prompt_text = pair[0] if pair else _studio_preserve_training_text(record.get('prompt') or record.get('instruction') or '')
    response_text = pair[1] if pair else _studio_preserve_training_text(record.get('output') or record.get('response') or '')
    return {
        'label': label,
        'id': record.get('id') or '',
        'source_path': record.get('source_path') or '',
        'source_dataset_path': record.get('source_dataset_path') or '',
        'source_row_index': record.get('source_row_index'),
        'structured_example': bool(record.get('structured_example')),
        'dataset_format': record.get('dataset_format') or '',
        'reasons': list(reasons or []),
        'prompt_preview': _studio_trim_debug_text(prompt_text),
        'response_preview': _studio_trim_debug_text(response_text),
        'text_preview': _studio_trim_debug_text(record.get('text') or record.get('raw_text') or ''),
    }


def _studio_write_debug_sample_dump(path: Path, rows: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('w', encoding='utf-8') as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False) + '\n')


def _studio_structured_record_near_dedupe_key(record: dict[str, Any]) -> str:
    try:
        pair = _studio_extract_prompt_completion_pair(record)
    except Exception:
        pair = None
    if pair is not None:
        prompt_text, completion_text = pair
        prompt_norm = _studio_compact_text_for_near_dedupe(prompt_text)
        completion_norm = _studio_compact_text_for_near_dedupe(completion_text)
        payload = {
            'prompt': ' '.join(prompt_norm.split()[:48]),
            'completion': ' '.join(completion_norm.split()[:96]),
        }
        if payload['prompt'] or payload['completion']:
            return _studio_hash_text(json.dumps(payload, ensure_ascii=False, sort_keys=True))
    text_norm = _studio_compact_text_for_near_dedupe(record.get('text') or record.get('raw_text') or '')
    if not text_norm:
        return ''
    payload = {
        'text': ' '.join(text_norm.split()[:144]),
        'dataset_format': str(record.get('dataset_format') or '').strip().lower(),
    }
    return _studio_hash_text(json.dumps(payload, ensure_ascii=False, sort_keys=True))


def _studio_structured_fieldnames_look_supported(fieldnames: list[str]) -> bool:
    keys = {str(name or "").strip().lower() for name in fieldnames if str(name or "").strip()}
    if not keys:
        return False
    text_like = {"text", "content", "body", "conversation", "messages"}
    prompt_like = {"prompt", "instruction", "question", "query", "input", "context", "task"}
    answer_like = {"output", "response", "answer", "completion", "label", "target"}
    if keys & text_like:
        return True
    return bool(keys & prompt_like) and bool(keys & answer_like)


def _studio_build_alpaca_prompt(instruction: str, input_text: str) -> str:
    instruction = _studio_preserve_training_text(instruction)
    input_text = _studio_preserve_training_text(input_text)
    if input_text:
        return (
            "Below is an instruction that describes a task, paired with an input that provides further context. "
            "Write a response that appropriately completes the request.\n\n"
            f"### Instruction:\n{instruction}\n\n"
            f"### Input:\n{input_text}\n\n"
            "### Response:\n"
        )
    return (
        "Below is an instruction that describes a task. Write a response that appropriately completes the request.\n\n"
        f"### Instruction:\n{instruction}\n\n"
        "### Response:\n"
    )


def _studio_try_parse_messages_field(raw_value: Any) -> list[dict[str, Any]]:
    if isinstance(raw_value, list):
        return [item for item in raw_value if isinstance(item, dict)]
    raw_text = _studio_row_value_as_text(raw_value).strip()
    if not raw_text:
        return []
    try:
        payload = json.loads(raw_text)
        if isinstance(payload, list):
            return [item for item in payload if isinstance(item, dict)]
    except Exception:
        pass
    return []


def _studio_structured_row_to_sft_payload(row: dict[str, Any]) -> dict[str, Any] | None:
    data = _studio_row_to_lower_map(row)
    if not data:
        return None

    instruction = _studio_clean_structured_prompt_text(_studio_row_value_as_text(data.get("instruction")))
    input_text = _studio_clean_structured_prompt_text(_studio_row_value_as_text(data.get("input")))
    output_text = _studio_clean_structured_response_text(_studio_row_value_as_text(data.get("output") or data.get("response") or data.get("answer") or data.get("completion")))
    prompt_text = _studio_clean_structured_prompt_text(_studio_row_value_as_text(data.get("prompt")))
    plain_text = _studio_preserve_training_text(_studio_row_value_as_text(data.get("text") or data.get("content") or data.get("body") or data.get("conversation"))).strip()
    messages = _studio_try_parse_messages_field(data.get("messages"))
    if messages:
        cleaned_messages: list[dict[str, Any]] = []
        for msg in messages:
            role = str(msg.get("role") or "user").strip().lower() or "user"
            content = msg.get("content") or ""
            if role == 'assistant':
                content = _studio_clean_structured_response_text(content)
            else:
                content = _studio_clean_structured_prompt_text(content)
            if content:
                cleaned_messages.append({'role': role, 'content': content})
        messages = cleaned_messages

    dataset_format = ""
    training_text = ""

    if prompt_text and output_text:
        dataset_format = "prompt_output"
        prompt_clean = _studio_preserve_training_text(prompt_text)
        output_clean = _studio_preserve_training_text(output_text)
        if output_clean and output_clean in prompt_clean:
            training_text = prompt_clean
        else:
            joiner = "" if (not prompt_clean or prompt_clean.endswith(("\n", " ", "\t"))) else "\n"
            training_text = f"{prompt_clean}{joiner}{output_clean}".strip("\n")
    elif prompt_text:
        dataset_format = "prompt"
        training_text = _studio_preserve_training_text(prompt_text)
    elif instruction and output_text:
        dataset_format = "instruction_input_output"
        training_text = (_studio_build_alpaca_prompt(instruction, input_text) + _studio_preserve_training_text(output_text)).strip("\n")
    elif plain_text:
        dataset_format = "text"
        training_text = _studio_preserve_training_text(plain_text)
    elif messages:
        parts: list[str] = []
        for msg in messages:
            role = str(msg.get("role") or "user").strip().lower() or "user"
            content = _studio_preserve_training_text(msg.get("content") or "")
            if not content:
                continue
            pretty_role = role[:1].upper() + role[1:]
            parts.append(f"{pretty_role}: {content}")
        if parts:
            dataset_format = "messages"
            training_text = "\n\n".join(parts)

    training_text = _studio_preserve_training_text(training_text)
    if not training_text:
        return None

    payload: dict[str, Any] = {
        "text": training_text,
        "preserve_formatting": True,
        "structured_example": bool(dataset_format and dataset_format != 'text'),
        "dataset_format": dataset_format or "text",
    }
    if instruction:
        payload["instruction"] = _studio_preserve_training_text(instruction)
    if input_text:
        payload["input"] = _studio_preserve_training_text(input_text)
    if output_text:
        payload["output"] = _studio_preserve_training_text(output_text)
    if prompt_text:
        payload["prompt"] = _studio_preserve_training_text(prompt_text)
    if plain_text:
        payload["raw_text"] = _studio_preserve_training_text(plain_text)
    if messages:
        payload["messages"] = messages
    return payload


def collect_training_sources_local_only(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults_collect_local_only(copy.deepcopy(config))
    dataset = config.get('dataset', {})
    project_root = Path(config.get('project_root') or PROJECT_ROOT).resolve()
    collect_dir = Path(dataset.get('collect_dir') or (ARTIFACTS_DIR / '01_collect'))
    raw_dir = collect_dir / 'raw_sources'
    collect_dir.mkdir(parents=True, exist_ok=True)
    raw_dir.mkdir(parents=True, exist_ok=True)

    records: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    validation_report: list[dict[str, Any]] = []
    file_count = 0
    structured_dataset_files = 0
    structured_example_count = 0
    python_code_file_count = 0
    candidate_files = list(_studio_iter_collect_file_candidates(config))

    if not candidate_files:
        append_log('[collect] ! Δεν βρέθηκαν υποψήφια αρχεία από τα Source Files / Source Folders με τα τρέχοντα extensions.')

    for file_path in candidate_files:
        try:
            rel_path = str(file_path.resolve().relative_to(project_root)) if str(file_path.resolve()).startswith(str(project_root)) else str(file_path)
            structured_examples = _studio_load_structured_dataset_examples(file_path)
            if structured_examples:
                structured_dataset_files += 1
                accepted_here = 0
                for row_index, payload in enumerate(structured_examples, start=1):
                    text = _studio_preserve_training_text(payload.get('text') or '')
                    if len(text) < 8:
                        skipped.append({
                            'path': str(file_path),
                            'reason': 'structured_example_too_short',
                            'row_index': row_index,
                        })
                        continue
                    record_id = _studio_hash_text(f"{rel_path}|{row_index}|{text[:500]}")
                    record = {
                        'id': f"dataset_{record_id[:16]}",
                        'source_kind': 'structured_dataset_row',
                        'source_path': rel_path,
                        'source_dataset_path': rel_path,
                        'source_row_index': row_index,
                        'title': f"{file_path.name} · row {row_index}",
                        'text': text,
                        'char_count': len(text),
                        'sha1': _studio_hash_text(text),
                        'preserve_formatting': True,
                        'structured_example': True,
                        'dataset_format': payload.get('dataset_format') or 'text',
                    }
                    for key in ('instruction', 'input', 'output', 'prompt', 'messages', 'raw_text'):
                        if payload.get(key):
                            record[key] = payload.get(key)
                    records.append(record)
                    accepted_here += 1
                    structured_example_count += 1
                    (raw_dir / f"{record['id']}.txt").write_text(text, encoding='utf-8')
                append_log(f"[collect] + structured dataset: {rel_path} | examples={accepted_here}")
                continue

            is_python_code_file = _studio_is_python_code_path(file_path)
            raw_text = _studio_read_text_file(file_path)
            text = _studio_preserve_training_text(raw_text) if is_python_code_file else _studio_normalize_space(raw_text)
            validation = None
            validator = globals().get('_studio_validate_source_completeness')
            if not is_python_code_file and callable(validator):
                try:
                    validation = validator(text, dataset=dataset, source_kind='file', title=file_path.name, locator=rel_path)
                except Exception:
                    validation = None

            min_chars = 8 if is_python_code_file else 20
            if validation is not None:
                if not bool(validation.get('complete')):
                    skipped.append({
                        'path': str(file_path),
                        'reason': f"incomplete_source: {validation.get('reason')}",
                        'validation': validation.get('metrics', {}),
                    })
                    validation_report.append({
                        'kind': 'file',
                        'path': rel_path,
                        'accepted': False,
                        'reason': validation.get('reason'),
                        'metrics': validation.get('metrics', {}),
                    })
                    append_log(f"[collect] - παραλείφθηκε ελλιπές αρχείο: {rel_path} | {validation.get('reason')}")
                    continue
            elif len(text) < min_chars:
                skipped.append({'path': str(file_path), 'reason': 'too_short'})
                append_log(f'[collect] - παραλείφθηκε πολύ μικρό αρχείο: {rel_path}')
                continue

            record_id = _studio_hash_text(rel_path + '|' + text[:500])
            record = {
                'id': f"file_{record_id[:16]}",
                'source_kind': 'code_file' if is_python_code_file else 'file',
                'source_path': rel_path,
                'title': file_path.name,
                'text': text,
                'char_count': len(text),
                'sha1': _studio_hash_text(text),
            }
            if is_python_code_file:
                record['preserve_formatting'] = True
                record['code_file'] = True
                record['code_language'] = 'python'
                record['dataset_format'] = 'code_corpus'
                python_code_file_count += 1
            if validation is not None:
                record['validation'] = validation.get('metrics', {})
                validation_report.append({
                    'kind': 'file',
                    'path': rel_path,
                    'accepted': True,
                    'reason': '',
                    'metrics': validation.get('metrics', {}),
                })

            records.append(record)
            file_count += 1
            (raw_dir / f"{record['id']}.txt").write_text(text, encoding='utf-8')
            if is_python_code_file:
                append_log(f'[collect] + Python code file: {rel_path}')
            else:
                append_log(f'[collect] + αρχείο: {rel_path}')
        except Exception as exc:
            friendly_reason = _studio_format_collect_file_error(file_path, exc)
            skipped.append({'path': str(file_path), 'reason': friendly_reason})
            append_log(f'[collect] ! αποτυχία αρχείου: {file_path} | {friendly_reason}')

    corpus_path = collect_dir / 'collected_corpus.jsonl'
    _studio_jsonl_dump(corpus_path, records)
    manifest = {
        'stage': 'collect',
        'status': 'completed' if records else 'empty',
        'records': len(records),
        'file_records': file_count,
        'structured_dataset_files': structured_dataset_files,
        'structured_example_records': structured_example_count,
        'python_code_files': python_code_file_count,
        'web_records': 0,
        'web_records_by_language': {'en': 0, 'el': 0},
        'skipped': len(skipped),
        'configured_web_sources': 0,
        'discovered_web_sources': 0,
        'collect_mode': 'local_files_and_directories_only',
        'collect_dir': str(collect_dir.resolve()),
        'corpus_path': str(corpus_path.resolve()),
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    (collect_dir / 'collect_manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')
    (collect_dir / 'skipped_files.json').write_text(json.dumps(skipped, ensure_ascii=False, indent=2), encoding='utf-8')
    (collect_dir / 'source_validation_report.json').write_text(json.dumps(validation_report, ensure_ascii=False, indent=2), encoding='utf-8')
    (collect_dir / 'collect_report.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8')

    append_log(
        f"[collect] Σύνολο υποψήφιων: {len(candidate_files)} | αποδεκτά: {len(records)} | "
        f"structured_examples: {structured_example_count} | python_code_files: {python_code_file_count} | skipped: {len(skipped)}"
    )
    if not records:
        append_log('[collect] ! Το collected_corpus.jsonl είναι άδειο. Έλεγξε Source Files / Source Folders, extensions και δικαιώματα πρόσβασης.')
    return manifest


def preprocess_training_sources(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults(config)
    dataset = config.get('dataset', {})
    collect_dir = Path(dataset.get('collect_dir') or (ARTIFACTS_DIR / '01_collect'))
    preprocess_dir = Path(dataset.get('preprocess_dir') or (ARTIFACTS_DIR / '02_preprocess'))
    preprocess_dir.mkdir(parents=True, exist_ok=True)

    records = _studio_jsonl_load(collect_dir / 'collected_corpus.jsonl')
    if not records:
        append_log('[preprocess] ! Δεν βρέθηκαν records στο collected_corpus.jsonl από το προηγούμενο Collect.')
    processed: list[dict[str, Any]] = []
    seen_hashes: set[str] = set()
    seen_near_hashes: set[str] = set()
    duplicates_removed = 0
    near_duplicates_removed = 0
    too_short_removed = 0
    contaminated_removed = 0
    echo_like_removed = 0
    debug_kept_rows: list[dict[str, Any]] = []
    debug_contaminated_rows: list[dict[str, Any]] = []
    debug_echo_rows: list[dict[str, Any]] = []

    for item in records:
        preserve = _studio_should_preserve_record_formatting(item)
        working_item = copy.deepcopy(item)
        is_structured = bool(working_item.get('structured_example'))
        if is_structured:
            if working_item.get('instruction'):
                working_item['instruction'] = _studio_clean_structured_prompt_text(working_item.get('instruction'))
            if working_item.get('input'):
                working_item['input'] = _studio_clean_structured_prompt_text(working_item.get('input'))
            if working_item.get('prompt'):
                working_item['prompt'] = _studio_clean_structured_prompt_text(working_item.get('prompt'))
            if working_item.get('output'):
                working_item['output'] = _studio_clean_structured_response_text(working_item.get('output'))
            if isinstance(working_item.get('messages'), list):
                cleaned_messages: list[dict[str, Any]] = []
                for msg in list(working_item.get('messages') or []):
                    if not isinstance(msg, dict):
                        continue
                    role = str(msg.get('role') or 'user').strip().lower() or 'user'
                    content = msg.get('content') or ''
                    if role == 'assistant':
                        content = _studio_clean_structured_response_text(content)
                    else:
                        content = _studio_clean_structured_prompt_text(content)
                    if content:
                        cleaned_messages.append({'role': role, 'content': content})
                working_item['messages'] = cleaned_messages
            rebuilt_text = _studio_extract_training_text(working_item)
            if rebuilt_text:
                working_item['text'] = rebuilt_text

        raw_text = working_item.get('text') or ''
        text_value = _studio_preserve_training_text(raw_text) if preserve else _studio_normalize_space(raw_text)
        if len(text_value) < 8:
            too_short_removed += 1
            continue

        if is_structured:
            pair = _studio_extract_prompt_completion_pair(working_item)
            prompt_text = pair[0] if pair else _studio_preserve_training_text(working_item.get('prompt') or working_item.get('instruction') or '')
            response_text = pair[1] if pair else _studio_preserve_training_text(working_item.get('output') or working_item.get('response') or '')
            contamination_reasons = []
            for reason in _studio_detect_contamination_reasons(response_text):
                contamination_reasons.append(f'response::{reason}')
            for reason in _studio_detect_contamination_reasons(text_value):
                contamination_reasons.append(f'text::{reason}')
            contamination_reasons = list(dict.fromkeys(contamination_reasons))
            if response_text and contamination_reasons:
                contaminated_removed += 1
                if len(debug_contaminated_rows) < STUDIO_PATCH_DEBUG_SAMPLE_DUMP_LIMIT:
                    debug_contaminated_rows.append(_studio_record_debug_snapshot(working_item, reasons=contamination_reasons, label='contaminated_rejected'))
                continue
            echo_reasons = _studio_detect_echo_reasons(prompt_text, response_text)
            if response_text and echo_reasons:
                echo_like_removed += 1
                if len(debug_echo_rows) < STUDIO_PATCH_DEBUG_SAMPLE_DUMP_LIMIT:
                    debug_echo_rows.append(_studio_record_debug_snapshot(working_item, reasons=echo_reasons, label='echo_rejected'))
                continue

        if is_structured:
            content_hash = _studio_structured_record_dedupe_key(working_item, text_value)
        else:
            content_hash = _studio_hash_text(text_value)

        if content_hash in seen_hashes:
            duplicates_removed += 1
            continue
        seen_hashes.add(content_hash)

        near_hash = _studio_structured_record_near_dedupe_key(working_item) if is_structured else ''
        if near_hash:
            if near_hash in seen_near_hashes:
                near_duplicates_removed += 1
                continue
            seen_near_hashes.add(near_hash)

        record = {
            'id': working_item.get('id') or f"item_{content_hash[:12]}",
            'title': working_item.get('title') or working_item.get('source_path') or working_item.get('source_url') or 'source',
            'source_kind': working_item.get('source_kind') or 'unknown',
            'source_path': working_item.get('source_path') or '',
            'source_dataset_path': working_item.get('source_dataset_path') or working_item.get('source_path') or '',
            'source_url': working_item.get('source_url') or '',
            'text': text_value,
            'char_count': len(text_value),
            'sha1': content_hash,
            'preserve_formatting': preserve,
            'structured_example': is_structured,
            'dataset_format': working_item.get('dataset_format') or '',
        }
        for key in ('instruction', 'input', 'output', 'prompt', 'messages', 'raw_text', 'source_row_index', 'code_file', 'code_language'):
            if key in working_item and working_item.get(key) not in (None, ''):
                record[key] = copy.deepcopy(working_item.get(key))
        processed.append(record)
        if is_structured and len(debug_kept_rows) < STUDIO_PATCH_DEBUG_SAMPLE_DUMP_LIMIT:
            debug_kept_rows.append(_studio_record_debug_snapshot(record, reasons=[], label='kept_structured'))
        append_log(f"[preprocess] + {record['id']}")

    out_path = preprocess_dir / 'preprocessed_corpus.jsonl'
    _studio_jsonl_dump(out_path, processed)
    contaminated_dump_path = preprocess_dir / 'debug_preprocess_contaminated_samples.jsonl'
    echo_dump_path = preprocess_dir / 'debug_preprocess_echo_samples.jsonl'
    kept_dump_path = preprocess_dir / 'debug_preprocess_kept_structured_samples.jsonl'
    _studio_write_debug_sample_dump(contaminated_dump_path, debug_contaminated_rows)
    _studio_write_debug_sample_dump(echo_dump_path, debug_echo_rows)
    _studio_write_debug_sample_dump(kept_dump_path, debug_kept_rows)
    report = {
        'stage': 'preprocess',
        'status': 'completed' if processed else 'empty',
        'input_records': len(records),
        'records': len(processed),
        'duplicates_removed': duplicates_removed,
        'near_duplicates_removed': near_duplicates_removed,
        'too_short_removed': too_short_removed,
        'contaminated_removed': contaminated_removed,
        'echo_like_removed': echo_like_removed,
        'structured_example_records': sum(1 for item in processed if item.get('structured_example')),
        'python_code_files': sum(1 for item in processed if item.get('code_file') or str(item.get('source_kind') or '').strip().lower() == 'code_file'),
        'output_path': str(out_path.resolve()),
        'debug_contaminated_dump': str(contaminated_dump_path.resolve()),
        'debug_echo_dump': str(echo_dump_path.resolve()),
        'debug_kept_dump': str(kept_dump_path.resolve()),
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    (preprocess_dir / 'preprocess_report.json').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
    append_log(f"[STUDIO PATCH] {STUDIO_PATCH_FINGERPRINT} ACTIVE | stage=preprocess")
    append_log(
        '[preprocess] '
        + f"input={report['input_records']} | kept={report['records']} | duplicates_removed={report['duplicates_removed']} | near_duplicates_removed={report['near_duplicates_removed']} | contaminated_removed={report['contaminated_removed']} | echo_like_removed={report['echo_like_removed']} | too_short={report['too_short_removed']}"
    )
    append_log(f"[preprocess] debug_dump | kept={kept_dump_path} | contaminated={contaminated_dump_path} | echo={echo_dump_path}")
    if not processed:
        append_log('[preprocess] ! Το preprocessed_corpus.jsonl είναι άδειο. Δεν θα μπορέσει να ξεκινήσει CPT.')
    return report

def _studio_extract_training_text(record: dict[str, Any]) -> str:
    preserve = _studio_should_preserve_record_formatting(record)

    def _clean(value: Any) -> str:
        return _studio_preserve_training_text(value) if preserve else _studio_normalize_space(value)

    pair = _studio_extract_prompt_completion_pair(record)
    if pair is not None:
        prompt_text, completion_text = pair
        if prompt_text and completion_text:
            return _clean(f"User: {prompt_text}\n\nAssistant: {completion_text}")
        if completion_text:
            return _clean(completion_text)
        if prompt_text:
            return _clean(prompt_text)

    messages = record.get('messages')
    if isinstance(messages, list):
        parts = []
        for msg in messages:
            if not isinstance(msg, dict):
                continue
            role = str(msg.get('role') or 'user').strip().title()
            content = str(msg.get('content') or '').strip()
            if role.lower() == 'assistant':
                content = _studio_clean_structured_response_text(content)
            else:
                content = _studio_clean_structured_prompt_text(content)
            if content:
                parts.append(f"{role}: {content}")
        if parts:
            return _clean("\n\n".join(parts))

    for key in ('text', 'content', 'body', 'raw_text'):
        value = record.get(key)
        if isinstance(value, str) and value.strip():
            return _clean(value)

    prompt = _studio_clean_structured_prompt_text(record.get('prompt') or record.get('instruction') or '')
    response = _studio_clean_structured_response_text(record.get('response') or record.get('output') or '')
    if prompt and response:
        joined = f"User: {prompt}\n\nAssistant: {response}"
        return _clean(joined)
    if prompt:
        return _clean(prompt)
    if response:
        return _clean(response)
    return ''


# Ενεργοποίηση του τελικού file-only Collect με αυτόματο structured dataset ingestion.
collect_training_sources = collect_training_sources_local_only

