def _studio_tokenize_text_ids(tokenizer: Any, text: str, *, add_special_tokens: bool = False) -> list[int]:
    text = str(text or '')
    if not text:
        return []
    try:
        tokenized = tokenizer(text, add_special_tokens=add_special_tokens, truncation=False, verbose=False)
    except TypeError:
        tokenized = tokenizer(text, add_special_tokens=add_special_tokens, truncation=False)
    token_ids = tokenized.get('input_ids') or []
    if token_ids and isinstance(token_ids[0], list):
        token_ids = token_ids[0]
    return [int(tok) for tok in token_ids]


def _studio_extract_prompt_completion_pair(record: dict[str, Any]) -> tuple[str, str] | None:
    preserve = _studio_should_preserve_record_formatting(record)

    def _clean(value: Any) -> str:
        return _studio_preserve_training_text(value) if preserve else _studio_normalize_space(value)

    prompt_value = ''
    for key in ('prompt', 'question', 'query', 'task'):
        value = record.get(key)
        if isinstance(value, str) and value.strip():
            prompt_value = value
            break

    instruction = str(record.get('instruction') or '').strip()
    input_text = str(record.get('input') or '').strip()
    response_value = ''
    for key in ('response', 'output', 'answer', 'completion'):
        value = record.get(key)
        if isinstance(value, str) and value.strip():
            response_value = value
            break

    if instruction and response_value:
        prompt_text = _studio_build_alpaca_prompt(instruction, input_text)
        completion_text = _clean(response_value)
        if completion_text:
            return _clean(prompt_text), completion_text

    if prompt_value and response_value:
        prompt_text = _clean(prompt_value)
        completion_text = _clean(response_value)
        if completion_text:
            if prompt_text.endswith(completion_text):
                trimmed_prompt = prompt_text[:-len(completion_text)].rstrip()
                if trimmed_prompt:
                    prompt_text = trimmed_prompt
            return prompt_text, completion_text

    messages = record.get('messages')
    if isinstance(messages, list):
        normalized_messages: list[dict[str, str]] = []
        for msg in messages:
            if not isinstance(msg, dict):
                continue
            role = str(msg.get('role') or 'user').strip().lower() or 'user'
            content = _clean(msg.get('content') or '')
            if content:
                normalized_messages.append({'role': role, 'content': content})
        if normalized_messages:
            last_assistant_index = -1
            for idx in range(len(normalized_messages) - 1, -1, -1):
                if normalized_messages[idx].get('role') == 'assistant':
                    last_assistant_index = idx
                    break
            if last_assistant_index >= 0:
                prompt_parts: list[str] = []
                for msg in normalized_messages[:last_assistant_index]:
                    role = msg.get('role') or 'user'
                    content = msg.get('content') or ''
                    if content:
                        prompt_parts.append(f"{role.title()}: {content}")
                completion_text = normalized_messages[last_assistant_index].get('content') or ''
                if completion_text:
                    prompt_parts.append('Assistant:')
                    prompt_text = '\n\n'.join(part for part in prompt_parts if part).strip()
                    return prompt_text, completion_text

    raw_text = record.get('text') or record.get('raw_text') or ''
    if prompt_value and raw_text and not response_value:
        prompt_text = _clean(prompt_value)
        text_clean = _clean(raw_text)
        if text_clean.startswith(prompt_text):
            completion_text = text_clean[len(prompt_text):].lstrip('\n ')
            if completion_text:
                return prompt_text, completion_text

    return None



def _studio_build_messages_response_only_item(record: dict[str, Any], tokenizer: Any, max_length: int) -> dict[str, Any] | None:
    messages = record.get('messages')
    if not isinstance(messages, list):
        return None

    normalized_messages: list[dict[str, str]] = []
    for msg in messages:
        if not isinstance(msg, dict):
            continue
        role = str(msg.get('role') or 'user').strip().lower() or 'user'
        content = str(msg.get('content') or '').strip()
        if not content:
            continue
        if role == 'assistant':
            content = _studio_clean_structured_response_text(content)
        else:
            content = _studio_clean_structured_prompt_text(content)
        if content:
            normalized_messages.append({'role': role, 'content': content})

    if not normalized_messages:
        return None

    last_assistant_index = -1
    for idx in range(len(normalized_messages) - 1, -1, -1):
        if normalized_messages[idx].get('role') == 'assistant':
            last_assistant_index = idx
            break
    if last_assistant_index < 0:
        return None

    prompt_messages = normalized_messages[:last_assistant_index]
    assistant_message = normalized_messages[last_assistant_index]
    completion_text = str(assistant_message.get('content') or '').strip()
    if not completion_text:
        return None

    prompt_text = _studio_render_chat_text(tokenizer, prompt_messages, add_generation_prompt=True)
    full_text = _studio_render_chat_text(tokenizer, prompt_messages + [assistant_message], add_generation_prompt=False)

    prompt_ids = _studio_tokenize_text_ids(tokenizer, prompt_text, add_special_tokens=False)
    full_ids = _studio_tokenize_text_ids(tokenizer, full_text, add_special_tokens=False)
    if not prompt_ids or not full_ids:
        return None

    if len(full_ids) <= len(prompt_ids):
        return None
    if full_ids[:len(prompt_ids)] != prompt_ids:
        return None

    completion_ids = full_ids[len(prompt_ids):]
    if not completion_ids:
        return None

    input_ids = list(full_ids)
    labels = ([-100] * len(prompt_ids)) + list(completion_ids)

    if max_length > 0 and len(input_ids) > max_length:
        active_len = len(completion_ids)
        if active_len >= max_length:
            input_ids = input_ids[-max_length:]
            labels = labels[-max_length:]
        else:
            keep_prompt_tokens = max_length - active_len
            if keep_prompt_tokens < len(prompt_ids):
                input_ids = input_ids[len(prompt_ids) - keep_prompt_tokens:]
                labels = labels[len(prompt_ids) - keep_prompt_tokens:]

    if not input_ids or _studio_count_active_labels(labels) <= 0:
        return None

    attention_mask = [1] * len(input_ids)
    return {
        'input_ids': [int(tok) for tok in input_ids],
        'attention_mask': [int(tok) for tok in attention_mask],
        'labels': [int(tok) for tok in labels],
        'response_only': True,
        'structured_example': True,
        'templated_messages': True,
        'rendered_prompt_preview': prompt_text[:500],
        'rendered_full_preview': full_text[:500],
    }


def _studio_build_response_only_item(record: dict[str, Any], tokenizer: Any, max_length: int) -> dict[str, Any] | None:
    templated_messages_item = _studio_build_messages_response_only_item(record, tokenizer, max_length=max_length)
    if templated_messages_item is not None:
        return templated_messages_item

    pair = _studio_extract_prompt_completion_pair(record)
    if not pair:
        return None

    prompt_text, completion_text = pair
    prompt_ids = _studio_tokenize_text_ids(tokenizer, prompt_text, add_special_tokens=False)
    completion_ids = _studio_tokenize_text_ids(tokenizer, completion_text, add_special_tokens=False)
    if not completion_ids:
        return None

    bos_id = getattr(tokenizer, 'bos_token_id', None)
    eos_id = getattr(tokenizer, 'eos_token_id', None)

    prefix_ids: list[int] = []
    if bos_id is not None:
        prefix_ids.append(int(bos_id))
    prefix_ids.extend(prompt_ids)

    completion_part_ids = list(completion_ids)
    if eos_id is not None:
        completion_part_ids.append(int(eos_id))

    if max_length > 0:
        if len(completion_part_ids) >= max_length:
            completion_part_ids = completion_part_ids[:max_length]
            prefix_ids = []
        else:
            keep_prompt_tokens = max_length - len(completion_part_ids)
            if len(prefix_ids) > keep_prompt_tokens:
                prefix_ids = prefix_ids[-keep_prompt_tokens:]

    input_ids = prefix_ids + completion_part_ids
    if not input_ids:
        return None

    labels = ([-100] * len(prefix_ids)) + list(completion_part_ids)
    if len(labels) != len(input_ids):
        return None

    item = {
        'input_ids': input_ids,
        'attention_mask': [1] * len(input_ids),
        'labels': labels,
        'structured_example': True,
        'response_only': True,
    }
    return item


class _StudioSmartDataCollatorForLanguageModeling:
    def __init__(self, tokenizer: Any, mlm: bool = False, pad_to_multiple_of: int | None = None, **_: Any) -> None:
        self.tokenizer = tokenizer
        self.mlm = bool(mlm)
        self.pad_to_multiple_of = pad_to_multiple_of

    def __call__(self, features: list[dict[str, Any]]) -> Any:
        import torch

        if not features:
            return {
                'input_ids': torch.empty((0, 0), dtype=torch.long),
                'attention_mask': torch.empty((0, 0), dtype=torch.long),
                'labels': torch.empty((0, 0), dtype=torch.long),
            }

        token_features: list[dict[str, Any]] = []
        for feature in features:
            token_features.append({
                'input_ids': list(feature.get('input_ids') or []),
                'attention_mask': list(feature.get('attention_mask') or ([1] * len(feature.get('input_ids') or []))),
            })

        batch = self.tokenizer.pad(
            token_features,
            padding=True,
            pad_to_multiple_of=self.pad_to_multiple_of,
            return_tensors='pt',
        )

        has_explicit_labels = any('labels' in feature and feature.get('labels') is not None for feature in features)
        if has_explicit_labels:
            max_len = int(batch['input_ids'].shape[1]) if getattr(batch.get('input_ids'), 'shape', None) is not None else 0
            padding_side = str(getattr(self.tokenizer, 'padding_side', 'right') or 'right').lower()
            padded_labels: list[list[int]] = []
            for feature in features:
                label_ids = [int(x) for x in list(feature.get('labels') or [])]
                if len(label_ids) > max_len:
                    label_ids = label_ids[:max_len] if padding_side == 'right' else label_ids[-max_len:]
                pad_len = max_len - len(label_ids)
                if padding_side == 'left':
                    label_ids = ([-100] * pad_len) + label_ids
                else:
                    label_ids = label_ids + ([-100] * pad_len)
                padded_labels.append(label_ids)
            batch['labels'] = torch.tensor(padded_labels, dtype=torch.long)
            return batch

        labels = batch['input_ids'].clone()
        pad_token_id = getattr(self.tokenizer, 'pad_token_id', None)
        if pad_token_id is not None:
            labels[labels == int(pad_token_id)] = -100
        batch['labels'] = labels
        return batch


def _studio_import_training_stack(require_peft: bool = False):
    try:
        import torch
        from transformers import (
            AutoModelForCausalLM,
            AutoTokenizer,
            DataCollatorForLanguageModeling,
            Trainer,
            TrainingArguments,
        )
    except Exception as exc:
        raise RuntimeError(
            "Λείπουν πακέτα training. Εγκατέστησε: pip install -U torch transformers accelerate"
        ) from exc

    peft_exports = {}
    if require_peft:
        try:
            from peft import LoraConfig, PeftModel, TaskType, get_peft_model
            peft_exports = {
                'LoraConfig': LoraConfig,
                'PeftModel': PeftModel,
                'TaskType': TaskType,
                'get_peft_model': get_peft_model,
            }
        except Exception as exc:
            raise RuntimeError("Λείπει το πακέτο peft. Εγκατέστησε: pip install -U peft") from exc

    stack = {
        'torch': torch,
        'AutoModelForCausalLM': AutoModelForCausalLM,
        'AutoTokenizer': AutoTokenizer,
        'DataCollatorForLanguageModeling': _StudioSmartDataCollatorForLanguageModeling,
        'Trainer': Trainer,
        'TrainingArguments': TrainingArguments,
        **peft_exports,
    }
    try:
        from transformers import TrainerCallback as _HFTrainerCallback  # type: ignore
        stack['TrainerCallback'] = _HFTrainerCallback
    except Exception:
        pass
    try:
        from datasets import Dataset as _HFDataset  # type: ignore
        stack['Dataset'] = _HFDataset
    except Exception:
        pass
    return stack


def _studio_build_plain_lm_items(records: list[dict[str, Any]], tokenizer: Any, max_length: int, max_train_samples: int = 0) -> tuple[list[dict[str, Any]], int]:
    items: list[dict[str, Any]] = []
    aggregate_token_ids: list[int] = []
    total_raw_tokens = 0
    eos_id = getattr(tokenizer, 'eos_token_id', None)
    chunk_size = max(128, int(max_length))
    min_chunk = max(32, min(128, chunk_size // 4))

    for record in records:
        text = _studio_extract_training_text(record)
        if not text:
            continue
        token_ids = _studio_tokenize_text_ids(tokenizer, text, add_special_tokens=True)
        if not token_ids:
            continue
        total_raw_tokens += len(token_ids)
        if eos_id is not None and token_ids[-1] != int(eos_id):
            token_ids = token_ids + [int(eos_id)]
        aggregate_token_ids.extend(token_ids)

    if aggregate_token_ids:
        for start in range(0, len(aggregate_token_ids), chunk_size):
            chunk = aggregate_token_ids[start:start + chunk_size]
            if len(chunk) < min_chunk:
                continue
            items.append({'input_ids': chunk, 'attention_mask': [1] * len(chunk)})
            if max_train_samples and len(items) >= max_train_samples:
                break

    if max_train_samples:
        items = items[:max_train_samples]
    return items, total_raw_tokens


def _studio_prepare_lm_items(records: list[dict[str, Any]], tokenizer: Any, max_length: int, max_train_samples: int = 0, stage_key: str = 'cpt') -> tuple[list[dict[str, Any]], int]:
    stage_key = str(stage_key or 'cpt').strip().lower()
    if stage_key != 'sft':
        return _studio_build_plain_lm_items(records, tokenizer, max_length=max_length, max_train_samples=max_train_samples)

    items: list[dict[str, Any]] = []
    total_raw_tokens = 0
    fallback_records: list[dict[str, Any]] = []

    for record in records:
        response_only_item = _studio_build_response_only_item(record, tokenizer, max_length=max_length)
        if response_only_item is not None:
            item_len = len(response_only_item.get('input_ids') or [])
            total_raw_tokens += item_len
            if item_len >= 4:
                items.append(response_only_item)
            if max_train_samples and len(items) >= max_train_samples:
                return items[:max_train_samples], total_raw_tokens
            continue
        fallback_records.append(record)

    remaining_limit = (max_train_samples - len(items)) if max_train_samples else 0
    fallback_items, fallback_tokens = _studio_build_plain_lm_items(
        fallback_records,
        tokenizer,
        max_length=max_length,
        max_train_samples=remaining_limit if remaining_limit > 0 else 0,
    )
    items.extend(fallback_items)
    total_raw_tokens += fallback_tokens

    if max_train_samples:
        items = items[:max_train_samples]
    return items, total_raw_tokens


def _studio_stage_log_dataset_breakdown(stage_key: str, train_records: list[dict[str, Any]], eval_records: list[dict[str, Any]], train_items: list[dict[str, Any]], total_raw_tokens: int, max_length: int, trainable_params: int, total_params: int) -> None:
    stage_label = str(stage_key or '').strip()
    raw_train_count = len(train_records)
    raw_eval_count = len(eval_records)
    total_raw_records = raw_train_count + raw_eval_count
    runtime_sequence_count = len(train_items)

    avg_tokens_per_raw_record = (float(total_raw_tokens) / float(raw_train_count)) if raw_train_count > 0 else 0.0
    avg_tokens_per_runtime_sequence = (float(total_raw_tokens) / float(runtime_sequence_count)) if runtime_sequence_count > 0 else 0.0

    runtime_label = 'Packed train sequences' if str(stage_key or '').strip().lower() == 'cpt' else 'Prepared train items'

    append_log(
        f"[{stage_label}] Raw records | total={total_raw_records:,} | train={raw_train_count:,} | eval={raw_eval_count:,}"
    )
    append_log(
        f"[{stage_label}] Tokenization | train_tokens={total_raw_tokens:,} | avg_tokens/raw_train_record={avg_tokens_per_raw_record:.2f}"
    )
    append_log(
        f"[{stage_label}] {runtime_label} | count={runtime_sequence_count:,} | avg_tokens/runtime_sequence={avg_tokens_per_runtime_sequence:.2f} | max_seq_length={int(max_length)}"
    )
    append_log(
        f"[{stage_label}] Trainable params | trainable={trainable_params:,}/{total_params:,}"
    )

# =============================================================================
# ===== END RESPONSE-ONLY STRUCTURED SFT PATCH ================================
# =============================================================================


# =============================================================================
# ===== XLSX STRUCTURED DATASET SUPPORT PATCH =================================
# =============================================================================

_STUDIO_PREV_ENSURE_RUNTIME_DEFAULTS_XLSX = _studio_ensure_runtime_defaults

def _studio_ensure_runtime_defaults(config: dict[str, Any]) -> dict[str, Any]:
    config = _STUDIO_PREV_ENSURE_RUNTIME_DEFAULTS_XLSX(config)
    dataset = config.setdefault('dataset', {})
    training = config.setdefault('training', {})
    ext_order = [str(x).strip().lower() for x in list(dataset.get('source_extensions') or []) if str(x).strip()]
    for ext in ['.xlsx', '.xlsm']:
        if ext not in ext_order:
            ext_order.append(ext)
    dataset['source_extensions'] = ext_order
    if training.get('weight_decay') is None:
        training['weight_decay'] = 0.01
    # Global runtime policy: never rely on FlashAttention-only paths.
    training['packing'] = False
    training['padding_free'] = False
    training['attn_implementation'] = 'sdpa'
    return config


def _studio_is_missing_openpyxl_error(exc: Exception | None) -> bool:
    if exc is None:
        return False
    if isinstance(exc, ModuleNotFoundError) and str(getattr(exc, 'name', '') or '').strip().lower() == 'openpyxl':
        return True
    message = str(exc).strip().lower()
    return 'openpyxl' in message and ('no module named' in message or 'module not found' in message)


def _studio_format_collect_file_error(path: Path, exc: Exception) -> str:
    suffix = path.suffix.lower()
    if suffix in {'.xlsx', '.xlsm'} and _studio_is_missing_openpyxl_error(exc):
        return (
            'Λείπει το openpyxl για ανάγνωση αρχείων Excel (.xlsx/.xlsm). '
            'Εγκατάστησέ το με: pip install openpyxl'
        )
    message = str(exc).strip()
    return message or f'{exc.__class__.__name__} χωρίς επιπλέον λεπτομέρειες'


def _studio_extract_structured_rows_from_excel(path: Path) -> list[dict[str, Any]]:
    suffix = path.suffix.lower()
    rows: list[dict[str, Any]] = []

    def _normalize_header(value: Any) -> str:
        return str(value or '').strip()

    def _append_sheet_rows(sheet_name: str, table_rows: list[list[Any]]) -> None:
        if not table_rows:
            return
        header_index = -1
        headers: list[str] = []
        for index, raw_row in enumerate(table_rows):
            if not raw_row:
                continue
            if any(str(cell or '').strip() for cell in raw_row):
                header_index = index
                headers = [_normalize_header(cell) for cell in raw_row]
                break
        if header_index < 0 or not _studio_structured_fieldnames_look_supported(headers):
            return
        for raw_row in table_rows[header_index + 1:]:
            if not raw_row or not any(str(cell or '').strip() for cell in raw_row):
                continue
            padded = list(raw_row) + [None] * max(0, len(headers) - len(raw_row))
            row = {headers[idx]: padded[idx] if idx < len(padded) else None for idx in range(len(headers)) if headers[idx]}
            if row:
                row['_sheet_name'] = sheet_name
                rows.append(row)

    def _read_xlsx_with_openpyxl() -> list[dict[str, Any]]:
        from openpyxl import load_workbook  # type: ignore

        workbook = load_workbook(filename=str(path), read_only=True, data_only=True)
        try:
            workbook_rows: list[dict[str, Any]] = []
            for sheet in workbook.worksheets:
                table_rows = [list(raw_row or ()) for raw_row in sheet.iter_rows(values_only=True)]
                temp_rows: list[dict[str, Any]] = []
                header_index = -1
                headers: list[str] = []
                for index, raw_row in enumerate(table_rows):
                    if not raw_row:
                        continue
                    if any(str(cell or '').strip() for cell in raw_row):
                        header_index = index
                        headers = [_normalize_header(cell) for cell in raw_row]
                        break
                if header_index < 0 or not _studio_structured_fieldnames_look_supported(headers):
                    continue
                for raw_row in table_rows[header_index + 1:]:
                    if not raw_row or not any(str(cell or '').strip() for cell in raw_row):
                        continue
                    padded = list(raw_row) + [None] * max(0, len(headers) - len(raw_row))
                    row = {headers[idx]: padded[idx] if idx < len(padded) else None for idx in range(len(headers)) if headers[idx]}
                    if row:
                        row['_sheet_name'] = sheet.title
                        temp_rows.append(row)
                workbook_rows.extend(temp_rows)
            return workbook_rows
        finally:
            workbook.close()

    def _read_xlsx_with_stdlib() -> list[dict[str, Any]]:
        import posixpath
        import zipfile
        import xml.etree.ElementTree as ET

        ns_main = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
        ns_rel_doc = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'
        ns_rel_pkg = '{http://schemas.openxmlformats.org/package/2006/relationships}'

        def _col_to_index(cell_ref: str) -> int:
            letters = ''.join(ch for ch in str(cell_ref or '') if ch.isalpha()).upper()
            if not letters:
                return -1
            index = 0
            for ch in letters:
                index = (index * 26) + (ord(ch) - ord('A') + 1)
            return index - 1

        def _cell_text(cell_el: Any, shared_strings: list[str]) -> Any:
            cell_type = str(cell_el.attrib.get('t') or '').strip()
            inline_node = cell_el.find(f'{ns_main}is')
            if inline_node is not None:
                inline_parts = [node.text or '' for node in inline_node.iter() if str(node.tag).endswith('}t')]
                inline_text = ''.join(inline_parts).strip()
                if inline_text:
                    return inline_text
            value_node = cell_el.find(f'{ns_main}v')
            value_text = (value_node.text or '').strip() if value_node is not None and value_node.text is not None else ''
            if cell_type == 's':
                if value_text.isdigit():
                    index = int(value_text)
                    if 0 <= index < len(shared_strings):
                        return shared_strings[index]
                return value_text
            if cell_type == 'b':
                return 'TRUE' if value_text == '1' else 'FALSE'
            if cell_type in {'str', 'inlineStr'}:
                return value_text
            if value_text == '':
                return None
            try:
                number = float(value_text)
                if number.is_integer():
                    return int(number)
                return number
            except Exception:
                return value_text

        workbook_rows: list[dict[str, Any]] = []
        with zipfile.ZipFile(path) as zf:
            shared_strings: list[str] = []
            if 'xl/sharedStrings.xml' in zf.namelist():
                shared_root = ET.fromstring(zf.read('xl/sharedStrings.xml'))
                for si in shared_root.findall(f'{ns_main}si'):
                    parts = [node.text or '' for node in si.iter() if str(node.tag).endswith('}t')]
                    shared_strings.append(''.join(parts))

            rel_map: dict[str, str] = {}
            rels_path = 'xl/_rels/workbook.xml.rels'
            if rels_path in zf.namelist():
                rels_root = ET.fromstring(zf.read(rels_path))
                for rel in rels_root.findall(f'{ns_rel_pkg}Relationship'):
                    rel_id = str(rel.attrib.get('Id') or '').strip()
                    target = str(rel.attrib.get('Target') or '').strip()
                    if rel_id and target:
                        normalized = posixpath.normpath(posixpath.join('xl', target))
                        rel_map[rel_id] = normalized

            workbook_root = ET.fromstring(zf.read('xl/workbook.xml'))
            sheets_parent = workbook_root.find(f'{ns_main}sheets')
            if sheets_parent is None:
                return workbook_rows

            for sheet in sheets_parent.findall(f'{ns_main}sheet'):
                sheet_name = str(sheet.attrib.get('name') or '').strip() or 'Sheet'
                rel_id = str(sheet.attrib.get(f'{ns_rel_doc}id') or '').strip()
                sheet_path = rel_map.get(rel_id, '')
                if not sheet_path or sheet_path not in zf.namelist():
                    continue
                sheet_root = ET.fromstring(zf.read(sheet_path))
                sheet_data = sheet_root.find(f'{ns_main}sheetData')
                if sheet_data is None:
                    continue
                table_rows: list[list[Any]] = []
                for row_el in sheet_data.findall(f'{ns_main}row'):
                    values_by_index: dict[int, Any] = {}
                    sequential_index = 0
                    for cell_el in row_el.findall(f'{ns_main}c'):
                        ref = str(cell_el.attrib.get('r') or '').strip()
                        col_index = _col_to_index(ref)
                        if col_index < 0:
                            col_index = sequential_index
                        sequential_index = max(sequential_index, col_index + 1)
                        values_by_index[col_index] = _cell_text(cell_el, shared_strings)
                    if not values_by_index:
                        table_rows.append([])
                        continue
                    max_index = max(values_by_index)
                    row_values = [None] * (max_index + 1)
                    for idx, value in values_by_index.items():
                        if idx >= 0:
                            row_values[idx] = value
                    table_rows.append(row_values)
                _append_sheet_rows(sheet_name, table_rows)
        return workbook_rows or rows

    if suffix in {'.xlsx', '.xlsm'}:
        openpyxl_exc: Exception | None = None
        try:
            rows_from_openpyxl = _read_xlsx_with_openpyxl()
            if rows_from_openpyxl:
                return rows_from_openpyxl
        except Exception as exc:
            openpyxl_exc = exc

        try:
            rows_before = len(rows)
            stdlib_rows = _read_xlsx_with_stdlib()
            if stdlib_rows:
                if openpyxl_exc is not None:
                    try:
                        append_log(
                            f"[collect] ℹ Fallback ανάγνωσης Excel χωρίς openpyxl για: {path.name}. "
                            "Για πλήρη συμβατότητα εγκατάστησε: pip install openpyxl"
                        )
                    except Exception:
                        pass
                return stdlib_rows
            if openpyxl_exc is not None and not _studio_is_missing_openpyxl_error(openpyxl_exc):
                raise openpyxl_exc
            if len(rows) > rows_before:
                return rows
        except Exception:
            if openpyxl_exc is not None:
                raise openpyxl_exc
            raise
        if openpyxl_exc is not None and not _studio_is_missing_openpyxl_error(openpyxl_exc):
            raise openpyxl_exc
        return rows

    if suffix == '.xls':
        try:
            import pandas as pd  # type: ignore
            excel_file = pd.ExcelFile(path)
            for sheet_name in excel_file.sheet_names:
                df = excel_file.parse(sheet_name=sheet_name)
                headers = [str(col or '').strip() for col in list(df.columns)]
                if not _studio_structured_fieldnames_look_supported(headers):
                    continue
                for _, series in df.iterrows():
                    row = {str(col or '').strip(): (None if pd.isna(value) else value) for col, value in series.to_dict().items()}
                    if any(str(v or '').strip() for v in row.values()):
                        row['_sheet_name'] = sheet_name
                        rows.append(row)
        except Exception:
            return []
    return rows


def _studio_load_structured_dataset_examples(path: Path) -> list[dict[str, Any]]:
    suffix = path.suffix.lower()
    rows: list[dict[str, Any]] = []

    if suffix in {'.xlsx', '.xlsm', '.xls'}:
        for row in _studio_extract_structured_rows_from_excel(path):
            payload = _studio_structured_row_to_sft_payload(row)
            if payload is not None:
                sheet_name = str(row.get('_sheet_name') or '').strip()
                if sheet_name:
                    payload['sheet_name'] = sheet_name
                rows.append(payload)
        return rows

    if suffix in {'.csv', '.tsv'}:
        import csv
        import io
        raw_text = _studio_read_text_file(path)
        if not raw_text.strip():
            return []
        delimiter = '	' if suffix == '.tsv' else ','
        try:
            sample = raw_text[:8192]
            dialect = csv.Sniffer().sniff(sample, delimiters=',;	')
            delimiter = dialect.delimiter
        except Exception:
            pass
        reader = csv.DictReader(io.StringIO(raw_text), delimiter=delimiter)
        fieldnames = [str(name or '').strip() for name in (reader.fieldnames or [])]
        if not _studio_structured_fieldnames_look_supported(fieldnames):
            return []
        for row in reader:
            if not isinstance(row, dict):
                continue
            if not any(_studio_row_value_as_text(value).strip() for value in row.values()):
                continue
            rows.append(dict(row))
    elif suffix == '.jsonl':
        parsed_rows = _studio_jsonl_load(path)
        if not parsed_rows:
            return []
        preview_keys: list[str] = []
        for item in parsed_rows[:5]:
            if isinstance(item, dict):
                preview_keys.extend([str(k or '') for k in item.keys()])
        if not _studio_structured_fieldnames_look_supported(preview_keys):
            return []
        rows = [dict(item) for item in parsed_rows if isinstance(item, dict)]
    elif suffix == '.json':
        try:
            payload = json.loads(_studio_read_text_file(path))
        except Exception:
            return []
        items: list[Any] = []
        if isinstance(payload, list):
            items = payload
        elif isinstance(payload, dict):
            for key in ('records', 'items', 'data', 'examples', 'dataset', 'rows'):
                value = payload.get(key)
                if isinstance(value, list):
                    items = value
                    break
            if not items and _studio_row_to_lower_map(payload):
                items = [payload]
        preview_keys: list[str] = []
        for item in items[:5]:
            if isinstance(item, dict):
                preview_keys.extend([str(k or '') for k in item.keys()])
        if not _studio_structured_fieldnames_look_supported(preview_keys):
            return []
        rows = [dict(item) for item in items if isinstance(item, dict)]
    else:
        return []

    converted: list[dict[str, Any]] = []
    for row in rows:
        payload = _studio_structured_row_to_sft_payload(row)
        if payload is not None:
            converted.append(payload)
    return converted

def _studio_read_text_file_v3(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix in {'.xlsx', '.xlsm'}:
        rows = _studio_extract_structured_rows_from_excel(path)
        if rows:
            parts: list[str] = []
            for row in rows[:500]:
                visible = []
                for key, value in row.items():
                    if str(key).startswith('_'):
                        continue
                    cell = _studio_row_value_as_text(value).strip()
                    if cell:
                        visible.append(f'{key}: {cell}')
                if visible:
                    parts.append('\n'.join(visible))
            return '\n\n'.join(parts).strip()
    return _studio_read_text_file_v2(path)


_studio_read_text_file = _studio_read_text_file_v3  # noqa: F811


def _studio_browse_collect_source_files(self) -> None:
    filters = 'Supported Files (*.txt *.md *.rst *.json *.jsonl *.yaml *.yml *.toml *.ini *.cfg *.csv *.tsv *.xlsx *.xlsm *.ipynb *.pdf *.doc *.docx *.html *.htm *.xml *.py *.pyi);;All Files (*)'
    paths, _ = QFileDialog.getOpenFileNames(self, 'Επιλογή αρχείων πηγών για Collect', str(PROJECT_ROOT), filters)
    if not paths:
        return
    merged = _studio_merge_path_lines(_studio_collect_selected_file_lines(self), paths)
    _studio_set_text_widget_lines(getattr(self, 'collect_source_files_edit', None), merged)


try:
    PipelineStudioGUI.browse_collect_source_files = _studio_browse_collect_source_files
except Exception:
    pass

