# =============================================================================
# ===== AUTO TERMINAL FOR CPT / SFT / EVAL PATCH ==============================
# =============================================================================

_STUDIO_STAGE_TERMINAL_STAGES = {
    "collect": "Collect",
    "preprocess": "Preprocess",
    "cpt": "CPT",
    "build_sft": "Build SFT",
    "sft": "Train SFT",
    "eval": "Evaluate",
    "export": "Export",
}
_STUDIO_STAGE_TERMINAL_SENTINEL = "__STUDIO_STAGE_DONE__"
_STUDIO_STAGE_TERMINAL_ACTIVE_LOG: Path | None = None
_STUDIO_STAGE_TERMINAL_PROCS: list[subprocess.Popen] = []
_STUDIO_STAGE_TERMINAL_LOCK = threading.Lock()


def _studio_stage_terminal_log_dir() -> Path:
    folder = LOGS_DIR / "stage_live_logs"
    folder.mkdir(parents=True, exist_ok=True)
    return folder


def _studio_stage_terminal_log_path(stage_key: str) -> Path:
    stamp = time.strftime("%Y%m%d_%H%M%S")
    safe_stage = slugify(stage_key or "stage") or "stage"
    return _studio_stage_terminal_log_dir() / f"{stamp}_{safe_stage}_{os.getpid()}.log"


_STUDIO_STAGE_TERMINAL_RECENT_LINES: dict[str, float] = {}


def _studio_stage_terminal_strip_ansi(text: str) -> str:
    try:
        return re.sub(r'\x1b\[[0-9;?]*[A-Za-z]', '', str(text or ''))
    except Exception:
        return str(text or '')


def _studio_stage_terminal_is_tqdm_noise(text: str) -> bool:
    s = _studio_stage_terminal_strip_ansi(text).strip()
    if not s:
        return False
    try:
        patterns = (
            r'^\d+%\|.*\|\s*\d+/\d+\s*\[.*<.*[, ].*\]$',
            r'^(Loading weights|Adding EOS to train dataset|Tokenizing train dataset|Packing train dataset):\s+\d+%\|',
        )
        return any(re.search(p, s) for p in patterns)
    except Exception:
        return False


def _studio_stage_terminal_label(stage_key: str) -> str:
    key = str(stage_key or '').strip().lower()
    return str((_STUDIO_STAGE_TERMINAL_STAGES.get(key) or key.upper() or 'STAGE'))


def _studio_stage_terminal_pretty_line(text: str) -> str | None:
    s = _studio_stage_terminal_strip_ansi(text)
    if '\r' in s:
        s = s.split('\r')[-1]
    s = s.rstrip('\n').rstrip('\r').strip()
    if not s:
        return None
    if s.startswith(_STUDIO_STAGE_TERMINAL_SENTINEL):
        return s
    if _studio_stage_terminal_is_tqdm_noise(s):
        return s

    try:
        s = re.sub(r'^\[(\d{2}:\d{2}:\d{2})\]\s+\[embedded\]\s+', '', s)
        s = re.sub(r'^\[embedded\]\s+', '', s)

        m = re.match(r'^\[(\d{2}:\d{2}:\d{2})\]\s+\[([^\]]+)\]\s+(.*)$', s)
        if m:
            stage_key = m.group(2).strip().lower()
            rest = m.group(3).strip()
            if stage_key in _STUDIO_STAGE_TERMINAL_STAGES:
                s = f"[{_studio_stage_terminal_label(stage_key)}] {rest}"

        m = re.match(r'^\[([^\]]+)\]\s+(.*)$', s)
        if m:
            stage_key = m.group(1).strip().lower()
            rest = m.group(2).strip()
            if stage_key in _STUDIO_STAGE_TERMINAL_STAGES:
                s = f"[{_studio_stage_terminal_label(stage_key)}] {rest}"

        m = re.match(r'^Εκκίνηση pipeline από στάδιο:\s*([a-zA-Z0-9_\-]+)$', s)
        if m:
            return f"🚀 Εκκίνηση pipeline από στάδιο: {_studio_stage_terminal_label(m.group(1))}"

        m = re.match(r'^Εκκίνηση σταδίου:\s*([a-zA-Z0-9_\-]+)$', s)
        if m:
            label = _studio_stage_terminal_label(m.group(1))
            sep = '═' * 78
            pre_sep = '─' * 78
            return f"{pre_sep}\n▶ ΕΚΚΙΝΗΣΗ ΣΤΑΔΙΟΥ: {label}\n{sep}"

        m = re.match(r'^Ολοκληρώθηκε το στάδιο:\s*([a-zA-Z0-9_\-]+)$', s)
        if m:
            return f"✅ Ολοκληρώθηκε το στάδιο: {_studio_stage_terminal_label(m.group(1))}"

        m = re.match(r'^Αποτυχία σταδίου\s*([a-zA-Z0-9_\-]+)\s*:\s*(.*)$', s)
        if m:
            label = _studio_stage_terminal_label(m.group(1))
            detail = m.group(2).strip()
            return f"❌ Αποτυχία σταδίου: {label}" + (f" | {detail}" if detail else "")

        if s.startswith('Άνοιξε κοινό stage terminal:'):
            return f"🖥 Άνοιξε κοινό stage terminal: {s.split(':', 1)[1].strip()}"
        if s.startswith('Η εκτέλεση του σταδίου ολοκληρώθηκε.'):
            return '✅ Η εκτέλεση του σταδίου ολοκληρώθηκε.'
        if s.startswith('Η εκτέλεση του σταδίου τερματίστηκε με σφάλμα.'):
            return '❌ Η εκτέλεση του σταδίου τερματίστηκε με σφάλμα.'
        if s.startswith('Το pipeline ολοκληρώθηκε επιτυχώς.'):
            return '✅ Το pipeline ολοκληρώθηκε επιτυχώς.'
        if s.startswith('Το pipeline τερματίστηκε με κωδικό'):
            return f"❌ {s}"

        s = s.replace('model dtype=', 'dtype=')
        s = re.sub(r'\s*\|\s*', ' | ', s)
        s = re.sub(r'\s{2,}', ' ', s).strip()
        return s or None
    except Exception:
        return s or None


def _studio_stage_terminal_canonical_line(text: str) -> str:
    s = _studio_stage_terminal_strip_ansi(text)
    if '\r' in s:
        s = s.split('\r')[-1]
    s = s.rstrip('\n').rstrip('\r').strip()
    if not s:
        return ''
    try:
        s = re.sub(r'^\[(\d{2}:\d{2}:\d{2})\]\s+', '', s)
        s = re.sub(r'^\[embedded\]\s+', '', s)
        m = re.match(r'^\[([^\]]+)\]\s+(.*)$', s)
        if m:
            stage_key = m.group(1).strip().lower()
            rest = m.group(2).strip()
            if stage_key in _STUDIO_STAGE_TERMINAL_STAGES:
                s = f"[{_studio_stage_terminal_label(stage_key)}] {rest}"
        s = re.sub(r'\s*\|\s*', ' | ', s)
        s = re.sub(r'\s{2,}', ' ', s).strip()
    except Exception:
        pass
    return s


def _studio_stage_terminal_should_skip(path_obj: Path, pretty: str) -> bool:
    canon = _studio_stage_terminal_canonical_line(pretty)
    if not canon:
        return True
    try:
        now = time.monotonic()
        key = f"{Path(path_obj)}::{canon}"
        recent = globals().setdefault('_STUDIO_STAGE_TERMINAL_RECENT_LINES', {})
        for old_key, old_ts in list(recent.items()):
            if (now - float(old_ts)) > 3.0:
                recent.pop(old_key, None)
        last_ts = recent.get(key)
        if last_ts is not None and (now - float(last_ts)) <= 3.0:
            return True
        recent[key] = now
    except Exception:
        pass
    return False


def _studio_stage_terminal_write_pretty(path_obj: Path, message: str) -> None:
    try:
        msg = str(message or '')
        if msg.startswith(_STUDIO_STAGE_TERMINAL_SENTINEL):
            append_text_line(path_obj, msg)
            return
        pretty = _studio_stage_terminal_pretty_line(msg)
        if not pretty:
            return
        if _studio_stage_terminal_should_skip(path_obj, pretty):
            return
        append_text_line(path_obj, pretty)
        if pretty.startswith('✅ Ολοκληρώθηκε το στάδιο:') or pretty.startswith('❌ Αποτυχία σταδίου:'):
            append_text_line(path_obj, '')
    except Exception:
        pass


def _studio_stage_terminal_append(message: str) -> None:
    log_path = globals().get("_STUDIO_STAGE_TERMINAL_ACTIVE_LOG")
    if not log_path:
        return
    _studio_stage_terminal_write_pretty(Path(log_path), message)


class _StudioStageTerminalTee:
    def __init__(self, original_stream, log_path: Path | None) -> None:
        self._original_stream = original_stream
        self._log_path = Path(log_path) if log_path else None
        self._buffer = ""
        self.encoding = getattr(original_stream, "encoding", "utf-8")

    def write(self, data) -> int:
        text = "" if data is None else str(data)
        try:
            written = self._original_stream.write(text)
        except Exception:
            written = len(text)
        if self._log_path and text:
            self._buffer += text
            while "\n" in self._buffer:
                line, self._buffer = self._buffer.split("\n", 1)
                _studio_stage_terminal_write_pretty(self._log_path, line.rstrip("\r"))
        return written if isinstance(written, int) else len(text)

    def flush(self) -> None:
        try:
            self._original_stream.flush()
        except Exception:
            pass
        if self._log_path and self._buffer:
            _studio_stage_terminal_write_pretty(self._log_path, self._buffer.rstrip("\r"))
            self._buffer = ""

    def isatty(self):
        try:
            return self._original_stream.isatty()
        except Exception:
            return False

    def fileno(self):
        return self._original_stream.fileno()

    def __getattr__(self, name: str):
        return getattr(self._original_stream, name)

def _studio_prune_stage_terminal_processes() -> None:
    try:
        with _STUDIO_STAGE_TERMINAL_LOCK:
            globals()["_STUDIO_STAGE_TERMINAL_PROCS"] = [
                proc for proc in globals().get("_STUDIO_STAGE_TERMINAL_PROCS", [])
                if proc is not None and getattr(proc, "poll", lambda: 0)() is None
            ]
    except Exception:
        pass


def _studio_register_stage_terminal_process(proc: subprocess.Popen | None) -> None:
    if proc is None:
        return
    try:
        _studio_prune_stage_terminal_processes()
        with _STUDIO_STAGE_TERMINAL_LOCK:
            globals().setdefault("_STUDIO_STAGE_TERMINAL_PROCS", []).append(proc)
    except Exception:
        pass


def _studio_close_stage_terminal_process(proc: subprocess.Popen | None, force: bool = False) -> None:
    if proc is None:
        return
    try:
        if proc.poll() is not None:
            return
    except Exception:
        return

    try:
        if os.name == "nt":
            try:
                subprocess.run(
                    ["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    check=False,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                )
            except Exception:
                try:
                    proc.terminate()
                except Exception:
                    pass
        else:
            try:
                proc.terminate()
            except Exception:
                pass
            if force:
                try:
                    proc.kill()
                except Exception:
                    pass
    except Exception:
        pass

    try:
        proc.wait(timeout=1.5)
    except Exception:
        try:
            if proc.poll() is None:
                proc.kill()
        except Exception:
            pass


def _studio_kill_llm_studio_terminal_windows(force: bool = True) -> None:
    if os.name != "nt":
        return

    title_prefix = "LLM Studio -"
    creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)

    try:
        ps_script = rf"""
$ErrorActionPreference = 'SilentlyContinue'
Get-Process |
    Where-Object {{
        $_.MainWindowTitle -like '{title_prefix}*' -and
        ($_.ProcessName -match '^(powershell|pwsh|WindowsTerminal|OpenConsole|conhost|cmd)$')
    }} |
    ForEach-Object {{
        try {{
            Stop-Process -Id $_.Id {'-Force' if force else ''} -ErrorAction SilentlyContinue
        }} catch {{}}
    }}
""".strip()
        subprocess.run(
            [
                "powershell.exe",
                "-NoProfile",
                "-ExecutionPolicy",
                "Bypass",
                "-Command",
                ps_script,
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
            creationflags=creationflags,
        )
    except Exception:
        pass


def _studio_close_all_stage_terminals(force: bool = True) -> None:
    procs: list[subprocess.Popen] = []
    try:
        with _STUDIO_STAGE_TERMINAL_LOCK:
            procs = list(globals().get("_STUDIO_STAGE_TERMINAL_PROCS", []))
            globals()["_STUDIO_STAGE_TERMINAL_PROCS"] = []
    except Exception:
        try:
            procs = list(globals().get("_STUDIO_STAGE_TERMINAL_PROCS", []))
        except Exception:
            procs = []
        globals()["_STUDIO_STAGE_TERMINAL_PROCS"] = []

    for proc in procs:
        _studio_close_stage_terminal_process(proc, force=force)

    # Fallback για terminals που άνοιξαν από child/internal process και δεν
    # υπάρχουν πια στο τοπικό tracked list του κύριου GUI process.
    try:
        _studio_kill_llm_studio_terminal_windows(force=force)
    except Exception:
        pass


_STUDIO_PREV_APPEND_LOG_STAGE_TERMINAL = append_log


def _studio_append_log_with_stage_terminal(message: str) -> None:
    _STUDIO_PREV_APPEND_LOG_STAGE_TERMINAL(message)
    try:
        line = f"[{time.strftime('%H:%M:%S')}] {message}"
        _studio_stage_terminal_append(line)
    except Exception:
        pass


append_log = _STUDIO_PREV_APPEND_LOG_STAGE_TERMINAL  # noqa: F811


_STUDIO_PREV_RUN_EMBEDDED_STAGE_STAGE_TERMINAL = run_embedded_stage


def run_embedded_stage(stage_key: str, config_path: Path) -> int:
    stage_key = str(stage_key or "").strip().lower()
    previous_stage_log = globals().get("_STUDIO_STAGE_TERMINAL_ACTIVE_LOG")
    stage_log_path: Path | None = None
    terminal_opened = False
    success = False

    if stage_key in _STUDIO_STAGE_TERMINAL_STAGES:
        stage_log_path = _studio_stage_terminal_log_path(stage_key)
        globals()["_STUDIO_STAGE_TERMINAL_ACTIVE_LOG"] = stage_log_path
        header = f"[{time.strftime('%H:%M:%S')}] [embedded] Εκκίνηση live log για στάδιο: {stage_key}"
        _studio_stage_terminal_append(header)
        terminal_opened = _studio_open_stage_terminal(stage_key, stage_log_path)
        try:
            status_text = (
                f"[embedded] Άνοιξε terminal παρακολούθησης για {stage_key}: {stage_log_path}"
                if terminal_opened
                else f"[embedded] Live log αρχείου για {stage_key}: {stage_log_path}"
            )
            print(status_text, flush=True)
            _studio_stage_terminal_append(f"[{time.strftime('%H:%M:%S')}] {status_text}")
        except Exception:
            pass

    _prev_stdout = sys.stdout
    _prev_stderr = sys.stderr
    if stage_log_path is not None:
        sys.stdout = _StudioStageTerminalTee(_prev_stdout, stage_log_path)
        sys.stderr = _StudioStageTerminalTee(_prev_stderr, stage_log_path)

    try:
        code = _STUDIO_PREV_RUN_EMBEDDED_STAGE_STAGE_TERMINAL(stage_key, config_path)
        success = (code == 0)
        return code
    finally:
        try:
            if stage_log_path is not None:
                try:
                    sys.stdout.flush()
                except Exception:
                    pass
                try:
                    sys.stderr.flush()
                except Exception:
                    pass
        finally:
            sys.stdout = _prev_stdout
            sys.stderr = _prev_stderr
        if stage_log_path is not None:
            try:
                final_line = (
                    f"[{time.strftime('%H:%M:%S')}] [embedded] Ολοκληρώθηκε το στάδιο: {stage_key}"
                    if success
                    else f"[{time.strftime('%H:%M:%S')}] [embedded] Το στάδιο τερμάτισε με σφάλμα: {stage_key}"
                )
                _studio_stage_terminal_append(final_line)
                _studio_stage_terminal_append(f"{_STUDIO_STAGE_TERMINAL_SENTINEL}::{stage_key}::{int(success)}")
            except Exception:
                pass
        globals()["_STUDIO_STAGE_TERMINAL_ACTIVE_LOG"] = previous_stage_log


# =============================================================================
# ===== END AUTO TERMINAL FOR CPT / SFT / EVAL PATCH ==========================
# =============================================================================

# ===== SINGLE LIVE TERMINAL ONLY FIX =========================================
# Keep the single live terminal opened by the outer command runner and disable
# the extra per-stage terminal that was being opened inside embedded stages.
# This block is intentionally placed BEFORE main() so it is active at runtime.


# ===== END SINGLE LIVE TERMINAL ONLY FIX =====================================


# ===== SINGLE SHARED STAGE TERMINAL ONLY FIX ================================
# Use only ONE shared stage terminal for κάθε training run/pipeline.
# Disable the outer live terminal launcher and keep a single stage terminal
# open across all stages. The terminal stays open until the user closes it.

_STUDIO_STAGE_TERMINAL_SHARED_LOG: Path | None = None
_STUDIO_STAGE_TERMINAL_PIPELINE_ACTIVE = False

try:
    _STUDIO_STAGE_TERMINAL_STAGES.setdefault("pipeline", "Pipeline")
except Exception:
    pass


def _studio_is_live_terminal_command(command: list[str] | tuple[str, ...]) -> bool:
    return False


def _studio_stage_terminal_title_label(stage_key: str) -> str:
    key = str(stage_key or '').strip().lower()
    return _STUDIO_STAGE_TERMINAL_STAGES.get(key, key.upper() or 'Stage')


def _studio_open_stage_terminal(stage_key: str, log_path: Path) -> bool:
    if os.name != 'nt':
        return False
    try:
        import base64

        stage_label = _studio_stage_terminal_title_label(stage_key)
        title_text = f"LLM Studio - {stage_label}"
        ps_path = str(log_path.resolve()).replace("'", "''")
        sentinel = _STUDIO_STAGE_TERMINAL_SENTINEL.replace("'", "''")
        script = f"""
$ErrorActionPreference = 'SilentlyContinue'
$Host.UI.RawUI.WindowTitle = '{title_text}'
$p = '{ps_path}'
$sep = ('=' * 72)
Write-Host $sep -ForegroundColor DarkCyan
Write-Host ('LLM Studio  |  ' + '{stage_label}') -ForegroundColor Cyan
Write-Host ('Live log: ' + $p) -ForegroundColor DarkGray
Write-Host $sep -ForegroundColor DarkCyan
Write-Host ''
while (-not (Test-Path -LiteralPath $p)) {{
    Start-Sleep -Milliseconds 250
}}
Get-Content -LiteralPath $p -Wait -Encoding UTF8 | ForEach-Object {{
    if ($_ -like '{sentinel}*') {{
        break
    }}
    if ([string]::IsNullOrWhiteSpace($_)) {{
        return
    }}
    Write-Host $_
}}
Write-Host ''
Write-Host $sep -ForegroundColor DarkCyan
Write-Host 'Η παρακολούθηση ολοκληρώθηκε. Το παράθυρο μένει ανοιχτό.' -ForegroundColor Green
Write-Host $sep -ForegroundColor DarkCyan
Write-Host 'Κλείσε το παράθυρο όταν θελήσεις.' -ForegroundColor Yellow
""".strip()
        encoded = base64.b64encode(script.encode('utf-16le')).decode('ascii')
        proc = subprocess.Popen(
            ['powershell.exe', '-NoExit', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-EncodedCommand', encoded],
            creationflags=getattr(subprocess, 'CREATE_NEW_CONSOLE', 0),
            cwd=str(PROJECT_ROOT),
        )
        _studio_register_stage_terminal_process(proc)
        return True
    except Exception as exc:
        try:
            print(f"[embedded] ⚠ Αποτυχία ανοίγματος terminal για {stage_key}: {exc}", flush=True)
        except Exception:
            pass
        return False


def _studio_begin_shared_stage_terminal(stage_key: str) -> Path | None:
    shared_log = globals().get('_STUDIO_STAGE_TERMINAL_SHARED_LOG')
    if shared_log:
        try:
            shared_path = Path(shared_log)
            globals()['_STUDIO_STAGE_TERMINAL_ACTIVE_LOG'] = shared_path
            return shared_path
        except Exception:
            pass

    stage_log_path = _studio_stage_terminal_log_path(stage_key)
    globals()['_STUDIO_STAGE_TERMINAL_SHARED_LOG'] = stage_log_path
    globals()['_STUDIO_STAGE_TERMINAL_ACTIVE_LOG'] = stage_log_path

    try:
        _studio_open_stage_terminal(stage_key, stage_log_path)
    except Exception:
        pass

    try:
        _studio_stage_terminal_append(
            f"[{time.strftime('%H:%M:%S')}] [embedded] Άνοιξε κοινό stage terminal: {stage_log_path}"
        )
    except Exception:
        pass
    return stage_log_path


def _studio_finish_shared_stage_terminal(success: bool, message: str = '') -> None:
    shared_log = globals().get('_STUDIO_STAGE_TERMINAL_SHARED_LOG')
    if not shared_log:
        globals()['_STUDIO_STAGE_TERMINAL_ACTIVE_LOG'] = None
        globals()['_STUDIO_STAGE_TERMINAL_PIPELINE_ACTIVE'] = False
        return

    globals()['_STUDIO_STAGE_TERMINAL_ACTIVE_LOG'] = Path(shared_log)
    try:
        if message:
            _studio_stage_terminal_append(f"[{time.strftime('%H:%M:%S')}] {message}")
        _studio_stage_terminal_append(f"{_STUDIO_STAGE_TERMINAL_SENTINEL}::shared::{int(bool(success))}")
    except Exception:
        pass
    finally:
        globals()['_STUDIO_STAGE_TERMINAL_SHARED_LOG'] = None
        globals()['_STUDIO_STAGE_TERMINAL_ACTIVE_LOG'] = None
        globals()['_STUDIO_STAGE_TERMINAL_PIPELINE_ACTIVE'] = False


def run_embedded_stage(stage_key: str, config_path: Path) -> int:
    stage_key = str(stage_key or '').strip().lower()
    previous_stage_log = globals().get('_STUDIO_STAGE_TERMINAL_ACTIVE_LOG')
    stage_log_path: Path | None = None
    pipeline_active = bool(globals().get('_STUDIO_STAGE_TERMINAL_PIPELINE_ACTIVE'))
    started_shared_here = False
    success = False
    gpu_cleanup_stages = {'cpt', 'sft', 'eval', 'export'}

    if stage_key in _STUDIO_STAGE_TERMINAL_STAGES:
        stage_log_path = globals().get('_STUDIO_STAGE_TERMINAL_SHARED_LOG')
        if stage_log_path:
            stage_log_path = Path(stage_log_path)
            globals()['_STUDIO_STAGE_TERMINAL_ACTIVE_LOG'] = stage_log_path
        else:
            stage_log_path = _studio_begin_shared_stage_terminal(stage_key)
            started_shared_here = stage_log_path is not None

    _prev_stdout = sys.stdout
    _prev_stderr = sys.stderr
    if stage_log_path is not None:
        sys.stdout = _StudioStageTerminalTee(_prev_stdout, stage_log_path)
        sys.stderr = _StudioStageTerminalTee(_prev_stderr, stage_log_path)

    try:
        code = _STUDIO_PREV_RUN_EMBEDDED_STAGE_STAGE_TERMINAL(stage_key, config_path)
        success = (code == 0)
        return code
    finally:
        try:
            if stage_log_path is not None:
                try:
                    sys.stdout.flush()
                except Exception:
                    pass
                try:
                    sys.stderr.flush()
                except Exception:
                    pass
        finally:
            sys.stdout = _prev_stdout
            sys.stderr = _prev_stderr

        if stage_key in gpu_cleanup_stages:
            try:
                released = _studio_release_gpu_memory(f'μετά το στάδιο {stage_key}', include_inference_cache=False)
                if released:
                    print(f"[embedded] 🧹 VRAM cleanup ολοκληρώθηκε μετά το στάδιο: {stage_key}", flush=True)
            except Exception as cleanup_exc:
                print(f"[embedded] ⚠ Προειδοποίηση cleanup VRAM στο στάδιο {stage_key}: {cleanup_exc}", flush=True)

        if started_shared_here and not pipeline_active:
            _studio_finish_shared_stage_terminal(
                success,
                '[embedded] Η εκτέλεση του σταδίου ολοκληρώθηκε.'
                if success
                else '[embedded] Η εκτέλεση του σταδίου τερματίστηκε με σφάλμα.',
            )
        else:
            globals()['_STUDIO_STAGE_TERMINAL_ACTIVE_LOG'] = previous_stage_log


def run_embedded_pipeline(config_path: Path, start_stage: str = 'collect') -> int:
    order = [value for _, value in STAGE_CHOICES]
    if start_stage not in order:
        start_stage = order[0]

    globals()['_STUDIO_STAGE_TERMINAL_PIPELINE_ACTIVE'] = True
    _studio_begin_shared_stage_terminal('pipeline')
    _studio_stage_terminal_append(
        f"[{time.strftime('%H:%M:%S')}] [embedded] Εκκίνηση pipeline από στάδιο: {start_stage}"
    )

    success = False
    exit_code = 0
    config = _studio_ensure_runtime_defaults(load_config(config_path))
    try:
        for stage in order[order.index(start_stage):]:
            try:
                strategy = _studio_auto_dataset_strategy(config) if stage in {'cpt', 'build_sft', 'sft'} else {}
            except Exception as strategy_exc:
                strategy = {}
                _studio_stage_terminal_append(
                    f"[{time.strftime('%H:%M:%S')}] [embedded] ⚠ Αδυναμία ανάγνωσης στρατηγικής dataset πριν από το στάδιο {stage}: {strategy_exc}"
                )

            if stage == 'cpt' and _studio_auto_should_skip_cpt(strategy):
                _studio_stage_terminal_append(
                    f"[{time.strftime('%H:%M:%S')}] [embedded] Παράλειψη σταδίου CPT — βρέθηκαν μόνο structured chat examples."
                )
                continue
            if stage in {'build_sft', 'sft'} and _studio_auto_should_skip_sft(strategy):
                label = 'Build SFT' if stage == 'build_sft' else 'Train SFT'
                _studio_stage_terminal_append(
                    f"[{time.strftime('%H:%M:%S')}] [embedded] Παράλειψη σταδίου {label} — βρέθηκαν μόνο raw αρχεία χωρίς structured chat examples."
                )
                continue

            exit_code = run_embedded_stage(stage, config_path)
            if exit_code != 0:
                break
        success = (exit_code == 0)
        return exit_code
    finally:
        _studio_finish_shared_stage_terminal(
            success,
            '[embedded] Το pipeline ολοκληρώθηκε επιτυχώς.'
            if success
            else f'[embedded] Το pipeline τερματίστηκε με κωδικό {int(exit_code)}.',
        )


PipelineStudioGUI._start_command = _resp_start_command

