# Στόχος: το pipeline να μη γυρίζει σε runtime_base_model.json όταν υπάρχει ήδη
# επιλεγμένο Μοντέλο Βάσης στο GUI. Κρατάμε το τελευταίο έγκυρο repo_id και το
# χρησιμοποιούμε ως fallback στη δημιουργία του runtime config.

_STUDIO_PREV_UPDATE_SELECTED_MODEL_STATE_CONFIG_FIX = PipelineStudioGUI._update_selected_model_state
_STUDIO_PREV_GENERATE_RUNTIME_CONFIG_CONFIG_FIX = PipelineStudioGUI.generate_runtime_config
_STUDIO_PREV_CONFIG_PATH_CONFIG_FIX = PipelineStudioGUI._config_path


def _studio_extract_repo_from_selected_model_label(self) -> str:
    try:
        label = str(getattr(self, 'selected_model_label', None).text() or '').strip()
    except Exception:
        return ''
    if ':' not in label:
        return ''
    repo_id = label.split(':', 1)[1].strip()
    repo_id = repo_id.lstrip('✅🔲☁⚠✔✳•·- ').strip()
    if '/' in repo_id and ' ' not in repo_id:
        return repo_id
    return ''


def _studio_repo_from_runtime_payload(payload: dict[str, Any]) -> tuple[str, str]:
    repo_id = str(payload.get('selected_model_repo_id') or '').strip()
    local_dir = str(payload.get('selected_model_local_dir') or '').strip()
    base_model = str(payload.get('base_model') or '').strip()
    if repo_id:
        return repo_id, local_dir
    if local_dir:
        try:
            info = inspect_local_model_dir(Path(local_dir))
            detected = str(info.get('repo_id') or info.get('meta_repo_id') or '').strip()
            if detected:
                return detected, local_dir
        except Exception:
            pass
    if base_model and not Path(base_model).exists() and '/' in base_model:
        return base_model, local_dir
    if base_model and Path(base_model).exists():
        try:
            info = inspect_local_model_dir(Path(base_model))
            detected = str(info.get('repo_id') or info.get('meta_repo_id') or '').strip()
            if detected:
                return detected, base_model
        except Exception:
            pass
    return '', local_dir


def _studio_read_runtime_payload_from_path(path_value: object) -> dict[str, Any]:
    try:
        path_text = str(path_value or '').strip()
        if not path_text:
            return {}
        path = Path(path_text)
        if not path.exists() or not path.is_file():
            return {}
        return json.loads(path.read_text(encoding='utf-8'))
    except Exception:
        return {}


def _studio_resolve_effective_selected_model_for_runtime(self) -> tuple[str, str]:
    candidates: list[tuple[str, str]] = []

    try:
        current = self._current_selected_model()
        if current and str(current.get('repo_id') or '').strip():
            candidates.append((str(current.get('repo_id') or '').strip(), str(current.get('local_dir') or '').strip()))
    except Exception:
        pass

    try:
        repo_id = str(self._selected_model_repo_id() or '').strip()
        if repo_id:
            local_dir = ''
            try:
                local_path = self._local_dir_if_ready(repo_id)
                local_dir = str(local_path) if local_path else ''
            except Exception:
                local_dir = ''
            candidates.append((repo_id, local_dir))
    except Exception:
        pass

    try:
        repo_id = str(getattr(self, '_last_valid_selected_model_repo_id', '') or '').strip()
        local_dir = str(getattr(self, '_last_valid_selected_model_local_dir', '') or '').strip()
        if repo_id:
            candidates.append((repo_id, local_dir))
    except Exception:
        pass

    try:
        repo_id = _studio_extract_repo_from_selected_model_label(self)
        if repo_id:
            local_dir = ''
            try:
                local_path = self._local_dir_if_ready(repo_id)
                local_dir = str(local_path) if local_path else ''
            except Exception:
                local_dir = ''
            candidates.append((repo_id, local_dir))
    except Exception:
        pass

    for payload in (
        _studio_read_runtime_payload_from_path(getattr(self, '_runtime_config_path', '')),
        _studio_read_runtime_payload_from_path(getattr(self, 'runtime_config_edit', None).text() if getattr(self, 'runtime_config_edit', None) is not None else ''),
    ):
        repo_id, local_dir = _studio_repo_from_runtime_payload(payload)
        if repo_id:
            candidates.append((repo_id, local_dir))

    for repo_id, local_dir in candidates:
        repo_id = str(repo_id or '').strip()
        local_dir = str(local_dir or '').strip()
        if not repo_id or repo_id.lower() == 'base_model':
            continue
        if local_dir:
            try:
                info = inspect_local_model_dir(Path(local_dir), expected_repo_id=repo_id)
                if info.get('complete'):
                    return repo_id, local_dir
            except Exception:
                pass
        return repo_id, local_dir
    return '', ''


def _studio_update_selected_model_state_config_fix(self) -> None:
    _STUDIO_PREV_UPDATE_SELECTED_MODEL_STATE_CONFIG_FIX(self)
    try:
        current = self._current_selected_model()
        if current and str(current.get('repo_id') or '').strip():
            self._last_valid_selected_model_repo_id = str(current.get('repo_id') or '').strip()
            self._last_valid_selected_model_local_dir = str(current.get('local_dir') or '').strip()
    except Exception:
        pass


def _studio_repair_runtime_config_file(self) -> Path | None:
    runtime_path = getattr(self, '_runtime_config_path', None)
    if not runtime_path:
        return None
    try:
        runtime_path = Path(runtime_path)
    except Exception:
        return None
    if not runtime_path.exists():
        return runtime_path

    try:
        payload = json.loads(runtime_path.read_text(encoding='utf-8'))
    except Exception:
        return runtime_path

    repo_id, local_dir = _studio_resolve_effective_selected_model_for_runtime(self)
    if not repo_id:
        return runtime_path

    changed = False
    payload_repo = str(payload.get('selected_model_repo_id') or '').strip()
    payload_local_dir = str(payload.get('selected_model_local_dir') or '').strip()
    payload_base_model = str(payload.get('base_model') or '').strip()

    if payload_repo != repo_id:
        payload['selected_model_repo_id'] = repo_id
        changed = True

    desired_base_model = local_dir or repo_id
    if payload_base_model != desired_base_model:
        payload['base_model'] = desired_base_model
        changed = True

    if local_dir:
        if payload_local_dir != local_dir:
            payload['selected_model_local_dir'] = local_dir
            changed = True
    elif payload_local_dir:
        payload['selected_model_local_dir'] = ''
        changed = True

    desired_target = RUNTIME_CONFIG_DIR / f"runtime_{slugify(repo_id.replace('/', '__'))}.json"
    if runtime_path.resolve() != desired_target.resolve():
        changed = True

    if not changed:
        return runtime_path

    desired_target.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
    self._runtime_config_path = desired_target
    if getattr(self, 'runtime_config_edit', None) is not None:
        self.runtime_config_edit.setText(str(desired_target))
    try:
        self.log(f"✓ Διορθώθηκε runtime config: {desired_target}")
    except Exception:
        pass
    return desired_target


def _studio_generate_runtime_config_config_fix(self) -> None:
    _STUDIO_PREV_GENERATE_RUNTIME_CONFIG_CONFIG_FIX(self)
    try:
        _studio_repair_runtime_config_file(self)
    except Exception as exc:
        try:
            self.log(f"⚠ Αποτυχία ελέγχου runtime config: {exc}")
        except Exception:
            pass


def _studio_config_path_config_fix(self) -> str:
    path_value = _STUDIO_PREV_CONFIG_PATH_CONFIG_FIX(self)
    try:
        repaired = _studio_repair_runtime_config_file(self)
        if repaired is not None:
            return str(repaired)
    except Exception:
        pass
    return path_value


PipelineStudioGUI._update_selected_model_state = _studio_update_selected_model_state_config_fix
PipelineStudioGUI.generate_runtime_config = _studio_generate_runtime_config_config_fix
PipelineStudioGUI._config_path = _studio_config_path_config_fix

