# =============================================================================
# ===== AUTO DATA STRATEGY + VALIDATION + MODEL-AWARE TRAINING PATCH ==========
# =============================================================================

def _studio_auto_record_signature(record: dict[str, Any]) -> str:
    payload = {
        'text': str(record.get('text') or record.get('raw_text') or ''),
        'instruction': str(record.get('instruction') or ''),
        'input': str(record.get('input') or ''),
        'output': str(record.get('output') or record.get('response') or ''),
        'prompt': str(record.get('prompt') or ''),
        'messages': record.get('messages') or [],
        'source_path': str(record.get('source_path') or ''),
        'source_url': str(record.get('source_url') or ''),
    }
    return hashlib.sha1(json.dumps(payload, ensure_ascii=False, sort_keys=True).encode('utf-8')).hexdigest()


def _studio_auto_dedupe_records(records: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], int]:
    seen: set[str] = set()
    unique: list[dict[str, Any]] = []
    skipped = 0
    for record in list(records or []):
        try:
            sig = _studio_auto_record_signature(record)
        except Exception:
            sig = ''
        if sig and sig in seen:
            skipped += 1
            continue
        if sig:
            seen.add(sig)
        unique.append(record)
    return unique, skipped


def _studio_structured_record_dedupe_key(record: dict[str, Any], normalized_text: str) -> str:
    payload = {
        'instruction': record.get('instruction') or '',
        'input': record.get('input') or '',
        'output': record.get('output') or '',
        'prompt': record.get('prompt') or '',
        'messages': record.get('messages') or [],
        'raw_text': record.get('raw_text') or '',
        'text': normalized_text or '',
        'dataset_format': record.get('dataset_format') or '',
        'source_dataset_path': record.get('source_dataset_path') or record.get('source_path') or '',
        'source_row_index': record.get('source_row_index') or '',
    }
    return _studio_hash_text(json.dumps(payload, ensure_ascii=False, sort_keys=True))


def _studio_auto_has_pair_candidate(record: dict[str, Any]) -> bool:
    try:
        return _studio_extract_prompt_completion_pair(record) is not None
    except Exception:
        return False


def _studio_auto_is_structured_record(record: dict[str, Any]) -> bool:
    dataset_format = str(record.get('dataset_format') or '').strip().lower()
    if dataset_format == 'text':
        return False
    if _studio_auto_has_pair_candidate(record):
        return True
    if bool(record.get('structured_example')) and dataset_format != 'text':
        return True
    if dataset_format in {'alpaca', 'chatml', 'messages', 'instruction', 'prompt_completion', 'prompt_output', 'instruction_input_output'}:
        return True
    return False


def _studio_auto_should_skip_cpt(strategy: dict[str, Any]) -> bool:
    total_records = int(strategy.get('total_records') or 0)
    structured_records = int(strategy.get('structured_records') or 0)
    raw_records = int(strategy.get('raw_records') or 0)
    cpt_mode = str(strategy.get('cpt_mode') or '').strip().lower()
    if cpt_mode == 'skipped_pure_structured_sft':
        return True
    return total_records > 0 and structured_records == total_records and raw_records == 0


def _studio_auto_should_skip_sft(strategy: dict[str, Any]) -> bool:
    total_records = int(strategy.get('total_records') or 0)
    structured_records = int(strategy.get('structured_records') or 0)
    raw_records = int(strategy.get('raw_records') or 0)
    sft_mode = str(strategy.get('sft_mode') or '').strip().lower()
    if sft_mode == 'skipped_pure_raw_cpt':
        return True
    return total_records > 0 and raw_records == total_records and structured_records == 0


def _studio_auto_shuffle(items: list[dict[str, Any]], seed: int) -> list[dict[str, Any]]:
    import random as _random
    shuffled = list(items or [])
    _random.Random(int(seed)).shuffle(shuffled)
    return shuffled


def _studio_auto_split_records(records: list[dict[str, Any]], *, seed: int, desired_ratio: float = 0.15) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    grouped: dict[str, list[dict[str, Any]]] = {}
    for record in list(records or []):
        group_key = _studio_structured_record_near_dedupe_key(record) or _studio_auto_record_signature(record)
        grouped.setdefault(group_key, []).append(record)

    import random as _random
    ordered_keys = list(grouped.keys())
    _random.Random(int(seed)).shuffle(ordered_keys)
    ordered_groups = [grouped[key] for key in ordered_keys]
    items = [record for group in ordered_groups for record in group]
    count = len(items)
    if count <= 1:
        return items, []

    if count < 12:
        eval_count = 1
    elif count < 40:
        eval_count = max(2, int(round(count * 0.10)))
    elif count < 100:
        eval_count = max(8, int(round(count * 0.12)))
    else:
        eval_count = max(32, int(round(count * float(desired_ratio))))
        eval_count = min(eval_count, 192)

    eval_count = min(eval_count, count - 1)
    if eval_count <= 0:
        return items, []

    eval_groups: list[list[dict[str, Any]]] = []
    deferred_groups: list[list[dict[str, Any]]] = []
    eval_records: list[dict[str, Any]] = []

    for group in ordered_groups:
        if len(eval_records) < eval_count:
            remaining_needed = eval_count - len(eval_records)
            if len(group) <= remaining_needed or not eval_groups:
                eval_groups.append(group)
                eval_records.extend(group)
            else:
                deferred_groups.append(group)
        else:
            deferred_groups.append(group)

    if len(eval_records) < eval_count and deferred_groups:
        remaining_needed = eval_count - len(eval_records)
        # Keep groups intact: prefer the smallest remaining groups first so we approach the target
        # without splitting near-duplicate clusters between train and eval.
        deferred_groups = sorted(
            deferred_groups,
            key=lambda grp: (abs(len(grp) - remaining_needed), len(grp)),
        )
        while deferred_groups and len(eval_records) < eval_count:
            group = deferred_groups.pop(0)
            eval_groups.append(group)
            eval_records.extend(group)
            remaining_needed = eval_count - len(eval_records)
            deferred_groups = sorted(
                deferred_groups,
                key=lambda grp: (abs(len(grp) - remaining_needed), len(grp)),
            )

    train_records = [record for group in deferred_groups for record in group]

    if not train_records:
        # Ensure at least one train example remains. Move the last eval group back intact.
        if len(eval_groups) > 1:
            moved_group = eval_groups.pop()
            train_records = list(moved_group)
            eval_records = [record for group in eval_groups for record in group]
        else:
            train_records, eval_records = items, []

    return train_records, eval_records


def _studio_auto_dataset_strategy(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults(config)
    dataset_cfg = dict(config.get('dataset', {}) or {})
    training_cfg = dict(config.get('training', {}) or {})
    preprocess_dir = Path(dataset_cfg.get('preprocess_dir') or (ARTIFACTS_DIR / '02_preprocess'))
    build_dir = Path(dataset_cfg.get('build_sft_dir') or (ARTIFACTS_DIR / '04_build_sft'))
    preprocess_dir.mkdir(parents=True, exist_ok=True)
    build_dir.mkdir(parents=True, exist_ok=True)

    preprocess_path = preprocess_dir / 'preprocessed_corpus.jsonl'
    if not preprocess_path.exists():
        preprocess_training_sources(config)

    records = _studio_jsonl_load(preprocess_path)
    effective_records = list(records or [])
    seed = int(training_cfg.get('seed') or 42)

    structured_records = [r for r in effective_records if _studio_auto_is_structured_record(r)]
    raw_records = [r for r in effective_records if not _studio_auto_is_structured_record(r)]

    def _split_stage_records(stage_records: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        stage_records = list(stage_records or [])
        if not stage_records:
            return [], []
        train_split, eval_split = _studio_auto_split_records(stage_records, seed=seed, desired_ratio=0.15)
        if not train_split:
            train_split, eval_split = list(stage_records), []
        return train_split, eval_split

    cpt_train_records, cpt_eval_records = _split_stage_records(raw_records)
    sft_train_records, sft_eval_records = _split_stage_records(structured_records)

    if effective_records:
        status = 'completed'
    else:
        status = 'skipped_no_records'

    pure_structured_sft_only = bool(effective_records) and len(structured_records) == len(effective_records) and len(raw_records) == 0
    pure_raw_cpt_only = bool(effective_records) and len(raw_records) == len(effective_records) and len(structured_records) == 0
    mixed_raw_and_structured = bool(effective_records) and len(raw_records) > 0 and len(structured_records) > 0

    if pure_structured_sft_only:
        pipeline_policy = 'skip_cpt_for_pure_structured_sft_then_train_sft'
        mode = 'structured_only_stage_split'
        split_policy = 'structured_only_stage_split'
    elif pure_raw_cpt_only:
        pipeline_policy = 'run_cpt_only_for_raw_corpus_skip_sft'
        mode = 'raw_only_stage_split'
        split_policy = 'raw_only_stage_split'
    elif mixed_raw_and_structured:
        pipeline_policy = 'run_cpt_on_raw_then_sft_on_structured_records'
        mode = 'stage_specific_split_by_record_type'
        split_policy = 'stage_specific_split_by_record_type'
    else:
        pipeline_policy = 'skipped_no_records'
        mode = 'skipped_no_records'
        split_policy = 'skipped_no_records'

    cpt_train_path = preprocess_dir / 'auto_cpt_train.jsonl'
    cpt_eval_path = preprocess_dir / 'auto_cpt_eval.jsonl'
    sft_train_path = build_dir / 'sft_dataset.jsonl'
    sft_eval_path = build_dir / 'sft_eval_dataset.jsonl'

    _studio_jsonl_dump(cpt_train_path, cpt_train_records)
    _studio_jsonl_dump(cpt_eval_path, cpt_eval_records)
    _studio_jsonl_dump(sft_train_path, sft_train_records)
    _studio_jsonl_dump(sft_eval_path, sft_eval_records)

    strategy = {
        'stage': 'auto_strategy',
        'status': status,
        'mode': mode,
        'pipeline_policy': pipeline_policy,
        'split_policy': split_policy,
        'stage_specific_split': bool(mixed_raw_and_structured),
        'shared_split': not bool(mixed_raw_and_structured),
        'total_records': len(effective_records),
        'effective_records': len(effective_records),
        'structured_records': len(structured_records),
        'raw_records': len(raw_records),
        'pure_structured_sft_only': pure_structured_sft_only,
        'pure_raw_cpt_only': pure_raw_cpt_only,
        'mixed_raw_and_structured': mixed_raw_and_structured,
        'shared_train_records': 0,
        'shared_eval_records': 0,
        'cpt_mode': 'skipped_pure_structured_sft' if pure_structured_sft_only else ('raw_only' if raw_records else 'skipped_no_records'),
        'sft_mode': 'skipped_pure_raw_cpt' if pure_raw_cpt_only else ('structured_only' if structured_records else 'skipped_no_records'),
        'cpt_train_records': len(cpt_train_records),
        'cpt_eval_records': len(cpt_eval_records),
        'sft_train_records': len(sft_train_records),
        'sft_eval_records': len(sft_eval_records),
        'cpt_source_records': len(raw_records),
        'sft_source_records': len(structured_records),
        'cpt_train_path': str(cpt_train_path.resolve()),
        'cpt_eval_path': str(cpt_eval_path.resolve()),
        'sft_train_path': str(sft_train_path.resolve()),
        'sft_eval_path': str(sft_eval_path.resolve()),
        'preprocess_dir': str(preprocess_dir.resolve()),
        'build_sft_dir': str(build_dir.resolve()),
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    (build_dir / 'auto_training_strategy.json').write_text(json.dumps(strategy, ensure_ascii=False, indent=2), encoding='utf-8')
    return strategy


def build_sft_dataset(config: dict[str, Any]) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults(config)
    strategy = _studio_auto_dataset_strategy(config)
    build_dir = Path(config.get('dataset', {}).get('build_sft_dir') or (ARTIFACTS_DIR / '04_build_sft'))
    build_dir.mkdir(parents=True, exist_ok=True)

    train_path = Path(strategy.get('sft_train_path') or (build_dir / 'sft_dataset.jsonl'))
    eval_path = Path(strategy.get('sft_eval_path') or (build_dir / 'sft_eval_dataset.jsonl'))
    train_dump_path = build_dir / 'debug_sft_train_samples.jsonl'
    eval_dump_path = build_dir / 'debug_sft_eval_samples.jsonl'

    if _studio_auto_should_skip_sft(strategy):
        _studio_write_debug_sample_dump(train_dump_path, [])
        _studio_write_debug_sample_dump(eval_dump_path, [])
        report = {
            'stage': 'build_sft',
            'status': 'skipped_pure_raw_cpt',
            'mode': 'raw_only_cpt',
            'pipeline_policy': str(strategy.get('pipeline_policy') or 'run_cpt_only_for_raw_corpus_skip_sft'),
            'split_policy': str(strategy.get('split_policy') or 'stage_specific_split_by_record_type'),
            'shared_split': bool(strategy.get('shared_split', True)),
            'dataset_path': str(train_path.resolve()),
            'eval_dataset_path': str(eval_path.resolve()),
            'train_records': 0,
            'eval_records': 0,
            'train_suspect_records': 0,
            'eval_suspect_records': 0,
            'train_debug_dump': str(train_dump_path.resolve()),
            'eval_debug_dump': str(eval_dump_path.resolve()),
            'source_records': int(strategy.get('total_records') or 0),
            'raw_source_records': int(strategy.get('raw_records') or 0),
            'structured_source_records': int(strategy.get('structured_records') or 0),
            'reason': 'pure_raw_corpus_without_structured_examples',
            'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
        }
        (build_dir / 'build_sft_report.json').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
        append_log(
            '[build_sft] ℹ Παράλειψη Build SFT — εντοπίστηκαν μόνο raw αρχεία (π.χ. Python files) χωρίς structured chat examples. '
            'Θα συνεχίσουμε με CPT → Evaluate → Export.'
        )
        return report

    train_records = _studio_jsonl_load(train_path)
    eval_records = _studio_jsonl_load(eval_path)

    train_debug_rows: list[dict[str, Any]] = []
    eval_debug_rows: list[dict[str, Any]] = []
    train_suspect_count = 0
    eval_suspect_count = 0
    for record in train_records:
        reasons = list(dict.fromkeys(_studio_detect_contamination_reasons(record.get('output') or record.get('response') or '') + _studio_detect_contamination_reasons(record.get('text') or '')))
        if reasons:
            train_suspect_count += 1
        if len(train_debug_rows) < STUDIO_PATCH_DEBUG_SAMPLE_DUMP_LIMIT:
            train_debug_rows.append(_studio_record_debug_snapshot(record, reasons=reasons, label='train_sample'))
    for record in eval_records:
        reasons = list(dict.fromkeys(_studio_detect_contamination_reasons(record.get('output') or record.get('response') or '') + _studio_detect_contamination_reasons(record.get('text') or '')))
        if reasons:
            eval_suspect_count += 1
        if len(eval_debug_rows) < STUDIO_PATCH_DEBUG_SAMPLE_DUMP_LIMIT:
            eval_debug_rows.append(_studio_record_debug_snapshot(record, reasons=reasons, label='eval_sample'))

    _studio_write_debug_sample_dump(train_dump_path, train_debug_rows)
    _studio_write_debug_sample_dump(eval_dump_path, eval_debug_rows)

    report = {
        'stage': 'build_sft',
        'status': 'completed' if train_records else 'skipped_no_records',
        'mode': 'structured_only_for_sft',
        'pipeline_policy': str(strategy.get('pipeline_policy') or 'run_cpt_on_raw_then_sft_on_structured_records'),
        'split_policy': str(strategy.get('split_policy') or 'stage_specific_split_by_record_type'),
        'shared_split': bool(strategy.get('shared_split', True)),
        'dataset_path': str(train_path.resolve()),
        'eval_dataset_path': str(eval_path.resolve()),
        'train_records': len(train_records),
        'eval_records': len(eval_records),
        'train_suspect_records': train_suspect_count,
        'eval_suspect_records': eval_suspect_count,
        'train_debug_dump': str(train_dump_path.resolve()),
        'eval_debug_dump': str(eval_dump_path.resolve()),
        'source_records': int(strategy.get('total_records') or 0),
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    (build_dir / 'build_sft_report.json').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
    append_log(
        '[build_sft] '
        + f"policy={report['pipeline_policy']} | split={report['split_policy']} | train={report['train_records']} | eval={report['eval_records']} | train_suspect={report['train_suspect_records']} | eval_suspect={report['eval_suspect_records']}"
    )
    append_log(f"[build_sft] debug_dump | train={train_dump_path} | eval={eval_dump_path}")
    if not train_records:
        append_log('[build_sft] ⚠ Δεν βρέθηκαν structured εγγραφές μετά το Preprocess. Το SFT dataset έμεινε κενό.')
    return report

def _studio_auto_read_stage_records(config: dict[str, Any], stage_key: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any]]:
    config = _studio_ensure_runtime_defaults(config)
    strategy = _studio_auto_dataset_strategy(config)
    dataset_cfg = dict(config.get('dataset', {}) or {})
    preprocess_dir = Path(dataset_cfg.get('preprocess_dir') or (ARTIFACTS_DIR / '02_preprocess'))
    build_dir = Path(dataset_cfg.get('build_sft_dir') or (ARTIFACTS_DIR / '04_build_sft'))

    stage = str(stage_key or '').strip().lower()
    if stage == 'cpt':
        train_path = Path(strategy.get('cpt_train_path') or (preprocess_dir / 'auto_cpt_train.jsonl'))
        eval_path = Path(strategy.get('cpt_eval_path') or (preprocess_dir / 'auto_cpt_eval.jsonl'))
    elif stage == 'sft':
        train_path = Path(strategy.get('sft_train_path') or (build_dir / 'sft_dataset.jsonl'))
        eval_path = Path(strategy.get('sft_eval_path') or (build_dir / 'sft_eval_dataset.jsonl'))
    else:
        train_path = preprocess_dir / 'preprocessed_corpus.jsonl'
        eval_path = build_dir / f'{stage}_eval_dataset.jsonl'

    train_records = _studio_jsonl_load(train_path)
    eval_records = _studio_jsonl_load(eval_path)
    meta = {
        'stage': stage,
        'mode': 'all_records' if train_records else 'skipped_no_records',
        'shared_split': bool(strategy.get('shared_split', True)),
        'train_path': str(train_path.resolve()),
        'eval_path': str(eval_path.resolve()),
        'strategy': strategy,
    }
    return train_records, eval_records, meta


