def _studio_format_seconds_hms(total_seconds: float | int | None) -> str:
    try:
        seconds = int(max(0, float(total_seconds or 0)))
    except Exception:
        seconds = 0
    hours, rem = divmod(seconds, 3600)
    minutes, secs = divmod(rem, 60)
    return f"{hours:02d}:{minutes:02d}:{secs:02d}"


class _StudioTrainingMetricsCallback:
    def __init__(self, stage_key: str) -> None:
        self.stage_key = str(stage_key or 'train')
        self.start_ts = 0.0
        self.last_logged_step = -1

    def on_train_begin(self, args, state, control, **kwargs):
        self.start_ts = time.time()
        total_steps = int(getattr(state, 'max_steps', 0) or 0)
        append_log(f"[{self.stage_key}] Live metrics ενεργές | συνολικά βήματα: {total_steps or 'άγνωστα'}")
        append_log(f"[{self.stage_key}] Η ακρίβεια δεν υπολογίζεται live στο training loop αυτού του Causal LM· θα εμφανιστεί token_accuracy στο Evaluate.")
        return control

    def on_log(self, args, state, control, logs=None, **kwargs):
        logs = dict(logs or {})
        step = int(getattr(state, 'global_step', 0) or 0)
        if step <= 0 or step == self.last_logged_step:
            return control
        self.last_logged_step = step

        max_steps = int(getattr(state, 'max_steps', 0) or 0)
        epoch = logs.get('epoch', getattr(state, 'epoch', None))
        loss = logs.get('loss', logs.get('train_loss'))
        lr = logs.get('learning_rate')
        grad_norm = logs.get('grad_norm')

        elapsed = max(0.0, time.time() - self.start_ts)
        steps_per_sec = (step / elapsed) if elapsed > 0 else 0.0
        remaining_steps = max(0, max_steps - step) if max_steps > 0 else 0
        eta_seconds = (remaining_steps / steps_per_sec) if (steps_per_sec > 0 and max_steps > 0 and remaining_steps > 0) else None
        pct = ((step / max_steps) * 100.0) if max_steps > 0 else None

        parts = [f"[{self.stage_key}] progress"]
        if pct is not None:
            parts.append(f"{pct:5.1f}%")
        parts.append(f"step={step}/{max_steps if max_steps > 0 else '?'}")
        if epoch is not None:
            try:
                parts.append(f"epoch={float(epoch):.2f}")
            except Exception:
                parts.append(f"epoch={epoch}")
        if loss is not None:
            try:
                parts.append(f"loss={float(loss):.4g}")
            except Exception:
                parts.append(f"loss={loss}")
        if grad_norm is not None:
            try:
                parts.append(f"grad_norm={float(grad_norm):.4g}")
            except Exception:
                parts.append(f"grad_norm={grad_norm}")
        if lr is not None:
            try:
                parts.append(f"lr={float(lr):.6g}")
            except Exception:
                parts.append(f"lr={lr}")
        parts.append(f"elapsed={_studio_format_seconds_hms(elapsed)}")
        if eta_seconds is not None:
            parts.append(f"ETA={_studio_format_seconds_hms(eta_seconds)}")
        if steps_per_sec > 0:
            parts.append(f"steps/s={steps_per_sec:.3f}")
        append_log(' | '.join(parts))
        return control

    def on_train_end(self, args, state, control, **kwargs):
        elapsed = max(0.0, time.time() - self.start_ts)
        total_steps = int(getattr(state, 'global_step', 0) or 0)
        append_log(f"[{self.stage_key}] Live metrics τέλος | elapsed={_studio_format_seconds_hms(elapsed)} | total_steps={total_steps}")
        return control


def _studio_safe_gpu_cleanup(torch_module=None, include_inference_cache: bool = False) -> None:
    """Safe VRAM cleanup without disturbing normal app flow.

    - Runs gc.collect() first.
    - Clears CUDA cache only when CUDA is available.
    - Keeps inference cache intact by default.
    """
    try:
        import gc
        gc.collect()
    except Exception:
        pass

    torch_mod = torch_module
    if torch_mod is None:
        try:
            import torch as torch_mod  # type: ignore
        except Exception:
            return

    try:
        cuda = getattr(torch_mod, 'cuda', None)
        if cuda is None or not callable(getattr(cuda, 'is_available', None)) or not cuda.is_available():
            return
        try:
            cuda.synchronize()
        except Exception:
            pass
        try:
            cuda.empty_cache()
        except Exception:
            pass
        if include_inference_cache:
            try:
                cuda.ipc_collect()
            except Exception:
                pass
    except Exception:
        pass


