# ===== PRE-MAIN UNIFIED TRAINING STAGE PATCH ================================
# =============================================================================


def _studio_apply_small_dataset_training_guard(
    training_cfg: dict[str, Any],
    *,
    stage_key: str,
    raw_train_records: int,
    raw_eval_records: int,
) -> tuple[dict[str, Any], list[str]]:
    cfg = dict(training_cfg or {})
    notes: list[str] = []

    enabled = bool(cfg.get('auto_training_rule_enabled', cfg.get('small_dataset_guard_enabled', True)))
    if not enabled:
        return cfg, notes

    total_records = max(0, int(raw_train_records) + int(raw_eval_records))
    tiny_threshold = max(1, int(cfg.get('auto_training_rule_tiny_threshold') or cfg.get('very_small_dataset_guard_threshold') or 1200))
    small_threshold = max(tiny_threshold, int(cfg.get('auto_training_rule_small_threshold') or cfg.get('small_dataset_guard_threshold') or 4000))
    medium_threshold = max(small_threshold, int(cfg.get('auto_training_rule_medium_threshold') or 12000))

    if total_records <= tiny_threshold:
        profile = 'tiny'
    elif total_records <= small_threshold:
        profile = 'small'
    elif total_records <= medium_threshold:
        profile = 'medium'
    else:
        cfg['_auto_training_profile'] = 'large'
        cfg['_auto_training_total_records'] = total_records
        return cfg, notes

    stage = str(stage_key or '').strip().lower()

    def _fmt_value(value: Any) -> str:
        if isinstance(value, float):
            if value == 0:
                return '0'
            if abs(value) < 1e-3 or abs(value) >= 1e3:
                return f"{value:.3g}"
            return f"{value:.4f}".rstrip('0').rstrip('.')
        return str(value)

    changes: list[str] = []

    def _apply(key: str, new_value: Any, mode: str = 'set') -> None:
        old_value = cfg.get(key)
        if mode == 'min':
            final_value = min(float(old_value), float(new_value))
        elif mode == 'max':
            final_value = max(float(old_value), float(new_value))
        else:
            final_value = new_value

        changed = False
        if isinstance(final_value, float) or isinstance(old_value, float):
            try:
                changed = abs(float(old_value) - float(final_value)) > 1e-12
            except Exception:
                changed = old_value != final_value
        else:
            changed = old_value != final_value

        cfg[key] = final_value
        if changed:
            changes.append(f"{key}: {_fmt_value(old_value)} → {_fmt_value(final_value)}")

    if bool(cfg.get('auto_training_rule_force_disable_packing', True)):
        _apply('packing', False, mode='set')

    if profile == 'tiny':
        target_warmup = float(cfg.get('auto_tiny_warmup_ratio') or cfg.get('very_small_dataset_warmup_ratio') or 0.10)
    elif profile == 'small':
        target_warmup = float(cfg.get('auto_small_warmup_ratio') or cfg.get('small_dataset_warmup_ratio') or 0.08)
    else:
        target_warmup = float(cfg.get('auto_medium_warmup_ratio') or 0.06)

    _apply('warmup_ratio', target_warmup, mode='max')
    _apply('weight_decay', float(cfg.get('auto_training_weight_decay') or cfg.get('small_dataset_weight_decay') or 0.02), mode='max')
    _apply('neftune_noise_alpha', float(cfg.get('auto_training_neftune_noise_alpha') or cfg.get('small_dataset_neftune_noise_alpha') or 3.0), mode='min')
    _apply('max_grad_norm', float(cfg.get('auto_training_max_grad_norm') or cfg.get('small_dataset_max_grad_norm') or 0.8), mode='min')

    if stage == 'cpt':
        if profile == 'tiny':
            target_lr = float(cfg.get('auto_tiny_cpt_learning_rate') or 8e-5)
        elif profile == 'small':
            target_lr = float(cfg.get('auto_small_cpt_learning_rate') or cfg.get('small_dataset_cpt_learning_rate') or 1e-4)
        else:
            target_lr = float(cfg.get('auto_medium_cpt_learning_rate') or 1.5e-4)
        _apply('learning_rate', target_lr, mode='min')

    elif stage == 'sft':
        if profile == 'tiny':
            target_lr = float(cfg.get('auto_tiny_sft_learning_rate') or cfg.get('very_small_dataset_sft_learning_rate') or 3e-5)
            target_epochs = float(cfg.get('auto_tiny_sft_max_epochs') or 2.0)
        elif profile == 'small':
            target_lr = float(cfg.get('auto_small_sft_learning_rate') or cfg.get('small_dataset_sft_learning_rate') or 5e-5)
            target_epochs = float(cfg.get('auto_small_sft_max_epochs') or 2.5)
        else:
            target_lr = float(cfg.get('auto_medium_sft_learning_rate') or 8e-5)
            target_epochs = float(cfg.get('auto_medium_sft_max_epochs') or 3.0)

        _apply('learning_rate', target_lr, mode='min')
        _apply('epochs', target_epochs, mode='min')

    cfg['_auto_training_profile'] = profile
    cfg['_auto_training_total_records'] = total_records

    if bool(cfg.get('auto_training_rule_notify', True)):
        notes.append(
            f"AUTO_TRAINING_RULE ενεργό | profile={profile} | stage={stage.upper()} | "
            f"total_records={total_records} | train={int(raw_train_records)} | eval={int(raw_eval_records)}"
        )
        if changes:
            notes.append("AUTO_TRAINING_RULE αλλαγές | " + " | ".join(changes))
        else:
            notes.append("AUTO_TRAINING_RULE ενεργό αλλά δεν χρειάστηκαν αλλαγές στα hyperparameters.")

    return cfg, notes


def _studio_train_stage_with_live_metrics(config: dict[str, Any], stage_key: str) -> dict[str, Any]:
    config = _studio_ensure_runtime_defaults(config)
    training_cfg = dict(config.get('training', {}) or {})
    stage_key = str(stage_key or '').strip().lower()

    train_records, eval_records, stage_meta = _studio_auto_read_stage_records(config, stage_key)
    dataset_path = Path(stage_meta.get('train_path') or '')
    eval_dataset_path = Path(stage_meta.get('eval_path') or '')
    strategy = dict(stage_meta.get('strategy') or {})
    if stage_key == 'cpt' and _studio_auto_should_skip_cpt(strategy):
        append_log(
            f"[{stage_key}] ℹ Παράλειψη CPT — εντοπίστηκε καθαρά structured SFT dataset χωρίς raw corpus. "
            "Θα συνεχίσουμε απευθείας με Build SFT και Train SFT πάνω στο base model."
        )
        report = {
            'stage': stage_key,
            'status': 'skipped_pure_structured_sft',
            'dataset_path': str(dataset_path.resolve()) if str(dataset_path) else '',
            'eval_dataset_path': str(eval_dataset_path.resolve()) if str(eval_dataset_path) else '',
            'records': len(train_records),
            'eval_records': len(eval_records),
            'shared_split': bool(strategy.get('shared_split', True)),
            'pipeline_policy': str(strategy.get('pipeline_policy') or 'skip_cpt_for_pure_structured_sft_then_train_sft'),
            'reason': 'pure_structured_sft_dataset_without_raw_corpus',
            'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
        }
        out_dir = _studio_stage_model_dir(config, stage_key)
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / 'TRAINING_REPORT.json').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
        return report

    if stage_key == 'sft' and _studio_auto_should_skip_sft(strategy):
        append_log(
            f"[{stage_key}] ℹ Παράλειψη SFT — εντοπίστηκαν μόνο raw αρχεία (π.χ. Python files) χωρίς structured chat examples. "
            "Θα κρατήσουμε μόνο το CPT για αυτό το dataset."
        )
        report = {
            'stage': stage_key,
            'status': 'skipped_pure_raw_cpt',
            'dataset_path': str(dataset_path.resolve()) if str(dataset_path) else '',
            'eval_dataset_path': str(eval_dataset_path.resolve()) if str(eval_dataset_path) else '',
            'records': len(train_records),
            'eval_records': len(eval_records),
            'shared_split': bool(strategy.get('shared_split', True)),
            'pipeline_policy': str(strategy.get('pipeline_policy') or 'run_cpt_only_for_raw_corpus_skip_sft'),
            'reason': 'pure_raw_corpus_without_structured_examples',
            'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
        }
        out_dir = _studio_stage_model_dir(config, stage_key)
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / 'TRAINING_REPORT.json').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
        return report

    if not train_records:
        raise RuntimeError(
            f'Δεν βρέθηκαν εγγραφές training για το στάδιο {stage_key}. '
            'Έλεγξε αν υπάρχουν κατάλληλες εγγραφές για το συγκεκριμένο στάδιο (raw για CPT, structured για SFT).'
        )

    training_cfg, _safety_notes = _studio_apply_small_dataset_training_guard(
        training_cfg,
        stage_key=stage_key,
        raw_train_records=len(train_records),
        raw_eval_records=len(eval_records),
    )
    for _note in _safety_notes:
        append_log(f"[{stage_key}] {_note}")

    max_steps = int(training_cfg.get('cpt_max_steps') or 0) if stage_key == 'cpt' else int(training_cfg.get('sft_max_steps') or 0)

    base_dir, adapter_dir, training_base_kind = _studio_resolve_training_start(config, stage_key)
    append_log(f"[{stage_key}] Μοντέλο: {base_dir} | mode={training_base_kind}" + (f" | adapter={adapter_dir}" if adapter_dir else ""))
    append_log(
        f"[{stage_key}] unified_policy={stage_meta.get('strategy', {}).get('pipeline_policy', 'run_cpt_on_raw_then_sft_on_structured_records')}"
        + f" | shared_split={bool(stage_meta.get('shared_split'))} | train={len(train_records)} | eval={len(eval_records)}"
    )

    tokenizer = _studio_load_tokenizer_for_runtime(adapter_dir or base_dir, base_dir=base_dir)
    if getattr(tokenizer, 'pad_token', None) is None:
        tokenizer.pad_token = tokenizer.eos_token
        tokenizer.pad_token_id = tokenizer.eos_token_id

    max_length = int(training_cfg.get('max_length') or 2048)
    model_max_len = int(getattr(tokenizer, 'model_max_length', max_length) or max_length)
    if 0 < model_max_len < 1_000_000:
        max_length = min(max_length, model_max_len)

    train_items, total_raw_tokens = _studio_prepare_lm_items(
        train_records,
        tokenizer,
        max_length=max_length,
        max_train_samples=int(training_cfg.get('max_train_samples') or 0),
        stage_key=stage_key,
    )
    if not train_items:
        raise RuntimeError('Το training dataset δεν παρήγαγε έγκυρα tokenized δείγματα.')

    stack = _studio_import_training_stack(require_peft=bool(config.get('lora', {}).get('enabled', True)))
    torch = stack['torch']
    out_dir = _studio_stage_model_dir(config, stage_key)
    out_dir.mkdir(parents=True, exist_ok=True)

    model = _studio_load_model_for_runtime(base_dir, adapter_dir=adapter_dir, trainable=True, config=config)
    _studio_align_padding_for_generation(tokenizer, model)
    trainable_params, total_params = _studio_count_trainable_params(model)

    _cuda_ok = torch.cuda.is_available()
    _model_dtype = _studio_detect_model_dtype(model)
    _bf16_ok = (_model_dtype == 'bf16')
    _fp16_ok = (_model_dtype == 'fp16') or (not _bf16_ok and _cuda_ok and bool(training_cfg.get('fp16_fallback', True)))
    if bool(training_cfg.get('bf16', False)):
        _bf16_ok = True
        _fp16_ok = False
    if bool(training_cfg.get('fp16', False)) and not _bf16_ok:
        _fp16_ok = True

    append_log(f"[{stage_key}] model dtype={_model_dtype} → bf16={_bf16_ok} fp16={_fp16_ok}")

    _gc = bool(training_cfg.get('gradient_checkpointing', True))
    if _gc and hasattr(model, 'gradient_checkpointing_enable'):
        try:
            model.gradient_checkpointing_enable(gradient_checkpointing_kwargs={'use_reentrant': False})
        except TypeError:
            try:
                model.gradient_checkpointing_enable()
            except Exception:
                pass

    _epochs = float(training_cfg.get('epochs') or 3)
    _micro_batch = int(training_cfg.get('micro_batch_size') or 1)
    _grad_accum = int(training_cfg.get('gradient_accumulation_steps') or 16)
    _total_steps = max(1, int(len(train_items) / max(1, _micro_batch) / max(1, _grad_accum) * _epochs))
    _warmup_steps = max(1, int(_total_steps * float(training_cfg.get('warmup_ratio') or 0.05)))

    _optim = 'adamw_torch_fused'
    try:
        import inspect as _ins
        if 'optim' not in set(_ins.signature(stack['TrainingArguments'].__init__).parameters):
            _optim = 'adamw_torch'
    except Exception:
        _optim = 'adamw_torch'

    training_cfg['logging_steps'] = 1

    _ta_kwargs = dict(
        output_dir=str(out_dir),
        num_train_epochs=_epochs,
        per_device_train_batch_size=_micro_batch,
        gradient_accumulation_steps=_grad_accum,
        learning_rate=float(training_cfg.get('learning_rate') or 2e-4),
        lr_scheduler_type=str(training_cfg.get('lr_scheduler_type') or 'cosine'),
        warmup_steps=_warmup_steps,
        weight_decay=float(training_cfg.get('weight_decay') or 0.01),
        max_grad_norm=float(training_cfg.get('max_grad_norm') or 1.0),
        fp16=_fp16_ok,
        bf16=_bf16_ok,
        tf32=_cuda_ok,
        gradient_checkpointing=_gc,
        gradient_checkpointing_kwargs={'use_reentrant': False} if _gc else {},
        optim=_optim,
        dataloader_pin_memory=_cuda_ok,
        dataloader_num_workers=int(training_cfg.get('dataloader_num_workers') or 0),
        logging_steps=max(1, int(training_cfg.get('logging_steps') or 1)),
        logging_first_step=True,
        log_level='warning',
        save_steps=max(10, int(training_cfg.get('save_steps') or 100)),
        save_total_limit=max(1, int(training_cfg.get('save_total_limit') or 2)),
        report_to=[],
        remove_unused_columns=False,
        seed=int(training_cfg.get('seed') or 42),
        max_steps=max_steps if max_steps > 0 else -1,
        ddp_find_unused_parameters=False,
        load_best_model_at_end=False,
    )
    args, dropped = _studio_build_training_arguments(stack['TrainingArguments'], _ta_kwargs)
    if dropped:
        append_log(f"[{stage_key}] ⚠ TrainingArguments παραλείφθηκαν: {', '.join(dropped)}")

    _neftune = float(training_cfg.get('neftune_noise_alpha') or 5.0)

    def _apply_neftune(mdl, noise):
        try:
            import torch as _t
            embed = mdl.get_input_embeddings()
            if embed is None:
                return
            _orig = embed.forward
            def _noisy(x):
                out = _orig(x)
                if _t.is_grad_enabled():
                    # uniform_() requires plain Python scalars, not Tensors
                    if out.dim() >= 3:
                        dims = float(out.shape[1] * out.shape[2])
                    elif out.dim() == 2:
                        dims = float(out.shape[1])
                    else:
                        dims = float(out.numel())
                    scale = noise / (dims ** 0.5) if dims > 0 else 0.0
                    out = out + _t.zeros_like(out).uniform_(-scale, scale)
                return out
            embed.forward = _noisy
        except Exception:
            pass

    trainer = None
    if bool(training_cfg.get('packing', False)):
        append_log(f"[{stage_key}] ℹ packing=False επιβλήθηκε στο runtime για αποφυγή FlashAttention/TRL warnings.")
    if trainer is None:
        if _neftune > 0:
            _apply_neftune(model, _neftune)
            append_log(f"[{stage_key}] ✓ NEFTune noise_alpha={_neftune}")
        trainer = stack['Trainer'](
            model=model,
            args=args,
            train_dataset=_StudioTokenDataset(train_items),
            data_collator=stack['DataCollatorForLanguageModeling'](tokenizer=tokenizer, mlm=False, pad_to_multiple_of=8),
        )

    try:
        from transformers import TrainerCallback as _HFTrainerCallback  # type: ignore

        class _StudioHFTrainingMetricsCallback(_HFTrainerCallback):
            def __init__(self, stage: str) -> None:
                super().__init__()
                self._delegate = _StudioTrainingMetricsCallback(stage)

            def on_train_begin(self, args, state, control, **kwargs):
                return self._delegate.on_train_begin(args, state, control, **kwargs)

            def on_log(self, args, state, control, logs=None, **kwargs):
                return self._delegate.on_log(args, state, control, logs=logs, **kwargs)

            def on_train_end(self, args, state, control, **kwargs):
                return self._delegate.on_train_end(args, state, control, **kwargs)

        trainer.add_callback(_StudioHFTrainingMetricsCallback(stage_key))
        try:
            from transformers import PrinterCallback as _HFPrinterCallback, ProgressCallback as _HFProgressCallback  # type: ignore
            trainer.remove_callback(_HFPrinterCallback)
            trainer.remove_callback(_HFProgressCallback)
        except Exception:
            pass
    except Exception as exc:
        append_log(f"[{stage_key}] ⚠ Δεν προστέθηκε live metrics callback: {exc}")

    _studio_stage_log_dataset_breakdown(
        stage_key=stage_key,
        train_records=train_records,
        eval_records=eval_records,
        train_items=train_items,
        total_raw_tokens=total_raw_tokens,
        max_length=max_length,
        trainable_params=trainable_params,
        total_params=total_params,
    )
    append_log(f"[{stage_key}] LR={_ta_kwargs['learning_rate']} | sched={_ta_kwargs['lr_scheduler_type']} | warmup={_warmup_steps} | wd={_ta_kwargs['weight_decay']} | {_optim}")

    result = trainer.train()
    metrics = dict(getattr(result, 'metrics', {}) or {})
    if metrics:
        try:
            pretty = ' | '.join(f"{k}={v:.6g}" if isinstance(v, (int, float)) else f"{k}={v}" for k, v in metrics.items())
        except Exception:
            pretty = str(metrics)
        append_log(f"[{stage_key}] Τελικά metrics | {pretty}")

    _studio_align_padding_for_generation(tokenizer, model)
    trainer.save_model(str(out_dir))
    tokenizer.save_pretrained(str(out_dir))
    report = {
        'stage': stage_key,
        'status': 'trained',
        'dataset_path': str(dataset_path.resolve()),
        'eval_dataset_path': str(eval_dataset_path.resolve()),
        'records': len(train_records),
        'eval_records': len(eval_records),
        'train_samples': len(train_items),
        'total_raw_tokens': total_raw_tokens,
        'base_model_dir': str(base_dir),
        'adapter_start_dir': str(adapter_dir) if adapter_dir else '',
        'training_base_kind': training_base_kind,
        'output_dir': str(out_dir.resolve()),
        'contains_adapter': _studio_has_adapter_files(out_dir),
        'trainable_params': trainable_params,
        'total_params': total_params,
        'shared_split': bool(strategy.get('shared_split', True)),
        'pipeline_policy': str(stage_meta.get('strategy', {}).get('pipeline_policy') or 'run_cpt_on_raw_then_sft_on_structured_records'),
        'metrics': metrics,
        'hyperparams': {
            'lr': _ta_kwargs['learning_rate'],
            'scheduler': _ta_kwargs['lr_scheduler_type'],
            'warmup_steps': _warmup_steps,
            'weight_decay': _ta_kwargs['weight_decay'],
            'neftune_alpha': _neftune,
            'model_dtype': _model_dtype,
            'precision': 'bf16' if _bf16_ok else 'fp16' if _fp16_ok else 'fp32',
            'optim': _optim,
            'small_dataset_guard_enabled': bool(training_cfg.get('small_dataset_guard_enabled', True)),
            'small_dataset_guard_notes': list(_safety_notes),
            'auto_training_rule_enabled': bool(training_cfg.get('auto_training_rule_enabled', True)),
            'auto_training_rule_profile': str(training_cfg.get('_auto_training_profile') or 'none'),
            'auto_training_rule_total_records': int(training_cfg.get('_auto_training_total_records') or (len(train_records) + len(eval_records))),
        },
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    (out_dir / 'TRAINING_REPORT.json').write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
    return report


_studio_train_stage_auto = _studio_train_stage_with_live_metrics
_studio_train_stage = _studio_train_stage_with_live_metrics
_studio_patched_train_stage = _studio_train_stage_with_live_metrics

if __name__ == "__main__":
    main()


# =============================================================================
# ===== CHAT STRUCTURED STREAM / DESCRIPTION-CODE-PREREQS PATCH ==============
# =============================================================================

_STUDIO_PREV_CHAT_RENDER_PLAIN_INLINE = _studio_chat_render_plain_with_inline_code
_STUDIO_PREV_CHAT_NORMALIZE_PYTHON_REPLY = _studio_chat_normalize_python_reply


def _studio_chat_is_code_only_request(user_text: str) -> bool:
    low = str(user_text or '').casefold()
    if not low:
        return False
    markers = (
        'code only', 'only code', 'just code', 'only the code', 'return only code',
        'single code block', 'one code block', 'single block', 'one block',
        'χωρίς εξηγήσεις', 'χωρις εξηγησεις', 'μόνο κώδικ', 'μονο κωδικ',
        'μόνο το code', 'μονο το code', 'σκέτο κώδικ', 'σκετο κωδικ',
        'no explanation', 'no explanations', 'without explanation', 'without explanations',
    )
    return any(token in low for token in markers)


def _studio_chat_should_use_structured_code_reply(user_text: str) -> bool:
    return bool(_studio_chat_is_python_request(user_text) and not _studio_chat_is_code_only_request(user_text))


def _studio_chat_clean_section_text(raw: str) -> str:
    text = str(raw or '').replace('\r\n', '\n').replace('\r', '\n')
    if not text.strip():
        return ''
    lines: list[str] = []
    last_blank = False
    for raw_line in text.split('\n'):
        line = str(raw_line or '').strip()
        if not line:
            if not last_blank:
                lines.append('')
            last_blank = True
            continue
        low = line.casefold().strip(': ')
        if low in {
            'περιγραφή εφαρμογής', 'κώδικας', 'προαπαιτούμενα', 'αναφορές',
            'προαπαιτούμενα / αναφορές', 'application description', 'code',
            'requirements', 'prerequisites', 'references'
        }:
            continue
        if line.startswith('```'):
            continue
        lines.append(line)
        last_blank = False
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    return '\n'.join(lines).strip()


_STUDIO_IMPORT_TO_PIP_MAP = {
    'cv2': 'opencv-python',
    'PIL': 'Pillow',
    'sklearn': 'scikit-learn',
    'yaml': 'PyYAML',
    'bs4': 'beautifulsoup4',
    'serial': 'pyserial',
    'dotenv': 'python-dotenv',
    'Crypto': 'pycryptodome',
    'fitz': 'PyMuPDF',
    'googleapiclient': 'google-api-python-client',
    'websocket': 'websocket-client',
    'ultralytics': 'ultralytics',
}


def _studio_chat_collect_imported_modules(code_text: str) -> list[str]:
    import ast

    code = str(code_text or '').strip()
    if not code:
        return []

    found: list[str] = []
    seen: set[str] = set()

    def _add(name: str) -> None:
        root = str(name or '').split('.', 1)[0].strip()
        if not root or root in seen:
            return
        seen.add(root)
        found.append(root)

    try:
        tree = ast.parse(code + '\n')
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in list(node.names or []):
                    _add(getattr(alias, 'name', ''))
            elif isinstance(node, ast.ImportFrom):
                if int(getattr(node, 'level', 0) or 0) > 0:
                    continue
                _add(getattr(node, 'module', '') or '')
    except Exception:
        for raw_line in code.split('\n'):
            line = str(raw_line or '').strip()
            if line.startswith('import '):
                payload = line[len('import '):]
                for part in payload.split(','):
                    _add(part.strip().split(' as ', 1)[0].strip())
            elif line.startswith('from '):
                payload = line[len('from '):]
                module_name = payload.split(' import ', 1)[0].strip()
                if module_name and not module_name.startswith('.'):
                    _add(module_name)
    return found


def _studio_chat_build_auto_prerequisites_from_code(code_text: str) -> str:
    modules = _studio_chat_collect_imported_modules(code_text)
    stdlib_names = set(getattr(sys, 'stdlib_module_names', set()) or set())
    third_party_packages: list[str] = []
    seen_pkgs: set[str] = set()
    for module_name in modules:
        root = str(module_name or '').split('.', 1)[0].strip()
        if not root or root in stdlib_names or root in {'__future__'}:
            continue
        pip_name = _STUDIO_IMPORT_TO_PIP_MAP.get(root, root)
        if pip_name in seen_pkgs:
            continue
        seen_pkgs.add(pip_name)
        third_party_packages.append(pip_name)

    lines: list[str] = ['- Python 3.10+']
    if third_party_packages:
        lines.append(f"- Εγκατάσταση πακέτων: pip install {' '.join(third_party_packages)}")
    else:
        lines.append('- Δεν χρειάζονται extra βιβλιοθήκες πέρα από την Python standard library.')
    lines.append('- Αποθήκευσε τον κώδικα σε αρχείο .py.')
    lines.append('- Εκτέλεση από τερματικό: python όνομα_αρχείου.py')
    return '\n'.join(lines)


def _studio_chat_extract_text_around_code(raw_text: str) -> tuple[str, str, str]:
    text = str(raw_text or '').replace('\r\n', '\n').replace('\r', '\n').strip()
    if not text:
        return '', '', ''

    merged = _studio_chat_merge_python_fenced_blocks(text)
    block_re = re.compile(r"```([^\n`]*)\n?([\s\S]*?)```")
    matches = list(block_re.finditer(merged))
    if matches:
        before_text = merged[:matches[0].start()].strip()
        after_text = merged[matches[-1].end():].strip()
        candidate_code = ''
        for match in matches:
            lang = str(match.group(1) or '').strip().lower()
            code = str(match.group(2) or '').strip('\n')
            if lang in {'python', 'py'}:
                candidate_code = code
                break
            if not candidate_code and _studio_chat_looks_like_python_code(code):
                candidate_code = code
        if candidate_code:
            try:
                candidate_code = _studio_chat_format_python_code(candidate_code)
            except Exception:
                pass
            return before_text, candidate_code.strip('\n'), after_text

    if _studio_chat_looks_like_python_code(text):
        try:
            code_text = _studio_chat_format_python_code(text)
        except Exception:
            code_text = text
        return '', code_text.strip('\n'), ''

    tail = _studio_chat_extract_pythonish_tail(text)
    if tail:
        prefix = text[:text.find(tail)].strip() if tail in text else ''
        try:
            tail = _studio_chat_format_python_code(tail)
        except Exception:
            pass
        return prefix, tail.strip('\n'), ''

    return text, '', ''


def _studio_chat_guess_description_text(user_text: str, before_text: str, after_text: str, code_text: str) -> str:
    candidates = [
        _studio_chat_clean_section_text(before_text),
        _studio_chat_clean_section_text(after_text),
    ]
    for candidate in candidates:
        if candidate and not _studio_chat_looks_like_python_code(candidate):
            pieces = [part.strip() for part in candidate.split('\n') if part.strip()]
            if pieces:
                return ' '.join(pieces[:4]).strip()

    user_summary = ' '.join(str(user_text or '').replace('\r', ' ').replace('\n', ' ').split()).strip()
    if user_summary:
        if len(user_summary) > 180:
            user_summary = user_summary[:177].rstrip() + '...'
        return (
            'Παρακάτω δίνεται μία πλήρης υλοποίηση σε Python για το ζητούμενο, '
            'με έτοιμο κώδικα και συνοπτικά βήματα εκτέλεσης.'
        )

    if code_text:
        return 'Παρακάτω δίνεται μία πλήρης υλοποίηση σε Python της εφαρμογής/λύσης που ζητήθηκε.'
    return 'Παρακάτω δίνεται συνοπτική περιγραφή της λύσης.'


def _studio_chat_build_prerequisites_text(code_text: str, trailing_text: str) -> str:
    tail = _studio_chat_clean_section_text(trailing_text)
    auto_text = _studio_chat_build_auto_prerequisites_from_code(code_text)
    if not tail:
        return auto_text

    tail_lines = [line.strip() for line in tail.split('\n') if line.strip()]
    normalized_tail = '\n'.join(
        line if line.startswith(('-', '•')) else f'- {line}'
        for line in tail_lines
    ).strip()
    if 'pip install' not in normalized_tail.casefold():
        auto_lines = [line.strip() for line in auto_text.split('\n') if line.strip()]
        install_lines = [line for line in auto_lines if 'pip install' in line.casefold()]
        run_lines = [line for line in auto_lines if 'python όνομα_αρχείου.py' in line.casefold()]
        extras = install_lines + [line for line in run_lines if line not in normalized_tail]
        if extras:
            normalized_tail = (normalized_tail + '\n' + '\n'.join(extras)).strip()
    return normalized_tail or auto_text


def _studio_chat_finalize_structured_code_reply(raw_text: str, user_text: str = '') -> str:
    original = str(raw_text or '').replace('\r\n', '\n').replace('\r', '\n').strip()
    if not original:
        return original

    before_text, code_text, after_text = _studio_chat_extract_text_around_code(original)
    if not code_text:
        return original

    code_text = _studio_chat_collapse_repeated_python_script(code_text).strip('\n')
    try:
        code_text = _studio_chat_format_python_code(code_text)
    except Exception:
        pass

    description_text = _studio_chat_guess_description_text(user_text, before_text, after_text, code_text)
    prerequisites_text = _studio_chat_build_prerequisites_text(code_text, after_text)

    return (
        'Περιγραφή εφαρμογής:\n'
        f'{description_text.strip()}\n\n'
        'Κώδικας:\n'
        f'```python\n{code_text.rstrip()}\n```\n\n'
        'Προαπαιτούμενα:\n'
        f'{prerequisites_text.strip()}'
    ).strip()



def _studio_chat_normalize_python_reply(raw_text: str, user_text: str = '') -> str:  # noqa: F811
    if _studio_chat_is_code_only_request(user_text):
        return _STUDIO_PREV_CHAT_NORMALIZE_PYTHON_REPLY(raw_text, user_text)
    if _studio_chat_should_use_structured_code_reply(user_text):
        normalized = _studio_chat_finalize_structured_code_reply(raw_text, user_text)
        if normalized.strip():
            return normalized
    return _STUDIO_PREV_CHAT_NORMALIZE_PYTHON_REPLY(raw_text, user_text)



def _studio_chat_build_generation_messages(self) -> list[dict[str, str]]:  # noqa: F811
    history_limit = max(1, int(self.history_turns_spin.value())) * 2
    history = self._messages[-history_limit:]
    messages: list[dict[str, str]] = []
    last_user_text = _studio_chat_find_last_user_text(history)
    system_prompt = self.system_prompt_edit.toPlainText().strip()

    if _studio_chat_is_code_only_request(last_user_text):
        extra_instruction = (
            'For the next reply, if you provide Python code, return only one complete ```python``` block '
            'and nothing before or after it. Do not add headings, explanations, duplicate code, or split '
            'the solution into multiple blocks.'
        )
        system_prompt = f"{system_prompt}\n\n{extra_instruction}".strip() if system_prompt else extra_instruction
    elif _studio_chat_should_use_structured_code_reply(last_user_text):
        extra_instruction = (
            'For the next reply, stream the answer in this exact order using explicit newline-separated sections.\n'
            "1) Start with the plain heading 'Περιγραφή εφαρμογής:' and then 2-6 short lines of plain text describing what the application/script does.\n"
            "2) Then write the plain heading 'Κώδικας:' and immediately after it exactly one complete ```python``` block with the full solution. Preserve indentation and keep the code in a single block.\n"
            "3) Finish with the plain heading 'Προαπαιτούμενα:' and short bullet lines for packages, setup steps, and how to run the script.\n"
            'Never place prerequisites before the code. Never duplicate the script. Keep the answer streaming-friendly and readable line by line.'
        )
        system_prompt = f"{system_prompt}\n\n{extra_instruction}".strip() if system_prompt else extra_instruction

    if system_prompt:
        messages.append({'role': 'system', 'content': system_prompt})
    for item in history:
        role = str(item.get('role') or 'user')
        content = str(item.get('content') or '').strip()
        if role == 'user':
            attachment_context = str(item.get('attachment_context') or '').strip()
            if attachment_context:
                content = (
                    f"{content}\n\n"
                    'Χρησιμοποίησε και τα παρακάτω συνημμένα αρχεία ως context για την απάντηση:\n'
                    f'{attachment_context}'
                ).strip()
        if content:
            messages.append({'role': role, 'content': content})
    return messages



def _studio_chat_render_plain_with_inline_code(text: str, inline_style: str = '') -> str:  # noqa: F811
    if not text:
        return ''

    heading_map = {
        'περιγραφή εφαρμογής:': '🧾 Περιγραφή εφαρμογής',
        'κώδικας:': '💻 Κώδικας',
        'προαπαιτούμενα:': '⚙ Προαπαιτούμενα',
        'αναφορές:': '📌 Αναφορές',
        'προαπαιτούμενα / αναφορές:': '⚙ Προαπαιτούμενα / Αναφορές',
        'application description:': '🧾 Application description',
        'code:': '💻 Code',
        'requirements:': '⚙ Requirements',
        'prerequisites:': '⚙ Prerequisites',
        'references:': '📌 References',
    }

    lines = str(text or '').replace('\r\n', '\n').replace('\r', '\n').split('\n')
    parts: list[str] = []
    for raw_line in lines:
        line = str(raw_line or '')
        stripped = line.strip()
        if not stripped:
            parts.append("<div style='height:7px;'></div>")
            continue
        low = stripped.casefold()
        if low in heading_map:
            parts.append(
                "<div style='margin:10px 0 6px 0;font-size:13.5px;font-weight:800;"
                "color:#2563eb;letter-spacing:0.2px;'>"
                + html.escape(heading_map[low]) +
                "</div>"
            )
            continue
        if re.match(r'^[\-•]\s+', stripped):
            body = re.sub(r'^[\-•]\s+', '', stripped)
            body_html = _STUDIO_PREV_CHAT_RENDER_PLAIN_INLINE(body, inline_style=inline_style)
            parts.append(
                "<div style='margin:2px 0 2px 18px;text-indent:-12px;'>"
                "<span style='font-weight:700;'>•</span> " + body_html + "</div>"
            )
            continue
        rendered_line = _STUDIO_PREV_CHAT_RENDER_PLAIN_INLINE(stripped, inline_style=inline_style)
        parts.append(f'<div>{rendered_line}</div>')
    return ''.join(parts)



def _studio_chat_partition_stream_text_for_commit(buffer_text: str, *, force: bool = False) -> tuple[str, str]:
    text = str(buffer_text or '').replace('\r\n', '\n').replace('\r', '\n')
    if force or not text:
        return text, ''

    last_newline = text.rfind('\n')
    if last_newline >= 0:
        return text[:last_newline + 1], text[last_newline + 1:]

    if len(text) >= 160:
        best_cut = -1
        for marker in ('. ', '! ', '? ', ': '):
            idx = text.rfind(marker)
            if idx > best_cut:
                best_cut = idx + len(marker) if idx >= 0 else best_cut
        if best_cut > 0:
            return text[:best_cut], text[best_cut:]
    return '', text



def _studio_chat_flush_stream_chunks_line_buffered(self) -> None:
    lock = getattr(self, '_stream_pending_lock', None)
    if lock is None:
        lock = threading.Lock()
        self._stream_pending_lock = lock
    with lock:
        pending_chunks = list(getattr(self, '_stream_pending_chunks', []) or [])
        pending_statuses = list(getattr(self, '_stream_pending_statuses', []) or [])
        self._stream_pending_chunks = []
        self._stream_pending_statuses = []

    render_needed = False
    if pending_chunks and self._messages and self._messages[-1].get('role') == 'assistant':
        incoming = ''.join(pending_chunks)
        carry = str(getattr(self, '_chat_stream_line_buffer', '') or '')
        visible_text, residual = _studio_chat_partition_stream_text_for_commit(carry + incoming, force=False)
        self._chat_stream_line_buffer = residual
        if visible_text:
            current = str(self._messages[-1].get('content') or '')
            self._messages[-1]['content'] = current + visible_text
            self._messages[-1]['streaming'] = True
            self._chat_stream_chars_since_render = 0
            self._chat_stream_last_visible_ts = time.monotonic()
            render_needed = True

    if render_needed:
        _studio_chat_schedule_refresh(self, force=False)
    if pending_statuses:
        try:
            self._set_status(str(pending_statuses[-1]))
        except Exception:
            pass



def _studio_chat_flush_stream_chunks_line_buffered_gui_safe(self) -> None:
    if not _studio_is_object_in_gui_thread(self):
        _studio_run_on_gui_thread(lambda s=self: _studio_chat_flush_stream_chunks_line_buffered_gui_safe(s))
        return
    _studio_chat_flush_stream_chunks_line_buffered(self)



def _studio_chat_start_generation_realtime_buffered_with_stop(self) -> None:  # noqa: F811
    model_dir = self.model_dir_edit.text().strip()
    messages = self._build_generation_messages()
    options = self._current_generation_options()
    self._stream_pending_chunks = []
    self._stream_pending_statuses = []
    self._stream_pending_lock = threading.Lock()
    self._chat_stop_event = threading.Event()
    self._chat_stream_line_buffer = ''
    self._chat_render_min_interval_s = 0.06
    self._chat_stream_chars_since_render = 0
    self._chat_stream_last_visible_ts = 0.0
    self._chat_stream_min_chars_before_render = 1
    self._chat_stream_max_silence_s = 0.20
    self._chat_ensure_stream_timer()
    if not self._stream_flush_timer.isActive():
        self._stream_flush_timer.start()
    self._set_busy(True, 'Φόρτωση runtime και παραγωγή απάντησης...')
    self._messages.append({'role': 'assistant', 'content': '', 'streaming': True})
    _studio_chat_schedule_refresh(self, force=True)

    def _worker_fn(local_model_dir: str, local_messages: list[dict[str, str]], local_options: dict[str, Any], progress_callback: Callable[[str], None] | None = None) -> dict[str, Any]:
        _ = progress_callback
        return _studio_chat_generate_worker_streaming_v2(
            local_model_dir,
            local_messages,
            local_options,
            progress_callback=self._on_generation_progress,
            stop_event=self._chat_stop_event,
        )

    self._chat_thread = QThread(self)
    worker = BackgroundWorker(_worker_fn, model_dir, copy.deepcopy(messages), copy.deepcopy(options))
    self._chat_worker = worker
    worker.moveToThread(self._chat_thread)
    self._chat_thread.started.connect(worker.run)
    worker.finished.connect(self._on_generation_finished, Qt.QueuedConnection)
    worker.error.connect(self._on_generation_error, Qt.QueuedConnection)
    worker.finished.connect(self._chat_thread.quit, Qt.QueuedConnection)
    worker.error.connect(self._chat_thread.quit, Qt.QueuedConnection)
    self._chat_thread.finished.connect(self._clear_generation_thread, Qt.QueuedConnection)
    self._chat_thread.start()



def _studio_chat_on_generation_finished_with_stop(self, result: object) -> None:  # noqa: F811
    try:
        carry = str(getattr(self, '_chat_stream_line_buffer', '') or '')
        if carry and self._messages and self._messages[-1].get('role') == 'assistant':
            current = str(self._messages[-1].get('content') or '')
            self._messages[-1]['content'] = current + carry
            self._messages[-1]['streaming'] = True
            self._chat_stream_line_buffer = ''
    except Exception:
        self._chat_stream_line_buffer = ''
    _studio_chat_on_generation_finished_gui_safe(self, result)
    stopped = bool((result or {}).get('stopped')) if isinstance(result, dict) else False
    if stopped:
        self._set_status('Η απάντηση διακόπηκε από τον χρήστη.')
    try:
        _studio_chat_sync_action_buttons(self, True)
    except Exception:
        pass



def _studio_chat_on_generation_error_realtime_threadsafe(self, message: str) -> None:  # noqa: F811
    try:
        carry = str(getattr(self, '_chat_stream_line_buffer', '') or '')
        if carry and self._messages and self._messages[-1].get('role') == 'assistant':
            current = str(self._messages[-1].get('content') or '')
            self._messages[-1]['content'] = current + carry
            self._chat_stream_line_buffer = ''
    except Exception:
        self._chat_stream_line_buffer = ''
    try:
        self._flush_stream_chunks()
    except Exception:
        pass
    timer = getattr(self, '_stream_flush_timer', None)
    if timer is not None and timer.isActive():
        timer.stop()
    if self._messages and self._messages[-1].get('role') == 'assistant' and not str(self._messages[-1].get('content') or '').strip():
        self._messages.pop()
    _studio_chat_schedule_refresh(self, force=True)
    self._set_busy(False, f'Σφάλμα chat: {message}')
    QMessageBox.critical(self, APP_TITLE, message)


# Activate patched symbols.
StudioModelChatWindow._build_generation_messages = _studio_chat_build_generation_messages
StudioModelChatWindow._flush_stream_chunks = _studio_chat_flush_stream_chunks_line_buffered_gui_safe
StudioModelChatWindow._start_generation = _studio_chat_start_generation_realtime_buffered_with_stop
StudioModelChatWindow._on_generation_finished = _studio_chat_on_generation_finished_with_stop
StudioModelChatWindow._on_generation_error = _studio_chat_on_generation_error_realtime_threadsafe
